DATE_ISO_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
_DATE_DMY_RE = re.compile(r"^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})$")


def attach_tooltip(widget, text, wrap=340):
    """Tiny dependency-free hover tooltip for plain-language explanations."""
    tip = {"win": None}

    def _show(_e=None):
        try:
            if tip["win"] is not None:
                return
            x = widget.winfo_rootx() + 12
            y = widget.winfo_rooty() + widget.winfo_height() + 6
            w = tk.Toplevel(widget)
            w.wm_overrideredirect(True)
            w.wm_geometry(f"+{x}+{y}")
            tk.Label(w, text=text, justify="left", wraplength=wrap,
                     bg="#0f172a", fg="#e2e8f0", padx=8, pady=6,
                     font=(FONT_FAMILY, FS_BODY)).pack()
            tip["win"] = w
        except Exception:
            pass

    def _hide(_e=None):
        try:
            if tip["win"] is not None:
                tip["win"].destroy()
                tip["win"] = None
        except Exception:
            pass

    widget.bind("<Enter>", _show)
    widget.bind("<Leave>", _hide)
    return widget


def parse_date_flex(s):
    """Tolerant date parse: ISO YYYY-MM-DD first, then DD-MM-YYYY /
    DD/MM/YYYY / DD.MM.YYYY (how dates are commonly typed in Egypt).
    Returns datetime.date or None. Exists because legacy data contains
    non-ISO strings like '28-06-2026' that crashed strict fromisoformat."""
    raw = (str(s) if s is not None else "").strip().split(" ")[0]
    if not raw:
        return None
    try:
        return dt.date.fromisoformat(raw)
    except Exception:
        pass
    m = _DATE_DMY_RE.match(raw)
    if m:
        d_, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return dt.date(y, mo, d_)
        except Exception:
            return None
    return None


def iso_date_or_keep(s):
    """Normalize any parseable date string to ISO; keep original otherwise."""
    d = parse_date_flex(s)
    return d.isoformat() if d is not None else (s or "")

