def wire_date_validation(entry, var):
    """Live YYYY-MM-DD validation: text turns red while the date is invalid.

    Empty is allowed (optional fields). Attach to any ttk.Entry + StringVar.
    """
    def _check(*_):
        s = (var.get() or "").strip()
        ok = not s
        if s and DATE_ISO_RE.match(s):
            try:
                dt.date.fromisoformat(s)
                ok = True
            except Exception:
                ok = False
        try:
            entry.configure(foreground=CLR["text"] if ok else CLR["danger"])
        except Exception:
            pass
    def _normalize(_e=None):
        # Entry ease: accept DD-MM-YYYY / DD/MM/YYYY and quietly convert to
        # ISO when the user leaves the field, instead of demanding the
        # format up front. Red highlight remains for genuinely bad dates.
        s = (var.get() or "").strip()
        if not s or DATE_ISO_RE.match(s):
            return
        d = parse_date_flex(s)
        if d is not None:
            var.set(d.isoformat())
    try:
        entry.bind("<FocusOut>", _normalize, add="+")
    except Exception:
        pass
    try:
        var.trace_add("write", _check)
    except Exception:
        var.trace("w", lambda *a: _check())
    _check()
    return entry

