def get_app_data_dir():
    """User-writable app data folder under Documents."""
    try:
        docs = os.path.join(os.path.expanduser("~"), "Documents")
    except Exception:
        docs = os.path.expanduser("~")
    base = os.path.join(docs, "ImportDecisionApp")
    os.makedirs(base, exist_ok=True)
    return base

def get_default_export_dir():
    p = os.path.join(get_app_data_dir(), EXPORT_DIR_NAME)
    os.makedirs(p, exist_ok=True)
    return p

def get_backup_dir():
    p = os.path.join(get_app_data_dir(), BACKUP_DIR_NAME)
    os.makedirs(p, exist_ok=True)
    return p

def state_file_path():
    """Canonical location for app_state.json (works for EXE too)."""
    return os.path.join(get_app_data_dir(), "app_state.json")


def error_log_path():
    return os.path.join(get_app_data_dir(), "error_log.txt")

# Rolling in-session error buffer surfaced in the status bar. Complements
# the persistent state["data_issues"] written by record_data_issue().
RECENT_ERRORS = []
_RECENT_ERRORS_MAX = 200


def log_exception(exc: Exception, context: str = "Unhandled error"):
    try:
        _msg = f"{type(exc).__name__}: {exc}"
        # Deduplicate: repeated identical failures (e.g. the same fetch
        # retrying every 30 min) keep ONE chip entry, moved to most-recent.
        for _i in range(len(RECENT_ERRORS) - 1, -1, -1):
            if RECENT_ERRORS[_i][1] == context and RECENT_ERRORS[_i][2] == _msg:
                del RECENT_ERRORS[_i]
                break
        RECENT_ERRORS.append((
            dt.datetime.now().strftime("%H:%M:%S"),
            context,
            f"{type(exc).__name__}: {exc}",
        ))
        del RECENT_ERRORS[:-_RECENT_ERRORS_MAX]
    except Exception:
        pass
    try:
        os.makedirs(get_app_data_dir(), exist_ok=True)
        with open(error_log_path(), "a", encoding="utf-8") as f:
            f.write("\n" + "=" * 80 + "\n")
            f.write(f"[{dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] {context}\n")
            f.write("".join(traceback.format_exception(type(exc), exc, exc.__traceback__)))
    except Exception:
        pass


def now_ts():
    return dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def to_float(x, default=None):
    """Compatibility delegate to the testable modular numeric helper."""
    return _core_to_float(x, default)


def safe_div(a, b, default=0.0):
    try:
        if b == 0:
            return default
        return a / b
    except Exception:
        return default

def fmt_num(x, decimals=2):
    if x is None:
        return "-"
    try:
        return f"{float(x):,.{decimals}f}"
    except Exception:
        return "-"

def fmt_int(x):
    if x is None:
        return "-"
    try:
        return f"{int(round(float(x))):,d}"
    except Exception:
        return "-"


GLOSSARY = [
    ("CBOT", "Chicago Board of Trade futures price — the global reference for "
             "corn / soybean / SBM, quoted in cents per bushel (corn, soybean) "
             "or USD per short ton (SBM)."),
    ("Premium (basis)", "The seller's add-on over the CBOT futures price for "
             "physical delivery — covers origin, quality, freight to port and "
             "the seller's margin. Quoted in the same unit as CBOT."),
    ("CIF (USD/MT)", "Cost + Insurance + Freight: the USD price per metric ton "
             "delivered to the Egyptian port, before local costs. For CORN: "
             "(CBOT + Premium) × 0.3937 converts cents/bu to USD/MT."),
    ("Own-After (EGP/MT)", "The full landed cost per ton in EGP: CIF × FX + "
             "discharge, clearance and inland freight (Finance-sheet "
             "convention, cash basis). The Deal Evaluator additionally shows "
             "finance carry as its own line. Own-After is NEVER the same "
             "field as CIF — CIF is goods-at-port in USD; Own-After is "
             "everything, in EGP."),
    ("Open MTM", "Mark-to-Market on OPEN contracts: what the contract is worth "
             "today using the latest CBOT and FX — a live, unrealized figure "
             "that changes with the market."),
    ("Open MTM Edge", "Own-After of open contracts vs. today's local price: "
             "positive = the import currently beats buying local."),
    ("Realized Savings", "For CLOSED contracts only: (local market price on the "
             "delivery date − actual Own-After) × quantity. Evidence-grade — "
             "it no longer moves with the market."),
    ("Sav/MT", "Saving per metric ton: local price minus Own-After for one "
             "ton. Multiply by contract MT for total impact."),
    ("Marginal threshold", "If |Sav/MT| is within ± this EGP value, the app "
             "flags the decision 'Marginal' instead of a firm Import / Local "
             "call. Editable in Setup & Data → Data Management."),
    ("FX Live vs Locked", "Live = value everything at today's USD/EGP. "
             "Locked = use each contract's delivery-date FX and delivery-date "
             "local price — the fair basis for judging a past decision."),
    ("Carry (finance cost)", "Interest cost of the money tied up between "
             "payment and consumption: price × rate × days / 360."),
    ("Break-even FX", "The USD/EGP rate at which the import saving becomes "
             "exactly zero — above it, buying local wins."),
    ("Slot / Roll", "A CBOT 'slot' is one futures-month pricing tranche of a "
             "contract. Rolling moves an unpriced slot to a later futures "
             "month, paying/receiving the spread."),
    ("FLAT contract", "A contract priced at a fixed flat USD/MT rather than "
             "CBOT + premium."),
    ("Form 4 (نموذج ٤)", "The Egyptian bank import form. Its issuance date is "
             "when the bank allocates/converts the USD for the shipment, so "
             "'FX at Form 4' is the rate actually paid for the currency — "
             "the cash cost. 'FX at delivery' is the market rate when the "
             "goods arrive, used for fair local-vs-import comparison. The "
             "gap between them is the FX timing gain/loss on the contract."),
    ("Futures curve", "The strip of prices for successive futures delivery "
             "months. Upward slope (contango) means later months cost more — "
             "the market pays you to buy sooner; downward (backwardation) "
             "rewards waiting."),
    ("Market movement", "Percent change of the front futures price over 1d / "
             "5d / 20d windows, classified into a trend signal on Home."),
]


def normalize_origin(value):
    """Return a controlled, canonical origin label for grouping/filtering.

    This deliberately prevents silent fragmentation such as Brazil/BRZ/brasil.
    Unknown values are upper-cased; the UI keeps users on a controlled list.
    """
    raw = (value or "").strip()
    if not raw:
        return ""
    key = re.sub(r"\s+", " ", raw.upper()).strip()
    compact_key = re.sub(r"[^A-Z0-9/]", "", key)
    if key in ORIGIN_ALIASES:
        return ORIGIN_ALIASES[key]
    if compact_key in ORIGIN_ALIASES:
        return ORIGIN_ALIASES[compact_key]
    return key


def make_provenance(source="manual", as_of=None, entered_by="user", confidence="manual", note=""):
    """Small provenance block to attach to money-impact records.

    Every KPI should be traceable back to source + as-of. This is intentionally
    lightweight so it works with the existing JSON state file.
    """
    return {
        "source": source or "manual",
        "as_of": as_of or now_ts(),
        "entered_by": entered_by or "user",
        "confidence": confidence or "manual",
        "note": note or "",
        "recorded_at": now_ts(),
    }


def append_audit_event(state, event_type, entity, entity_id="", details=None, level="INFO"):
    """Append a compact audit event without letting the log grow forever."""
    try:
        log = state.setdefault("audit_log", [])
        log.append({
            "ts": now_ts(),
            "level": level,
            "event_type": event_type,
            "entity": entity,
            "entity_id": str(entity_id or ""),
            "details": details or {},
        })
        if len(log) > 1000:
            del log[:-1000]
    except Exception as exc:
        log_exception(exc, "append_audit_event")


def record_data_issue(state, context, message, severity="WARN"):
    """Record visible data-quality issues instead of swallowing them silently."""
    try:
        issues = state.setdefault("data_issues", [])
        issues.append({
            "ts": now_ts(),
            "severity": severity,
            "context": context,
            "message": str(message),
        })
        if len(issues) > 300:
            del issues[:-300]
    except Exception as exc:
        log_exception(exc, "record_data_issue")

def fetch_yahoo_futures_quote(symbol, timeout=8):
    """
    Fetch delayed futures quote from Yahoo Finance using the public chart endpoint.
    Returns a dict with price, symbol, exchange name, and market timestamp text.
    """
    safe_symbol = urllib.parse.quote(symbol, safe="")
    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{safe_symbol}?interval=1m&range=1d"
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8")
    payload = json.loads(raw)
    chart = ((payload or {}).get("chart") or {})
    if chart.get("error"):
        raise RuntimeError(str(chart.get("error")))
    result = (chart.get("result") or [None])[0]
    if not result:
        raise RuntimeError("No quote data returned.")
    meta = result.get("meta") or {}

    price = meta.get("regularMarketPrice")
    prev_close = meta.get("previousClose")
    if price in (None, ""):
        price = prev_close
    if price in (None, ""):
        closes = (((result.get("indicators") or {}).get("quote") or [{}])[0]).get("close") or []
        closes = [x for x in closes if x is not None]
        if closes:
            price = closes[-1]
    if price in (None, ""):
        raise RuntimeError("Price not available from Yahoo Finance.")

    market_ts = meta.get("regularMarketTime")
    market_time_text = ""
    if market_ts:
        try:
            market_time_text = dt.datetime.fromtimestamp(int(market_ts)).strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            market_time_text = str(market_ts)

    return {
        "symbol": meta.get("symbol") or symbol,
        "price": float(price),
        "currency": meta.get("currency") or "",
        "exchange_name": meta.get("exchangeName") or "Yahoo Finance",
        "instrument_type": meta.get("instrumentType") or "",
        "market_time_text": market_time_text,
    }


def fetch_yahoo_fx_rate(timeout=8):
    """Fetch delayed USD/EGP from Yahoo Finance using EGP=X."""
    return fetch_yahoo_futures_quote(YAHOO_FX_SYMBOL, timeout=timeout)



def _http_get_text(url, timeout=12):
    req = urllib.request.Request(
        url,
        headers={"User-Agent": "Mozilla/5.0", "Accept-Language": "en-US,en;q=0.9", "Cache-Control": "no-cache"},
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read()
        try:
            return raw.decode("utf-8", errors="replace")
        except Exception:
            return raw.decode(errors="replace")

def _strip_html(s):
    return re.sub(r"<[^>]+>", " ", s or "")

def _compact_spaces(s):
    return re.sub(r"\s+", " ", s or "").strip()



def _source_confidence(source_name, has_market_time):
    source_name = (source_name or "").upper()
    if source_name == "CME":
        return "HIGH" if has_market_time else "MEDIUM"
    if source_name == "STOOQ":
        return "MEDIUM" if has_market_time else "LOW"
    if source_name == "YAHOO":
        return "MEDIUM" if has_market_time else "LOW"
    return "LOW"

def _extract_cme_last_price_text(html):
    patterns = [
        r'"last"\s*:\s*"(?P<px>[0-9,]+(?:\.[0-9]+)?(?:\'[0-9]+)?)"',
        r'"lastPrice"\s*:\s*"?(?P<px>[0-9,]+(?:\.[0-9]+)?(?:\'[0-9]+)?)"?',
        r'\bLast\b[^0-9]{0,80}(?P<px>[0-9,]+(?:\.[0-9]+)?(?:\'[0-9]+)?)',
    ]
    for pat in patterns:
        m = re.search(pat, html, re.I | re.S)
        if m:
            return m.group("px")
    txt = _compact_spaces(_strip_html(html))
    for pat in patterns[2:]:
        m = re.search(pat, txt, re.I | re.S)
        if m:
            return m.group("px")
    raise RuntimeError("Could not parse CME last price from the page.")

def _cme_fractional_to_float(price_text):
    s = (price_text or "").strip().replace(",", "")
    if not s:
        raise RuntimeError("Empty CME price text.")
    if "'" in s:
        whole, frac = s.split("'", 1)
        frac_digits = re.sub(r"[^0-9]", "", frac)
        return float(whole) + (int(frac_digits) / 8.0 if frac_digits else 0.0)
    return float(s)

def _extract_cme_timestamp(html):
    txt = _compact_spaces(_strip_html(html))
    patterns = [
        r'Last Updated[: ]+([0-9]{1,2}\s+[A-Za-z]{3}\s+[0-9]{4}\s+[0-9:]{7,8}\s*(?:AM|PM)?\s*[A-Z]{0,4})',
        r'Updated[: ]+([0-9]{1,2}\s+[A-Za-z]{3}\s+[0-9]{4}\s+[0-9:]{7,8}\s*(?:AM|PM)?\s*[A-Z]{0,4})',
    ]
    for pat in patterns:
        m = re.search(pat, txt, re.I)
        if m:
            return m.group(1).strip()
    return ""

def fetch_cme_delayed_quote(commodity, timeout=12):
    comm = (commodity or "").strip().upper()
    url = CME_QUOTE_URLS.get(comm)
    if not url:
        raise RuntimeError(f"No CME quote URL configured for {comm}.")
    html = _http_get_text(url, timeout=timeout)
    price_text = _extract_cme_last_price_text(html)
    price = float(_cme_fractional_to_float(price_text))
    stamp = _extract_cme_timestamp(html)
    fetched_at = now_ts()
    return {
        "symbol": comm,
        "price": price,
        "display_price_text": price_text,
        "currency": "US cents/bu" if comm in ("CORN", "SOYBEAN", "WHEAT") else "$/st",
        "exchange_name": "CME Group",
        "instrument_type": "FUTURE",
        "market_time_text": stamp,
        "fetched_at": fetched_at,
        "source_url": url,
        "source": "CME",
        "confidence": _source_confidence("CME", bool(stamp)),
        "time_note": "Exchange timestamp" if stamp else "Fetched time only",
    }

def _extract_stooq_last_price(html):
    txt = _compact_spaces(_strip_html(html))
    patterns = [
        r'\bLast[: ]+([0-9]+(?:\.[0-9]+)?)\b',
        r'\bClose[: ]+([0-9]+(?:\.[0-9]+)?)\b',
        r'\b([0-9]+(?:\.[0-9]+)?)\b\s*Date[: ]+[A-Za-z]{3}\s+[0-9]{1,2}',
    ]
    for pat in patterns:
        m = re.search(pat, txt, re.I)
        if m:
            return float(m.group(1))
    m = re.search(r'(?:ZC\.F|ZS\.F|ZW\.F|ZM\.F)[A-Z \-]*([0-9]+(?:\.[0-9]+)?)', txt, re.I)
    if m:
        return float(m.group(1))
    raise RuntimeError("Could not parse Stooq price.")

def _extract_stooq_timestamp(html):
    txt = _compact_spaces(_strip_html(html))
    patterns = [
        r'Date[: ]+([A-Za-z]{3}\s+[0-9]{1,2}(?:\s+[0-9:]{8})?)',
        r'([A-Za-z]{3}\s+[0-9]{1,2}\s+[0-9:]{8})',
    ]
    for pat in patterns:
        m = re.search(pat, txt, re.I)
        if m:
            return m.group(1)
    return ""

def fetch_stooq_delayed_quote(commodity, timeout=12):
    comm = (commodity or "").strip().upper()
    symbol = STOOQ_SYMBOLS.get(comm)
    if not symbol:
        raise RuntimeError(f"No delayed quote symbol configured for {comm}.")
    url = f"https://stooq.com/q/?s={symbol}"
    html = _http_get_text(url, timeout=timeout)
    price = _extract_stooq_last_price(html)
    stamp = _extract_stooq_timestamp(html)
    fetched_at = now_ts()
    return {
        "symbol": comm,
        "price": float(price),
        "display_price_text": f"{price:.2f}",
        "currency": "US cents/bu" if comm in ("CORN", "SOYBEAN", "WHEAT") else "$/st",
        "exchange_name": "Stooq",
        "instrument_type": "FUTURE",
        "market_time_text": stamp,
        "fetched_at": fetched_at,
        "source_url": url,
        "source": "STOOQ",
        "confidence": _source_confidence("STOOQ", bool(stamp)),
        "time_note": "Page timestamp" if stamp else "Fetched time only",
    }

def fetch_yahoo_delayed_quote(commodity, timeout=12):
    comm = (commodity or "").strip().upper()
    symbol = YAHOO_FUTURES_SYMBOLS.get(comm)
    if not symbol:
        raise RuntimeError(f"No Yahoo symbol configured for {comm}.")
    quote = fetch_yahoo_futures_quote(symbol, timeout=timeout)
    fetched_at = now_ts()
    quote["source"] = "YAHOO"
    quote["fetched_at"] = fetched_at
    quote["display_price_text"] = f"{quote.get('price', 0.0):.2f}"
    quote["confidence"] = _source_confidence("YAHOO", bool(quote.get("market_time_text")))
    quote["time_note"] = "Market timestamp" if quote.get("market_time_text") else "Fetched time only"
    return quote

def fetch_best_commodity_quote(commodity, timeout=12):
    errors = []
    for source_name in DATA_SOURCE_PRIORITY:
        try:
            if source_name == "CME":
                return fetch_cme_delayed_quote(commodity, timeout=timeout)
            if source_name == "STOOQ":
                return fetch_stooq_delayed_quote(commodity, timeout=timeout)
            if source_name == "YAHOO":
                return fetch_yahoo_delayed_quote(commodity, timeout=timeout)
        except Exception as e:
            errors.append(f"{source_name}: {e}")
    raise RuntimeError("All commodity sources failed. " + " | ".join(errors))


# ── V8.2 Public/free market intelligence layer ───────────────────────────
def _yahoo_chart_payload(symbol, range_="1mo", interval="1d", timeout=12):
    """Return Yahoo public chart JSON for a symbol. Prototype/free feed only."""
    safe_symbol = urllib.parse.quote(symbol, safe="")
    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{safe_symbol}?interval={interval}&range={range_}"
    req = urllib.request.Request(url, headers={
        "User-Agent": "Mozilla/5.0",
        "Accept": "application/json",
        "Cache-Control": "no-cache",
    })
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        payload = json.loads(resp.read().decode("utf-8", errors="replace"))
    chart = (payload or {}).get("chart") or {}
    if chart.get("error"):
        raise RuntimeError(str(chart.get("error")))
    result = (chart.get("result") or [None])[0]
    if not result:
        raise RuntimeError(f"No chart data returned for {symbol}.")
    return result

def _chart_result_to_history(result):
    """Parse Yahoo chart result into sorted rows: {date, close, volume}."""
    import datetime as _dt
    timestamps = result.get("timestamp") or []
    q = ((result.get("indicators", {}) or {}).get("quote") or [{}])[0] or {}
    closes = q.get("close") or []
    vols = q.get("volume") or []
    rows = []
    for i, ts in enumerate(timestamps):
        close = closes[i] if i < len(closes) else None
        if close is None:
            continue
        try:
            d = _dt.datetime.utcfromtimestamp(int(ts)).strftime("%Y-%m-%d")
            rows.append({
                "date": d,
                "close": float(close),
                "volume": float(vols[i]) if i < len(vols) and vols[i] is not None else None,
            })
        except Exception:
            continue
    rows.sort(key=lambda r: r.get("date", ""))
    return rows

def classify_market_trend(change_1d_pct=None, change_5d_pct=None, change_20d_pct=None):
    """Compact trend label for Home dashboard. Pure function for tests."""
    vals = [v for v in (change_1d_pct, change_5d_pct, change_20d_pct) if v is not None]
    if not vals:
        return "No signal"
    strong_up = sum(1 for v in vals if v > 0.75)
    strong_dn = sum(1 for v in vals if v < -0.75)
    up = sum(1 for v in vals if v > 0.10)
    dn = sum(1 for v in vals if v < -0.10)
    if strong_up >= 2 or (up >= 2 and vals[-1] > 0):
        return "Bullish pressure"
    if strong_dn >= 2 or (dn >= 2 and vals[-1] < 0):
        return "Bearish pressure"
    if up and dn:
        return "Mixed / choppy"
    return "Flat / quiet"

def calc_market_movement_from_history(rows):
    """Calculate 1D/5D/20D movement and simple volatility from daily rows."""
    clean = [r for r in (rows or []) if to_float(r.get("close"), None) is not None]
    clean.sort(key=lambda r: r.get("date", ""))
    if not clean:
        return {}
    last = clean[-1]
    last_px = to_float(last.get("close"), None)
    def pct_back(n):
        if last_px is None or len(clean) <= n:
            return None
        prev = to_float(clean[-1-n].get("close"), None)
        if prev in (None, 0):
            return None
        return (last_px - prev) / prev * 100.0
    # Daily return volatility over latest up to 20 observations.
    rets = []
    tail = clean[-21:]
    for a, b in zip(tail, tail[1:]):
        pa = to_float(a.get("close"), None)
        pb = to_float(b.get("close"), None)
        if pa not in (None, 0) and pb is not None:
            rets.append((pb - pa) / pa * 100.0)
    vol20 = None
    if len(rets) >= 2:
        mean = sum(rets) / len(rets)
        vol20 = math.sqrt(sum((x - mean) ** 2 for x in rets) / (len(rets) - 1))
    chg1 = pct_back(1)
    chg5 = pct_back(5)
    chg20 = pct_back(20)
    volume = last.get("volume")
    return {
        "last": last_px,
        "last_date": last.get("date", ""),
        "change_1d_pct": chg1,
        "change_5d_pct": chg5,
        "change_20d_pct": chg20,
        "vol20_daily_pct": vol20,
        "last_volume": volume,
        "trend": classify_market_trend(chg1, chg5, chg20),
    }

def fetch_public_market_movement(commodity, timeout=12):
    """Fetch daily market movement from public Yahoo chart endpoint.

    Free/prototype only. This is not licensed CME redistribution.
    """
    comm = (commodity or "").strip().upper()
    symbol = YAHOO_FUTURES_SYMBOLS.get(comm)
    if not symbol:
        raise RuntimeError(f"No public movement symbol configured for {comm}.")
    result = _yahoo_chart_payload(symbol, range_="3mo", interval="1d", timeout=timeout)
    hist = _chart_result_to_history(result)
    mv = calc_market_movement_from_history(hist)
    if not mv:
        raise RuntimeError(f"No movement history parsed for {comm}.")
    meta = result.get("meta") or {}
    mv.update({
        "commodity": comm,
        "symbol": symbol,
        "source": "Yahoo public chart",
        "feed_status": PUBLIC_MARKET_FEED_POLICY["status"],
        "as_of": mv.get("last_date") or now_ts(),
        "currency": meta.get("currency") or "",
        "exchange_name": meta.get("exchangeName") or "Yahoo Finance",
    })
    return mv

def _futures_symbol_for_contract(commodity, month_code, year):
    comm = (commodity or "").strip().upper()
    root = YAHOO_FUTURES_ROOTS.get(comm)
    if not root:
        raise RuntimeError(f"No Yahoo futures root configured for {comm}.")
    yy = int(year) % 100
    return f"{root}{month_code}{yy:02d}{YAHOO_FUTURES_EXCHANGE_SUFFIX}"

def next_public_futures_contracts(commodity, today=None, count=6):
    """Return next likely Yahoo contract symbols for the CBOT commodity."""
    comm = (commodity or "").strip().upper()
    today = today or dt.date.today()
    months = FUTURES_MONTH_CODES_BY_COMMODITY.get(comm) or FUTURES_MONTH_CODES_ALL
    out = []
    year = today.year
    while len(out) < count and year <= today.year + 4:
        for code, month_num, month_name in months:
            # Use a conservative roll cutoff: include current contract month only
            # until the 20th. Exact last-trade dates require licensed exchange
            # calendars and should not be guessed.
            if year == today.year and (month_num < today.month or (month_num == today.month and today.day > 20)):
                continue
            symbol = _futures_symbol_for_contract(comm, code, year)
            out.append({
                "commodity": comm,
                "symbol": symbol,
                "month_code": code,
                "contract_month": f"{month_name} {year}",
                "year": year,
                "month": month_num,
            })
            if len(out) >= count:
                break
        year += 1
    return out

def fetch_public_futures_curve(commodity, count=6, timeout=8):
    """Fetch an indicative public futures curve from Yahoo contract symbols."""
    comm = (commodity or "").strip().upper()
    contracts = next_public_futures_contracts(comm, count=count)
    rows = []
    errors = []
    front_price = None
    for item in contracts:
        try:
            q = fetch_yahoo_futures_quote(item["symbol"], timeout=timeout)
            price = to_float(q.get("price"), None)
            if price is None:
                raise RuntimeError("No price")
            if front_price is None:
                front_price = price
            rows.append({
                **item,
                "price": price,
                "vs_front": (price - front_price) if front_price is not None else None,
                "source": "Yahoo public contract quote",
                "feed_status": PUBLIC_MARKET_FEED_POLICY["status"],
                "as_of": q.get("market_time_text") or q.get("fetched_at") or now_ts(),
                "confidence": "LOW",
            })
        except Exception as e:
            errors.append(f"{item.get('symbol')}: {e}")
            continue
    if not rows:
        raise RuntimeError("No futures-curve contracts returned. " + " | ".join(errors[:4]))
    return {
        "commodity": comm,
        "rows": rows,
        "source": "Yahoo public contract quote",
        "feed_status": PUBLIC_MARKET_FEED_POLICY["status"],
        "as_of": rows[0].get("as_of") or now_ts(),
        "errors": errors[:10],
    }

def fetch_public_market_intelligence(commodities=("CORN", "SOYBEAN", "WHEAT", "SBM"), timeout=10):
    """Fetch movement + futures curve for dashboard storage."""
    out = {"movement": {}, "futures_curves": {}, "errors": [], "fetched_at": now_ts()}
    for comm in commodities:
        try:
            out["movement"][comm] = fetch_public_market_movement(comm, timeout=timeout)
        except Exception as e:
            out["errors"].append(f"movement {comm}: {e}")
        try:
            out["futures_curves"][comm] = fetch_public_futures_curve(comm, count=5, timeout=timeout)
        except Exception as e:
            out["errors"].append(f"curve {comm}: {e}")
    return out

def fetch_fx_rate_api(timeout=12):
    req = urllib.request.Request(
        FX_API_URL,
        headers={"User-Agent": "Mozilla/5.0", "Accept": "application/json", "Cache-Control": "no-cache"},
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
    data = json.loads(raw)
    rate = (data or {}).get("rate")
    if rate in (None, ""):
        raise RuntimeError("FX rate not found in API response.")
    rate = float(rate)
    return {
        "symbol": "USD/EGP",
        "price": rate,
        "buy": None,
        "sell": rate,
        "currency": "EGP",
        "exchange_name": "Frankfurter",
        "instrument_type": "FX",
        "market_time_text": (data or {}).get("date") or now_ts(),
        "source_url": FX_API_URL,
        "source": "Frankfurter official-source blend",
    }

def fetch_best_fx_rate(timeout=12):
    """Fetch current USD/EGP rate. Primary: Frankfurter API.
    Falls back to Yahoo Finance EGP=X."""
    errors = []
    try:
        return fetch_fx_rate_api(timeout=timeout)
    except Exception as e:
        errors.append(f"Frankfurter: {e}")
    try:
        result = fetch_yahoo_futures_quote(YAHOO_FX_SYMBOL, timeout=timeout)
        result["source"] = "Yahoo-Finance-FX"
        return result
    except Exception as e:
        errors.append(f"Yahoo: {e}")
    raise RuntimeError(f"All FX sources failed: {'; '.join(errors)}")

def fetch_fx_rate_for_date(date_str, timeout=12):
    """Fetch USD/EGP for a specific historical date.
    Tries frankfurter.dev with ?date=, then Yahoo Finance as fallback.
    Returns (rate_float, source_str) or raises RuntimeError."""
    errors = []

    # ── Primary: frankfurter.dev with date param ──────────────────
    try:
        url = f"https://api.frankfurter.dev/v2/rate/USD/EGP?date={date_str}"
        req = urllib.request.Request(url, headers={
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json",
            "Cache-Control": "no-cache",
        })
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="replace"))
        rate = data.get("rate")
        if rate:
            return float(rate), "Frankfurter"
        raise RuntimeError("No rate in response")
    except Exception as e:
        errors.append(f"Frankfurter: {e}")

    # ── Fallback: frankfurter.app (v1) ────────────────────────────
    try:
        url2 = f"https://api.frankfurter.app/{date_str}?from=USD&to=EGP"
        req2 = urllib.request.Request(url2, headers={
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json",
        })
        with urllib.request.urlopen(req2, timeout=timeout) as resp2:
            data2 = json.loads(resp2.read().decode("utf-8", errors="replace"))
        rate2 = (data2.get("rates") or {}).get("EGP")
        if rate2:
            return float(rate2), "Frankfurter-v1"
        raise RuntimeError("No EGP rate in response")
    except Exception as e:
        errors.append(f"Frankfurter-v1: {e}")

    # ── Fallback: Yahoo Finance USDEGP=X historical ───────────────
    try:
        import time as _time
        import datetime as _dt
        d = _dt.date.fromisoformat(date_str)
        ts_start = int(_time.mktime(d.timetuple()))
        ts_end   = ts_start + 86400
        url3 = (f"https://query1.finance.yahoo.com/v8/finance/chart/USDEGP=X"
                f"?interval=1d&period1={ts_start}&period2={ts_end}")
        req3 = urllib.request.Request(url3, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
            "Accept": "application/json",
        })
        with urllib.request.urlopen(req3, timeout=timeout) as resp3:
            data3 = json.loads(resp3.read().decode("utf-8", errors="replace"))
        closes = (data3.get("chart", {}).get("result", [{}])[0]
                  .get("indicators", {}).get("quote", [{}])[0]
                  .get("close", []))
        closes = [c for c in closes if c is not None]
        if closes:
            return float(closes[0]), "Yahoo-Finance"
        raise RuntimeError("No close price in Yahoo response")
    except Exception as e:
        errors.append(f"Yahoo: {e}")

    raise RuntimeError(f"All FX sources failed for {date_str}: {'; '.join(errors)}")


def fetch_fx_history_backfill(existing_dates, start_date_str="2025-12-01",
                               timeout=10):
    """Return a list of {date, rate, source} for every weekday from
    start_date_str to yesterday that is missing from existing_dates.
    Fetches one date at a time. Weekends / holidays return no data —
    silently skipped. Returns list of successfully fetched entries."""
    import datetime as _dt
    results = []
    today    = _dt.date.today()
    start    = _dt.date.fromisoformat(start_date_str)
    end      = today - _dt.timedelta(days=1)   # up to yesterday
    current  = start
    while current <= end:
        date_str = current.isoformat()
        if date_str not in existing_dates:
            # Only weekdays (banks are closed Sat/Sun)
            if current.weekday() < 5:
                try:
                    rate, source = fetch_fx_rate_for_date(date_str, timeout=timeout)
                    results.append({
                        "date":   date_str,
                        "rate":   rate,
                        "source": source,
                    })
                except Exception:
                    pass   # silently skip — holiday or API unavailable
        current += _dt.timedelta(days=1)
    return results


