def get_cbot_seed_entries():
    """Return all hardcoded seed entries as a flat list."""
    entries = []
    for comm, dates in _CBOT_SEED.items():
        for date_str, price in sorted(dates.items()):
            entries.append({
                "date":      date_str,
                "price":     price,
                "commodity": comm,
                "source":    "seed-historical",
            })
    return entries

def fetch_cbot_daily_history(commodity, start_date_str="2025-12-01", timeout=20):
    """Fetch full daily close history for a CBOT commodity from Yahoo Finance.
    Returns list of {date, price, commodity, source}."""
    import datetime as _dt
    import calendar as _cal
    symbol = CBOT_YAHOO_SYMBOLS.get(commodity.upper())
    if not symbol:
        raise RuntimeError(f"No Yahoo symbol for {commodity}")

    # Use UTC midnight to avoid timezone-shift issues
    start  = _dt.date.fromisoformat(start_date_str)
    today  = _dt.date.today()
    ts_start = _cal.timegm(start.timetuple())
    ts_end   = _cal.timegm(today.timetuple()) + 86400

    # Try period1/period2 first (specific range), fall back to max range
    errors = []
    for attempt, url in enumerate([
        (f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}"
         f"?interval=1d&period1={ts_start}&period2={ts_end}"),
        (f"https://query2.finance.yahoo.com/v8/finance/chart/{symbol}"
         f"?interval=1d&period1={ts_start}&period2={ts_end}"),
        (f"https://query1.finance.yahoo.com/v8/finance/chart/{symbol}"
         f"?interval=1d&range=2y"),
    ]):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
                "Accept":     "application/json",
                "Accept-Language": "en-US,en;q=0.9",
            })
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                data = json.loads(resp.read().decode("utf-8", errors="replace"))

            if data.get("chart",{}).get("error"):
                raise RuntimeError(str(data["chart"]["error"]))

            result = (data.get("chart",{}).get("result") or [None])[0]
            if not result:
                raise RuntimeError("No result block")

            timestamps = result.get("timestamp") or []
            closes     = ((result.get("indicators",{})
                           .get("quote",[{}]) or [{}])[0]
                          .get("close") or [])

            if not timestamps:
                raise RuntimeError("Empty timestamps")

            entries = []
            for ts, cl in zip(timestamps, closes):
                if cl is None:
                    continue
                try:
                    # Use UTC for date conversion
                    d_str = _dt.datetime.utcfromtimestamp(ts).strftime("%Y-%m-%d")
                    # Only include dates from start_date onwards
                    if d_str >= start_date_str:
                        entries.append({
                            "date":      d_str,
                            "price":     round(float(cl), 4),
                            "commodity": commodity.upper(),
                            "source":    "Yahoo-Finance",
                        })
                except Exception as _e_1296:
                    log_exception(_e_1296, "fetch_cbot_daily_history")

            if entries:
                return entries
            raise RuntimeError(f"No valid entries parsed (got {len(timestamps)} timestamps)")

        except Exception as e:
            errors.append(f"attempt {attempt+1}: {e}")
            continue

    raise RuntimeError(f"All attempts failed for {symbol}: {'; '.join(errors)}")


