def _migrate_freight_rates_2026_03_10(state):
    """One-time correction of the freight table.

    Earlier builds seeded freight lanes that did not match the source sheet
    (e.g. CORN | الدخيلة | النوبارية was stored as 252.37, which is actually
    the صويا | برج العرب rate; the correct corn rate is 301.74). Freight feeds
    landed cost, so a wrong lane quietly biases every own-after figure that
    used it. This removes only the untouched bad rows; the corrected sheet is
    then re-seeded by the normal loader.
    """
    try:
        if (state.get("meta", {}) or {}).get("freight_seed_version") == "2026-03-10":
            return 0
        fr = state.get("freight_rates", {}) or {}
        removed = 0
        for comm, port, dest, bad_new in _FREIGHT_BAD_SEED_V95:
            key = f"{comm}|{port}|{dest}"
            rec = fr.get(key)
            if not isinstance(rec, dict):
                continue
            cur = to_float(rec.get("rate"), None)
            if cur is not None and abs(cur - bad_new) < 0.01:
                del fr[key]
                removed += 1
        state.setdefault("meta", {})["freight_seed_version"] = "2026-03-10"
        if removed:
            record_data_issue(
                state, "freight_migration",
                f"Removed {removed} misattributed freight lane(s) seeded by an "
                f"earlier version; reloaded from the 10-3-2026 sheet. Re-check "
                f"contracts whose freight was auto-filled before this update.",
                severity="WARN")
        return removed
    except Exception as e:
        log_exception(e, "_migrate_freight_rates_2026_03_10")
        return 0


def ensure_state_schema(state):
    """Backwards-compatible state migration for V8.1 guardrails."""
    if not isinstance(state, dict):
        return default_state()
    state.setdefault("origins", list(DEFAULT_ORIGINS))
    # Keep defaults but preserve any user-added controlled origin labels.
    normalized_origins = []
    for item in list(state.get("origins") or []) + list(DEFAULT_ORIGINS):
        n = normalize_origin(item)
        if n and n not in normalized_origins:
            normalized_origins.append(n)
    state["origins"] = normalized_origins

    state.setdefault("data_policy", dict(DATA_SOURCE_POLICY))
    state.setdefault("audit_log", [])
    # ── CIF/Own-After separation (V9.8) ─────────────────────────────────
    # Every save used to mirror cif_usd_mt into own_after_usd_mt, making the
    # two fields interchangeable. Where they are still byte-equal the copy
    # carries no information — remove it so each field means one thing.
    if not (state.get("meta", {}) or {}).get("cif_ownafter_migrated"):
        _stripped = 0
        for _c in (state.get("contracts", {}) or {}).values():
            if not isinstance(_c, dict):
                continue
            _cf = to_float(_c.get("cif_usd_mt"), None)
            _oa = to_float(_c.get("own_after_usd_mt"), None)
            if _cf is not None and _oa is not None and abs(_cf - _oa) < 1e-9:
                _c.pop("own_after_usd_mt", None)
                _stripped += 1
        state.setdefault("meta", {})["cif_ownafter_migrated"] = True
        if _stripped:
            record_data_issue(state, "cif_ownafter_migration",
                              f"Removed {_stripped} mirrored own_after_usd_mt "
                              f"value(s) that merely duplicated CIF. CIF and "
                              f"Own-After are now separate figures.",
                              severity="INFO")

    state.setdefault("data_issues", [])
    if not isinstance(state.get("open_mtm_daily"), list):
        state["open_mtm_daily"] = []
    else:
        state.setdefault("open_mtm_daily", [])
    md = state.setdefault("market_data", {})
    md.setdefault("data_quality", {})
    md.setdefault("cbot_quote_details", {})
    md.setdefault("market_movement", {})
    md.setdefault("futures_curves", {})
    md.setdefault("feed_policy", PUBLIC_MARKET_FEED_POLICY)
    state.setdefault("meta", {})["version"] = APP_BUILD

    # Normalize existing contract origins once on load/save so filters remain reliable.
    for cid, c in (state.get("contracts", {}) or {}).items():
        if isinstance(c, dict):
            old = c.get("origin", "")
            new = normalize_origin(old)
            if new and old != new:
                c["origin_original"] = old
                c["origin"] = new
                append_audit_event(state, "normalize_origin", "contract", cid, {"from": old, "to": new})

    # Add lightweight provenance to existing manual records without overwriting user data.
    for rec in state.get("local_prices", []) or []:
        if isinstance(rec, dict) and "provenance" not in rec:
            rec["provenance"] = make_provenance(
                source=rec.get("source", "manual"),
                as_of=rec.get("date") or now_ts(),
                confidence="manual",
                note="Backfilled provenance by V8.1 migration",
            )
    return state


def get_commodity_freight_egp_mt(state, commodity):
    """Correct per-commodity local freight, resolved in priority order:
      1. user override in state['commodity_freight_defaults']
      2. seeded DEFAULT_COMMODITY_FREIGHT_EGP_MT
      3. flat get_default_local_transport_egp_mt() as last resort.
    Commodity suffixes like '-BRZ'/'-UKR' are stripped to the base.
    """
    comm = (commodity or "").strip().upper()
    base = comm.split("-")[0] if "-" in comm else comm
    try:
        if isinstance(state, dict):
            overrides = state.get("commodity_freight_defaults") or {}
            for k in (comm, base):
                v = to_float(overrides.get(k), None)
                if v is not None and v > 0:
                    return float(v)
    except Exception as _e_1417:
        log_exception(_e_1417, "get_commodity_freight_egp_mt")
    for k in (comm, base):
        v = DEFAULT_COMMODITY_FREIGHT_EGP_MT.get(k)
        if v is not None:
            return float(v)
    return get_default_local_transport_egp_mt(state)


def get_default_local_transport_egp_mt(state=None):
    """Default local transportation fee used for local prices/purchases."""
    default_rate = DEFAULT_LOCAL_TRANSPORT_EGP_MT
    try:
        if isinstance(state, dict):
            ui = state.setdefault("ui", {})
            val = to_float(ui.get("local_transport_default_egp_mt"), None)
            if val is None:
                ui["local_transport_default_egp_mt"] = default_rate
                return default_rate
            return float(val)
    except Exception:
        pass
    return default_rate


def apply_default_local_transport_to_stored_data(state):
    """One-time migration: put 323.13 EGP/MT transport on stored local data.

    This covers both daily local prices and local purchase rows so all local-fee
    calculations become all-in (base price + transport) consistently.
    """
    if not isinstance(state, dict):
        return False
    meta = state.setdefault("meta", {})
    ui = state.setdefault("ui", {})
    rate = get_default_local_transport_egp_mt(state)
    ui["local_transport_default_egp_mt"] = rate

    # Apply only once automatically. If a user later edits a transport value, the
    # app will not overwrite it on every launch.
    if meta.get(LOCAL_TRANSPORT_MIGRATION_KEY):
        return False

    changed = False
    for list_name in ("local_prices", "local_purchases"):
        rows = state.setdefault(list_name, [])
        if not isinstance(rows, list):
            continue
        for rec in rows:
            if not isinstance(rec, dict):
                continue
            # User asked to add 323.13 to all stored local data, so the first
            # run standardizes every stored local transport value to this rate.
            if rec.get("transport_egp_mt") != rate:
                rec["transport_egp_mt"] = rate
                changed = True
    meta[LOCAL_TRANSPORT_MIGRATION_KEY] = True
    return changed

def _normalize_sbm_contract_reference(value):
    """Return a stable SCN reference for matching CPC spreadsheet rows.

    Examples accepted: ``SCN 7314``, ``SCN-7314``, and
    ``NVO / SCN 7314 / SBM``. Non-SCN values are normalized conservatively.
    """
    raw = (str(value) if value is not None else "").strip().upper()
    if not raw:
        return ""
    match = re.search(r"\bSCN\s*[-_/]?\s*(\d{3,8})\b", raw)
    if match:
        return f"SCN{match.group(1)}"
    return re.sub(r"[^A-Z0-9]+", "", raw)


def apply_sbm_contract_delivery_storage_dates(state):
    """Apply CPC's spreadsheet Delivery date to matching SBM contracts once.

    Only ``delivery_date`` and ``storage_start`` are replaced. ``storage_end``
    is deliberately preserved because the user requested the single Delivery
    column as the source for Delivery Date and Storage Date (start).

    Matching is by Contract No. embedded in the contract name/reference and is
    restricted to base commodity SBM. Each updated contract receives a private
    migration marker so later manual edits are never overwritten on startup.
    """
    report = {
        "source_rows": len(SBM_CONTRACT_DELIVERY_DATES),
        "matched": 0,
        "updated": 0,
        "already_processed": 0,
        "unmatched_source_contracts": [],
    }
    if not isinstance(state, dict):
        return report
    contracts = state.get("contracts") or {}
    if not isinstance(contracts, dict):
        return report

    source_by_key = {
        _normalize_sbm_contract_reference(ref): (ref, target)
        for ref, target in SBM_CONTRACT_DELIVERY_DATES.items()
    }
    matched_refs = set()

    for cid, contract in contracts.items():
        if not isinstance(contract, dict):
            continue
        commodity = (contract.get("commodity") or "").strip().upper()
        if commodity.split("-")[0] != "SBM":
            continue

        source_item = None
        for candidate in (
            contract.get("name"), contract.get("contract_no"),
            contract.get("reference"), contract.get("ref"),
        ):
            key = _normalize_sbm_contract_reference(candidate)
            if key and key in source_by_key:
                source_item = source_by_key[key]
                break
        if source_item is None:
            continue

        source_ref, target_date = source_item
        matched_refs.add(source_ref)
        report["matched"] += 1

        # Marker means the spreadsheet instruction has already been applied.
        # Do not re-apply after a user later edits the dates manually.
        if contract.get(SBM_DATE_UPDATE_FIELD) == target_date:
            report["already_processed"] += 1
            continue

        old_delivery = contract.get("delivery_date", "")
        old_storage_start = contract.get("storage_start", "")
        contract["delivery_date"] = target_date
        contract["storage_start"] = target_date
        contract[SBM_DATE_UPDATE_FIELD] = target_date
        contract["updated_ts"] = now_ts()
        append_audit_event(state, "sbm_delivery_storage_date_sync", "contract", cid, {
            "contract_no": source_ref,
            "source": SBM_DATE_UPDATE_SOURCE,
            "source_sha256": SBM_DATE_UPDATE_SOURCE_SHA256,
            "delivery_date_from": old_delivery,
            "delivery_date_to": target_date,
            "storage_start_from": old_storage_start,
            "storage_start_to": target_date,
            "storage_end_preserved": contract.get("storage_end", ""),
        })
        report["updated"] += 1

    report["unmatched_source_contracts"] = [
        ref for ref in SBM_CONTRACT_DELIVERY_DATES if ref not in matched_refs
    ]
    if report["updated"]:
        meta = state.setdefault("meta", {})
        meta["sbm_delivery_storage_date_sync_v1087"] = {
            "source": SBM_DATE_UPDATE_SOURCE,
            "source_sha256": SBM_DATE_UPDATE_SOURCE_SHA256,
            "updated_ts": now_ts(),
            "updated_contracts": report["updated"],
            "matched_contracts": report["matched"],
            "source_rows": report["source_rows"],
        }
        record_data_issue(
            state,
            "sbm_delivery_storage_date_sync",
            f"Updated {report['updated']} SBM contract(s): Delivery Date and "
            "Storage Start now follow SBM Purchases.xlsx; Storage End was preserved.",
            severity="INFO",
        )
    return report


def load_state():
    # Ensure app data dir exists (important for EXE runs)
    try:
        os.makedirs(get_app_data_dir(), exist_ok=True)
    except Exception:
        pass
    if os.path.exists(state_file_path()):
        try:
            with open(state_file_path(), "r", encoding="utf-8") as f:
                s = json.load(f)
            d = default_state()

            # Top-level merge
            for k, v in d.items():
                if k not in s:
                    s[k] = v
            if "ui" not in s:
                s["ui"] = d["ui"]
            if "meta" not in s:
                s["meta"] = d["meta"]

            # Deep-merge default commodity fields (backward compatible upgrades)
            if "commodities" not in s or not isinstance(s["commodities"], dict):
                s["commodities"] = {}
            for cname, cdef in d.get("commodities", {}).items():
                if cname not in s["commodities"] or not isinstance(s["commodities"].get(cname), dict):
                    s["commodities"][cname] = dict(cdef)
                else:
                    for ck, cv in cdef.items():
                        if ck not in s["commodities"][cname]:
                            s["commodities"][cname][ck] = cv

            # ── Conversion-factor migration (V8.5.1) ──────────────────
            # Stamp the correct locked_factor on EVERY CBOT grain commodity
            # (including origin variants like CORN-ARG/BRZ/USA), and align the
            # legacy conversion_value so the Commodities table stops showing a
            # mix of 0.3937 and 39.368. locked_factor is what actually drives
            # the math; conversion_value is kept consistent for display only.
            _FACTOR_BY_BASE = {
                "CORN": CORN_FACTOR, "SOYBEAN": SOYBEAN_FACTOR,
                "WHEAT": WHEAT_FACTOR, "SBM": SBM_ST_PER_MT,
            }
            for _cname, _cmeta in (s.get("commodities") or {}).items():
                if not isinstance(_cmeta, dict):
                    continue
                _base = _cname.upper().split("-")[0]
                _f = _FACTOR_BY_BASE.get(_base)
                if _f is None:
                    continue
                # Only CBOT-typed commodities get the CBOT conversion. Origin
                # variants explicitly typed NONCBOT (priced in EGP) are left.
                if (_cmeta.get("type") or "").upper() == "CBOT":
                    _cmeta["locked_factor"] = _f
                    _cmeta.setdefault("premium_mode", "CBOT_UNIT")
                    if _base == "SBM":
                        _cmeta["conversion_type"] = "st_per_mt"
                        _cmeta["conversion_value"] = SBM_ST_PER_MT
                    else:
                        # cents/bu path: display value = factor × 100 (bu/MT)
                        _cmeta["conversion_type"] = "bu_per_mt"
                        _cmeta["conversion_value"] = round(_f * 100.0, 4)

            # ── Date-format migration (V8.6.1) ────────────────────────
            # Legacy rows contain DD-MM-YYYY dates (e.g. '28-06-2026') that
            # crash strict ISO parsing in savings/performance. Normalize
            # every stored date field to ISO once, and report how many.
            _fixed_dates = 0
            _date_fields_contract = ("delivery_date", "form4_date",
                                     "storage_start", "storage_end", "date")
            for _c in (s.get("contracts") or {}).values():
                if not isinstance(_c, dict):
                    continue
                for _fld in _date_fields_contract:
                    _v = _c.get(_fld)
                    if _v:
                        _iso = iso_date_or_keep(_v)
                        if _iso != _v:
                            _c[_fld] = _iso
                            _fixed_dates += 1
            for _lname in ("local_prices", "local_purchases", "consumption_log"):
                for _r in (s.get(_lname) or []):
                    if isinstance(_r, dict) and _r.get("date"):
                        _iso = iso_date_or_keep(_r["date"])
                        if _iso != _r["date"]:
                            _r["date"] = _iso
                            _fixed_dates += 1
            if _fixed_dates:
                record_data_issue(s, "date_migration",
                                  f"Normalized {_fixed_dates} legacy non-ISO date(s) "
                                  f"(e.g. DD-MM-YYYY) to YYYY-MM-DD", severity="INFO")

            _sbm_date_report = apply_sbm_contract_delivery_storage_dates(s)
            _state = ensure_state_schema(s)
            if _sbm_date_report.get("updated"):
                # Persist immediately so the one-time migration survives even if
                # the user closes the app without editing another record.
                save_state(_state)
            return _state
        except Exception as e:
            messagebox.showwarning(APP_NAME, f"Could not load state file. Starting fresh.\n\n{e}")
    return ensure_state_schema(default_state())

def save_state(state):
    try:
        # Ensure app data dir exists (important for EXE runs)
        os.makedirs(get_app_data_dir(), exist_ok=True)
        # Rolling backup before overwrite
        backup_state_file()
        state = ensure_state_schema(state)
        state["meta"]["saved_ts"]=now_ts()
        # Atomic write: dump to a temp file in the SAME directory, then
        # os.replace() — a crash mid-write can no longer leave a truncated
        # or half-written state file behind.
        final = state_file_path()
        tmp = final + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, final)
    except Exception as e:
        messagebox.showerror(APP_NAME, f"Could not save state:\n{e}")


def open_folder(path):
    try:
        if os.name == "nt":
            os.startfile(path)  # type: ignore
        else:
            import subprocess as _sp
            _sp.Popen(["xdg-open", path])
    except Exception as e:
        messagebox.showerror(APP_NAME, f"Could not open folder:\n{e}")

def backup_state_file():
    """Keep rolling backups of the state file (last 7)."""
    try:
        if not os.path.exists(state_file_path()):
            return
        bdir = get_backup_dir()
        ts = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        dst = os.path.join(bdir, f"app_state_{ts}.json")
        import shutil as _sh
        _sh.copy2(state_file_path(), dst)
        files = sorted([os.path.join(bdir,f) for f in os.listdir(bdir) if f.lower().endswith(".json")])
        if len(files) > 7:
            for f in files[:-7]:
                try: os.remove(f)
                except Exception: pass
    except Exception:
        pass

def new_contract_id(state):
    n = len(state["contracts"]) + 1
    while True:
        cid = f"C{n:04d}"
        if cid not in state["contracts"]:
            return cid
        n += 1

def new_snapshot_id(state):
    """Unique snapshot id from a persistent counter.

    The old formula (count+1) produced DUPLICATE ids after any deletion:
    delete S000003 from five snapshots and the next one is S000005 — twice.
    The counter is seeded from the highest existing numeric id so legacy
    files continue without collision."""
    meta = state.setdefault("meta", {})
    seq = meta.get("snapshot_seq")
    if not isinstance(seq, int):
        seq = 0
        for s in state.get("snapshots", []) or []:
            sid = str(s.get("snapshot_id") or s.get("id") or "")
            if sid.startswith("S") and sid[1:].isdigit():
                seq = max(seq, int(sid[1:]))
    seq += 1
    meta["snapshot_seq"] = seq
    return f"S{seq:06d}"

def contract_label(state, cid):
    if cid == "ALL":
        return "ALL - (All Contracts)"
    c = state["contracts"].get(cid, {})
    name = c.get("name","")
    return f"{cid} - {name}" if name else cid

