    def _build_local_purchases(self):
        p = self.tab_local_purchases
        p.columnconfigure(0, weight=1)
        p.rowconfigure(4, weight=1)

        ttk.Label(p, text="🛒  Local Market Purchases — Register, Track & Compare vs Import",
                  font=("Segoe UI", 12, "bold")).grid(
                      row=0, column=0, sticky="w", pady=(0, 4))

        # ── Filter bar ────────────────────────────────────────────────
        lff = ttk.Frame(p)
        lff.grid(row=1, column=0, sticky="ew", pady=(0, 6))
        ttk.Label(lff, text="Commodity:").pack(side="left", padx=(0, 6))
        self.lp_filter_comm_var = tk.StringVar(value="All")
        self.lp_filter_comm_combo = ttk.Combobox(
            lff, textvariable=self.lp_filter_comm_var,
            values=["All","CORN","CORN-BRZ","CORN-UKR","CORN-ARG",
                    "SBM","SFM","DDGS","SOYBEAN"],
            width=12, state="readonly")
        self.lp_filter_comm_combo.pack(side="left", padx=(0,12))
        self.lp_filter_comm_combo.bind(
            "<<ComboboxSelected>>", lambda e: self.refresh_local_purchases())
        ttk.Label(lff, text="Supplier:").pack(side="left", padx=(0,6))
        self.lp_filter_sup_var = tk.StringVar(value="All")
        self.lp_filter_sup_combo = ttk.Combobox(
            lff, textvariable=self.lp_filter_sup_var,
            values=["All"], width=16, state="readonly")
        self.lp_filter_sup_combo.pack(side="left", padx=(0,12))
        self.lp_filter_sup_combo.bind(
            "<<ComboboxSelected>>", lambda e: self.refresh_local_purchases())
