        card_fields = [
            ("count",  "Days stored"),
            ("first",  "First date"),
            ("last",   "Latest date"),
            ("gaps",   "Missing weekdays"),
            ("seed",   "Seed entries"),
            ("live",   "Live-fetched"),
        ]
        for ci, comm in enumerate(["CORN","SOYBEAN","SBM"]):
            cbot_cov.columnconfigure(ci, weight=1)
            color = comm_colors.get(comm,"#444")
            card = tk.Frame(cbot_cov, bg="#ffffff",
                            highlightthickness=1,
                            highlightbackground="#d0dcea")
            card.grid(row=0, column=ci, sticky="nsew", padx=(0,8), pady=2)
            tk.Label(card, text=comm,
                     font=("Segoe UI", 10, "bold"),
                     bg="#ffffff", fg=color).pack(anchor="w", padx=8, pady=(6,2))
            tk.Frame(card, bg=color, height=2).pack(fill="x", padx=8)
            self._cbot_cov_vars[comm] = {}
            for key, label in card_fields:
                row_f = tk.Frame(card, bg="#ffffff")
                row_f.pack(fill="x", padx=8, pady=1)
                tk.Label(row_f, text=f"{label}:",
                         font=("Segoe UI", 9), bg="#ffffff",
                         fg="#666", width=16, anchor="w").pack(side="left")
                var = tk.StringVar(value="—")
                fg = "#c0392b" if key == "gaps" else "#1a2d40"
                tk.Label(row_f, textvariable=var,
                         font=("Segoe UI", 9, "bold"),
                         bg="#ffffff", fg=fg).pack(side="left")
                self._cbot_cov_vars[comm][key] = var
            tk.Frame(card, height=4, bg="#ffffff").pack()

        cf2 = ttk.Frame(p)
        cf2.grid(row=6, column=0, sticky="nsew")
        cf2.columnconfigure(0, weight=1)
        cf2.rowconfigure(0, weight=1)

        cbot_cols = [("Date",110,"center"),("Commodity",100,"center"),
                     ("Close (¢/bu)",120,"e"),("Source",180,"w"),
                     ("Days Ago",90,"center")]
        self._cbot_hist_tree = ttk.Treeview(
            cf2, columns=[c[0] for c in cbot_cols],
            show="headings", selectmode="browse", height=8)
        for col, w, anc in cbot_cols:
            self._cbot_hist_tree.heading(col, text=col)
