        self._cbot_hist_tree.tag_configure("SBM",     foreground="#1a6ebd")
        self._cbot_hist_tree.tag_configure("SOYBEAN", foreground="#1a7a1a")
        self._cbot_hist_tree.tag_configure("seed",    foreground="#888888")

        cb2 = ttk.Frame(p)
        cb2.grid(row=7, column=0, sticky="ew", pady=(4,0))
