    def _run_supplier_scorecard(self):
        contracts = self.state_obj.get("contracts", {}) or {}
        f_comm = self._sup_comm_var.get()

        tv = self._sup_tree
        tv.delete(*tv.get_children())

        closed_count = sum(1 for c in contracts.values()
                           if (c.get("status") or "Open") == "Closed")
        if closed_count == 0:
            self._sup_notes_var.set(
                "📭 No closed contracts yet. The Supplier Scorecard ranks "
                "suppliers using realized (closed) contracts only — once "
                "contracts are marked Closed with delivery data, they'll "
                "appear here.")
            return

        from collections import defaultdict
        sup_data = defaultdict(lambda: {
            "contracts":0, "qty":0, "cbot_edges":[], "premiums":[],
            "vs_local":[], "total_sav":0, "wins":0, "n_local":0,
            "best_contract":None, "best_sav":-1e18,
        })

        for cid, c in contracts.items():
            if (c.get("status") or "Open") != "Closed":
                continue
            comm = (c.get("commodity") or "").upper()
            base = comm.split("-")[0] if "-" in comm else comm
            if f_comm != "All" and base != f_comm and comm != f_comm:
                continue

            sup = c.get("supplier","Unknown")
            r = self._an_analyse_contract(cid, c, 90, 14, None)

            sd = sup_data[sup]
            sd["contracts"] += 1
            sd["qty"]       += r.get("qty") or 0
            if r.get("cbot_edge") is not None:
                sd["cbot_edges"].append(r["cbot_edge"])
            if r.get("premium") is not None:
                sd["premiums"].append(r["premium"])
            if r.get("local_edge") is not None:
                sd["vs_local"].append(r["local_edge"])
                sd["n_local"] += 1
                if r["local_edge"] > 0:
                    sd["wins"] += 1
                tot = r["local_edge"] * (r.get("qty") or 0)
                sd["total_sav"] += tot
                if tot > sd["best_sav"]:
                    sd["best_sav"] = tot
                    sd["best_contract"] = r.get("name")

        rows = []
        for sup, sd in sup_data.items():
            avg_edge   = sum(sd["cbot_edges"])/len(sd["cbot_edges"]) if sd["cbot_edges"] else None
            avg_prem   = sum(sd["premiums"])/len(sd["premiums"]) if sd["premiums"] else None
            avg_local  = sum(sd["vs_local"])/len(sd["vs_local"]) if sd["vs_local"] else None
            win_rate   = sd["wins"]/sd["n_local"]*100 if sd["n_local"] else None
            rows.append((sup, sd["contracts"], sd["qty"], avg_edge, avg_prem,
                         avg_local, sd["total_sav"], win_rate,
                         sd["best_contract"]))

        # Rank by avg CBOT edge (the unbiased metric)
        rows.sort(key=lambda x: (x[3] if x[3] is not None else -999), reverse=True)

        for rank, (sup, n, qty, edge, prem, avg_local, tot_sav, win_rate, best) in enumerate(rows, 1):
            if   rank == 1:                grade, tag = "A+", "A"
            elif edge and edge > 0:        grade, tag = "A",  "A"
            elif edge and edge > -10:      grade, tag = "B",  "B"
            elif edge and edge > -30:      grade, tag = "C",  "C"
            else:                          grade, tag = "D",  "D"

            tv.insert("", "end", tags=(tag,), values=(
                rank, sup, n, fmt_num(qty,0),
                f"{edge:+.2f}" if edge is not None else "—",
                f"{prem:.2f}" if prem is not None else "—",
                f"{avg_local:+,.0f}" if avg_local is not None else "—",
                f"{tot_sav:+,.0f}" if tot_sav else "—",
                f"{win_rate:.0f}%" if win_rate is not None else "—",
                best or "—", grade))

        if rows:
            best_sup = rows[0][0]
            self._sup_notes_var.set(
                f"🏆 Best supplier by CBOT timing: {best_sup}  "
                f"(avg edge {rows[0][3]:+.2f}¢/bu — consistently prices below market)  |  "
                f"Ranked by avg CBOT edge, not total volume, to remove the bias "
                f"toward suppliers you simply bought more from.")
        else:
            self._sup_notes_var.set(
                f"📭 No closed {f_comm} contracts found "
                f"({closed_count} closed contracts exist for other commodities). "
                f"Try 'All' or a different commodity filter.")

    def _export_supplier_scorecard(self):
        if not _need_openpyxl():
            return
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
            from openpyxl.utils import get_column_letter

            fp = filedialog.asksaveasfilename(
                initialdir=get_default_export_dir(),
                initialfile=f"Supplier_Scorecard_{now_ts()[:10]}.xlsx",
                defaultextension=".xlsx", filetypes=[("Excel","*.xlsx")],
                title="Export Supplier Scorecard")
            if not fp: return

            wb = Workbook()
            ws = wb.active
            ws.title = "Supplier Scorecard"

            thin = Side(style="thin", color="CCCCCC")
            brd  = Border(left=thin,right=thin,top=thin,bottom=thin)
            hdr_bg = PatternFill("solid", fgColor="1A2D40")
            grn = PatternFill("solid", fgColor="E6F4EA")
            red = PatternFill("solid", fgColor="FDECEA")
            amb = PatternFill("solid", fgColor="FFF8E1")
            hf  = Font(name="Calibri", bold=True, color="FFFFFF", size=10)
            df_ = Font(name="Calibri", size=10)

            cols = [c[0] for c in [
                ("Rank",8),("Supplier",22),("Contracts",10),("Total MT",12),
                ("Avg CBOT Edge ¢",14),("Avg Premium ¢",13),
                ("Avg vs Local EGP/MT",16),("Total Saving EGP",16),
                ("Win Rate",10),("Best Contract",18),("Grade",8)]]
            for ci,(h,w) in enumerate([
                ("Rank",8),("Supplier",22),("Contracts",10),("Total MT",12),
                ("Avg CBOT Edge ¢",14),("Avg Premium ¢",13),
                ("Avg vs Local EGP/MT",16),("Total Saving EGP",16),
                ("Win Rate",10),("Best Contract",18),("Grade",8)],1):
                c = ws.cell(row=1, column=ci, value=h)
                c.font, c.fill, c.border = hf, hdr_bg, brd
                c.alignment = Alignment(horizontal="center")
                ws.column_dimensions[get_column_letter(ci)].width = w

            for ri, iid in enumerate(self._sup_tree.get_children(), 2):
                vals = self._sup_tree.item(iid, "values")
                tag  = self._sup_tree.item(iid, "tags")
                bg = grn if tag and tag[0] in ("A","B") else (
                     amb if tag and tag[0]=="C" else red if tag else None)
                for ci, v in enumerate(vals, 1):
                    c = ws.cell(row=ri, column=ci, value=v)
                    c.font, c.border = df_, brd
                    if bg: c.fill = bg
            wb.save(fp)
            messagebox.showinfo(APP_NAME, f"Supplier scorecard exported.\n\n{fp}")
        except Exception as e:
            log_exception(e, "_export_supplier_scorecard")
            messagebox.showerror(APP_NAME, f"Export failed: {e}")

