        ttk.Button(fr_box, text="🔍 Lookup",
                   command=lambda: _lookup_freight()).grid(
                       row=0, column=9, padx=(4, 8))

        # Row 1: Quick-pick dropdown — shows all available rates for this commodity
        _fb_lbl(1, 0, "Quick-pick from table:")
        self._c_freight_pick_var = tk.StringVar(value="")
        self.c_freight_pick_combo = ttk.Combobox(
            fr_box, textvariable=self._c_freight_pick_var,
            values=[], width=55, state="readonly")
        self.c_freight_pick_combo.grid(
            row=1, column=1, columnspan=7, sticky="w", padx=(0, 8))

        def _apply_picked_rate(*_):
            """Parse selected quick-pick label and fill port/dest/rate fields."""
            sel = self._c_freight_pick_var.get()
            if not sel:
                return
            # format: "Port → Dest : RATE EGP/MT"
            try:
                parts = sel.split(":")
                rate_part = parts[-1].strip().replace("EGP/MT","").strip().replace(",","")
                route_part = parts[0].strip()   # "Port → Dest"
                if "→" in route_part:
                    port_s, dest_s = route_part.split("→", 1)
                    self.c_loading_port_var.set(port_s.strip())
                    self.c_destination_var.set(dest_s.strip())
                self.c_freight_var.set(rate_part)
                self._c_freight_lookup_var.set(
                    f"✓ Applied: {float(rate_part):,.2f} EGP/MT")
            except Exception as e:
                self._surface_error("Apply freight quick-pick failed", e)

        self.c_freight_pick_combo.bind(
            "<<ComboboxSelected>>", _apply_picked_rate)

        ttk.Button(fr_box, text="▶ Apply",
                   command=_apply_picked_rate).grid(
                       row=1, column=8, padx=(0, 4))

        def _lookup_freight(*_):
            """Auto-lookup by commodity+port+dest, and refresh quick-pick list."""
            comm  = self.c_commodity_var.get().strip().upper()
            port  = self.c_loading_port_var.get().strip()
            dest  = self.c_destination_var.get().strip()
            comm_key = comm.split("-")[0] if "-" in comm else comm

            # Refresh quick-pick list for this commodity
            fr = self.state_obj.get("freight_rates", {}) or {}
            picks = []
            for key, rec in sorted(fr.items()):
                rc = (rec.get("commodity") or "").upper()
                if rc == comm or rc == comm_key:
                    r  = rec.get("rate", 0)
                    p  = rec.get("port", "")
                    d  = rec.get("destination", "")
                    picks.append(
                        f"{p} → {d} : {r:,.2f} EGP/MT")
            self.c_freight_pick_combo["values"] = picks
            if self._c_freight_pick_var.get() not in picks:
                self._c_freight_pick_var.set(picks[0] if picks else "")

            # Auto-fill if port+dest already selected
            if comm and port and dest:
                for ck in [comm, comm_key]:
                    fkey = f"{ck}|{port}|{dest}"
                    rate_rec = fr.get(fkey)
                    if rate_rec:
                        rate = rate_rec.get("rate", 0)
                        eff  = rate_rec.get("effective","")
                        self.c_freight_var.set(str(round(rate, 2)))
                        self._c_freight_lookup_var.set(
                            f"✓ {rate:,.2f} EGP/MT  (eff. {eff})")
                        return
                self._c_freight_lookup_var.set(
                    "⚠ No rate for this port/dest — pick from table above")
            elif picks:
                self._c_freight_lookup_var.set(
                    f"{len(picks)} rate(s) available — pick from Quick-pick")
            else:
                self._c_freight_lookup_var.set(
                    "No rates found — add in Setup → Freight Rates")

        self.c_loading_port_combo.bind("<<ComboboxSelected>>", _lookup_freight)
        self.c_destination_combo.bind("<<ComboboxSelected>>", _lookup_freight)
        self.c_commodity_combo.bind("<<ComboboxSelected>>",
                                    lambda e: (_lookup_freight(),))

        # ── CBOT Premium Box (CORN contracts) ──────────────────────────
        prem_box = ttk.LabelFrame(pricing, text="📌 Premium Box  (CORN — cents/bu)", padding=5)
        # Place Premium below the Freight box. Keeping both on row=2 caused
