        def _pb_ent(r, c, var, w=11):
            e = ttk.Entry(prem_box, textvariable=var, width=w)
            e.grid(row=r, column=c, sticky="w", padx=(0, 12), pady=(0, 4))
            return e

        _pb_lbl(0, 0, "Premium (¢/bu)")
