        ttk.Button(btns, text="⧉ Duplicate", command=self.duplicate_contract).pack(side="left", padx=(0,8))
        # Entry ease: pressing Enter in any editor field saves (update if a
        # contract is loaded, add if the form is fresh) — hands stay on keys.
        def _editor_return(_e=None):
            try:
                if (self.c_id_var.get() or "").strip():
                    self.update_contract()
                else:
                    self.add_contract()
            except Exception as e:
                log_exception(e, "editor_return_save")
            return "break"
        def _bind_return(widget):
            for ch in widget.winfo_children():
                if isinstance(ch, (ttk.Entry, ttk.Combobox)):
                    ch.bind("<Return>", _editor_return, add="+")
                _bind_return(ch)
