    def on_future_inputs_change(self):
        comm = (self.fu_commodity_var.get().strip() or "").upper()
        sup = (self.fu_supplier_var.get().strip() or "")
        if not comm or not sup:
            return
        try:
            d = self.state_obj.get("suppliers", {}).get(sup, {}).get(comm, {}).get("direct_egp_mt")
            i = self.state_obj.get("suppliers", {}).get(sup, {}).get(comm, {}).get("indirect_egp_mt")
            if d is not None: self.fu_intake_d_var.set(str(d))
            if i is not None: self.fu_intake_i_var.set(str(i))
        except Exception:
            pass

    def _build_future_snapshot_dict(self):
        comm = (self.fu_commodity_var.get().strip() or "").upper()
        if not comm:
            raise ValueError("Commodity is required.")
        comm_meta = self.state_obj.get("commodities", {}).get(comm, {"type":"NONCBOT","conversion_type":"none","conversion_value":1.0})

        fx = to_float(self.fu_fx_var.get(), None)
        qty = to_float(self.fu_qty_var.get(), None)
        local = to_float(self.fu_local_var.get(), None)
        fin_days = to_float(self.fu_fin_days_var.get(), None)
        rate_in = to_float(self.fu_rate_var.get(), None)
        cbot = to_float(self.fu_cbot_var.get(), None)
        prem = to_float(self.fu_premium_var.get(), None)
        imp_usd = to_float(self.fu_impusd_var.get(), None)

        # Normalize interest input:
        # - If user enters 0.24 treat as 24%
        # - If user enters 24 treat as 24%
        rate_pct = None
        if rate_in is not None:
            rate_pct = rate_in * 100.0 if rate_in <= 1.5 else rate_in

        intake_d = to_float(self.fu_intake_d_var.get(), 0.0)
        intake_i = to_float(self.fu_intake_i_var.get(), 0.0)
        sup = (self.fu_supplier_var.get().strip() or "")

        ctype = (comm_meta.get("type","NONCBOT") or "NONCBOT").upper()
        conv_val = to_float(comm_meta.get("conversion_value", 1.0), 1.0)

        # If commodity is CBOT-based, compute Import USD/MT using the same conversion
        # logic as the main Single Deal calculator.
        if ctype == "CBOT" and imp_usd is None:
            if cbot is None or prem is None:
                raise ValueError("For CBOT commodities, enter CBOT and Premium (or enter Import USD/MT).")
            imp_usd = cbot_to_usd_mt(comm_meta, cbot, prem)

        # If non-CBOT and user didn't provide import USD/MT, keep as None (compute_decision may handle),
        # but we prefer to require it to avoid accidental zeros.
        if ctype != "CBOT" and imp_usd is None:
            # allow blank only if CBOT formula is used; otherwise require
            raise ValueError("For non-CBOT commodities, enter Import USD/MT (Non-CBOT).")

        snap = {
            "id": int(dt.datetime.now().timestamp()*1000),
            "ts": dt.datetime.now().isoformat(timespec="seconds"),
            "contract_id": None,
            "contract_name": self.fu_note_var.get().strip() or f"Future {comm}",
            "commodity": comm,
            "supplier": sup,
            "qty_mt": qty,
            "fx": fx,
            "local_egp_mt": local,
            "cbot_price": cbot,
            "premium": prem,
            "import_usd_mt": imp_usd,
            "finance_days": fin_days,
            "interest_rate": rate_pct,  # percent
            "supplier_direct_egp_mt": intake_d,
            "supplier_indirect_egp_mt": intake_i,
            "conversion_type": comm_meta.get("conversion_type","none"),
            "conversion_value": conv_val,
            "conversion_factor": cbot_conv_factor(comm, strict=True) if ctype == "CBOT" else (conv_val / 100.0 if comm_meta.get("conversion_type") == "bu_per_mt" else conv_val),
            "premium_mode": comm_meta.get("premium_mode", "CBOT_UNIT" if ctype == "CBOT" else "USD_MT"),
            "commodity_type": ctype,
        }
        return snap
    def calculate_future(self):
        try:
            snap = self._build_future_snapshot_dict()
            out = compute_decision(snap)
            snap.update(out)
            self.fu_last_snapshot = snap
            self.fu_out_text.delete("1.0", "end")
            lines = [
                f"Import USD/MT: {fmt_num(out.get('import_usd_mt'),2)}",
                f"Carry USD/MT: {fmt_num(out.get('carry_usd_mt'),2)}",
                f"Own After USD/MT: {fmt_num(out.get('own_after_usd_mt'),2)}",
                f"Own After EGP/MT: {fmt_num(out.get('own_after_egp_mt'),0)}",
                f"Direct Own After EGP/MT: {fmt_num(out.get('direct_own_after_egp_mt'),0)}",
                f"Indirect Own After EGP/MT: {fmt_num(out.get('indirect_own_after_egp_mt'),0)}",
                f"Direct Saving EGP/MT: {fmt_num(out.get('direct_saving_egp_mt'),0)}",
                f"Indirect Saving EGP/MT: {fmt_num(out.get('indirect_saving_egp_mt'),0)}",
                f"Break-even FX (Direct): {fmt_num(out.get('break_even_fx_direct'),2)}",
                f"Break-even FX (Indirect): {fmt_num(out.get('break_even_fx_indirect'),2)}",
            ]
            self.fu_out_text.insert("1.0", "\n".join(lines))
        except Exception as e:
            messagebox.showerror(APP_NAME, str(e))

    def create_future_snapshot(self):
        """
        Save a future snapshot into history WITHOUT creating a contract.
        (User asked: snapshot-only, no contract selection needed.)
        """
        try:
            snap = self._build_future_snapshot_dict()

            # Keep a friendly label inside the snapshot itself
            comm = snap.get("commodity") or ""
            name = (snap.get("contract_name") or "").strip() or f"Future {comm}"
            snap["contract_id"] = None
            snap["future_name"] = name
            snap["is_future"] = True

            out = compute_decision(snap)
            snap.update(out)

            self.fu_last_snapshot = snap
            self.state_obj.setdefault("snapshots", []).append(snap)
            # keep history alias for any other code paths
            self.state_obj["history"] = self.state_obj["snapshots"]
            save_state(self.state_obj)
            self.refresh_all()
            messagebox.showinfo(APP_NAME, "Future snapshot saved to History (no contract created).")
        except Exception as e:
            messagebox.showerror(APP_NAME, str(e))


