    def apply_default_transport_to_all_local_data(self):
        """Manual button: re-apply the 323.13 EGP/MT transport to all local rows."""
        try:
            rate = get_default_local_transport_egp_mt(self.state_obj)
            count = 0
            for list_name in ("local_prices", "local_purchases"):
                rows = self.state_obj.setdefault(list_name, [])
                if not isinstance(rows, list):
                    continue
                for rec in rows:
                    if isinstance(rec, dict):
                        rec["transport_egp_mt"] = rate
                        count += 1
            self.state_obj.setdefault("meta", {})[LOCAL_TRANSPORT_MIGRATION_KEY] = True
            save_state(self.state_obj)
            self.refresh_local_prices_tree()
            try:
                self.refresh_local_purchases()
            except Exception:
                pass
            try:
                self.refresh_savings_tracker()
            except Exception:
                pass
            messagebox.showinfo(APP_NAME, f"Applied EGP {rate:,.2f}/MT transportation to {count} stored local row(s).")
        except Exception as e:
            messagebox.showerror(APP_NAME, str(e))

    def refresh_local_prices_tree(self):
        tv = getattr(self, "lp_tree", None)
        if tv is None:
            return
        for i in tv.get_children():
            tv.delete(i)
        rows = sorted(
            self.state_obj.get("local_prices", []),
            key=lambda r: (r.get("date",""), r.get("commodity","")))
        for r in rows:
            base  = to_float(r.get("price_egp_mt"), None)
            trans = to_float(r.get("transport_egp_mt"), None)
            if trans is None:
                trans = get_default_local_transport_egp_mt(self.state_obj)
            allin = (base + trans) if base is not None else None
            tag   = "has_transport" if trans > 0 else "no_transport"
            tv.insert("", "end", tags=(tag,), values=(
                r.get("date",""),
                r.get("commodity",""),
                fmt_num(base,  0) if base  is not None else "—",
                fmt_num(trans, 0) if trans > 0 else "—",
                fmt_num(allin, 0) if allin is not None else "—",
            ))
        if hasattr(self, "lp_commodity_cb"):
            self.lp_commodity_cb["values"] = sorted(
                list(self.state_obj.get("commodities",{}).keys()))
        self.refresh_local_monthly_contract_values()

    def refresh_local_monthly_contract_values(self):
        if not hasattr(self, "local_monthly_contract_combo"):
            return
        contracts = self.state_obj.get("contracts", {}) or {}
        values = []
        for cid, c in self._contracts_table_items(contracts):
            if (c.get("status") or "Open") == "Closed":
                continue
            commodity = (c.get("commodity") or "").upper()
            origin = (c.get("origin") or "")
            values.append(f"{cid} | {commodity} | {origin}" if origin else f"{cid} | {commodity}")
        self.local_monthly_contract_combo["values"] = values
        cur = (self.local_monthly_contract_var.get() or "").strip()
        if values and cur not in values:
            self.local_monthly_contract_var.set(values[0])
        elif not values:
            self.local_monthly_contract_var.set("")

    def _selected_local_monthly_contract_id(self):
        raw = (self.local_monthly_contract_var.get() or "").strip()
        return raw.split(" | ", 1)[0].strip() if raw else None

    def refresh_local_monthly_summary(self):
        if not hasattr(self, "local_monthly_tree"):
            return
        for i in self.local_monthly_tree.get_children():
            self.local_monthly_tree.delete(i)

        cid = self._selected_local_monthly_contract_id()
        if not cid:
            if hasattr(self, "local_monthly_summary_var"):
                self.local_monthly_summary_var.set("Select a contract to view monthly averages and monthly saving comparison.")
            return

        rows = self._monthly_contract_comparison_rows(cid)
        local_months = 0
        comp_months = 0
        saving_sum = 0.0
        saving_n = 0
        for idx, r in enumerate(rows):
            self.local_monthly_tree.insert("", "end", iid=f"lm_{idx}", values=(
                r["Month"], fmt_num(r["AvgLocalEGP_MT"],2), fmt_num(r["AvgProvisionalEGP_MT"],2),
                fmt_num(r["AvgSavingVsLocalEGP_MT"],2), r["LocalDays"], r["SnapshotDays"]
            ))
            if r["LocalDays"]:
                local_months += 1
            if r["AvgSavingVsLocalEGP_MT"] is not None:
                comp_months += 1
                saving_sum += r["AvgSavingVsLocalEGP_MT"]
                saving_n += 1
        avg_monthly_saving = (saving_sum / saving_n) if saving_n else None
        contracts = self.state_obj.get("contracts", {}) or {}
        c = contracts.get(cid, {})
        commodity = (c.get("commodity") or "")
        if hasattr(self, "local_monthly_summary_var"):
            self.local_monthly_summary_var.set(
                f"Contract: {cid} | Commodity: {commodity} | Months: {len(rows)} | Months with local data: {local_months} | Comparable months: {comp_months} | Avg monthly saving vs local: {fmt_num(avg_monthly_saving,2)}"
            )

    def _ma_refresh(self):
        """Refresh Monthly Market Intelligence panel."""
        if not hasattr(self, "_ma_tree"):
            return
        tv = self._ma_tree
        tv.delete(*tv.get_children())

        comm = self._ma_comm_var.get().strip().upper()
        if not comm:
            return

        try:
            alert_pct = float(self._ma_alert_var.get())
        except Exception:
            alert_pct = 5.0

        # Get all logged prices for commodity
        lp = self.state_obj.get("local_prices", []) or []
        base_comm = comm.split("-")[0] if "-" in comm else comm
        entries = []
        for e in lp:
            ec = (e.get("commodity","")).upper()
            if ec == comm or ec == base_comm:
                try:
                    d = dt.date.fromisoformat(e.get("date",""))
                    base  = to_float(e.get("price_egp_mt"), None)
                    trans = to_float(e.get("transport_egp_mt"), 0) or 0
                    if base is not None:
                        entries.append((d, base + trans))
                except Exception:
                    pass

        if not entries:
            self._ma_summary_var.set(f"No local prices logged for {comm}.")
            return

        # Group by month
        from collections import defaultdict
        by_month = defaultdict(list)
        for d, price in entries:
            key = d.strftime("%Y-%m")
            by_month[key].append(price)

        sorted_months = sorted(by_month.keys())

        # Live CBOT + FX for import parity
        md       = self.state_obj.get("market_data", {}) or {}
        cq       = md.get("cbot_quotes", {}) or {}
        cbot_raw = cq.get(base_comm)
        live_cbot= to_float(cbot_raw.get("price") if isinstance(cbot_raw, dict)
                            else cbot_raw, None)
        live_fx  = to_float((md.get("fx",{}) or {}).get("price"), None)

        # Typical fees for import parity
        contracts = self.state_obj.get("contracts",{}) or {}
        fees_list = []
        for c in contracts.values():
            if (c.get("commodity","").upper().startswith(base_comm)
                    and (c.get("status","Open")) == "Closed"):
                d2 = to_float(c.get("discharge_egp_mt"),0) or 0
                cl = to_float(c.get("clearance_egp_mt"),0) or 0
                fr = to_float(c.get("freight_egp_mt"),0) or 0
                fees_list.append(d2+cl+fr)
        avg_fees = sum(fees_list)/len(fees_list) if fees_list else 600.0

        # Get typical premium from open contracts
        prem_list = [to_float(c.get("premium_cents"))
                     for c in contracts.values()
                     if c.get("commodity","").upper().startswith(base_comm)
                     and to_float(c.get("premium_cents")) is not None]
        avg_prem = sum(prem_list)/len(prem_list) if prem_list else 0.0

        CONV = cbot_conv_factor(base_comm)
        def import_parity(cbot, prem, fx, fees):
            if not (cbot and fx): return None
            return (cbot + prem) * CONV * fx + fees

        prev_avg = None
        alert_months = []
        rows_data = []

        for month in sorted_months:
            prices  = by_month[month]
            avg     = sum(prices) / len(prices)
            lo      = min(prices)
            hi      = max(prices)
            rng     = hi - lo
            vol_pct = rng / avg * 100 if avg else 0

            # Trend vs previous month
            if prev_avg is not None:
                delta    = avg - prev_avg
                delta_pct= delta / prev_avg * 100 if prev_avg else 0
                if   delta_pct >  1: trend, tag = "↑ Rising", "up"
                elif delta_pct < -1: trend, tag = "↓ Falling","down"
                else:                trend, tag = "→ Flat",   "flat"
                vs_prev = f"{delta:+,.0f} ({delta_pct:+.1f}%)"
            else:
                delta_pct = 0
                trend, tag = "—", "flat"
                vs_prev = "—"

            # Volatility flag
            if   vol_pct >= 5: vol_label = f"⚠ {vol_pct:.1f}%"
            elif vol_pct >= 2: vol_label = f"△ {vol_pct:.1f}%"
            else:              vol_label = f"✔ {vol_pct:.1f}%"

            # Import parity (current live prices applied to this month for context)
            parity = import_parity(live_cbot, avg_prem, live_fx, avg_fees)
            parity_vs = (parity - avg) if parity is not None else None

            # Alert: movement > threshold vs previous month
            is_alert = abs(delta_pct) >= alert_pct and prev_avg is not None
            if is_alert:
                alert_months.append((month, delta_pct, avg))

            row_tag = "alert" if is_alert else ("hi_vol" if vol_pct >= 5 else tag)

            tv.insert("", "end", tags=(row_tag,), values=(
                month,
                str(len(prices)),
                f"{lo:,.0f}",
                f"{avg:,.0f}",
                f"{hi:,.0f}",
                f"{rng:,.0f}",
                vol_label,
                vs_prev,
                trend,
                f"{parity:,.0f}" if parity else "—",
                (f"{parity_vs:+,.0f}" if parity_vs is not None else "—"),
            ))
            rows_data.append(avg)
            prev_avg = avg

        # Summary line
        all_prices  = [p for ps in by_month.values() for p in ps]
        grand_avg   = sum(all_prices)/len(all_prices)
        grand_lo    = min(all_prices)
        grand_hi    = max(all_prices)
        latest_avg  = by_month[sorted_months[-1]]
        latest_mean = sum(latest_avg)/len(latest_avg)
        parity_now  = import_parity(live_cbot, avg_prem, live_fx, avg_fees)

        parts = [
            f"  {comm}  |  {len(sorted_months)} months  |  "
            f"Overall avg: EGP {grand_avg:,.0f}  |  "
            f"Range: EGP {grand_lo:,.0f}–{grand_hi:,.0f}  |  "
            f"Latest month avg: EGP {latest_mean:,.0f}"
        ]
        if parity_now:
            diff = parity_now - latest_mean
            parts.append(
                f"  |  Import parity NOW: EGP {parity_now:,.0f}  "
                f"({'import EGP '+f'{abs(diff):,.0f} costlier' if diff>0 else 'import EGP '+f'{abs(diff):,.0f} cheaper'})")
        if alert_months:
            parts.append(
                f"  |  ⚠ ALERT: {len(alert_months)} month(s) moved >{alert_pct:.0f}%: "
                + ", ".join(f"{m} ({d:+.1f}%)" for m, d, _ in alert_months))
        self._ma_summary_var.set("".join(parts))

        # Push price alert to Action Center if significant movement
        if hasattr(self, "_hd_action_alerts"):
            # Remove any stale alerts previously pushed for this commodity
            self._hd_action_alerts = [
                a for a in self._hd_action_alerts
                if not a.get("issue", "").startswith(f"Local {comm} ")
            ]
            for month, delta_pct, avg_price in alert_months:
                direction = "surged" if delta_pct > 0 else "dropped"
                self._hd_action_alerts.append({
                    "priority": "Medium",
                    "issue":    f"Local {comm} {direction} {abs(delta_pct):.1f}% in {month}",
                    "action":   f"Review {comm} local price: avg EGP {avg_price:,.0f}/MT in {month}. "
                                f"Check if import parity has changed.",
                })

    def add_or_update_local_price(self):
        try:
            d     = (self.lp_date_var.get() or "").strip()
            comm  = (self.lp_commodity_var.get() or "").strip()
            price = to_float(self.lp_price_var.get(), None)
            trans = to_float(
                getattr(self, "lp_transport_lp_setup_var",
                        tk.StringVar()).get(), None)
            if trans is None:
                trans = get_commodity_freight_egp_mt(self.state_obj, comm)
            if not d or not comm or price is None:
                messagebox.showerror(APP_NAME,
                    "Date, Commodity, and Price are required.")
                return
            try:
                dt.date.fromisoformat(d)
            except Exception:
                messagebox.showerror(APP_NAME, "Date must be YYYY-MM-DD.")
                return
            lp = self.state_obj.setdefault("local_prices", [])
            updated = False
            for r in lp:
                if r.get("date") == d and r.get("commodity") == comm:
                    r["price_egp_mt"]     = price
                    r["transport_egp_mt"] = trans
                    r["provenance"] = make_provenance(source="manual", as_of=d, confidence="manual")
                    updated = True
                    break
            if not updated:
                lp.append({
                    "date":             d,
                    "commodity":        comm,
                    "price_egp_mt":     price,
                    "transport_egp_mt": trans,
                    "provenance": make_provenance(source="manual", as_of=d, confidence="manual"),
                })
            append_audit_event(self.state_obj, "upsert_local_price", "local_price", f"{d}|{comm}", {"price": price, "transport": trans})
            save_state(self.state_obj)
            self.refresh_local_prices_tree()
            messagebox.showinfo(APP_NAME, "Saved.")
        except Exception as e:
            messagebox.showerror(APP_NAME, str(e))

    def delete_selected_local_prices(self):
        try:
            tv = getattr(self, "lp_tree", None)
            if tv is None:
                return
            sels = tv.selection()
            if not sels:
                messagebox.showinfo(APP_NAME, "Select rows first.")
                return
            if not messagebox.askyesno(APP_NAME, f"Delete {len(sels)} row(s)?"):
                return
            to_del=set()
            for iid in sels:
                vals = tv.item(iid,"values")
                if vals and len(vals)>=2:
                    to_del.add((str(vals[0]), str(vals[1])))
            lp = self.state_obj.setdefault("local_prices", [])
            lp[:] = [r for r in lp if (r.get("date"), r.get("commodity")) not in to_del]
            save_state(self.state_obj)
            self.refresh_local_prices_tree()
        except Exception as e:
            messagebox.showerror(APP_NAME, str(e))

    def backfill_commodity_freight(self, only_flat=True, dry_run=False):
        """Correct the historical mistake where every local row got 323.13.

        For each local_prices / local_purchases row, look up the correct
        per-commodity freight and restamp it. With only_flat=True (default)
        we touch a row only if its current transport equals the old flat
        rate (or is blank), so any manually-set value is preserved.
        Returns (changed_count, sample_changes)."""
        flat = round(get_default_local_transport_egp_mt(self.state_obj), 2)
        changed = 0
        sample = []
        for list_name in ("local_prices", "local_purchases"):
            for rec in self.state_obj.get(list_name, []) or []:
                if not isinstance(rec, dict):
                    continue
                comm = rec.get("commodity") or ""
                correct = round(get_commodity_freight_egp_mt(self.state_obj, comm), 2)
                cur = to_float(rec.get("transport_egp_mt"), None)
                cur_r = round(cur, 2) if cur is not None else None
                if only_flat and cur_r is not None and cur_r != flat:
                    continue  # user-edited → leave alone
                if cur_r == correct:
                    continue  # already correct
                if len(sample) < 12:
                    sample.append((rec.get("date", ""), comm,
                                   cur_r if cur_r is not None else "—", correct))
                if not dry_run:
                    rec["transport_egp_mt"] = correct
                changed += 1
        if changed and not dry_run:
            save_state(self.state_obj)
        return changed, sample

    def run_commodity_freight_backfill(self):
        """UI entry: preview the correction, confirm, apply."""
        try:
            preview, sample = self.backfill_commodity_freight(only_flat=True, dry_run=True)
            if preview == 0:
                messagebox.showinfo(
                    APP_NAME,
                    "Nothing to correct.\n\nAll local rows already carry the "
                    "right per-commodity freight (or were manually edited).")
                return
            lines = "\n".join(
                f"  {d or '—':<12} {c:<10} {old} → {new} EGP/MT"
                for d, c, old, new in sample)
            more = f"\n  … and {preview - len(sample)} more" if preview > len(sample) else ""
            if not messagebox.askyesno(
                APP_NAME,
                f"Correct freight on {preview} local row(s) that still carry the "
                f"flat {round(get_default_local_transport_egp_mt(self.state_obj),2)} "
                f"EGP/MT?\n\nManually edited rows are left untouched.\n\n"
                f"Examples:\n{lines}{more}\n\nApply now?"):
                return
            changed, _ = self.backfill_commodity_freight(only_flat=True, dry_run=False)
            try:
                self.refresh_local_prices_tree()
                self.refresh_all()
            except Exception as e:
                log_exception(e, "backfill:refresh")
            messagebox.showinfo(APP_NAME, f"Corrected {changed} row(s).")
        except Exception as e:
            self._surface_error("run_commodity_freight_backfill", e, show=True)

    # ══════════════════════════════════════════════════════════════════
    #  FINANCE BRIEF  — reproduces the corn comparison sheet layout exactly:
    #  No | Date | Supplier | QTY | Origin | Notes | USD | Price EGP/MT at
    #  port | Avg local expenses | CIF USD/MT | Avr CBOT | Premium over July
    #  | Market price EGP/MT at port | Market CIF USD/MT | Premium over July
    #  | Diff EGP/MT | Diff USD/MT | Diff Premium — split Import vs Contract,
    #  with the FX-impact note block and Finance sign-off footer.
    # ══════════════════════════════════════════════════════════════════
    _BRIEF_LOCAL_EXPENSES_EGP_MT = 500   # sheet's flat "average local expenses"
    _BRIEF_CORN_FACTOR = 0.3937

    def _brief_market_egp_at_port(self, commodity, as_of_date):
        """Latest logged local (base+transport) for commodity on/before date,
        expressed at-port using the sheet's flat 500 expenses convention:
        we return the logged all-in EGP/MT (base+transport) as the market
        reference, which the sheet calls 'market price at port'."""
        best = None
        for r in self.state_obj.get("local_prices", []) or []:
            if (r.get("commodity") or "").upper().split("-")[0] != commodity.upper().split("-")[0]:
                continue
            d = r.get("date", "")
            if as_of_date and d > as_of_date:
                continue
            if best is None or d > best[0]:
                base = to_float(r.get("price_egp_mt"), 0) or 0
                trans = to_float(r.get("transport_egp_mt"), 0) or 0
                best = (d, base + trans)
        return best[1] if best else None

    def _brief_avg_cbot(self, commodity, start=None, end=None):
        """Average CBOT close over the window for the commodity (¢/bu)."""
        base = commodity.upper().split("-")[0]
        vals = []
        for e in self.state_obj.get("cbot_history", []) or []:
            if (e.get("commodity") or "").upper() != base:
                continue
            d = e.get("date", "")
            if start and d < start:
                continue
            if end and d > end:
                continue
            px = to_float(e.get("close", e.get("price")), None)
            if px is not None:
                vals.append(px)
        if vals:
            return sum(vals) / len(vals)
        # Fallback: if nothing in-window, average ALL closes for the commodity
        # so the brief's CBOT column is never blank when history exists.
        allpx = [to_float(e.get("close", e.get("price")), None)
                 for e in self.state_obj.get("cbot_history", []) or []
                 if (e.get("commodity") or "").upper() == base]
        allpx = [p for p in allpx if p is not None]
        return sum(allpx) / len(allpx) if allpx else None

    def export_periodic_brief(self):
        """Weekly / monthly purchasing brief at FULL Finance-sheet depth.

        Import rows use the audited corn-comparison layout (18 columns):
        No · Date · Supplier · QTY · Origin · Notes · USD · Price EGP/MT at
        port · Avg local expenses · CIF · Avr CBOT (over the period) ·
        Premium · Market price at port · Market CIF · Market premium ·
        Diff EGP · Diff USD · Diff Premium — all derived cells as live Excel
        formulas — plus the FX-impact revaluation block (contract FX vs
        latest FX) and the local-purchases and summary sections.
        """
        try:
            if not _need_openpyxl():
                return
            # ── Period picker ─────────────────────────────────────────
            win = tk.Toplevel(self)
            win.title("Purchasing brief — choose period")
            win.transient(self); win.grab_set()
            frm = ttk.Frame(win, padding=12); frm.grid(row=0, column=0)
            ttk.Label(frm, text="Period").grid(row=0, column=0, sticky="w",
                                               padx=(0, 8))
            preset_var = tk.StringVar(value="This week")
            cb = ttk.Combobox(frm, textvariable=preset_var, state="readonly",
                              width=14,
                              values=["This week", "Last week", "This month",
                                      "Last month", "Custom"])
            cb.grid(row=0, column=1, sticky="w")
            ttk.Label(frm, text="From (YYYY-MM-DD)").grid(row=1, column=0,
                                                          sticky="w", pady=4)
            f_var = tk.StringVar(); t_var = tk.StringVar()
            ttk.Entry(frm, textvariable=f_var, width=14).grid(row=1, column=1,
                                                              sticky="w")
            ttk.Label(frm, text="To (YYYY-MM-DD)").grid(row=2, column=0,
                                                        sticky="w")
            ttk.Entry(frm, textvariable=t_var, width=14).grid(row=2, column=1,
                                                              sticky="w")

            def _preset(*_):
                today = dt.date.today()
                p = preset_var.get()
                if p == "This week":
                    lo = today - dt.timedelta(days=today.weekday())
                    hi = lo + dt.timedelta(days=6)
                elif p == "Last week":
                    lo = today - dt.timedelta(days=today.weekday() + 7)
                    hi = lo + dt.timedelta(days=6)
                elif p == "This month":
                    lo = today.replace(day=1)
                    nxt = (lo + dt.timedelta(days=32)).replace(day=1)
                    hi = nxt - dt.timedelta(days=1)
                elif p == "Last month":
                    first_this = today.replace(day=1)
                    hi = first_this - dt.timedelta(days=1)
                    lo = hi.replace(day=1)
                else:
                    return
                f_var.set(lo.isoformat()); t_var.set(hi.isoformat())
            cb.bind("<<ComboboxSelected>>", _preset)
            _preset()
            chosen = {"go": False}

            def _ok():
                chosen["go"] = True
                win.destroy()
            ttk.Button(frm, text="Create brief", command=_ok).grid(
                row=3, column=0, pady=(10, 0), sticky="w")
            ttk.Button(frm, text="Cancel", command=win.destroy).grid(
                row=3, column=1, pady=(10, 0), sticky="w")
            self.wait_window(win)
            if not chosen["go"]:
                return
            lo = parse_date_flex(f_var.get()); hi = parse_date_flex(t_var.get())
            if lo is None or hi is None or lo > hi:
                messagebox.showerror(APP_NAME, "Invalid period dates.")
                return
            lo_s, hi_s = lo.isoformat(), hi.isoformat()

            exp = self._basis_expenses_egp_mt()
            # latest FX for the revaluation block
            fxh = sorted(((e.get("date", ""), to_float(e.get("rate"), None))
                          for e in self.state_obj.get("fx_history", []) or []
                          if e.get("date")))
            fxh = [(d, v) for d, v in fxh if v is not None]
            latest_fx, latest_fx_d = (fxh[-1] if fxh else (None, ""))[1] if fxh else None,                                      (fxh[-1][0] if fxh else "")
            if fxh:
                latest_fx = fxh[-1][1]

            imports = []
            for cid, c in (self.state_obj.get("contracts", {}) or {}).items():
                dd = parse_date_flex(c.get("delivery_date"))
                if dd is None or not (lo <= dd <= hi):
                    continue
                imports.append((dd.isoformat(), cid, c))
            imports.sort(key=lambda t: t[0])
            locals_ = []
            for rec in (self.state_obj.get("local_purchases", []) or []):
                d = parse_date_flex(rec.get("date"))
                if d is None or not (lo <= d <= hi):
                    continue
                locals_.append((d.isoformat(), rec.get("commodity", ""),
                                to_float(rec.get("qty_mt"), 0) or 0,
                                to_float(rec.get("price_egp_mt"), None)))
            locals_.sort()
            if not imports and not locals_:
                messagebox.showinfo(APP_NAME,
                                    f"No purchases found between {lo_s} and {hi_s}.")
                return

            fp = filedialog.asksaveasfilename(
                title="Export Purchasing Brief",
                initialdir=get_default_export_dir(),
                initialfile=f"Purchasing_Brief_{lo_s}_to_{hi_s}.xlsx",
                defaultextension=".xlsx", filetypes=[("Excel", "*.xlsx")])
            if not fp:
                return

            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
            from openpyxl.utils import get_column_letter
            wb = Workbook()
            ws = wb.active; ws.title = "Purchasing Brief"
            wsA = wb.create_sheet("Assumptions")
            wsA["A1"] = "Purchasing Brief — input assumptions"
            wsA["A1"].font = Font(bold=True, size=12)
            wsA["A2"] = "CORN conversion factor (¢/bu → $/MT)"
            wsA["B2"] = self._BRIEF_CORN_FACTOR
            wsA["A3"] = "Average local expenses (EGP/MT)"; wsA["B3"] = exp
            wsA["A4"] = f"Latest USD/EGP rate ({latest_fx_d or 'none stored'})"
            wsA["B4"] = latest_fx if latest_fx is not None else ""
            wsA["A6"] = ("Formulas: CIF=(CBOT+premium)×B2 · EGP@port=CIF×FX+B3 · "
                         "mktCIF=(mkt−B3)÷FX · mktPrem=mktCIF÷B2−CBOT · "
                         "FX impact = (B4 − contract FX) × CIF")
            for _r in (2, 3, 4):
                wsA.cell(row=_r, column=1).font = Font(bold=True)
            wsA.column_dimensions["A"].width = 40
            wsA.column_dimensions["B"].width = 12

            thin = Side(style="thin", color="B0B7C3")
            border = Border(left=thin, right=thin, top=thin, bottom=thin)
            hdr_fill = PatternFill("solid", fgColor="1F3864")
            grp_fill = PatternFill("solid", fgColor="D9E1F2")
            hdr_font = Font(bold=True, color="FFFFFF", size=9)
            cen = Alignment(horizontal="center", vertical="center", wrap_text=True)
            BLUE = Font(color="1A4FA0")
            BOLD = Font(bold=True)

            ws["A1"] = f"Purchasing Brief   {lo_s} → {hi_s}"
            ws["A1"].font = Font(bold=True, size=13)
            ws.merge_cells("A1:R1")

            headers = ["No", "Date", "Supplier", "QTY", "Origin", "Notes",
                       "USD", "Price EGP/MT at port", "Avg local expenses EGP/MT",
                       "CIF USD/MT", "Avr CBOT", "Premium over July EGP/MT",
                       "Market price EGP/MT at port", "Market CIF USD/MT",
                       "Market Premium over July", "Diff EGP/MT", "Diff USD/MT",
                       "Diff Premium"]
            hr = 3
            for ci, h in enumerate(headers, start=1):
                cell = ws.cell(row=hr, column=ci, value=h)
                cell.fill = hdr_fill; cell.font = hdr_font
                cell.alignment = cen; cell.border = border
            gc = ws.cell(row=hr - 1, column=1,
                         value="IMPORT PURCHASES (delivering in period)")
            gc.font = BOLD
            r = hr + 1
            r0 = r
            fx_rows = []   # (row, name) for the FX-impact block
            for i, (d, cid, c) in enumerate(imports, start=1):
                comm = (c.get("commodity") or "CORN")
                qty = to_float(c.get("qty_mt"), 0) or 0
                fx = to_float(c.get("delivery_fx"), None)
                cif = to_float(c.get("cif_usd_mt"), None)
                cbot = self._brief_avg_cbot(comm, lo_s, hi_s)
                prem = to_float(c.get("premium_cents"), None)
                egp_port = (cif * fx + exp) if (cif is not None and fx is not None) else None
                mkt_port = self._brief_market_egp_at_port(comm, d)
                mkt_cif = ((mkt_port - exp) / fx) if (mkt_port is not None and fx) else None
                is_corn = comm.upper().startswith("CORN")
                factor = self._BRIEF_CORN_FACTOR if is_corn else None
                mkt_prem = ((mkt_cif / factor - cbot)
                            if (mkt_cif is not None and cbot and factor) else None)
                diff_egp = (mkt_port - egp_port) if (mkt_port is not None and egp_port is not None) else None
                diff_usd = (mkt_cif - cif) if (mkt_cif is not None and cif is not None) else None
                diff_prem = (mkt_prem - prem) if (mkt_prem is not None and prem is not None) else None
                can_formula = is_corn and cbot is not None and prem is not None
                f_exp  = "=Assumptions!$B$3"
                f_cif  = f"=(K{r}+L{r})*Assumptions!$B$2" if can_formula else cif
                f_egp  = (f"=J{r}*G{r}+I{r}"
                          if (fx is not None and (can_formula or cif is not None))
                          else egp_port)
                f_mcif = (f"=(M{r}-I{r})/G{r}"
                          if (mkt_port is not None and fx) else mkt_cif)
                f_mprm = (f"=N{r}/Assumptions!$B$2-K{r}"
                          if (mkt_port is not None and fx and can_formula) else mkt_prem)
                f_dE   = (f"=M{r}-H{r}"
                          if (mkt_port is not None and egp_port is not None) else diff_egp)
                f_dU   = (f"=N{r}-J{r}"
                          if (mkt_cif is not None and cif is not None) else diff_usd)
                f_dP   = (f"=O{r}-L{r}"
                          if (mkt_prem is not None and prem is not None) else diff_prem)
                vals = [i, d, c.get("supplier", ""), qty, c.get("origin", ""),
                        c.get("note", ""), fx, f_egp, f_exp, f_cif, cbot, prem,
                        mkt_port, f_mcif, f_mprm, f_dE, f_dU, f_dP]
                _fmt = {4: "#,##0", 7: "#,##0.00", 8: "#,##0", 9: "#,##0",
                        10: "#,##0.00", 11: "#,##0.00", 12: "#,##0.00",
                        13: "#,##0", 14: "#,##0.00", 15: "#,##0.0",
                        16: "#,##0", 17: "#,##0.00", 18: "#,##0.0"}
                for ci, v in enumerate(vals, start=1):
                    cell = ws.cell(row=r, column=ci, value=v)
                    cell.border = border
                    cell.alignment = Alignment(horizontal="center")
                    if ci in _fmt and v is not None:
                        cell.number_format = _fmt[ci]
                    if isinstance(v, str) and v.startswith("="):
                        cell.font = BLUE
                if fx is not None and (can_formula or cif is not None):
                    fx_rows.append((r, c.get("name") or cid, qty))
                r += 1
            imp_tot_row = None
            if imports:
                ws.cell(row=r, column=1, value="TOTAL").font = BOLD
                tq = ws.cell(row=r, column=4,
                             value=f"=SUM(D{r0}:D{r-1})" if r - 1 >= r0 else 0)
                tq.font = Font(bold=True, color="1A4FA0")
                tq.number_format = "#,##0"
                for ci in range(1, 19):
                    ws.cell(row=r, column=ci).fill = grp_fill
                imp_tot_row = r
                r += 2

            # ── FX-impact revaluation block (contract FX vs latest FX) ──
            if fx_rows and latest_fx is not None:
                ws.cell(row=r, column=1,
                        value="FX IMPACT — revaluation at latest rate "
                              f"({latest_fx_d})").font = BOLD
                r += 1
                for ci, h in enumerate(["Contract", "QTY", "Contract FX",
                                        "Latest FX", "CIF USD/MT",
                                        "Impact EGP/MT", "Total impact EGP"],
                                       start=1):
                    cell = ws.cell(row=r, column=ci, value=h)
                    cell.fill = hdr_fill; cell.font = hdr_font
                    cell.alignment = cen; cell.border = border
                r += 1
                fx0 = r
                for src_r, name, qty in fx_rows:
                    ws.cell(row=r, column=1, value=name)
                    ws.cell(row=r, column=2, value=f"=D{src_r}").font = BLUE
                    ws.cell(row=r, column=3, value=f"=G{src_r}").font = BLUE
                    lf = ws.cell(row=r, column=4, value="=Assumptions!$B$4")
                    lf.font = BLUE; lf.number_format = "#,##0.00"
                    ws.cell(row=r, column=5, value=f"=J{src_r}").font = BLUE
                    ic = ws.cell(row=r, column=6, value=f"=(D{r}-C{r})*E{r}")
                    ic.font = Font(color="1A4FA0", bold=True)
                    ic.number_format = "#,##0"
                    tc = ws.cell(row=r, column=7, value=f"=F{r}*B{r}")
                    tc.font = Font(color="1A4FA0", bold=True)
                    tc.number_format = "#,##0"
                    for ci in range(1, 8):
                        ws.cell(row=r, column=ci).border = border
                    r += 1
                ws.cell(row=r, column=1, value="TOTAL FX impact").font = BOLD
                tt = ws.cell(row=r, column=7, value=f"=SUM(G{fx0}:G{r-1})")
                tt.font = Font(bold=True, color="1A4FA0")
                tt.number_format = "#,##0"
                fx_tot_row = r
                r += 2
            else:
                fx_tot_row = None

            # ── Local purchases ───────────────────────────────────────
            loc_tot_row = None
            if locals_:
                ws.cell(row=r, column=1, value="LOCAL PURCHASES").font = BOLD
                r += 1
                for ci, h in enumerate(["Date", "Commodity", "Qty MT",
                                        "Price EGP/MT", "Value EGP"], start=1):
                    cell = ws.cell(row=r, column=ci, value=h)
                    cell.fill = hdr_fill; cell.font = hdr_font
                    cell.alignment = cen; cell.border = border
                r += 1
                loc0 = r
                for d, comm, qty, px in locals_:
                    ws.cell(row=r, column=1, value=d)
                    ws.cell(row=r, column=2, value=comm)
                    ws.cell(row=r, column=3, value=qty).number_format = "#,##0"
                    if px is not None:
                        ws.cell(row=r, column=4, value=px).number_format = "#,##0"
                        vc = ws.cell(row=r, column=5, value=f"=C{r}*D{r}")
                        vc.number_format = "#,##0"; vc.font = BLUE
                    for ci in range(1, 6):
                        ws.cell(row=r, column=ci).border = border
                    r += 1
                ws.cell(row=r, column=1, value="TOTAL local").font = BOLD
                tq = ws.cell(row=r, column=3, value=f"=SUM(C{loc0}:C{r-1})")
                tq.font = Font(bold=True, color="1A4FA0"); tq.number_format = "#,##0"
                wa = ws.cell(row=r, column=4,
                             value=f"=SUMPRODUCT(C{loc0}:C{r-1},D{loc0}:D{r-1})"
                                   f"/SUM(C{loc0}:C{r-1})")
                wa.font = Font(bold=True, color="1A4FA0"); wa.number_format = "#,##0"
                tv = ws.cell(row=r, column=5, value=f"=SUM(E{loc0}:E{r-1})")
                tv.font = Font(bold=True, color="1A4FA0"); tv.number_format = "#,##0"
                loc_tot_row = r
                r += 2

            # ── Summary + Finance note block ──────────────────────────
            ws.cell(row=r, column=1, value="PERIOD SUMMARY").font = BOLD
            r += 1
            if imp_tot_row:
                ws.cell(row=r, column=1, value="Import volume MT")
                ws.cell(row=r, column=3, value=f"=D{imp_tot_row}").font = BLUE
                r += 1
            if fx_tot_row:
                ws.cell(row=r, column=1, value="FX revaluation impact EGP")
                ws.cell(row=r, column=3, value=f"=G{fx_tot_row}").font = BLUE
                r += 1
            if loc_tot_row:
                ws.cell(row=r, column=1, value="Local volume MT / value EGP")
                ws.cell(row=r, column=3, value=f"=C{loc_tot_row}").font = BLUE
                ws.cell(row=r, column=4, value=f"=E{loc_tot_row}").font = BLUE
                r += 1
            ws.cell(row=r, column=1,
                    value=f"Contracts: {len(imports)}   ·   Local buys: {len(locals_)}")
            r += 2
            for txt in [
                "FX Impact: contract values are calculated at each contract's "
                "delivery/contract-date USD rate and compared with the latest "
                "USD rate (Assumptions!B4). The difference reflects the impact "
                "of the change in the USD exchange rate.",
                "A revaluation will be conducted to determine the over price.",
                "Reviewed and Verified by Finance.",
            ]:
                ws.cell(row=r, column=1, value=txt).alignment = Alignment(wrap_text=True)
                ws.merge_cells(start_row=r, start_column=1, end_row=r,
                               end_column=18)
                r += 1

            widths = [4, 11, 14, 8, 9, 10, 7, 14, 12, 10, 9, 13, 14, 12, 13, 11, 10, 11]
            for i2, w in enumerate(widths, start=1):
                ws.column_dimensions[get_column_letter(i2)].width = w
            wb.save(fp)
            messagebox.showinfo(APP_NAME,
                                f"Purchasing brief exported with live formulas:\n{fp}")
        except Exception as e:
            self._surface_error("export_periodic_brief", e, show=True)

    def export_finance_brief(self):
        if not _need_openpyxl():
            return
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
            from openpyxl.utils import get_column_letter

            contracts = self.state_obj.get("contracts", {}) or {}
            if not contracts:
                messagebox.showinfo(APP_NAME, "No contracts to brief.")
                return

            # Window = min..max delivery date across contracts (sheet header).
            dates = [c.get("delivery_date", "") for c in contracts.values()
                     if c.get("delivery_date")]
            win_lo, win_hi = (min(dates), max(dates)) if dates else ("", "")

            wb = Workbook(); ws = wb.active; ws.title = "Finance Brief"
            thin = Side(style="thin", color="808080")
            border = Border(left=thin, right=thin, top=thin, bottom=thin)
            hdr_fill = PatternFill("solid", fgColor="1F3864")
            grp_fill = PatternFill("solid", fgColor="D9E1F2")
            hdr_font = Font(bold=True, color="FFFFFF", size=9)
            cen = Alignment(horizontal="center", vertical="center", wrap_text=True)

            ws["A1"] = f"Corn Comparison Brief   {win_lo} to {win_hi}"
            ws["A1"].font = Font(bold=True, size=13)
            ws.merge_cells("A1:R1")

            # Assumptions sheet: the input cells every formula points at.
            wsA = wb.create_sheet("Assumptions")
            wsA["A1"] = "Finance Brief — input assumptions"
            wsA["A1"].font = Font(bold=True, size=12)
            wsA["A2"] = "CORN conversion factor (¢/bu → $/MT)"
            wsA["B2"] = self._BRIEF_CORN_FACTOR
            wsA["C2"] = "House convention 0.3937 (ARG/BRZ/USA). Applies to CORN rows only."
            wsA["A3"] = "Average local expenses (EGP/MT)"
            wsA["B3"] = self._basis_expenses_egp_mt()
            wsA["C3"] = "At-port costs inside the local price. Editable in Basis Tracker bar."
            wsA["A5"] = ("Row formulas:  CIF = (CBOT + premium) × factor   ·   "
                         "EGP at port = CIF × FX + expenses   ·   "
                         "market CIF = (market − expenses) ÷ FX   ·   "
                         "market premium = market CIF ÷ factor − CBOT")
            for _r in (2, 3):
                wsA.cell(row=_r, column=1).font = Font(bold=True)
            wsA.column_dimensions["A"].width = 36
            wsA.column_dimensions["B"].width = 12
            wsA.column_dimensions["C"].width = 78

            headers = ["No", "Date", "Supplier", "QTY", "Origin", "Notes",
                       "USD", "Price EGP/MT at port", "Avg local expenses EGP/MT",
                       "CIF USD/MT", "Avr CBOT", "Premium over July EGP/MT",
                       "Market price EGP/MT at port", "Market CIF USD/MT",
                       "Market Premium over July", "Diff EGP/MT", "Diff USD/MT",
                       "Diff Premium"]
            hr = 3
            for ci, h in enumerate(headers, start=1):
                cell = ws.cell(row=hr, column=ci, value=h)
                cell.fill = hdr_fill; cell.font = hdr_font
                cell.alignment = cen; cell.border = border

            def _emit_group(title, rows, r0):
                gc = ws.cell(row=r0, column=1, value=title)
                gc.font = Font(bold=True, size=10)
                gc.fill = grp_fill
                ws.merge_cells(start_row=r0, start_column=1, end_row=r0, end_column=18)
                r = r0 + 1
                tot_qty = 0.0
                for i, (cid, c) in enumerate(rows, start=1):
                    comm = (c.get("commodity") or "CORN")
                    qty = to_float(c.get("qty_mt"), 0) or 0
                    tot_qty += qty
                    fx = to_float(c.get("delivery_fx"), None)
                    cif = to_float(c.get("cif_usd_mt"), None)
                    cbot = self._brief_avg_cbot(comm, win_lo, win_hi)
                    prem = to_float(c.get("premium_cents"), None)
                    exp = self._BRIEF_LOCAL_EXPENSES_EGP_MT
                    # Price EGP/MT at port = CIF*FX + expenses (sheet formula)
                    egp_port = (cif * fx + exp) if (cif is not None and fx is not None) else None
                    mkt_port = self._brief_market_egp_at_port(comm, c.get("delivery_date", ""))
                    mkt_cif = ((mkt_port - exp) / fx) if (mkt_port is not None and fx) else None
                    factor = self._BRIEF_CORN_FACTOR if comm.upper().startswith("CORN") else None
                    mkt_prem = ((mkt_cif / factor - cbot) if (mkt_cif is not None and cbot and factor) else None)
                    diff_egp = (mkt_port - egp_port) if (mkt_port is not None and egp_port is not None) else None
                    diff_usd = (mkt_cif - cif) if (mkt_cif is not None and cif is not None) else None
                    diff_prem = (mkt_prem - prem) if (mkt_prem is not None and prem is not None) else None

                    is_corn = comm.upper().startswith("CORN")
                    can_formula = is_corn and cbot is not None and prem is not None
                    # Derived numbers become REAL Excel formulas (auditable):
                    f_exp  = "=Assumptions!$B$3"
                    f_cif  = f"=(K{r}+L{r})*Assumptions!$B$2" if can_formula else cif
                    f_egp  = (f"=J{r}*G{r}+I{r}"
                              if (fx is not None and (can_formula or cif is not None))
                              else egp_port)
                    f_mcif = (f"=(M{r}-I{r})/G{r}"
                              if (mkt_port is not None and fx) else mkt_cif)
                    f_mprm = (f"=N{r}/Assumptions!$B$2-K{r}"
                              if (mkt_port is not None and fx and can_formula)
                              else mkt_prem)
                    f_dE   = (f"=M{r}-H{r}"
                              if (mkt_port is not None and egp_port is not None) else diff_egp)
                    f_dU   = (f"=N{r}-J{r}"
                              if (mkt_cif is not None and cif is not None) else diff_usd)
                    f_dP   = (f"=O{r}-L{r}"
                              if (mkt_prem is not None and prem is not None) else diff_prem)
                    vals = [i, c.get("delivery_date", ""), c.get("supplier", ""),
                            qty, c.get("origin", ""), c.get("note", ""),
                            fx, f_egp, f_exp, f_cif, cbot, prem, mkt_port,
                            f_mcif, f_mprm, f_dE, f_dU, f_dP]
                    _fmt = {4: "#,##0", 7: "#,##0.00", 8: "#,##0", 9: "#,##0",
                            10: "#,##0.00", 11: "#,##0.00", 12: "#,##0.00",
                            13: "#,##0", 14: "#,##0.00", 15: "#,##0.0",
                            16: "#,##0", 17: "#,##0.00", 18: "#,##0.0"}
                    for ci, v in enumerate(vals, start=1):
                        cell = ws.cell(row=r, column=ci, value=v)
                        cell.border = border
                        cell.alignment = Alignment(horizontal="center")
                        if ci in _fmt and v is not None:
                            cell.number_format = _fmt[ci]
                        if isinstance(v, str) and v.startswith("="):
                            cell.font = Font(color="1A4FA0")
                    r += 1
                # group total row — a real SUM the user can audit
                ws.cell(row=r, column=1, value="TOTAL").font = Font(bold=True)
                tc = ws.cell(row=r, column=4,
                             value=f"=SUM(D{r0 + 1}:D{r - 1})" if r - 1 > r0 else tot_qty)
                tc.font = Font(bold=True); tc.number_format = "#,##0"
                for ci in range(1, 19):
                    ws.cell(row=r, column=ci).fill = grp_fill
                return r + 2

            # Split Import vs Contract exactly like the sheet (heuristic:
            # 'Delivery' note = import lane; others = contract). All contracts
            # go into both-aware grouping by status if notes absent.
            imports = [(cid, c) for cid, c in contracts.items()
                       if "deliver" in (c.get("note") or "").lower()]
            others = [(cid, c) for cid, c in contracts.items()
                      if (cid, c) not in imports]
            nr = _emit_group("Import contract", imports or list(contracts.items()),
                             hr + 1)
            if imports and others:
                nr = _emit_group("Contract", others, nr)

            # FX-impact note block (mirrors the sheet's paragraph).
            note_r = nr + 1
            notes = [
                "FX Impact: The contract value was calculated using the USD "
                "exchange rate on the contract/delivery date, and compared with "
                "the latest USD exchange rate. The difference reflects the impact "
                "of the reduction in the USD exchange rate.",
                "This represents the preliminary cost of the corn.",
                "A revaluation will be conducted within two days to determine "
                "the over price.",
                "Reviewed and Verified by Finance.",
            ]
            for txt in notes:
                ws.cell(row=note_r, column=1, value=txt).alignment = Alignment(wrap_text=True)
                ws.merge_cells(start_row=note_r, start_column=1,
                               end_row=note_r, end_column=18)
                note_r += 1

            widths = [4, 11, 14, 8, 9, 10, 7, 14, 12, 10, 9, 13, 14, 12, 13, 11, 10, 11]
            for i, w in enumerate(widths, start=1):
                ws.column_dimensions[get_column_letter(i)].width = w

            out = filedialog.asksaveasfilename(
                title="Export Finance Brief",
                initialdir=get_default_export_dir(),
                initialfile=f"Finance_Brief_{dt.date.today().isoformat()}.xlsx",
                defaultextension=".xlsx", filetypes=[("Excel", "*.xlsx")])
            if not out:
                return
            wb.save(out)
            messagebox.showinfo(APP_NAME,
                                f"Finance Brief exported with live formulas:\n{out}\n\n"
                                f"Change Assumptions!B2/B3 in Excel and the brief re-computes.")
        except Exception as e:
            self._surface_error("export_finance_brief", e, show=True)

    # ══════════════════════════════════════════════════════════════════
    #  PORTFOLIO EXPOSURE — the numbers a CFO asks for.
    # ══════════════════════════════════════════════════════════════════
    def portfolio_exposure(self):
        """Aggregate risk snapshot over OPEN contracts:
          open_mt / open_usd        total exposure
          priced vs unpriced MT     CBOT price risk still open
          fx_unsecured_usd          USD without a Form 4 (bank FX not yet
                                    allocated) — genuine currency exposure
          buckets                   days-to-delivery risk ladder
          by_supplier / top_supplier  concentration of open MT by supplier
        """
        today = dt.date.today()
        out = {"open_mt": 0.0, "open_usd": 0.0, "priced_mt": 0.0,
               "unpriced_mt": 0.0, "fx_unsecured_usd": 0.0,
               "fx_unsecured_mt": 0.0, "contracts": 0,
               "buckets": {"<7d": [], "7-30d": [], ">30d": [], "no date": []},
               "unpriced_near": [], "wavg_premium": None,
               "by_supplier": {}, "top_supplier": None}
        prem_num = prem_den = 0.0
        for cid, c in (self.state_obj.get("contracts", {}) or {}).items():
            if (c.get("status") or "Open").strip().lower() != "open":
                continue
            out["contracts"] += 1
            qty = to_float(c.get("qty_mt"), 0) or 0.0
            cif = to_float(c.get("cif_usd_mt"), None)
            usd = (qty * cif) if cif is not None else 0.0
            out["open_mt"] += qty
            out["open_usd"] += usd
            priced = bool(c.get("priced", True)) and cif is not None
            if priced:
                out["priced_mt"] += qty
            else:
                out["unpriced_mt"] += qty
            if not to_float(c.get("form4_fx"), None):
                out["fx_unsecured_usd"] += usd
                out["fx_unsecured_mt"] += qty
            prem = to_float(c.get("premium_cents"), None)
            if prem is not None and qty:
                prem_num += prem * qty; prem_den += qty
            dd = parse_date_flex(c.get("delivery_date"))
            label = c.get("name") or cid
            if dd is None:
                out["buckets"]["no date"].append((label, qty))
            else:
                days = (dd - today).days
                key = "<7d" if days < 7 else ("7-30d" if days <= 30 else ">30d")
                out["buckets"][key].append((label, qty))
                if not priced and days <= self._alert_near_days():
                    out["unpriced_near"].append((label, qty, days))
            supplier = (c.get("supplier") or "").strip() or "(no supplier)"
            sup_rec = out["by_supplier"].setdefault(supplier, {"mt": 0.0, "usd": 0.0})
            sup_rec["mt"] += qty
            sup_rec["usd"] += usd
        if prem_den:
            out["wavg_premium"] = prem_num / prem_den
        if out["open_mt"] and out["by_supplier"]:
            top_name, top_rec = max(out["by_supplier"].items(),
                                     key=lambda kv: kv[1]["mt"])
            out["top_supplier"] = {
                "name": top_name, "mt": top_rec["mt"],
                "usd": top_rec["usd"],
                "pct": top_rec["mt"] / out["open_mt"] * 100.0,
            }
        return out

    def portfolio_stress_test(self, fx_shock_pct, cbot_shock_pct):
        """First-order shock across the whole open book, combining an FX
        move and a CBOT move simultaneously — the portfolio-level view that
        the per-contract Scenario/What-If tab doesn't give.

        - FX shock applies to FX-unsecured USD exposure only (contracts with
          no Form 4 FX yet): a fx_shock_pct move in USD/EGP changes their
          landed EGP cost by usd_exposure * fx_now * fx_shock_pct/100.
        - CBOT shock applies to unpriced MT only (contracts with no CBOT/
          premium locked yet), grouped by commodity, using each commodity's
          latest CBOT print and its cents/bu -> USD/MT conversion factor.
        Both are linear/first-order approximations, not a full curve
        re-price — good enough to flag "how big could this book move."
        """
        s = self.state_obj
        fxh = sorted(((e.get("date", ""), to_float(e.get("rate"), None))
                      for e in s.get("fx_history", []) or []), key=lambda t: t[0])
        fx_now = fxh[-1][1] if fxh else None

        cbot_rows = {}
        for e in s.get("cbot_history", []) or []:
            comm = (e.get("commodity") or "").upper()
            px = to_float(e.get("close", e.get("price")), None)
            if comm and px is not None and e.get("date"):
                cbot_rows.setdefault(comm, []).append((e["date"], px))
        latest_cbot = {c: sorted(rows)[-1][1] for c, rows in cbot_rows.items() if rows}

        fx_exposed_usd = 0.0
        unpriced_by_comm = {}
        for cid, c in (s.get("contracts", {}) or {}).items():
            if (c.get("status") or "Open").strip().lower() != "open":
                continue
            qty = to_float(c.get("qty_mt"), 0) or 0.0
            cif = to_float(c.get("cif_usd_mt"), None)
            usd = (qty * cif) if cif is not None else 0.0
            if not to_float(c.get("form4_fx"), None):
                fx_exposed_usd += usd
            priced = bool(c.get("priced", True)) and cif is not None
            if not priced:
                base = (c.get("commodity") or "").upper().split("-")[0]
                unpriced_by_comm[base] = unpriced_by_comm.get(base, 0.0) + qty

        fx_impact_egp = (fx_exposed_usd * (fx_shock_pct / 100.0) * fx_now
                          if fx_now is not None else None)

        cbot_impact_egp = 0.0
        cbot_impact_known = False
        cbot_gaps = []
        for comm, qty in unpriced_by_comm.items():
            px = latest_cbot.get(comm)
            try:
                factor = cbot_conv_factor(comm, strict=False)
            except Exception:
                factor = None
            if px is None or not factor or fx_now is None:
                cbot_gaps.append(comm)
                continue
            cbot_impact_known = True
            move_usd_mt = px * (cbot_shock_pct / 100.0) * factor
            cbot_impact_egp += move_usd_mt * qty * fx_now

        total_impact_egp = (fx_impact_egp or 0.0) + (cbot_impact_egp if cbot_impact_known else 0.0)
        return {
            "fx_now": fx_now,
            "fx_exposed_usd": fx_exposed_usd,
            "fx_impact_egp": fx_impact_egp,
            "unpriced_by_comm": unpriced_by_comm,
            "cbot_impact_egp": cbot_impact_egp if cbot_impact_known else None,
            "cbot_gaps": cbot_gaps,
            "total_impact_egp": total_impact_egp,
        }

    # ══════════════════════════════════════════════════════════════════
    #  BASIS SERIES — physical premium vs CBOT over time.
    #  V8.7 audit enhancement: the table now keeps the full basis audit trail.
    #  Contract rows are enriched with FX, CBOT, conversion factor, CIF and
    #  own-after estimates where the app can resolve them from contract fields,
    #  snapshots, FX history or CBOT history. Market rows use the Finance-sheet
    #  convention: ((local_at_port − expenses)/FX)/factor − CBOT.
    # ══════════════════════════════════════════════════════════════════
    # Argentina and Brazil intentionally share one South-America color.
    # The point color identifies an origin group; it is not a profit/loss signal.
    _BASIS_ORIGIN_COLORS = {"BRAZIL": "#15803d", "ARGENTINA": "#15803d",
                            "USA": "#1d4ed8", "UKRAINE": "#b00020",
                            "ROMANIA": "#7c3aed"}
    _BASIS_MARKET_COLOR = "#1d4ed8"
    _BASIS_LOCAL_PURCHASE_COLOR = "#0f766e"

    def _basis_origin_legend_label(self, origin):
        org = normalize_origin(origin or "?") or "?"
        if org in ("ARGENTINA", "BRAZIL"):
            return "ARGENTINA / BRAZIL"
        return org

    def _basis_origin_color(self, origin):
        org = normalize_origin(origin or "?") or "?"
        return self._BASIS_ORIGIN_COLORS.get(org, "#334155")

    def _basis_expenses_egp_mt(self):
        """Editable basis expenses/local-cost assumption (EGP/MT).

        This is deliberately separate from Finance Brief's historic default so
        Basis Tracker can reproduce the user's Excel logic when expenses vary
        by day/deal, e.g. 850 EGP/MT instead of the old fixed 500.
        """
        ui = self.state_obj.setdefault("ui", {})
        val = to_float(ui.get("basis_expenses_egp_mt"), None)
        if val is None:
            val = self._BRIEF_LOCAL_EXPENSES_EGP_MT
            ui["basis_expenses_egp_mt"] = val
        return float(val)

    def _save_basis_expenses_from_ui(self):
        try:
            val = to_float(self.basis_expenses_var.get(), None)
            if val is None or val < 0:
                messagebox.showwarning(APP_NAME, "Enter a valid Basis expenses value (EGP/MT).")
                return
            self.state_obj.setdefault("ui", {})["basis_expenses_egp_mt"] = float(val)
            save_state(self.state_obj)
            self.refresh_basis_tracker()
        except Exception as e:
            self._surface_error("_save_basis_expenses_from_ui", e, show=True)

    def _basis_reference_mode(self):
        """Contract comparison mode for Basis Tracker.

        PRICING = judge the contract when the premium was agreed.
        DELIVERY = judge the contract against local market at arrival/delivery.
        TODAY = mark-to-market view using the latest available local/FX/CBOT data.
        """
        ui = self.state_obj.setdefault("ui", {})
        raw = ""
        try:
            raw = (getattr(self, "basis_mode_var", None).get() or "").strip()
        except Exception:
            raw = ""
        if not raw:
            raw = (ui.get("basis_reference_mode") or "Pricing Date").strip()
        norm = raw.upper().replace(" ", "_").replace("/", "_").replace("-", "_")
        if "TODAY" in norm or "MTM" in norm:
            mode, label = "TODAY", "Today / MTM"
        elif "DELIVERY" in norm or "ARRIVAL" in norm:
            mode, label = "DELIVERY", "Delivery Date"
        else:
            mode, label = "PRICING", "Pricing Date"
        ui["basis_reference_mode"] = label
        return mode, label

    def _save_basis_reference_mode_from_ui(self, *_):
        try:
            _mode, label = self._basis_reference_mode()
            self.state_obj.setdefault("ui", {})["basis_reference_mode"] = label
            save_state(self.state_obj)
            self.refresh_basis_tracker()
        except Exception as e:
            self._surface_error("_save_basis_reference_mode_from_ui", e)

    def _basis_reference_date_for_contract(self, c, mode=None):
        """Reference date for comparing a contract in Basis Tracker.

        Pricing Date mode must use the actual premium/basis agreement date.
        If that date is missing, return an explicit missing marker instead of
        silently falling back to delivery/storage.  Silent fallback was the
        reason many contract dots appeared stacked on one date.

        Delivery Date mode uses arrival/storage/delivery dates for realized
        comparison.  Today / MTM uses today's date.
        """
        if mode is None:
            mode, _label = self._basis_reference_mode()

        def _date_from_key(key):
            raw = c.get(key)
            if isinstance(raw, str):
                raw = raw.strip().split("T")[0].split(" ")[0]
            d = parse_date_flex(raw)
            return d.isoformat() if d is not None else ""

        today = dt.date.today().isoformat()
        if mode == "TODAY":
            return today, "today_mtm"

        if mode == "DELIVERY":
            primary_keys = (
                "delivery_date", "storage_start", "arrival_date", "eta",
                "discharge_date", "storage_end",
            )
            fallback_keys = (
                "form4_date", "pricing_date", "basis_date", "basis_pricing_date",
                "cbot_date", "futures_pricing_date", "contract_date", "purchase_date",
                "deal_date", "created_ts", "date",
            )
            for key in primary_keys:
                ds = _date_from_key(key)
                if ds:
                    return ds, key
            for key in fallback_keys:
                ds = _date_from_key(key)
                if ds:
                    return ds, f"fallback:{key}"
            return "", "missing_delivery_date"

        # PRICING mode: only use true pricing/deal-style fields.
        # Do not use Form 4, storage, or delivery dates here unless the user
        # explicitly saved them as pricing_date/deal_date.  This keeps the
        # chart honest: missing pricing dates stay missing instead of being
        # plotted at the wrong date.
        pricing_keys = (
            "pricing_date", "basis_date", "basis_pricing_date", "cbot_date",
            "futures_pricing_date", "contract_date", "purchase_date", "deal_date",
        )
        for key in pricing_keys:
            ds = _date_from_key(key)
            if ds:
                return ds, key
        return "", "missing_pricing_date"

    def _basis_history_lists(self, base):
        ch = sorted(((e.get("date", ""), to_float(e.get("close", e.get("price")), None))
                     for e in self.state_obj.get("cbot_history", []) or []
                     if (e.get("commodity") or "").upper() == base and e.get("date")),
                    key=lambda t: t[0])
        fxh = sorted(((e.get("date", ""), to_float(e.get("rate"), None))
                      for e in self.state_obj.get("fx_history", []) or []
                      if e.get("date")), key=lambda t: t[0])
        return ch, fxh

    def _basis_nearest_le(self, series, d):
        """Nearest value on/before d. Returns (value, date) or (None, '')."""
        best_v, best_d = None, ""
        if not d:
            return best_v, best_d
        for dd, v in series:
            if dd <= d and v is not None:
                best_v, best_d = v, dd
            elif dd > d:
                break
        return best_v, best_d

    def _basis_snapshot_for_contract(self, cid, ref_date=""):
        """Best saved calculation snapshot for a contract, if one exists."""
        snaps = []
        for s in self.state_obj.get("snapshots", []) or []:
            if str(s.get("contract_id") or "") != str(cid or ""):
                continue
            raw = (s.get("date") or s.get("ts") or "").strip()
            ds = raw.split("T")[0].split(" ")[0] if raw else ""
            if parse_date_flex(ds) is None:
                ds = ""
            snaps.append((ds, s))
        if not snaps:
            return None, ""
        if ref_date:
            before = [(d, s) for d, s in snaps if d and d <= ref_date]
            if before:
                before.sort(key=lambda x: x[0])
                return before[-1][1], before[-1][0]
        snaps.sort(key=lambda x: x[0] or "9999-12-31")
        return snaps[0][1], snaps[0][0]

    def _basis_local_at_port(self, base, ref_date):
        """Latest logged local all-in price (base + transport) on/before date."""
        best = None
        if not ref_date:
            return None, ""
        for r in self.state_obj.get("local_prices", []) or []:
            if (r.get("commodity") or "").upper().split("-")[0] != base:
                continue
            d = r.get("date", "")
            if not d or d > ref_date:
                continue
            px = to_float(r.get("price_egp_mt"), None)
            if px is None:
                continue
            trans = to_float(r.get("transport_egp_mt"), 0) or 0
            val = px + trans
            if best is None or d > best[0]:
                best = (d, val)
        return (best[1], best[0]) if best else (None, "")

    def _basis_contract_cbot(self, cid, c, base, ref_date, ch, factor, premium, cif, mode="PRICING"):
        """Resolve CBOT for a contract based on the selected Basis Tracker mode.

        Pricing mode prioritizes the deal's saved/reconstructed pricing CBOT.
        Delivery/Today modes prioritize market history for that reference date so
        the local implied basis is compared against the correct market day.
        """
        def explicit_contract_cbot():
            for key in ("pricing_cbot", "cbot_price", "cbot", "cbot_ref", "contract_cbot"):
                v = to_float(c.get(key), None)
                if v is not None:
                    d = c.get("pricing_date") or c.get("cbot_date") or ref_date
                    return v, d, f"contract {key}"
            return None, "", ""

        def snapshot_cbot():
            snap, snap_date = self._basis_snapshot_for_contract(cid, ref_date)
            if snap:
                for key in ("cbot_price", "cbot", "cbot_ref"):
                    v = to_float(snap.get(key), None)
                    if v is not None:
                        return v, snap_date or ref_date, f"snapshot {key}"
            return None, "", ""

        def reverse_cbot():
            # CIF USD/MT = (CBOT + premium) × factor  =>  CBOT = CIF/factor − premium
            if cif is not None and premium is not None and factor:
                return (cif / factor) - premium, ref_date, "computed from CIF/premium"
            return None, "", ""

        hist_cbot, hist_date = self._basis_nearest_le(ch, ref_date)

        if mode == "PRICING":
            for resolver in (explicit_contract_cbot, snapshot_cbot, reverse_cbot):
                v, d, src = resolver()
                if v is not None:
                    return v, d, src
            if hist_cbot is not None:
                return hist_cbot, hist_date, "nearest CBOT history"
        else:
            # Delivery/MTM should use the market CBOT for that comparison date.
            if hist_cbot is not None:
                return hist_cbot, hist_date, "nearest CBOT history"
            for resolver in (explicit_contract_cbot, snapshot_cbot, reverse_cbot):
                v, d, src = resolver()
                if v is not None:
                    return v, d, src + " fallback"
        return None, "", "missing"

    def _basis_contract_fx(self, cid, c, ref_date, fxh, cif, fees_egp, mode="PRICING"):
        """Resolve FX based on the selected Basis Tracker mode.

        CPC SBM policy:
        - Soybean-meal contracts are purchased without Form 4.
        - Their Basis comparison must use ONLY the specific FX stored in
          Contracts → Pricing & Savings Data → FX at delivery.
        - No nearest-history, Form 4, snapshot, or reverse-calculation fallback
          is allowed for SBM. A missing stored FX remains visibly missing.

        Other commodities keep the normal mode-based resolver order.
        """
        base_commodity = (c.get("commodity") or "").strip().upper().split("-")[0]
        if base_commodity == "SBM":
            fx = to_float(c.get("delivery_fx"), None)
            if fx is not None and fx > 0:
                return (fx, c.get("delivery_date") or ref_date,
                        "contract SBM Pricing & Savings FX")
            return None, "", "missing contract SBM Pricing & Savings FX"
        def fx_history():
            fx, fx_date = self._basis_nearest_le(fxh, ref_date)
            if fx is not None:
                return fx, fx_date, "nearest FX history"
            return None, "", ""

        def explicit_pricing_fx():
            for key in ("pricing_fx", "contract_fx", "fx_rate"):
                fx = to_float(c.get(key), None)
                if fx is not None:
                    d = c.get("pricing_date") or c.get("contract_date") or ref_date
                    return fx, d, f"contract {key}"
            return None, "", ""

        def explicit_delivery_fx():
            fx = to_float(c.get("delivery_fx"), None)
            if fx is not None:
                return fx, c.get("delivery_date") or ref_date, "contract delivery_fx"
            fx = to_float(c.get("form4_fx"), None)
            if fx is not None:
                return fx, c.get("form4_date") or ref_date, "contract form4_fx"
            return None, "", ""

        def snapshot_fx():
            snap, snap_date = self._basis_snapshot_for_contract(cid, ref_date)
            if snap:
                fx = to_float(snap.get("fx"), None)
                if fx is not None:
                    return fx, snap_date or ref_date, "snapshot fx"
            return None, "", ""

        def reverse_fx():
            own_after = to_float(c.get("own_after_egp_mt"), None)
            if own_after is not None and cif:
                fx = (own_after - fees_egp) / cif
                if fx > 0:
                    return fx, ref_date, "computed from own-after/CIF"
            return None, "", ""

        if mode == "DELIVERY":
            order = (explicit_delivery_fx, fx_history, explicit_pricing_fx, snapshot_fx, reverse_fx)
        elif mode == "TODAY":
            order = (fx_history, explicit_delivery_fx, explicit_pricing_fx, snapshot_fx, reverse_fx)
        else:  # PRICING
            order = (explicit_pricing_fx, fx_history, snapshot_fx, explicit_delivery_fx, reverse_fx)

        for resolver in order:
            fx, fx_date, src = resolver()
            if fx is not None:
                return fx, fx_date, src
        return None, "", "missing"

    def _basis_contract_price_egp_mt(self, cif_usd_mt, fx_rate):
        """Contract goods price in EGP/MT before local fees.

        This is the visible contract-price figure requested for Basis Tracker:
            CIF USD/MT × the contract FX used by the Basis comparison.
        It is deliberately separate from Own-After, which adds discharge,
        clearance, freight, and any other local costs.
        """
        cif = to_float(cif_usd_mt, None)
        fx = to_float(fx_rate, None)
        if cif is None or fx is None or fx <= 0:
            return None
        return cif * fx

    def _basis_contract_pricing_type(self, c, lots=None, saved_cif=None):
        """Classify a contract as PREMIUM or FLAT for Basis Tracker.

        Older contract records can contain ``premium_cents = 0`` as a blank
        placeholder even though the commercial deal is a flat CIF contract.
        Treat that legacy zero as FLAT when a CIF exists and there are no
        pricing lots.  An explicit pricing-type field always wins, so a true
        zero-basis premium deal can still be preserved as PREMIUM.
        """
        c = c or {}
        lots = lots or []
        explicit = str(
            c.get("pricing_type") or c.get("price_type")
            or c.get("contract_pricing_type") or ""
        ).strip().upper().replace("-", "_").replace(" ", "_")
        if explicit in {"FLAT", "FIXED", "FIXED_PRICE", "FLAT_PRICE"}:
            return "FLAT"
        if explicit in {"PREMIUM", "BASIS", "PREMIUM_BASIS", "BASIS_PREMIUM"}:
            return "PREMIUM"
        if lots:
            return "PREMIUM"
        if saved_cif is None:
            saved_cif = to_float(c.get("cif_usd_mt") or c.get("own_after_usd_mt"), None)
        premium = to_float(c.get("premium_cents"), None)
        if saved_cif is not None and (premium is None or abs(premium) <= 1e-9):
            return "FLAT"
        return "PREMIUM"

    def _basis_enriched_rows(self, base_comm="CORN", origin_filter="ALL"):
        """Build auditable Basis rows for quotations, purchases, and contracts.

        Contract behavior:
        - Non-SBM premium contracts use the stored premium/basis.
        - Non-SBM flat contracts reconstruct an equivalent basis from CIF and CBOT.
        - SBM final-price contracts compare CIF ÷ 1.1023 with the local base
          price converted by the stored contract FX; local CBOT is excluded.
        - SBM open unpriced premium contracts use current CBOT + agreed premium
          until a final CIF is entered or the contract is closed.
        - Open contracts carry a current comparison against the latest local
          reference so their position remains visible.
        """
        base = (base_comm or "CORN").upper().split("-")[0]
        origin_filter = (origin_filter or "ALL").strip().upper()
        factor = cbot_conv_factor(base)
        exp = self._basis_expenses_egp_mt()
        ch, fxh = self._basis_history_lists(base)
        ref_mode, ref_mode_label = self._basis_reference_mode()
        rows = []

        # Market-implied rows from logged local price observations.
        for r in self.state_obj.get("local_prices", []) or []:
            if (r.get("commodity") or "").upper().split("-")[0] != base:
                continue
            parsed_date = parse_date_flex(r.get("date"))
            d = parsed_date.isoformat() if parsed_date is not None else ""
            px = to_float(r.get("price_egp_mt"), None)
            if not d or px is None:
                continue
            transport = to_float(r.get("transport_egp_mt"), 0) or 0
            local_at_port = px + transport
            cbot, cbot_date = self._basis_nearest_le(ch, d)
            fx, fx_date = self._basis_nearest_le(fxh, d)
            implied = None
            comparison_metric = "BASIS"
            if base == "SBM":
                # Apple-to-apple SBM rule: the local line is the factory/local
                # commodity price converted into USD/short ton.  CBOT is kept
                # only as a reference for open premium contracts; it is not
                # subtracted from the local side.
                comparison_metric = "SBM_EQ_PRICE"
                if fx is not None and factor:
                    implied = (px / fx) / factor
            elif cbot is not None and fx is not None and factor:
                implied = ((local_at_port - exp) / fx) / factor - cbot
            missing = []
            if fx is None:
                missing.append("FX")
            if base != "SBM" and cbot is None:
                missing.append("CBOT")
            status = "Complete" if not missing else "Missing " + ", ".join(missing)
            rows.append({
                "date": d, "plot_date": d, "kind": "MARKET",
                "ref_mode": "Market history", "contract": "",
                "contract_id": "", "contract_status": "MARKET", "qty_mt": None,
                "commodity": base, "origin": "—", "local_base_egp_mt": px,
                "transport_egp_mt": transport, "local_egp_mt": local_at_port,
                "expenses_egp_mt": 0.0 if base == "SBM" else exp,
                "fx": fx, "fx_date": fx_date,
                "fx_source": "nearest FX history" if fx is not None else "missing",
                "cbot": cbot, "cbot_date": cbot_date,
                "cbot_source": "reference only" if base == "SBM" else ("nearest CBOT history" if cbot is not None else "missing"),
                "factor": factor, "contract_basis": None, "implied_basis": implied,
                "comparison_metric": comparison_metric,
                "spread": None, "cif_usd_mt": None, "own_after_egp_mt": None,
                "detail": ("local base price converted to equivalent USD/ST; CBOT excluded"
                           if base == "SBM" else "implied from logged local market price"),
                "data_status": status,
            })

        # The newest complete market row is the current comparison anchor for
        # every open contract. It remains visible when Status=Open is selected.
        complete_market_rows = [
            r for r in rows
            if (r.get("kind") or "").upper() == "MARKET"
            and r.get("implied_basis") is not None
        ]
        latest_market = max(complete_market_rows, key=lambda r: r.get("date") or "", default=None)

        # Actual local purchases are separate points from market quotations.
        for index, r in enumerate(self.state_obj.get("local_purchases", []) or [], 1):
            if (r.get("commodity") or "").upper().split("-")[0] != base:
                continue
            parsed_date = parse_date_flex(r.get("date"))
            d = parsed_date.isoformat() if parsed_date is not None else ""
            purchase_id = r.get("id")
            px = to_float(r.get("price_egp_mt"), None)
            transport = to_float(r.get("transport_egp_mt"), None)
            if transport is None:
                transport = get_commodity_freight_egp_mt(self.state_obj, base)
            local_at_port = (px + transport) if px is not None else None

            cbot = to_float(r.get("cbot_ref"), None)
            if cbot is not None:
                cbot_date, cbot_source = d, "purchase CBOT reference"
            else:
                cbot, cbot_date = self._basis_nearest_le(ch, d)
                cbot_source = "nearest CBOT history" if cbot is not None else "missing"

            fx = to_float(r.get("fx_ref"), None)
            if fx is not None:
                fx_date, fx_source = d, "purchase FX reference"
            else:
                fx, fx_date = self._basis_nearest_le(fxh, d)
                fx_source = "nearest FX history" if fx is not None else "missing"

            implied = None
            comparison_metric = "BASIS"
            if base == "SBM":
                comparison_metric = "SBM_EQ_PRICE"
                if px is not None and fx is not None and factor:
                    implied = (px / fx) / factor
            elif local_at_port is not None and cbot is not None and fx is not None and factor:
                implied = ((local_at_port - exp) / fx) / factor - cbot
            missing = []
            if not d:
                missing.append("purchase date")
            if px is None:
                missing.append("purchase price")
            if fx is None:
                missing.append("FX")
            if base != "SBM" and cbot is None:
                missing.append("CBOT")
            status = "Complete" if not missing else "Missing " + ", ".join(missing)
            supplier = (r.get("supplier") or "Unspecified supplier").strip()
            label_id = purchase_id if purchase_id not in (None, "") else index
            rows.append({
                "date": d, "plot_date": d, "kind": "LOCAL_PURCHASE",
                "ref_mode": "Purchase date", "contract": f"Local purchase #{label_id}",
                "contract_id": "", "purchase_id": purchase_id,
                "purchase_index": index, "supplier": supplier,
                "contract_status": "PURCHASED", "qty_mt": to_float(r.get("qty_mt"), None),
                "commodity": base,
                "origin": normalize_origin(r.get("origin") or "EGYPT/LOCAL") or "EGYPT/LOCAL",
                "local_base_egp_mt": px, "transport_egp_mt": transport,
                "local_egp_mt": local_at_port, "expenses_egp_mt": exp,
                "fx": fx, "fx_date": fx_date, "fx_source": fx_source,
                "cbot": cbot, "cbot_date": cbot_date, "cbot_source": cbot_source,
                "factor": factor, "contract_basis": None, "implied_basis": implied,
                "comparison_metric": comparison_metric,
                "spread": None, "cif_usd_mt": None, "own_after_egp_mt": None,
                "detail": (f"actual local purchase from {supplier} · base {fmt_num(px,0)} EGP/MT "
                           f"+ transport {fmt_num(transport,0)} EGP/MT"
                           + (f" · {r.get('note')}" if r.get("note") else "")),
                "data_status": status,
            })

        def _current_open_comparison(c, contract_basis, pricing_type, saved_cif):
            """Return the current open-contract equivalent basis versus local.

            For SBM, recompute the latest local implied Basis with the contract's
            stored Pricing & Savings FX. This keeps the open comparison on the
            same CPC-specific FX basis and never substitutes historical FX.
            """
            if not latest_market:
                return {
                    "current_market_date": "", "current_local_basis": None,
                    "current_contract_basis": None, "current_spread": None,
                    "current_position": "Needs current local basis",
                }
            current_cbot = to_float(latest_market.get("cbot"), None)
            market_basis = to_float(latest_market.get("implied_basis"), None)
            comparison_fx = to_float(latest_market.get("fx"), None)
            comparison_fx_source = latest_market.get("fx_source") or "local market FX"
            if base == "SBM":
                comparison_fx = to_float(c.get("delivery_fx"), None)
                comparison_fx_source = "contract SBM Pricing & Savings FX"
                local_all_in = to_float(latest_market.get("local_egp_mt"), None)
                if (comparison_fx is not None and comparison_fx > 0
                        and local_all_in is not None and current_cbot is not None and factor):
                    market_basis = ((local_all_in - exp) / comparison_fx) / factor - current_cbot
                else:
                    market_basis = None
            current_contract_basis = contract_basis
            # A flat price has no permanent premium. Its equivalent basis moves
            # with CBOT, so calculate it using the current market reference.
            if pricing_type == "FLAT" and saved_cif is not None and current_cbot is not None and factor:
                current_contract_basis = (saved_cif / factor) - current_cbot
            spread = None
            position = "Needs current local basis"
            if current_contract_basis is not None and market_basis is not None:
                spread = current_contract_basis - market_basis
                if spread < -0.005:
                    position = f"DOWN {abs(spread):.1f} vs local · favorable"
                elif spread > 0.005:
                    position = f"UP {spread:.1f} vs local · unfavorable"
                else:
                    position = "AT local basis"
            return {
                "current_market_date": latest_market.get("date") or "",
                "current_local_basis": market_basis,
                "current_contract_basis": current_contract_basis,
                "current_spread": spread,
                "current_position": position,
                "current_market_cbot": current_cbot,
                "current_market_fx": comparison_fx,
                "current_market_fx_source": comparison_fx_source,
                "current_market_local_egp_mt": to_float(latest_market.get("local_egp_mt"), None),
            }

        def _append_sbm_equivalent_price_row(cid, c, pricing_type, saved_cif, premium):
            """Append one apple-to-apple SBM price-comparison row.

            Final-price rule (flat contracts, closed premium contracts, or any
            open premium contract after a final CIF is entered):
                contract equivalent USD/ST = final CIF USD/MT / 1.1023
                local equivalent USD/ST    = local base EGP/MT / contract FX / 1.1023

            Open unpriced premium rule:
                contract equivalent USD/ST = current CBOT + agreed premium
                estimated CIF USD/MT        = contract equivalent × 1.1023

            CBOT is never subtracted from the local side.  Transport/freight is
            kept outside this equivalent-price spread and remains visible in
            the delivered-cost savings calculation.
            """
            contract_status = (c.get("status") or "Open").strip() or "Open"
            is_open = contract_status.upper() == "OPEN"
            fx = to_float(c.get("delivery_fx"), None)
            premium = to_float(premium, None)
            saved_cif = to_float(saved_cif, None)
            use_live_estimate = is_open and pricing_type == "PREMIUM" and saved_cif is None

            delivery_obj = parse_date_flex(c.get("delivery_date") or c.get("storage_start"))
            delivery_date = delivery_obj.isoformat() if delivery_obj is not None else ""
            local = {"date": "", "base": None, "transport": None, "all_in": None, "source": ""}
            cbot = cbot_date = ""
            cbot_value = None
            contract_equivalent = None
            comparison_method = ""
            final_or_estimated_cif = saved_cif
            ref_date = delivery_date
            ref_label = "Delivery Date · final price"

            if use_live_estimate:
                ref_label = "Current market · open premium estimate"
                if latest_market is not None:
                    ref_date = latest_market.get("date") or ""
                    local = {
                        "date": latest_market.get("date") or "",
                        "base": to_float(latest_market.get("local_base_egp_mt"), None),
                        "transport": to_float(latest_market.get("transport_egp_mt"), 0) or 0.0,
                        "all_in": to_float(latest_market.get("local_egp_mt"), None),
                        "source": f"latest SBM local price {latest_market.get('date') or ''}",
                    }
                    cbot_value = to_float(latest_market.get("cbot"), None)
                    cbot_date = latest_market.get("cbot_date") or latest_market.get("date") or ""
                if cbot_value is None and ref_date:
                    cbot_value, cbot_date = self._basis_nearest_le(ch, ref_date)
                if cbot_value is not None and premium is not None:
                    contract_equivalent = cbot_value + premium
                    final_or_estimated_cif = contract_equivalent * factor
                comparison_method = "OPEN PREMIUM ESTIMATE = current CBOT + agreed premium"
            else:
                # Final-price comparison.  Closed premium and flat contracts do
                # not require CBOT or a Pricing Date once the final CIF exists.
                if delivery_date:
                    local = self._sbm_local_price_components(c, delivery_date)
                elif latest_market is not None:
                    local = {
                        "date": latest_market.get("date") or "",
                        "base": to_float(latest_market.get("local_base_egp_mt"), None),
                        "transport": to_float(latest_market.get("transport_egp_mt"), 0) or 0.0,
                        "all_in": to_float(latest_market.get("local_egp_mt"), None),
                        "source": "latest SBM local price fallback; delivery date missing",
                    }
                    ref_date = local.get("date") or ""
                if saved_cif is not None and factor:
                    contract_equivalent = saved_cif / factor
                comparison_method = "FINAL PRICE = CIF USD/MT ÷ SBM conversion factor"

            local_base = to_float(local.get("base"), None)
            local_transport = to_float(local.get("transport"), 0) or 0.0
            local_all_in = to_float(local.get("all_in"), None)
            local_equivalent = None
            if local_base is not None and fx is not None and fx > 0 and factor:
                local_equivalent = (local_base / fx) / factor
            spread = (contract_equivalent - local_equivalent
                      if contract_equivalent is not None and local_equivalent is not None else None)

            discharge, clearance, freight = self._hd_resolve_fees(c, cid)
            contract_goods = self._basis_contract_price_egp_mt(final_or_estimated_cif, fx)
            own_after = (contract_goods + discharge + clearance + freight
                         if contract_goods is not None else None)
            saving_mt = (local_all_in - own_after
                         if local_all_in is not None and own_after is not None else None)

            missing = []
            if fx is None or fx <= 0:
                missing.append("SBM contract Pricing & Savings FX")
            if local_base is None:
                missing.append("local base price")
            if not use_live_estimate and saved_cif is None:
                missing.append("final CIF USD/MT")
            if use_live_estimate and premium is None:
                missing.append("agreed premium")
            if use_live_estimate and cbot_value is None:
                missing.append("current CBOT")
            if not use_live_estimate and not delivery_date:
                missing.append("Delivery Date")
            status_bits = ["Complete" if not missing else "Missing " + ", ".join(missing)]
            status_bits.append("SBM equivalent-price comparison; local CBOT excluded")
            if use_live_estimate:
                status_bits.append("open premium uses current CBOT + premium until final price/closure")
            else:
                status_bits.append("final CIF price used")

            position = "Needs comparable local price"
            if spread is not None:
                if spread < -0.005:
                    position = f"CHEAPER {abs(spread):.1f} USD/ST vs local · favorable"
                elif spread > 0.005:
                    position = f"HIGHER {spread:.1f} USD/ST vs local · unfavorable"
                else:
                    position = "AT local equivalent price"

            current_fields = {
                "current_market_date": local.get("date") or ref_date if is_open else "",
                "current_local_basis": local_equivalent if is_open else None,
                "current_contract_basis": contract_equivalent if is_open else None,
                "current_spread": spread if is_open else None,
                "current_position": position if is_open else "",
                "current_market_cbot": cbot_value if is_open else None,
                "current_market_fx": fx if is_open else None,
                "current_market_fx_source": "contract SBM Pricing & Savings FX" if is_open else "",
                "current_market_local_egp_mt": local_all_in if is_open else None,
            }

            rows.append({
                "date": ref_date or local.get("date") or "",
                "plot_date": local.get("date") or ref_date or "",
                "plot_basis": contract_equivalent,
                "historical_date": ref_date or local.get("date") or "",
                "historical_basis": contract_equivalent,
                "kind": "CONTRACT", "ref_mode": ref_label,
                "contract": c.get("name") or cid, "contract_id": cid,
                "contract_status": contract_status,
                "pricing_type": pricing_type,
                "basis_source": comparison_method,
                "qty_mt": to_float(c.get("qty_mt"), None),
                "commodity": "SBM", "origin": c.get("origin") or "?",
                "local_base_egp_mt": local_base,
                "transport_egp_mt": local_transport,
                "local_egp_mt": local_all_in,
                "local_date": local.get("date") or "",
                "expenses_egp_mt": 0.0,
                "fx": fx, "fx_date": c.get("delivery_date") or ref_date,
                "fx_source": ("contract SBM Pricing & Savings FX"
                              if fx is not None and fx > 0 else "missing contract SBM Pricing & Savings FX"),
                "cbot": cbot_value, "cbot_date": cbot_date,
                "cbot_source": ("current CBOT used only for open premium estimate"
                                if use_live_estimate else "not used for final-price comparison"),
                "factor": factor,
                "contract_basis": contract_equivalent,
                "implied_basis": local_equivalent,
                "spread": spread,
                "comparison_metric": "SBM_EQ_PRICE",
                "comparison_method": comparison_method,
                "cif_usd_mt": final_or_estimated_cif,
                "cif_value_type": "Estimated" if use_live_estimate else "Final",
                "contract_price_egp_mt": contract_goods,
                "contract_price_fx": fx,
                "contract_price_fx_source": "contract SBM Pricing & Savings FX",
                "discharge_egp_mt": discharge,
                "clearance_egp_mt": clearance,
                "freight_egp_mt": freight,
                "own_after_egp_mt": own_after,
                "saving_egp_mt": saving_mt,
                **current_fields,
                "detail": (f"{cid} · {pricing_type} · {comparison_method} · "
                           f"local equivalent excludes CBOT and transport · {local.get('source') or ''}"),
                "data_status": " | ".join(status_bits),
            })

        # Contract rows: premium contracts + flat-price equivalent basis.
        def _append_contract_basis_row(
                cid, c, contract_basis, ref_date, ref_source, lot_label="",
                lot_qty=None, lot_no=None, pricing_type="PREMIUM",
                basis_source="stored premium/basis", saved_cif=None,
                calculation_mode=None, row_ref_mode_label=None,
                required_date_label="Pricing Date", date_policy_note=""):
            # Some contract types use a business-specific reference date while
            # the screen remains in the global Pricing Date view.  Keep the
            # calculation mode explicit so CBOT/FX are resolved for the same
            # date shown on the chart.
            effective_calc_mode = calculation_mode or ref_mode
            effective_ref_label = row_ref_mode_label or ref_mode_label
            contract_status = (c.get("status") or "Open").strip() or "Open"
            is_open = contract_status.lower() == "open"
            saved_cif = to_float(saved_cif, None)
            current = _current_open_comparison(c, contract_basis, pricing_type, saved_cif)
            current_complete = (
                current.get("current_market_date")
                and current.get("current_contract_basis") is not None
                and current.get("current_local_basis") is not None
            )

            # In Pricing Date mode, retain the honest missing-date warning in
            # the table. Open contracts can still be charted at the latest
            # local-market date as an explicitly labelled monitor point.
            if not ref_date:
                display_fx = None
                display_fx_source = "missing stored contract FX"
                if base == "SBM":
                    display_fx = to_float(c.get("delivery_fx"), None)
                    if display_fx is not None and display_fx > 0:
                        display_fx_source = "contract SBM Pricing & Savings FX"
                else:
                    for _fx_key in ("pricing_fx", "contract_fx", "fx_rate", "delivery_fx", "form4_fx"):
                        display_fx = to_float(c.get(_fx_key), None)
                        if display_fx is not None and display_fx > 0:
                            display_fx_source = f"contract {_fx_key}"
                            break
                contract_price_egp = self._basis_contract_price_egp_mt(saved_cif, display_fx)
                status_bits = [f"Missing {required_date_label}"]
                if base == "SBM" and to_float(c.get("delivery_fx"), None) is None:
                    status_bits.append("Missing SBM contract Pricing & Savings FX")
                if contract_basis is None:
                    status_bits.append("missing premium/flat-basis reference")
                if is_open and current_complete:
                    status_bits.append("open monitor uses latest local basis")
                if date_policy_note:
                    status_bits.append(date_policy_note)
                rows.append({
                    "date": "", "plot_date": current.get("current_market_date") if is_open else "",
                    "plot_basis": current.get("current_contract_basis") if is_open else None,
                    "kind": "CONTRACT", "ref_mode": effective_ref_label,
                    "contract": c.get("name") or cid, "contract_id": cid,
                    "contract_status": contract_status,
                    "pricing_type": pricing_type, "basis_source": basis_source,
                    "qty_mt": lot_qty if lot_qty is not None else to_float(c.get("qty_mt"), None),
                    "commodity": base, "origin": c.get("origin") or "?",
                    "local_egp_mt": None, "local_date": "", "expenses_egp_mt": exp,
                    "fx": None, "fx_date": "", "fx_source": "missing",
                    "cbot": None, "cbot_date": "", "cbot_source": "missing",
                    "factor": factor, "contract_basis": contract_basis,
                    "implied_basis": None, "spread": None,
                    "cif_usd_mt": saved_cif,
                    "contract_price_egp_mt": contract_price_egp,
                    "contract_price_fx": display_fx,
                    "contract_price_fx_source": display_fx_source,
                    "own_after_egp_mt": None,
                    **current,
                    "detail": (f"{cid} · {pricing_type} · {basis_source} · mode: {effective_ref_label} · "
                               f"{ref_source}. Add a {required_date_label} for the historical dot."
                               + (f" · {date_policy_note}" if date_policy_note else "")),
                    "data_status": " | ".join(status_bits),
                })
                return

            fees_egp = sum((to_float(c.get(k), 0) or 0)
                           for k in ("discharge_egp_mt", "clearance_egp_mt", "freight_egp_mt"))
            cif = saved_cif
            if lot_no is not None and pricing_type != "FLAT":
                cif = None
            cbot, cbot_date, cbot_source = self._basis_contract_cbot(
                cid, c, base, ref_date, ch, factor, contract_basis, cif, effective_calc_mode)
            if cif is None and cbot is not None and contract_basis is not None and factor:
                cif = (cbot + contract_basis) * factor
            fx, fx_date, fx_source = self._basis_contract_fx(
                cid, c, ref_date, fxh, cif, fees_egp, effective_calc_mode)
            contract_price_egp = self._basis_contract_price_egp_mt(cif, fx)
            own_after = (contract_price_egp + fees_egp) if contract_price_egp is not None else None

            local_px, local_date = self._basis_local_at_port(base, ref_date)
            implied = None
            spread = None
            if local_px is not None and cbot is not None and fx is not None and factor:
                implied = ((local_px - exp) / fx) / factor - cbot
                if contract_basis is not None:
                    spread = contract_basis - implied

            missing = []
            if contract_basis is None:
                missing.append("contract basis")
            if fx is None:
                missing.append("SBM contract Pricing & Savings FX" if base == "SBM" else "FX")
            if cbot is None:
                missing.append("CBOT")
            status_bits = ["Complete" if not missing else "Missing " + ", ".join(missing)]
            if "nearest" in fx_source:
                status_bits.append("using nearest FX")
            if "nearest" in cbot_source:
                status_bits.append("using nearest CBOT")
            if "computed" in cbot_source or "computed" in fx_source:
                status_bits.append("computed missing refs")
            if lot_no is not None:
                status_bits.append("pricing lot")
            if pricing_type == "FLAT":
                status_bits.append("flat equivalent basis")
            if base == "SBM":
                status_bits.append("SBM uses stored Pricing & Savings FX only")
            if str(ref_source).startswith("fallback:"):
                status_bits.append(f"no pricing date; used {ref_source.split(':', 1)[1]}")
            if is_open and current_complete:
                status_bits.append("current local comparison available")
            if date_policy_note:
                status_bits.append(date_policy_note)

            detail = f"{cid} · {pricing_type} · {basis_source} · mode: {effective_ref_label} · ref: {ref_source}"
            if lot_label:
                detail += f" · {lot_label}"
            if lot_qty is not None:
                detail += f" · lot qty {fmt_num(lot_qty,0)} MT"
            if local_date:
                detail += f" · local {local_date}"
            if str(ref_source).startswith("fallback:"):
                detail += " · add pricing lots/date for true pricing view"
            if date_policy_note:
                detail += f" · {date_policy_note}"
            rows.append({
                "date": ref_date,
                "plot_date": current.get("current_market_date") if is_open and current_complete else ref_date,
                "plot_basis": current.get("current_contract_basis") if is_open and current_complete else contract_basis,
                "historical_date": ref_date, "historical_basis": contract_basis,
                "kind": "CONTRACT", "ref_mode": effective_ref_label,
                "contract": (c.get("name") or cid) + (f" Lot {lot_no}" if lot_no is not None else ""),
                "contract_id": cid, "contract_status": contract_status,
                "pricing_type": pricing_type, "basis_source": basis_source,
                "qty_mt": lot_qty if lot_qty is not None else to_float(c.get("qty_mt"), None),
                "commodity": base, "origin": c.get("origin") or "?",
                "local_egp_mt": local_px, "local_date": local_date,
                "expenses_egp_mt": exp, "fx": fx, "fx_date": fx_date,
                "fx_source": fx_source, "cbot": cbot, "cbot_date": cbot_date,
                "cbot_source": cbot_source, "factor": factor,
                "contract_basis": contract_basis, "implied_basis": implied,
                "spread": spread, "cif_usd_mt": cif,
                "contract_price_egp_mt": contract_price_egp,
                "contract_price_fx": fx, "contract_price_fx_source": fx_source,
                "own_after_egp_mt": own_after,
                **current,
                "detail": detail, "data_status": " | ".join(status_bits),
            })

        for cid, c in (self.state_obj.get("contracts", {}) or {}).items():
            if (c.get("commodity") or "").upper().split("-")[0] != base:
                continue
            corigin = normalize_origin(c.get("origin") or "")
            if origin_filter not in ("", "ALL") and corigin != origin_filter:
                continue
            lots = self._contract_pricing_lots(c)
            saved_cif = to_float(c.get("cif_usd_mt") or c.get("own_after_usd_mt"), None)
            inferred_pricing_type = self._basis_contract_pricing_type(c, lots, saved_cif)
            if base == "SBM":
                # SBM is intentionally one row per contract. Flat contracts and
                # premium contracts with a final price use the saved CIF; open
                # unpriced premium contracts use current CBOT + agreed premium.
                premium = self._weighted_pricing_lot_value(c, "premium_cents") if lots else None
                if premium is None:
                    premium = to_float(c.get("premium_cents"), None)
                _append_sbm_equivalent_price_row(
                    cid, c, inferred_pricing_type, saved_cif, premium)
                continue
            if ref_mode == "PRICING" and lots and inferred_pricing_type == "PREMIUM":
                appended = False
                for i, lot in enumerate(lots, 1):
                    prem = to_float(lot.get("premium_cents"), None)
                    if prem is None:
                        continue
                    lc = dict(c)
                    lc["pricing_date"] = lot.get("date", "")
                    if lot.get("cbot") is not None:
                        lc["pricing_cbot"] = lot.get("cbot")
                    if lot.get("fx") is not None:
                        lc["pricing_fx"] = lot.get("fx")
                    if lot.get("futures_month"):
                        lc["futures_month"] = lot.get("futures_month")
                    _append_contract_basis_row(
                        cid, lc, prem, lot.get("date", ""), f"pricing_lot_{i}",
                        lot_label=f"pricing lot {i}", lot_qty=lot.get("qty_mt"), lot_no=i,
                        pricing_type="PREMIUM", basis_source="pricing-lot premium",
                        saved_cif=to_float(c.get("cif_usd_mt") or c.get("own_after_usd_mt"), None))
                    appended = True
                if appended:
                    continue

            ref_date, ref_source = self._basis_reference_date_for_contract(c, ref_mode)
            prem = self._weighted_pricing_lot_value(c, "premium_cents") if lots and ref_mode != "PRICING" else None
            if prem is None:
                prem = to_float(c.get("premium_cents"), None)
            pricing_type = inferred_pricing_type
            basis_source = "stored premium/basis"
            calculation_mode = ref_mode
            row_ref_mode_label = ref_mode_label
            required_date_label = "Pricing Date"
            date_policy_note = ""

            # Flat contract support: derive its equivalent basis from its saved
            # flat CIF and the CBOT reference for the selected date. For an open
            # contract without a pricing date, use the latest local CBOT only for
            # the explicitly-labelled current monitor point.
            if pricing_type == "FLAT" and saved_cif is not None and factor:
                # Ignore a legacy zero premium placeholder. Flat contracts are
                # reconstructed from CIF and CBOT, not from the placeholder.
                prem = None
                basis_source = "flat CIF equivalent"

                # CPC policy: in the global Pricing Date view, an SBM flat
                # contract is anchored to its Delivery Date.  A flat deal has
                # no premium-fixation date, so delivery is the approved date
                # for reconstructing its equivalent Basis.  This exception is
                # deliberately limited to SBM + FLAT; premium SBM and every
                # other commodity keep the selected global reference mode.
                if base == "SBM" and ref_mode == "PRICING":
                    raw_delivery = c.get("delivery_date")
                    delivery_obj = parse_date_flex(raw_delivery)
                    if delivery_obj is not None:
                        ref_date = delivery_obj.isoformat()
                        ref_source = "delivery_date_for_sbm_flat"
                    else:
                        ref_date = ""
                        ref_source = "missing_delivery_date_for_sbm_flat"
                    calculation_mode = "DELIVERY"
                    row_ref_mode_label = "Delivery Date (SBM flat policy)"
                    required_date_label = "Delivery Date"
                    date_policy_note = "SBM flat uses Delivery Date"

                cbot_for_basis = None
                cbot_basis_source = "missing CBOT"
                if ref_date:
                    cbot_for_basis, _d, cbot_basis_source = self._basis_contract_cbot(
                        cid, c, base, ref_date, ch, factor, None, saved_cif, calculation_mode)
                elif latest_market is not None:
                    cbot_for_basis = to_float(latest_market.get("cbot"), None)
                    cbot_basis_source = "latest local-market CBOT for open monitor"
                if cbot_for_basis is not None:
                    prem = (saved_cif / factor) - cbot_for_basis
                    basis_source = f"flat CIF equivalent · {cbot_basis_source}"

            if lots and ref_mode != "PRICING":
                ref_source = f"{ref_source}; weighted {len(lots)} pricing lots"
            _append_contract_basis_row(
                cid, c, prem, ref_date, ref_source,
                pricing_type=pricing_type, basis_source=basis_source,
                saved_cif=saved_cif, calculation_mode=calculation_mode,
                row_ref_mode_label=row_ref_mode_label,
                required_date_label=required_date_label,
                date_policy_note=date_policy_note)

        kind_order = {"MARKET": 0, "LOCAL_PURCHASE": 1, "CONTRACT": 2}
        rows.sort(key=lambda r: (
            r.get("plot_date") or r.get("date") or "",
            kind_order.get((r.get("kind") or "").upper(), 9),
            r.get("contract") or ""))
        return rows

    def basis_series(self, base_comm="CORN", origin_filter="ALL"):
        """Backward-compatible return for chart/buy-signal logic.

        Returns:
          contract_pts = [(date, origin, premium_cents, label)]
          implied_pts  = [(date, implied_premium)]
        """
        rows = self._basis_enriched_rows(base_comm, origin_filter)
        contract_pts = [((r.get("plot_date") or r.get("date")), r.get("origin") or "?",
                         r.get("plot_basis") if r.get("plot_basis") is not None else r.get("contract_basis"),
                         r.get("contract") or "")
                        for r in rows if (r.get("kind") or "").upper() == "CONTRACT"
                        and (r.get("plot_date") or r.get("date"))
                        and (r.get("plot_basis") is not None or r.get("contract_basis") is not None)]
        implied_pts = [(r["date"], r.get("implied_basis"))
                       for r in rows if (r.get("kind") or "").upper() == "MARKET"
                       and r.get("implied_basis") is not None]
        contract_pts.sort(); implied_pts.sort()
        return contract_pts, implied_pts

    def _sbm_delivery_market_fx(self, delivery_date):
        """Nearest historical market FX on/before an SBM delivery date.

        This is a reference rate for management comparison only. SBM contract
        price, savings, and Basis calculations continue to use the contract's
        specific Pricing & Savings FX stored in ``delivery_fx``.
        """
        d = parse_date_flex(delivery_date)
        if d is None:
            return None, "", "missing delivery date"
        _cbot_history, fx_history = self._basis_history_lists("SBM")
        value, source_date = self._basis_nearest_le(fx_history, d.isoformat())
        if value is None:
            return None, "", "missing FX history on/before delivery"
        return value, source_date, "nearest FX history on/before delivery"

    def _sbm_local_price_components(self, contract, delivery_date):
        """Return the auditable local price matched to an SBM delivery date."""
        all_in, commodity_key, local_date = self._hd_local_for_contract(
            contract, delivery_date, latest=False)
        if all_in is None:
            return {
                "commodity_key": commodity_key or "SBM", "date": local_date or "",
                "base": None, "transport": None, "all_in": None,
                "source": "missing local price on/before delivery",
            }
        base_price = transport = None
        for record in self.state_obj.get("local_prices", []) or []:
            if (record.get("commodity") or "").upper() != (commodity_key or "SBM").upper():
                continue
            if (record.get("date") or "") != local_date:
                continue
            base_price = to_float(record.get("price_egp_mt"), None)
            transport = to_float(record.get("transport_egp_mt"), None)
            if transport is None:
                transport = get_default_local_transport_egp_mt(self.state_obj)
            break
        if base_price is None:
            # _hd_local_for_contract already resolved the all-in value. Preserve
            # it even when an older state lacks separate base/transport fields.
            base_price = all_in
            transport = 0.0
        return {
            "commodity_key": commodity_key or "SBM", "date": local_date,
            "base": base_price, "transport": transport or 0.0, "all_in": all_in,
            "source": f"{commodity_key or 'SBM'} local price carried forward from {local_date}",
        }

    def _collect_sbm_contract_vs_local_rows(self, origin_filter="ALL", status_filter="ALL"):
        """One management row per SBM contract plus pricing-lot Basis detail.

        Price/savings rules:
          contract goods EGP/MT = CIF USD/MT × stored SBM contract FX
          own-after EGP/MT      = contract goods + discharge + clearance + freight
          saving EGP/MT         = matched local all-in − own-after

        Equivalent-price spread rules:
          final flat/closed/priced contract = CIF ÷ 1.1023
          open unpriced premium             = current CBOT + agreed premium
          equivalent local                  = local base ÷ stored contract FX ÷ 1.1023
        CBOT is not subtracted from the local side.
        """
        origin_filter = (origin_filter or "ALL").strip().upper()
        status_filter = (status_filter or "ALL").strip().upper()
        basis_all = self._basis_enriched_rows("SBM", origin_filter)
        basis_detail = [r for r in basis_all if (r.get("kind") or "").upper() == "CONTRACT"]
        by_contract = {}
        for row in basis_detail:
            by_contract.setdefault(str(row.get("contract_id") or ""), []).append(row)

        output = []
        contracts = self.state_obj.get("contracts", {}) or {}
        ordered = sorted(contracts.items(), key=lambda item: (
            item[1].get("delivery_date") or item[1].get("storage_start") or "",
            item[1].get("name") or item[0]))
        for cid, c in ordered:
            base = (c.get("commodity") or "").strip().upper().split("-")[0]
            if base != "SBM":
                continue
            origin = normalize_origin(c.get("origin") or "")
            if origin_filter not in ("", "ALL") and origin != origin_filter:
                continue
            contract_status = (c.get("status") or "Open").strip() or "Open"
            if status_filter not in ("", "ALL") and contract_status.upper() != status_filter:
                continue

            delivery_obj = parse_date_flex(c.get("delivery_date") or c.get("storage_start"))
            delivery_date = delivery_obj.isoformat() if delivery_obj is not None else ""
            qty = to_float(c.get("qty_mt"), None)
            cif = self._contract_cif_usd(c, cid)
            contract_fx = to_float(c.get("delivery_fx"), None)
            delivery_fx, delivery_fx_date, delivery_fx_source = self._sbm_delivery_market_fx(delivery_date)
            discharge, clearance, freight = self._hd_resolve_fees(c, cid)
            local = self._sbm_local_price_components(c, delivery_date)
            pricing_lots = self._contract_pricing_lots(c)
            pricing_type = self._basis_contract_pricing_type(c, pricing_lots, cif)

            contract_basis_rows = by_contract.get(str(cid), [])
            metric_row = contract_basis_rows[0] if contract_basis_rows else {}
            contract_equivalent = to_float(metric_row.get("contract_basis"), None)
            local_equivalent = to_float(metric_row.get("implied_basis"), None)
            equivalent_spread = to_float(metric_row.get("spread"), None)
            basis_dates = sorted({
                (r.get("historical_date") or r.get("date") or "")
                for r in contract_basis_rows
                if (r.get("historical_date") or r.get("date") or "")
            })
            basis_status = sorted({
                str(r.get("data_status") or "") for r in contract_basis_rows
                if str(r.get("data_status") or "").strip()
            })

            # Use the exact Basis Tracker comparison row so the export cannot
            # disagree with the screen. Open unpriced premium contracts carry
            # an estimated CIF from current CBOT + premium; final-priced rows
            # carry the saved CIF.
            row_cif = to_float(metric_row.get("cif_usd_mt"), None)
            if row_cif is not None:
                cif = row_cif
            local = {
                "date": metric_row.get("local_date") or metric_row.get("date") or "",
                "base": to_float(metric_row.get("local_base_egp_mt"), None),
                "transport": to_float(metric_row.get("transport_egp_mt"), 0) or 0.0,
                "all_in": to_float(metric_row.get("local_egp_mt"), None),
                "source": (metric_row.get("detail") or "SBM equivalent-price comparison row"),
            }
            contract_goods = to_float(metric_row.get("contract_price_egp_mt"), None)
            own_after = to_float(metric_row.get("own_after_egp_mt"), None)
            saving_mt = to_float(metric_row.get("saving_egp_mt"), None)
            total_saving = (saving_mt * qty
                            if saving_mt is not None and qty is not None else None)
            cif_value_type = metric_row.get("cif_value_type") or ("Final" if cif is not None else "Missing")

            quality = []
            if contract_fx is None or contract_fx <= 0:
                quality.append("Missing stored SBM contract FX")
            if delivery_fx is None:
                quality.append("Missing delivery-date market FX history")
            if local.get("base") is None:
                quality.append("Missing local base price")
            if qty is None or qty <= 0:
                quality.append("Missing quantity")
            if contract_equivalent is None or local_equivalent is None:
                quality.append("Incomplete equivalent-price comparison")
            if "MISSING" in str(metric_row.get("data_status") or "").upper():
                quality.append(str(metric_row.get("data_status") or ""))

            output.append({
                "contract_id": cid,
                "contract": c.get("contract_ref") or c.get("name") or cid,
                "supplier": c.get("supplier") or "",
                "origin": c.get("origin") or "",
                "status": contract_status,
                "value_type": ("Realized" if contract_status.upper() == "CLOSED"
                               else ("Indicative / open" if cif_value_type == "Estimated" else "Priced / open")),
                "delivery_date": delivery_date,
                "local_date": local.get("date") or "",
                "pricing_type": pricing_type,
                "basis_ref_date": ", ".join(basis_dates),
                "comparison_method": metric_row.get("comparison_method") or metric_row.get("basis_source") or "",
                "cif_value_type": cif_value_type,
                "qty_mt": qty,
                "cif_usd_mt": cif,
                "contract_fx": contract_fx,
                "delivery_market_fx": delivery_fx,
                "delivery_market_fx_date": delivery_fx_date,
                "contract_goods_egp_mt": contract_goods,
                "discharge_egp_mt": discharge,
                "clearance_egp_mt": clearance,
                "freight_egp_mt": freight,
                "own_after_egp_mt": own_after,
                "local_base_egp_mt": local.get("base"),
                "local_transport_egp_mt": local.get("transport"),
                "local_all_in_egp_mt": local.get("all_in"),
                "saving_egp_mt": saving_mt,
                "total_saving_egp": total_saving,
                "contract_basis": contract_equivalent,
                "local_implied_basis": local_equivalent,
                "basis_spread": equivalent_spread,
                "contract_equivalent_usd_st": contract_equivalent,
                "local_equivalent_usd_st": local_equivalent,
                "equivalent_price_spread": equivalent_spread,
                "local_source": local.get("source") or "",
                "contract_fx_source": "Contracts → Pricing & Savings Data → FX at delivery",
                "delivery_fx_source": delivery_fx_source,
                "data_quality": "Complete" if not quality else " | ".join(quality),
                "notes": ("Equivalent-price spread excludes CBOT from the local side. "
                          "Final flat/closed or priced contracts use CIF ÷ 1.1023; open unpriced premium contracts use current CBOT + premium. "
                          "Delivery-date FX is reference only; stored contract FX drives the comparison."
                          + (" Status: " + " || ".join(basis_status) if basis_status else "")),
            })
        return output, basis_detail

    def _build_sbm_contract_vs_local_workbook(self, rows, basis_detail_rows=None, filter_note=""):
        """Build the dedicated SBM contract-versus-local management workbook."""
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from openpyxl.utils import get_column_letter
        from openpyxl.formatting.rule import CellIsRule, FormulaRule
        from openpyxl.chart import BarChart, Reference

        wb = Workbook()
        try:
            wb.calculation.fullCalcOnLoad = True
            wb.calculation.forceFullCalc = True
        except Exception:
            pass
        navy = "17365D"; blue = "1F4E78"; pale_blue = "D9EAF7"
        green = "E2F0D9"; red = "FCE4D6"; amber = "FFF2CC"; grey = "E7E6E6"
        white = "FFFFFF"; thin = Side(style="thin", color="C9D2E3")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)

        summary = wb.active
        summary.title = "Summary"
        summary.merge_cells("A1:F1")
        summary["A1"] = "CAIRO POULTRY GROUP — SBM CONTRACTS VS LOCAL"
        summary["A1"].font = Font(bold=True, size=16, color=white)
        summary["A1"].fill = PatternFill("solid", fgColor=navy)
        summary["A1"].alignment = Alignment(horizontal="center")
        summary.merge_cells("A2:F2")
        summary["A2"] = f"Generated {now_ts()}" + (f" · {filter_note}" if filter_note else "")
        summary["A2"].font = Font(italic=True, color="64748B")
        summary["A2"].alignment = Alignment(horizontal="center")

        ws = wb.create_sheet("SBM vs Local")
        headers = [
            "Contract No.", "Supplier", "Origin", "Status", "Value Type",
            "Delivery Date", "Matched Local Date", "Pricing Type", "Comparison Date",
            "Qty MT", "CIF USD/MT", "Contract FX EGP/USD",
            "Delivery-Date FX EGP/USD", "FX Difference",
            "Contract Goods EGP/MT", "Discharge EGP/MT", "Clearance EGP/MT",
            "Freight EGP/MT", "Own-After EGP/MT", "Local Base EGP/MT",
            "Local Transport EGP/MT", "Local All-in EGP/MT", "Saving EGP/MT",
            "Total Saving EGP", "Contract Eq USD/ST", "Local Eq USD/ST",
            "Price Spread USD/ST", "Price Position", "Local Price Source",
            "Contract FX Source", "Delivery-Date FX Source", "Data Quality", "Notes",
        ]
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(headers))
        ws.cell(1, 1, "SBM CONTRACTS AGAINST LOCAL MARKET — SAVINGS & EQUIVALENT-PRICE SPREAD")
        ws.cell(1, 1).font = Font(bold=True, size=14, color=white)
        ws.cell(1, 1).fill = PatternFill("solid", fgColor=navy)
        ws.cell(1, 1).alignment = Alignment(horizontal="center")
        ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=len(headers))
        ws.cell(2, 1, "Final prices use CIF ÷ 1.1023; open unpriced premiums use current CBOT + premium. Local CBOT is excluded.")
        ws.cell(2, 1).font = Font(italic=True, color="44546A")
        ws.cell(2, 1).alignment = Alignment(horizontal="center")
        header_row = 4
        for col, heading in enumerate(headers, 1):
            cell = ws.cell(header_row, col, heading)
            cell.font = Font(bold=True, color=white, size=9)
            cell.fill = PatternFill("solid", fgColor=blue)
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.border = border

        first_data_row = header_row + 1
        for row_no, record in enumerate(rows, first_data_row):
            static_values = [
                record.get("contract"), record.get("supplier"), record.get("origin"),
                record.get("status"), record.get("value_type"), record.get("delivery_date"),
                record.get("local_date"), record.get("pricing_type"), record.get("basis_ref_date"),
                record.get("qty_mt"), record.get("cif_usd_mt"), record.get("contract_fx"),
                record.get("delivery_market_fx"), None, None,
                record.get("discharge_egp_mt"), record.get("clearance_egp_mt"),
                record.get("freight_egp_mt"), None, record.get("local_base_egp_mt"),
                record.get("local_transport_egp_mt"), None, None, None,
                record.get("contract_basis"), record.get("local_implied_basis"), None, None,
                record.get("local_source"), record.get("contract_fx_source"),
                (f"{record.get('delivery_fx_source','')} {record.get('delivery_market_fx_date','')}".strip()),
                record.get("data_quality"), record.get("notes"),
            ]
            for col, value in enumerate(static_values, 1):
                cell = ws.cell(row_no, col, value)
                cell.border = border
                cell.alignment = Alignment(vertical="top", wrap_text=col in (9, 28, 29, 30, 31, 32, 33))
            ws.cell(row_no, 14, f'=IF(AND(ISNUMBER(L{row_no}),ISNUMBER(M{row_no})),L{row_no}-M{row_no},"")')
            ws.cell(row_no, 15, f'=IF(AND(ISNUMBER(K{row_no}),ISNUMBER(L{row_no})),K{row_no}*L{row_no},"")')
            ws.cell(row_no, 19, f'=IF(ISNUMBER(O{row_no}),SUM(O{row_no}:R{row_no}),"")')
            ws.cell(row_no, 22, f'=IF(ISNUMBER(T{row_no}),T{row_no}+IF(ISNUMBER(U{row_no}),U{row_no},0),"")')
            ws.cell(row_no, 23, f'=IF(AND(ISNUMBER(V{row_no}),ISNUMBER(S{row_no})),V{row_no}-S{row_no},"")')
            ws.cell(row_no, 24, f'=IF(AND(ISNUMBER(W{row_no}),ISNUMBER(J{row_no})),W{row_no}*J{row_no},"")')
            ws.cell(row_no, 27, f'=IF(AND(ISNUMBER(Y{row_no}),ISNUMBER(Z{row_no})),Y{row_no}-Z{row_no},"")')
            ws.cell(row_no, 28, f'=IF(ISNUMBER(AA{row_no}),IF(AA{row_no}<=0,"Favorable / contract cheaper than local","Unfavorable / contract higher than local"),"Missing comparison")')
            for col in range(1, len(headers) + 1):
                ws.cell(row_no, col).border = border

        last_data_row = max(first_data_row, first_data_row + len(rows) - 1)
        ws.freeze_panes = f"A{first_data_row}"
        ws.auto_filter.ref = f"A{header_row}:AG{last_data_row}"
        for col in (10, 16, 17, 18):
            for r in range(first_data_row, last_data_row + 1):
                ws.cell(r, col).number_format = '#,##0.00'
        for col in (11, 12, 13, 14):
            for r in range(first_data_row, last_data_row + 1):
                ws.cell(r, col).number_format = '#,##0.0000'
        for col in (15, 19, 20, 21, 22, 23):
            for r in range(first_data_row, last_data_row + 1):
                ws.cell(r, col).number_format = '#,##0.00'
        for r in range(first_data_row, last_data_row + 1):
            ws.cell(r, 24).number_format = '#,##0'
            for col in (25, 26, 27):
                ws.cell(r, col).number_format = '#,##0.00'
        if rows:
            ws.conditional_formatting.add(
                f"W{first_data_row}:X{last_data_row}",
                CellIsRule(operator="greaterThanOrEqual", formula=["0"], fill=PatternFill("solid", fgColor=green)))
            ws.conditional_formatting.add(
                f"W{first_data_row}:X{last_data_row}",
                CellIsRule(operator="lessThan", formula=["0"], fill=PatternFill("solid", fgColor=red)))
            ws.conditional_formatting.add(
                f"AA{first_data_row}:AA{last_data_row}",
                CellIsRule(operator="lessThanOrEqual", formula=["0"], fill=PatternFill("solid", fgColor=green)))
            ws.conditional_formatting.add(
                f"AA{first_data_row}:AA{last_data_row}",
                CellIsRule(operator="greaterThan", formula=["0"], fill=PatternFill("solid", fgColor=red)))
            ws.conditional_formatting.add(
                f"AF{first_data_row}:AF{last_data_row}",
                FormulaRule(formula=[f'ISNUMBER(SEARCH("Missing",AF{first_data_row}))'],
                            fill=PatternFill("solid", fgColor=amber)))

        widths = [18, 20, 12, 10, 16, 12, 14, 12, 22, 11, 12, 15, 18, 12,
                  17, 14, 14, 13, 17, 16, 18, 17, 15, 18, 13, 16, 13, 28,
                  30, 36, 36, 34, 55]
        for idx, width in enumerate(widths, 1):
            ws.column_dimensions[get_column_letter(idx)].width = width
        ws.row_dimensions[header_row].height = 42

        # KPI Summary
        data_ref = "'SBM vs Local'"
        summary_items = [
            ("Contracts", f'=COUNTA({data_ref}!A{first_data_row}:A{last_data_row})', "0"),
            ("Total Quantity MT", f'=SUM({data_ref}!J{first_data_row}:J{last_data_row})', '#,##0'),
            ("Closed / Realized Saving EGP", f'=SUMIF({data_ref}!D{first_data_row}:D{last_data_row},"Closed",{data_ref}!X{first_data_row}:X{last_data_row})', '#,##0'),
            ("Open / Indicative Saving EGP", f'=SUMIF({data_ref}!D{first_data_row}:D{last_data_row},"Open",{data_ref}!X{first_data_row}:X{last_data_row})', '#,##0'),
            ("Weighted Saving EGP/MT", f'=IFERROR(SUMPRODUCT({data_ref}!W{first_data_row}:W{last_data_row},{data_ref}!J{first_data_row}:J{last_data_row})/SUM({data_ref}!J{first_data_row}:J{last_data_row}),"")', '#,##0.00'),
            ("Weighted Price Spread USD/ST", f'=IFERROR(SUMPRODUCT({data_ref}!AA{first_data_row}:AA{last_data_row},{data_ref}!J{first_data_row}:J{last_data_row})/SUMIF({data_ref}!AA{first_data_row}:AA{last_data_row},"<>",{data_ref}!J{first_data_row}:J{last_data_row}),"")', '#,##0.00'),
            ("Average Contract FX", f'=IFERROR(AVERAGE({data_ref}!L{first_data_row}:L{last_data_row}),"")', '#,##0.0000'),
            ("Average Delivery-Date FX", f'=IFERROR(AVERAGE({data_ref}!M{first_data_row}:M{last_data_row}),"")', '#,##0.0000'),
        ]
        for idx, (label, formula, number_format) in enumerate(summary_items, 4):
            summary.cell(idx, 1, label).font = Font(bold=True, color="44546A")
            summary.cell(idx, 1).fill = PatternFill("solid", fgColor=pale_blue)
            summary.cell(idx, 1).border = border
            summary.cell(idx, 2, formula).font = Font(bold=True, color=navy, size=12)
            summary.cell(idx, 2).number_format = number_format
            summary.cell(idx, 2).border = border
        summary.merge_cells("A14:F14")
        summary["A14"] = ("Policy: final flat/closed/priced contracts use final CIF ÷ 1.1023; open unpriced premiums use "
                          "current CBOT + premium. Local equivalent price uses local base ÷ stored contract FX ÷ 1.1023, "
                          "with no CBOT subtraction. Delivery-date FX is reference only.")
        summary["A14"].fill = PatternFill("solid", fgColor=amber)
        summary["A14"].alignment = Alignment(wrap_text=True)
        summary["A14"].font = Font(bold=True, color="7F6000")
        summary.row_dimensions[14].height = 42
        summary.column_dimensions["A"].width = 35
        summary.column_dimensions["B"].width = 22
        for col in "CDEF":
            summary.column_dimensions[col].width = 15

        if rows:
            chart_last = min(last_data_row, first_data_row + 14)
            chart = BarChart()
            chart.type = "bar"
            chart.style = 10
            chart.title = "Saving EGP/MT — first 15 exported contracts"
            chart.y_axis.title = "Contract"
            chart.x_axis.title = "EGP/MT"
            chart.height = 8
            chart.width = 15
            chart.add_data(Reference(ws, min_col=23, min_row=header_row, max_row=chart_last), titles_from_data=True)
            chart.set_categories(Reference(ws, min_col=1, min_row=first_data_row, max_row=chart_last))
            summary.add_chart(chart, "D4")

        detail = wb.create_sheet("Equivalent Price Detail")
        detail_headers = [
            "Reference Date", "Contract", "Contract ID", "Status", "Pricing Type",
            "Qty MT", "Contract Eq USD/ST", "Local Eq USD/ST", "Price Spread USD/ST",
            "Local EGP/MT", "Contract FX", "FX Source", "CBOT", "CBOT Source",
            "CIF USD/MT", "Contract EGP/MT", "Reference Mode", "Data Quality", "Detail",
        ]
        for col, heading in enumerate(detail_headers, 1):
            cell = detail.cell(1, col, heading)
            cell.font = Font(bold=True, color=white)
            cell.fill = PatternFill("solid", fgColor=blue)
            cell.alignment = Alignment(horizontal="center", wrap_text=True)
            cell.border = border
        for row_no, record in enumerate(basis_detail_rows or [], 2):
            values = [
                record.get("historical_date") or record.get("date"), record.get("contract"),
                record.get("contract_id"), record.get("contract_status"), record.get("pricing_type"),
                record.get("qty_mt"), record.get("contract_basis"), record.get("implied_basis"),
                record.get("spread"), record.get("local_egp_mt"), record.get("fx"),
                f"{record.get('fx_source','')} {record.get('fx_date','')}".strip(),
                record.get("cbot"), f"{record.get('cbot_source','')} {record.get('cbot_date','')}".strip(),
                record.get("cif_usd_mt"), record.get("contract_price_egp_mt"),
                record.get("ref_mode"), record.get("data_status"), record.get("detail"),
            ]
            for col, value in enumerate(values, 1):
                cell = detail.cell(row_no, col, value)
                cell.border = border
                cell.alignment = Alignment(vertical="top", wrap_text=col in (12, 14, 18, 19))
            for col in (6, 7, 8, 9, 10, 13, 15, 16):
                detail.cell(row_no, col).number_format = '#,##0.00'
            detail.cell(row_no, 11).number_format = '#,##0.0000'
        detail.freeze_panes = "A2"
        if detail.max_row >= 1:
            detail.auto_filter.ref = f"A1:S{detail.max_row}"
        detail_widths = [14, 24, 15, 10, 12, 11, 14, 16, 13, 15, 12, 34, 11, 34, 12, 16, 18, 38, 55]
        for idx, width in enumerate(detail_widths, 1):
            detail.column_dimensions[get_column_letter(idx)].width = width

        assumptions = wb.create_sheet("Method & Assumptions")
        assumptions["A1"] = "SBM apple-to-apple equivalent-price methodology"
        assumptions["A1"].font = Font(bold=True, size=14, color=navy)
        method_rows = [
            ("Contract FX", "Stored Contracts → Pricing & Savings Data → FX at delivery (delivery_fx)."),
            ("Delivery-Date FX", "Nearest historical FX on or before Delivery Date; visibility/reference only."),
            ("Contract Goods EGP/MT", "CIF USD/MT × Contract FX"),
            ("Own-After EGP/MT", "Contract Goods + Discharge + Clearance + Freight"),
            ("Matched Local", "Latest logged SBM local all-in price on or before Delivery Date."),
            ("Saving EGP/MT", "Local All-in − Own-After"),
            ("Total Saving EGP", "Saving EGP/MT × Contract Quantity MT"),
            ("Equivalent Price Spread", "Contract Eq USD/ST − Local Eq USD/ST; negative/zero is favorable."),
            ("Final flat / priced comparison", "Final CIF USD/MT ÷ 1.1023 versus local base price converted with the stored contract FX."),
            ("Open unpriced premium comparison", "Current CBOT + agreed premium until a final CIF is entered or the contract is closed."),
            ("SBM conversion factor", SBM_ST_PER_MT),
            ("Local CBOT and Basis expenses", "Not used in the SBM equivalent-price comparison."),
            ("Local price basis", "Local base EGP/MT ÷ stored contract FX ÷ 1.1023; CBOT is not subtracted."),
            ("Export filters", filter_note or "All SBM contracts"),
        ]
        for row_no, (key, value) in enumerate(method_rows, 3):
            assumptions.cell(row_no, 1, key).font = Font(bold=True, color="44546A")
            assumptions.cell(row_no, 1).fill = PatternFill("solid", fgColor=grey)
            assumptions.cell(row_no, 1).border = border
            assumptions.cell(row_no, 2, value).border = border
            assumptions.cell(row_no, 2).alignment = Alignment(wrap_text=True)
        assumptions.column_dimensions["A"].width = 32
        assumptions.column_dimensions["B"].width = 95
        return wb

    def export_sbm_vs_local_excel(self):
        """Export SBM contracts against matched local prices with savings/equivalent-price spread."""
        if not _need_openpyxl():
            return
        try:
            origin = (self.basis_origin_var.get()
                      if hasattr(self, "basis_origin_var") else "ALL") or "ALL"
            status = (self.basis_status_var.get()
                      if hasattr(self, "basis_status_var") else "ALL") or "ALL"
            rows, basis_detail = self._collect_sbm_contract_vs_local_rows(origin, status)
            if not rows:
                messagebox.showinfo(
                    APP_NAME,
                    "No SBM contracts match the current Origin and Status filters.")
                return
            filter_note = (f"SBM; origin={origin}; status={status}; "
                           "SBM equivalent-price policy")
            workbook = self._build_sbm_contract_vs_local_workbook(
                rows, basis_detail, filter_note)
            out = filedialog.asksaveasfilename(
                title="Export SBM Contracts vs Local",
                initialdir=get_default_export_dir(),
                initialfile=f"SBM_Contracts_vs_Local_{dt.date.today().isoformat()}.xlsx",
                defaultextension=".xlsx",
                filetypes=[("Excel Workbook", "*.xlsx")])
            if not out:
                return
            workbook.save(out)
            messagebox.showinfo(
                APP_NAME,
                f"Exported {len(rows)} SBM contract(s) against local market:\n{out}")
        except Exception as exc:
            self._surface_error("export_sbm_vs_local_excel", exc, show=True)

    def export_basis_excel(self):
        """Use the single audited exporter for Basis and SBM equivalent-price rows."""
        return self.export_basis_tracker_excel()

    def _basis_filter_date_cutoff(self):
        label = (getattr(self, "basis_date_range_var", None).get()
                 if hasattr(self, "basis_date_range_var") else "1Y")
        label = (label or "1Y").strip().upper()
        days = {"30D": 30, "90D": 90, "1Y": 365}.get(label)
        if days is None:
            return ""
        return (dt.date.today() - dt.timedelta(days=days)).isoformat()

    def _basis_apply_accessibility_filters(self, rows):
        """Apply quick-access filters without changing Basis calculations."""
        search = ((self.basis_search_var.get() if hasattr(self, "basis_search_var") else "") or "").strip().lower()
        status = ((self.basis_status_var.get() if hasattr(self, "basis_status_var") else "ALL") or "ALL").strip().upper()
        row_view = ((self.basis_row_view_var.get() if hasattr(self, "basis_row_view_var") else "Both") or "Both").strip().upper()
        missing_only = bool(self.basis_missing_only_var.get()) if hasattr(self, "basis_missing_only_var") else False
        cutoff = self._basis_filter_date_cutoff()
        out = []
        for r in rows or []:
            kind = (r.get("kind") or "").upper()
            is_contract = kind == "CONTRACT"
            is_market = kind == "MARKET"
            is_purchase = kind == "LOCAL_PURCHASE"
            if row_view.startswith("CONTRACT") and not is_contract:
                continue
            if (row_view.startswith("MARKET") or row_view.startswith("LOCAL MARKET")) and not is_market:
                continue
            if row_view.startswith("LOCAL PURCHASE") and not is_purchase:
                continue
            if status != "ALL" and is_contract:
                if (r.get("contract_status") or "Open").strip().upper() != status:
                    continue
            # Open-monitor points use the latest market date; historical rows
            # retain their true contract reference date.
            ds = (r.get("plot_date") or r.get("date") or "").strip()
            if cutoff and ds and ds < cutoff:
                continue
            data_status = str(r.get("data_status") or "")
            if missing_only and "MISSING" not in data_status.upper():
                continue
            if search:
                hay = " ".join(str(r.get(k) or "") for k in (
                    "contract_id", "contract", "purchase_id", "supplier", "origin",
                    "commodity", "contract_status", "pricing_type", "current_position",
                    "date", "plot_date", "data_status", "detail", "ref_mode"
                )).lower()
                if search not in hay:
                    continue
            out.append(r)
        return out

    def _basis_contract_display_status(self, r):
        if (r.get("kind") or "").upper() != "CONTRACT":
            return "Market reference"
        raw = str(r.get("data_status") or "")
        if "MISSING" in raw.upper():
            return "Needs data"
        is_sbm_price = r.get("comparison_metric") == "SBM_EQ_PRICE"
        is_open = (r.get("contract_status") or "Open").strip().upper() == "OPEN"
        current_spread = to_float(r.get("current_spread"), None)
        if is_open and current_spread is not None:
            if current_spread < -0.005:
                return "Open ↓ cheaper than local" if is_sbm_price else "Open ↓ below local"
            if current_spread > 0.005:
                return "Open ↑ higher than local" if is_sbm_price else "Open ↑ above local"
            return "Open = local price" if is_sbm_price else "Open = local basis"
        spread = to_float(r.get("spread"), None)
        if spread is None:
            return "Complete — no comparison"
        if spread <= 0:
            return "Cheaper than local" if is_sbm_price else "At/below market"
        return "Higher than local" if is_sbm_price else "Above market"

    def _basis_weighted_average(self, rows, key):
        num = den = 0.0
        plain = []
        for r in rows or []:
            v = to_float(r.get(key), None)
            if v is None:
                continue
            q = to_float(r.get("qty_mt"), None)
            plain.append(v)
            if q is not None and q > 0:
                num += v * q
                den += q
        if den:
            return num / den
        return (sum(plain) / len(plain)) if plain else None

    def _basis_set_kpi(self, name, value, sub=""):
        var = getattr(self, f"basis_kpi_{name}_var", None)
        subvar = getattr(self, f"basis_kpi_{name}_sub_var", None)
        if var is not None:
            var.set(value)
        if subvar is not None:
            subvar.set(sub)

    def _basis_update_decision_summary(self, rows, ref_label):
        contract_rows = [r for r in rows if (r.get("kind") or "").upper() == "CONTRACT"]
        is_sbm_price = any(r.get("comparison_metric") == "SBM_EQ_PRICE" for r in rows)
        market_rows = [r for r in rows if (r.get("kind") or "").upper() == "MARKET"
                       and r.get("implied_basis") is not None]
        purchase_rows = [r for r in rows if (r.get("kind") or "").upper() == "LOCAL_PURCHASE"]
        market_rows.sort(key=lambda r: r.get("date") or "")
        cur_market = to_float(market_rows[-1].get("implied_basis"), None) if market_rows else None
        cutoff90 = (dt.date.today() - dt.timedelta(days=90)).isoformat()
        market90 = [to_float(r.get("implied_basis"), None) for r in market_rows
                    if (r.get("date") or "") >= cutoff90]
        market90 = [v for v in market90 if v is not None]
        avg90 = (sum(market90) / len(market90)) if market90 else None
        avg_contract = self._basis_weighted_average(contract_rows, "contract_basis")
        comparison_rows = []
        for row in contract_rows:
            row = dict(row)
            if (row.get("contract_status") or "Open").strip().upper() == "OPEN"                     and row.get("current_spread") is not None:
                row["comparison_spread"] = row.get("current_spread")
            else:
                row["comparison_spread"] = row.get("spread")
            if row.get("comparison_spread") is not None:
                comparison_rows.append(row)
        avg_spread = self._basis_weighted_average(comparison_rows, "comparison_spread")
        missing = [r for r in rows if "MISSING" in str(r.get("data_status") or "").upper()]

        self._basis_set_kpi("market", fmt_num(cur_market, 1) if cur_market is not None else "—",
                            f"{market_rows[-1].get('date','') if market_rows else 'No market history'}")
        if avg90 is not None:
            delta = (cur_market - avg90) if cur_market is not None else None
            self._basis_set_kpi("avg90", fmt_num(avg90, 1),
                                f"Current {'+' if (delta or 0) >= 0 else ''}{fmt_num(delta,1)}"
                                if delta is not None else "90-day mean")
        else:
            self._basis_set_kpi("avg90", "—", "Need 90-day market data")
        self._basis_set_kpi("contract", fmt_num(avg_contract, 1) if avg_contract is not None else "—",
                            f"{len(contract_rows)} visible contract point(s)")
        if avg_spread is None:
            self._basis_set_kpi(
                "edge", "—",
                "Need local price, stored contract FX, and final/open price inputs"
                if is_sbm_price else "Need matched local/FX/CBOT data")
        else:
            if is_sbm_price:
                edge_text = "Cheaper than local is favorable" if avg_spread <= 0 else "Higher than local is unfavorable"
            else:
                edge_text = "Below market is favorable" if avg_spread <= 0 else "Above market is unfavorable"
            self._basis_set_kpi("edge", f"{avg_spread:+.1f}", edge_text)

        by_origin = {}
        for r in contract_rows:
            spread = to_float(
                r.get("current_spread") if (r.get("contract_status") or "Open").strip().upper() == "OPEN"
                else r.get("spread"), None)
            if spread is None:
                continue
            org = normalize_origin(r.get("origin") or "?") or "?"
            by_origin.setdefault(org, []).append(spread)
        if by_origin:
            best_org, vals = min(by_origin.items(), key=lambda kv: sum(kv[1]) / len(kv[1]))
            best_avg = sum(vals) / len(vals)
            self._basis_set_kpi("origin", best_org, f"Average spread {best_avg:+.1f}")
        else:
            self._basis_set_kpi("origin", "—", "No comparable origin points")
        self._basis_set_kpi("quality", str(len(missing)),
                            "visible point(s) need data" if missing else "No visible data gaps")

        if not rows:
            summary = "No rows match the current filters. Reset filters or add local, FX, and CBOT history."
        elif avg_spread is not None:
            direction = "below" if avg_spread <= 0 else "above"
            judgement = "favorable" if avg_spread <= 0 else "unfavorable"
            if is_sbm_price:
                summary = (f"Visible SBM contracts average {abs(avg_spread):.1f} USD/ST {direction} the equivalent local price "
                           f"— {judgement}. Final flat/closed prices use CIF; open unpriced premiums use current CBOT + premium. "
                           "CBOT is not subtracted from the local side.")
            else:
                summary = (f"Visible contracts average {abs(avg_spread):.1f} basis units {direction} the market-equivalent basis "
                           f"in {ref_label} mode — {judgement} versus the available local-market reference.")
        elif contract_rows:
            summary = ("SBM contracts are visible, but the equivalent-price comparison needs local base price, stored contract FX, "
                       "and either final CIF or current CBOT + premium."
                       if is_sbm_price else
                       "Contracts are visible, but a complete market comparison needs matched local price, FX, and CBOT data.")
        elif purchase_rows:
            summary = (f"{len(purchase_rows)} actual local purchase point(s) are visible. "
                       "Use them to compare what CPC paid locally with market quotations and import-contract basis.")
        else:
            summary = "Market history is visible. Switch Record type to Both or Contracts only to compare physical contracts."
        if missing:
            summary += f"  {len(missing)} visible point(s) need attention."
        self.basis_decision_var.set(summary)

    def _basis_reset_filters(self):
        self.basis_search_var.set("")
        self.basis_status_var.set("ALL")
        self.basis_date_range_var.set("1Y")
        self.basis_row_view_var.set("Both")
        self.basis_missing_only_var.set(False)
        self.basis_origin_var.set("ALL")
        self.refresh_basis_tracker()
        try:
            self.basis_search_entry.focus_set()
        except Exception:
            pass

    def _basis_trees(self):
        """Return Basis record trees in navigation priority order."""
        trees = []
        for name in ("basis_contract_tree", "basis_local_tree", "basis_purchase_tree"):
            tv = getattr(self, name, None)
            if tv is not None:
                trees.append(tv)
        if not trees and getattr(self, "basis_tree", None) is not None:
            trees.append(self.basis_tree)
        return trees

    def _basis_tree_for_row(self, row):
        kind = (row.get("kind") or "").upper()
        if kind == "CONTRACT":
            return getattr(self, "basis_contract_tree", None)
        if kind == "LOCAL_PURCHASE":
            return getattr(self, "basis_purchase_tree", None)
        return getattr(self, "basis_local_tree", None)

    def _basis_select_iid(self, iid, tree=None):
        """Select one Basis record and synchronize all three record lists."""
        row = getattr(self, "_basis_row_by_iid", {}).get(iid)
        if tree is None and row is not None:
            tree = self._basis_tree_for_row(row)
        if tree is None:
            return False
        try:
            for other in self._basis_trees():
                if other is not tree:
                    other.selection_remove(other.selection())
            self._basis_active_tree = tree
            if hasattr(self, "_basis_records_nb"):
                if tree is getattr(self, "basis_contract_tree", None):
                    self._basis_records_nb.select(self._basis_contract_records_tab)
                elif tree is getattr(self, "basis_purchase_tree", None):
                    self._basis_records_nb.select(self._basis_purchase_records_tab)
                elif tree is getattr(self, "basis_local_tree", None):
                    self._basis_records_nb.select(self._basis_local_records_tab)
            if not tree.exists(iid):
                return False
            tree.selection_set(iid)
            tree.focus(iid)
            tree.see(iid)
            return True
        except Exception as exc:
            log_exception(exc, "_basis_select_iid")
            return False

    def _basis_selected_row(self):
        trees = self._basis_trees()
        active = getattr(self, "_basis_active_tree", None)
        if active in trees:
            trees = [active] + [tv for tv in trees if tv is not active]
        for tv in trees:
            try:
                sel = tv.selection()
                if sel:
                    return self._basis_row_by_iid.get(sel[0])
            except Exception:
                continue
        return None

    def _basis_on_tree_select(self, _event=None):
        try:
            event_tree = getattr(_event, "widget", None)
            if event_tree in self._basis_trees():
                self._basis_active_tree = event_tree
                for other in self._basis_trees():
                    if other is not event_tree:
                        other.selection_remove(other.selection())
        except Exception:
            pass
        r = self._basis_selected_row()
        if not r:
            self.basis_detail_title_var.set("Select a row to see the decision in plain language")
            msg = ("Contract rows show agreed basis, market rows show quotations, and local-purchase rows "
                   "show the basis implied by prices CPC actually paid locally.")
            self.basis_detail_summary_var.set(msg)
            if hasattr(self, "basis_selected_brief_var"):
                self.basis_selected_brief_var.set(msg)
            self.basis_detail_tech_var.set("")
            self.basis_fix_button.configure(state="disabled")
            self.basis_open_button.configure(state="disabled")
            if hasattr(self, "basis_open_local_button"):
                self.basis_open_local_button.configure(state="disabled")
            if hasattr(self, "basis_open_purchase_button"):
                self.basis_open_purchase_button.configure(state="disabled")
            return
        kind = (r.get("kind") or "").upper()
        if kind == "CONTRACT":
            cid = r.get("contract_id") or ""
            name = r.get("contract") or cid
            spread = to_float(r.get("spread"), None)
            cb = to_float(r.get("contract_basis"), None)
            mb = to_float(r.get("implied_basis"), None)
            is_open = (r.get("contract_status") or "Open").strip().upper() == "OPEN"
            current_spread = to_float(r.get("current_spread"), None)
            current_cb = to_float(r.get("current_contract_basis"), None)
            current_mb = to_float(r.get("current_local_basis"), None)
            is_sbm_price = r.get("comparison_metric") == "SBM_EQ_PRICE"
            self.basis_detail_title_var.set(
                f"{name} · {r.get('pricing_type') or 'PREMIUM'} · {r.get('origin') or '?'} · "
                f"{r.get('date') or ('Missing comparison date' if is_sbm_price else 'Missing pricing date')}")
            if is_sbm_price:
                active_spread = current_spread if is_open and current_spread is not None else spread
                active_contract = current_cb if is_open and current_cb is not None else cb
                active_local = current_mb if is_open and current_mb is not None else mb
                if active_spread is None:
                    summary = ("SBM equivalent-price comparison needs the stored contract FX, a local base price, and either "
                               "the final CIF or—while an open premium is unpriced—current CBOT plus the agreed premium.")
                elif active_spread <= 0:
                    summary = (f"FAVORABLE: the contract equivalent price is {abs(active_spread):.1f} USD/ST cheaper than local "
                               f"({fmt_num(active_contract,1)} vs {fmt_num(active_local,1)}). CBOT is not subtracted from local.")
                else:
                    summary = (f"UNFAVORABLE: the contract equivalent price is {active_spread:.1f} USD/ST higher than local "
                               f"({fmt_num(active_contract,1)} vs {fmt_num(active_local,1)}). CBOT is not subtracted from local.")
                if str(r.get("cif_value_type") or "").upper() == "ESTIMATED":
                    summary += " This is an open estimate using current CBOT + premium until a final price is entered or the contract is closed."
            elif is_open and current_spread is not None:
                if current_spread <= 0:
                    summary = (f"OPEN CONTRACT: its current equivalent basis is {abs(current_spread):.1f} below local basis "
                               f"({fmt_num(current_cb,1)} vs {fmt_num(current_mb,1)}), favorable versus the latest local reference.")
                else:
                    summary = (f"OPEN CONTRACT: its current equivalent basis is {current_spread:.1f} above local basis "
                               f"({fmt_num(current_cb,1)} vs {fmt_num(current_mb,1)}), unfavorable versus the latest local reference.")
                if "MISSING PRICING DATE" in str(r.get("data_status") or "").upper():
                    summary += " The current monitor is valid, but add the original Pricing Date to restore its historical dot."
            elif "MISSING PRICING DATE" in str(r.get("data_status") or "").upper():
                summary = "This contract needs a pricing date for historical analysis and does not yet have enough current local data for an open monitor point."
            elif spread is None:
                summary = "This contract does not yet have enough matched local-price, FX, and CBOT data for a market comparison."
            elif spread <= 0:
                summary = (f"The agreed basis was {abs(spread):.1f} below the market-equivalent basis "
                           f"({fmt_num(cb,1)} vs {fmt_num(mb,1)}), which is favorable for the buyer.")
            else:
                summary = (f"The agreed basis was {spread:.1f} above the market-equivalent basis "
                           f"({fmt_num(cb,1)} vs {fmt_num(mb,1)}), which is unfavorable for the buyer.")
            self.basis_detail_summary_var.set(summary)
            if hasattr(self, "basis_selected_brief_var"):
                self.basis_selected_brief_var.set(summary)
            if is_sbm_price:
                tech = (f"Method: {r.get('comparison_method') or r.get('basis_source') or ''}\n"
                        f"Equivalent contract {fmt_num(r.get('contract_basis'),2)} USD/ST · "
                        f"Equivalent local {fmt_num(r.get('implied_basis'),2)} USD/ST · "
                        f"spread {fmt_num(r.get('spread'),2)} USD/ST\n"
                        f"CIF {fmt_num(r.get('cif_usd_mt'),2)} USD/MT ({r.get('cif_value_type') or 'Final'}) · "
                        f"stored FX {fmt_num(r.get('fx'),4)} · contract goods {fmt_num(r.get('contract_price_egp_mt'),2)} EGP/MT\n"
                        f"Local base {fmt_num(r.get('local_base_egp_mt'),2)} + transport {fmt_num(r.get('transport_egp_mt'),2)} "
                        f"= {fmt_num(r.get('local_egp_mt'),2)} EGP/MT · Own-After {fmt_num(r.get('own_after_egp_mt'),2)} EGP/MT · "
                        f"saving {fmt_num(r.get('saving_egp_mt'),2)} EGP/MT\n"
                        f"CBOT {fmt_num(r.get('cbot'),2)} ({r.get('cbot_source','')}) · {r.get('data_status','')} · {r.get('detail','')}")
            else:
                tech = (f"Pricing type {r.get('pricing_type') or 'PREMIUM'} · Basis source {r.get('basis_source') or 'stored'}\n"
                        f"Historical: CBOT {fmt_num(r.get('cbot'),2)} ({r.get('cbot_source','')}, {r.get('cbot_date','') or 'no date'})  ·  "
                        f"FX {fmt_num(r.get('fx'),4)} ({r.get('fx_source','')}, {r.get('fx_date','') or 'no date'})  ·  "
                        f"Local {fmt_num(r.get('local_egp_mt'),0)} EGP/MT  ·  CIF {fmt_num(r.get('cif_usd_mt'),2)} USD/MT\n"
                        f"Contract price {fmt_num(r.get('contract_price_egp_mt'),2)} EGP/MT (CIF × FX; before local fees)  ·  "
                        f"Own-After {fmt_num(r.get('own_after_egp_mt'),2)} EGP/MT\n"
                        f"Current open monitor: contract basis {fmt_num(r.get('current_contract_basis'),2)} · "
                        f"local basis {fmt_num(r.get('current_local_basis'),2)} · "
                        f"spread {fmt_num(r.get('current_spread'),2)} · {r.get('current_market_date') or 'no current date'}\n"
                        f"{r.get('data_status','')}  ·  {r.get('detail','')}")
            self.basis_detail_tech_var.set(tech)
            self.basis_open_button.configure(state="normal" if cid else "disabled")
            if hasattr(self, "basis_open_local_button"):
                self.basis_open_local_button.configure(state="disabled")
            if hasattr(self, "basis_open_purchase_button"):
                self.basis_open_purchase_button.configure(state="disabled")
            needs_pricing = (not is_sbm_price and
                             "MISSING PRICING DATE" in str(r.get("data_status") or "").upper())
            self.basis_fix_button.configure(state="normal" if cid and needs_pricing else "disabled")
        elif kind == "LOCAL_PURCHASE":
            supplier = r.get("supplier") or "Unspecified supplier"
            title_id = r.get("purchase_id") if r.get("purchase_id") not in (None, "") else r.get("purchase_index")
            self.basis_detail_title_var.set(
                f"Local purchase #{title_id} · {supplier} · {r.get('date') or 'Missing date'}")
            if r.get("comparison_metric") == "SBM_EQ_PRICE":
                purchase_msg = (f"CPC paid {fmt_num(r.get('local_egp_mt'),0)} EGP/MT all-in. "
                                f"Its commodity price is equivalent to {fmt_num(r.get('implied_basis'),1)} USD/ST; CBOT is excluded.")
            else:
                purchase_msg = (
                    f"CPC actually paid {fmt_num(r.get('local_egp_mt'),0)} EGP/MT all-in. "
                    f"That purchase implies a basis of {fmt_num(r.get('implied_basis'),1)} using the saved or nearest FX and CBOT references.")
            self.basis_detail_summary_var.set(purchase_msg)
            if hasattr(self, "basis_selected_brief_var"):
                self.basis_selected_brief_var.set(purchase_msg)
            self.basis_detail_tech_var.set(
                f"Base price {fmt_num(r.get('local_base_egp_mt'),0)} + transport {fmt_num(r.get('transport_egp_mt'),0)} EGP/MT  ·  "
                f"Qty {fmt_num(r.get('qty_mt'),0)} MT  ·  FX {fmt_num(r.get('fx'),4)} ({r.get('fx_source','')}, {r.get('fx_date','') or 'no date'})  ·  "
                f"CBOT {fmt_num(r.get('cbot'),2)} ({r.get('cbot_source','')}, {r.get('cbot_date','') or 'no date'})\n"
                f"{r.get('data_status','')}  ·  {r.get('detail','')}")
            self.basis_fix_button.configure(state="disabled")
            self.basis_open_button.configure(state="disabled")
            if hasattr(self, "basis_open_local_button"):
                self.basis_open_local_button.configure(state="disabled")
            if hasattr(self, "basis_open_purchase_button"):
                self.basis_open_purchase_button.configure(state="normal")
        else:
            self.basis_detail_title_var.set(f"Market reference · {r.get('date') or 'Undated'}")
            if r.get("comparison_metric") == "SBM_EQ_PRICE":
                market_msg = (f"The SBM local base quotation is equivalent to {fmt_num(r.get('implied_basis'),1)} USD/ST "
                              "after conversion with FX and 1.1023. CBOT is not subtracted.")
            else:
                market_msg = (
                    f"The local quotation implies a market-equivalent basis of {fmt_num(r.get('implied_basis'),1)} after removing "
                    f"{fmt_num(r.get('expenses_egp_mt'),0)} EGP/MT of local expenses and converting with the available FX and CBOT references.")
            self.basis_detail_summary_var.set(market_msg)
            if hasattr(self, "basis_selected_brief_var"):
                self.basis_selected_brief_var.set(market_msg)
            self.basis_detail_tech_var.set(
                f"Local at port {fmt_num(r.get('local_egp_mt'),0)} EGP/MT  ·  FX {fmt_num(r.get('fx'),4)} ({r.get('fx_date','')})  ·  "
                f"CBOT {fmt_num(r.get('cbot'),2)} ({r.get('cbot_date','')})  ·  {r.get('data_status','')}")
            self.basis_fix_button.configure(state="disabled")
            self.basis_open_button.configure(state="disabled")
            if hasattr(self, "basis_open_local_button"):
                can_open_local = bool(r.get("date") and r.get("commodity"))
                self.basis_open_local_button.configure(state="normal" if can_open_local else "disabled")
            if hasattr(self, "basis_open_purchase_button"):
                self.basis_open_purchase_button.configure(state="disabled")

    def _basis_open_contract_record(self, focus_pricing=False):
        r = self._basis_selected_row()
        cid = (r or {}).get("contract_id") or ""
        if not cid:
            return
        try:
            self.nb.select(self.tab_contracts_group)
            self._contracts_nb.select(self.tab_contracts_outer)
            if hasattr(self, "contract_search_var"):
                self.contract_search_var.set("")
            if hasattr(self, "contract_filter_commodity_var"):
                self.contract_filter_commodity_var.set("ALL")
            if hasattr(self, "contract_filter_status_var"):
                self.contract_filter_status_var.set("ALL")
            if hasattr(self, "contract_filter_origin_var"):
                self.contract_filter_origin_var.set("ALL")
            if hasattr(self, "contract_open_only_var"):
                self.contract_open_only_var.set(False)
            self.refresh_contracts_tree()
            if self.contract_tree.exists(cid):
                self.contract_tree.selection_set(cid)
                self.contract_tree.focus(cid)
                self.contract_tree.see(cid)
                self.load_contract_from_tree()
                self.update_contract_detail_panel()
            if focus_pricing and hasattr(self, "c_pricing_date_entry"):
                self.after_idle(self.c_pricing_date_entry.focus_set)
        except Exception as e:
            self._surface_error("_basis_open_contract_record", e, show=True)

    def _basis_open_local_record(self):
        """Open the selected market-basis row in Setup & Data → Local Prices."""
        r = self._basis_selected_row()
        if not r or (r.get("kind") or "").upper() != "MARKET":
            return
        target_date = str(r.get("date") or "")
        target_comm = str(r.get("commodity") or "").upper()
        if not target_date or not target_comm:
            messagebox.showinfo(APP_NAME, "The selected market row has no local-price key to open.")
            return
        try:
            self.nb.select(self.tab_setup_outer)
            if hasattr(self, "_setup_nb"):
                self._setup_nb.select(self.tab_local_prices)
            self.refresh_local_prices_tree()
            found = False
            for iid in self.lp_tree.get_children(""):
                vals = self.lp_tree.item(iid, "values") or ()
                if len(vals) >= 2 and str(vals[0]) == target_date and str(vals[1]).upper().split("-")[0] == target_comm.split("-")[0]:
                    self.lp_tree.selection_set(iid)
                    self.lp_tree.focus(iid)
                    self.lp_tree.see(iid)
                    self.lp_tree.event_generate("<<TreeviewSelect>>")
                    found = True
                    break
            if not found:
                messagebox.showwarning(
                    APP_NAME, f"Local price {target_comm} on {target_date} is no longer available in Setup & Data.")
        except Exception as e:
            self._surface_error("_basis_open_local_record", e, show=True)

    def _basis_open_local_purchase_record(self):
        """Open the selected Basis point in Contracts → Local Purchases."""
        r = self._basis_selected_row()
        if not r or (r.get("kind") or "").upper() != "LOCAL_PURCHASE":
            return
        target_id = r.get("purchase_id")
        target_date = str(r.get("date") or "")
        target_supplier = str(r.get("supplier") or "")
        target_comm = str(r.get("commodity") or "").upper()
        try:
            self.nb.select(self.tab_contracts_group)
            self._contracts_nb.select(self.tab_local_purchases_outer)
            if hasattr(self, "lp_filter_comm_var"):
                self.lp_filter_comm_var.set("All")
            if hasattr(self, "lp_filter_sup_var"):
                self.lp_filter_sup_var.set("All")
            self.refresh_local_purchases()
            found_iid = ""
            if target_id not in (None, "") and self.lp_purchases_tree.exists(str(target_id)):
                found_iid = str(target_id)
            else:
                for iid in self.lp_purchases_tree.get_children(""):
                    if iid == "__LP_TOTAL__":
                        continue
                    vals = self.lp_purchases_tree.item(iid, "values") or ()
                    if len(vals) >= 4 and str(vals[1]) == target_date \
                            and str(vals[2]) == target_supplier \
                            and str(vals[3]).upper().split("-")[0] == target_comm.split("-")[0]:
                        found_iid = iid
                        break
            if found_iid:
                self.lp_purchases_tree.selection_set(found_iid)
                self.lp_purchases_tree.focus(found_iid)
                self.lp_purchases_tree.see(found_iid)
                self.lp_purchases_tree.event_generate("<<TreeviewSelect>>")
            else:
                messagebox.showwarning(APP_NAME, "The selected local purchase is no longer available.")
        except Exception as e:
            self._surface_error("_basis_open_local_purchase_record", e, show=True)

    def _basis_jump_to_access_choice(self, role):
        """Jump directly to a contract, local price, or local purchase record."""
        try:
            if role == "contract":
                label = self.basis_contract_access_var.get()
                iid = getattr(self, "_basis_contract_access_map", {}).get(label)
                tree = getattr(self, "basis_contract_tree", None)
            elif role == "purchase":
                label = self.basis_purchase_access_var.get()
                iid = getattr(self, "_basis_purchase_access_map", {}).get(label)
                tree = getattr(self, "basis_purchase_tree", None)
            else:
                label = self.basis_local_access_var.get()
                iid = getattr(self, "_basis_local_access_map", {}).get(label)
                tree = getattr(self, "basis_local_tree", None)
            if iid and self._basis_select_iid(iid, tree):
                self._basis_on_tree_select()
        except Exception as e:
            self._surface_error("_basis_jump_to_access_choice", e)

    def _basis_focus_search(self, _event=None):
        try:
            self.basis_search_entry.focus_set()
            self.basis_search_entry.selection_range(0, "end")
            return "break"
        except Exception:
            return None

    def _basis_ctrl_f(self, event=None):
        try:
            if self.nb.select() == str(self.tab_analysis_outer) and self._an_nb.select() == str(self.tab_basis):
                return self._basis_focus_search(event)
        except Exception:
            pass
        return None

    def _basis_chart_hide_tip(self, _event=None):
        try:
            if getattr(self, "_basis_chart_tip", None) is not None:
                self._basis_chart_tip.destroy()
        except Exception:
            pass
        self._basis_chart_tip = None

    def _basis_chart_show_tip(self, event):
        cv = self.basis_canvas
        item = None
        try:
            hits = cv.find_overlapping(event.x - 5, event.y - 5, event.x + 5, event.y + 5)
            for candidate in reversed(hits):
                if candidate in getattr(self, "_basis_chart_item_rows", {}):
                    item = candidate
                    break
        except Exception:
            item = None
        if item is None:
            self._basis_chart_hide_tip()
            return
        r = self._basis_chart_item_rows.get(item) or {}
        key = (item, r.get("contract"), r.get("purchase_id"), r.get("date"))
        if getattr(self, "_basis_chart_tip_key", None) == key and getattr(self, "_basis_chart_tip", None) is not None:
            return
        self._basis_chart_hide_tip()
        kind = (r.get("kind") or "").upper()
        if kind == "CONTRACT":
            is_open = (r.get("contract_status") or "Open").strip().upper() == "OPEN"
            is_sbm_price = r.get("comparison_metric") == "SBM_EQ_PRICE"
            if is_sbm_price:
                text = (f"{('OPEN · ' if is_open else '')}{r.get('contract') or r.get('contract_id')} · {r.get('pricing_type') or 'PREMIUM'}\n"
                        f"{r.get('origin') or '?'} · {r.get('plot_date') or r.get('date') or 'Missing date'}\n"
                        f"Contract eq {fmt_num(r.get('current_contract_basis') if is_open else r.get('contract_basis'),1)} USD/ST · "
                        f"Local eq {fmt_num(r.get('current_local_basis') if is_open else r.get('implied_basis'),1)} USD/ST\n"
                        f"{r.get('current_position') or self._basis_contract_display_status(r)}")
            elif is_open and r.get("current_spread") is not None:
                text = (f"OPEN · {r.get('contract') or r.get('contract_id')} · {r.get('pricing_type') or 'PREMIUM'}\n"
                        f"{r.get('origin') or '?'} · monitor {r.get('current_market_date') or ''}\n"
                        f"Contract basis {fmt_num(r.get('current_contract_basis'),1)} · Local {fmt_num(r.get('current_local_basis'),1)}\n"
                        f"{r.get('current_position') or ''}")
            else:
                text = (f"{r.get('contract') or r.get('contract_id')} · {r.get('pricing_type') or 'PREMIUM'}\n"
                        f"{r.get('origin') or '?'} · {r.get('date') or 'Missing date'}\n"
                        f"Contract basis {fmt_num(r.get('contract_basis'),1)} · Market {fmt_num(r.get('implied_basis'),1)} · "
                        f"Spread {fmt_num(r.get('spread'),1)}")
        elif kind == "LOCAL_PURCHASE":
            metric = "Equivalent price" if r.get("comparison_metric") == "SBM_EQ_PRICE" else "Implied basis"
            unit = " USD/ST" if r.get("comparison_metric") == "SBM_EQ_PRICE" else ""
            text = (f"Actual local purchase · {r.get('supplier') or 'Unknown supplier'}\n{r.get('date') or 'Missing date'} · "
                    f"{fmt_num(r.get('qty_mt'),0)} MT\n{metric} {fmt_num(r.get('implied_basis'),1)}{unit} · "
                    f"Paid {fmt_num(r.get('local_egp_mt'),0)} EGP/MT")
        else:
            metric = "Equivalent price" if r.get("comparison_metric") == "SBM_EQ_PRICE" else "Implied basis"
            unit = " USD/ST" if r.get("comparison_metric") == "SBM_EQ_PRICE" else ""
            text = (f"Local market quotation · {r.get('date') or ''}\n{metric} {fmt_num(r.get('implied_basis'),1)}{unit}\n"
                    f"Local {fmt_num(r.get('local_egp_mt'),0)} EGP/MT")
        try:
            w = tk.Toplevel(self)
            w.wm_overrideredirect(True)
            w.wm_geometry(f"+{event.x_root + 12}+{event.y_root + 12}")
            tk.Label(w, text=text, justify="left", bg=CLR["dark"], fg="#ffffff",
                     padx=8, pady=6, font=(FONT_FAMILY, FS_BODY)).pack()
            self._basis_chart_tip = w
            self._basis_chart_tip_key = key
        except Exception:
            self._basis_chart_tip = None

    def _basis_chart_click(self, event):
        try:
            hits = self.basis_canvas.find_overlapping(event.x - 6, event.y - 6, event.x + 6, event.y + 6)
            for item in reversed(hits):
                r = getattr(self, "_basis_chart_item_rows", {}).get(item)
                iid = (r or {}).get("_iid")
                if iid and self._basis_select_iid(iid):
                    self._basis_on_tree_select()
                    return
        except Exception:
            pass

    def _build_basis_tracker(self):
        """Build the modern Basis Intelligence workspace.

        This is a presentation-only refactor. It deliberately reuses the
        existing basis calculations, filters, navigation, exports, state keys,
        and refresh methods so the upgrade cannot change commercial results.
        """
        p = self.tab_basis
        p.columnconfigure(0, weight=1)
        p.rowconfigure(4, weight=1)

        # Local styles keep the visual upgrade contained inside Basis Tracker.
        style = ttk.Style(self)
        style.configure("Basis.TButton", font=(FONT_FAMILY, FS_BODY, "bold"), padding=(12, 7))
        style.configure("Basis.Ghost.TButton", font=(FONT_FAMILY, FS_BODY), padding=(10, 7))
        style.configure("Basis.Treeview", rowheight=max(28, round(30 * getattr(self, "_font_scale", 1.0))),
                        font=(FONT_FAMILY, FS_BODY), borderwidth=0, relief="flat")
        style.configure("Basis.Treeview.Heading", font=(FONT_FAMILY, FS_BODY, "bold"),
                        padding=(8, 8), relief="flat")
        style.configure("Basis.TNotebook", borderwidth=0, tabmargins=(0, 0, 0, 0))
        style.configure("Basis.TNotebook.Tab", font=(FONT_FAMILY, FS_BODY, "bold"), padding=(16, 9))
        style.configure("Basis.TCombobox", padding=4)
        style.configure("Basis.TCheckbutton", font=(FONT_FAMILY, FS_BODY))

        def modern_button(parent, text, command, primary=False, **kwargs):
            bg = CLR["primary"] if primary else "#e8eef7"
            fg = "#ffffff" if primary else CLR["text"]
            active_bg = "#1d4ed8" if primary else "#dbe5f2"
            return tk.Button(
                parent, text=text, command=command, bg=bg, fg=fg,
                activebackground=active_bg, activeforeground=fg,
                disabledforeground="#94a3b8", relief="flat", bd=0,
                cursor="hand2", padx=14, pady=7,
                font=(FONT_FAMILY, FS_BODY, "bold"), **kwargs)

        def card(parent, bg=CLR["surface"], pad=12):
            return tk.Frame(parent, bg=bg, highlightthickness=1,
                            highlightbackground=CLR["border"], padx=pad, pady=pad)

        # ── Hero header ───────────────────────────────────────────────
        hero = tk.Frame(p, bg="#1b2036", padx=18, pady=14)
        hero.grid(row=0, column=0, sticky="ew", pady=(0, 8))
        hero.columnconfigure(0, weight=1)
        title_box = tk.Frame(hero, bg="#1b2036")
        title_box.grid(row=0, column=0, sticky="w")
        tk.Label(title_box, text="Basis Intelligence", bg="#1b2036", fg="#ffffff",
                 font=(FONT_FAMILY, FS_TITLE, "bold")).pack(anchor="w")
        tk.Label(
            title_box,
            text="Compare contracts, local market quotations, and actual local purchases on one auditable basis timeline.",
            bg="#1b2036", fg="#b9c9dc", font=(FONT_FAMILY, FS_BODY),
            justify="left", wraplength=920).pack(anchor="w", pady=(3, 0))
        hero_badges = tk.Frame(hero, bg="#1b2036")
        hero_badges.grid(row=0, column=1, sticky="e", padx=(14, 0))
        for text, bg, fg in (
            ("CONTRACT + MARKET + PURCHASE", "#16345d", "#dbeafe"),
            ("AUDITABLE", "#123c36", "#bbf7d0"),
        ):
            tk.Label(hero_badges, text=text, bg=bg, fg=fg,
                     font=(FONT_FAMILY, 8, "bold"), padx=9, pady=5).pack(
                         side="left", padx=(6, 0))

        # ── Search and filters card ───────────────────────────────────
        filter_card = card(p, pad=11)
        filter_card.grid(row=1, column=0, sticky="ew", pady=(0, 8))
        filter_card.columnconfigure(0, weight=1)

        self.basis_search_var = tk.StringVar(value="")
        self.basis_status_var = tk.StringVar(value="ALL")
        self.basis_date_range_var = tk.StringVar(value="1Y")
        self.basis_row_view_var = tk.StringVar(value="Both")
        self.basis_missing_only_var = tk.BooleanVar(value=False)
        self.basis_comm_var = tk.StringVar(value="CORN")
        self.basis_origin_var = tk.StringVar(value="ALL")
        self.basis_mode_var = tk.StringVar(
            value=self.state_obj.setdefault("ui", {}).get("basis_reference_mode", "Pricing Date"))
        self.basis_expenses_var = tk.StringVar(value=str(self._basis_expenses_egp_mt()))

        search_row = tk.Frame(filter_card, bg=CLR["surface"])
        search_row.grid(row=0, column=0, sticky="ew")
        search_row.columnconfigure(0, weight=1)
        search_box = tk.Frame(search_row, bg="#f8fafc", highlightthickness=1,
                              highlightbackground="#cbd5e1", padx=9, pady=4)
        search_box.grid(row=0, column=0, sticky="ew", padx=(0, 12))
        search_box.columnconfigure(1, weight=1)
        tk.Label(search_box, text="⌕", bg="#f8fafc", fg=CLR["muted"],
                 font=(FONT_FAMILY, 14, "bold")).grid(row=0, column=0, padx=(0, 7))
        self.basis_search_entry = tk.Entry(
            search_box, textvariable=self.basis_search_var, relief="flat", bd=0,
            bg="#f8fafc", fg=CLR["text"], insertbackground=CLR["text"],
            font=(FONT_FAMILY, FS_EMPH))
        self.basis_search_entry.grid(row=0, column=1, sticky="ew")
        attach_tooltip(
            self.basis_search_entry,
            "Search contract ID, contract name, origin, status, or a data warning. Ctrl+F focuses this box.")

        action_bar = tk.Frame(search_row, bg=CLR["surface"])
        action_bar.grid(row=0, column=1, sticky="e")
        modern_button(action_bar, "Refresh", self.refresh_basis_tracker).pack(side="left", padx=(0, 6))
        modern_button(action_bar, "Export Excel", self.export_basis_excel, primary=True).pack(side="left")
        modern_button(action_bar, "SBM vs Local Excel",
                      self.export_sbm_vs_local_excel).pack(side="left", padx=(6, 0))

        filter_grid = tk.Frame(filter_card, bg=CLR["surface"])
        filter_grid.grid(row=1, column=0, sticky="ew", pady=(11, 0))
        for col in range(4):
            filter_grid.columnconfigure(col, weight=1, uniform="basis_filter")

        def filter_box(row, col, label):
            box = tk.Frame(filter_grid, bg=CLR["surface"])
            box.grid(row=row, column=col, sticky="ew",
                     padx=(0 if col == 0 else 10, 0),
                     pady=(0 if row == 0 else 9, 0))
            tk.Label(box, text=label.upper(), bg=CLR["surface"], fg=CLR["muted"],
                     font=(FONT_FAMILY, 8, "bold")).pack(anchor="w", pady=(0, 4))
            return box

        box = filter_box(0, 0, "Commodity")
        basis_comm_cb = ttk.Combobox(box, textvariable=self.basis_comm_var,
                                     values=["CORN", "SOYBEAN", "SBM", "WHEAT"],
                                     state="readonly", style="Basis.TCombobox", width=14)
        basis_comm_cb.pack(fill="x")

        box = filter_box(0, 1, "Origin")
        self.basis_origin_combo = ttk.Combobox(
            box, textvariable=self.basis_origin_var,
            values=["ALL"] + self._origin_choices(), state="readonly",
            style="Basis.TCombobox", width=16)
        self.basis_origin_combo.pack(fill="x")

        box = filter_box(0, 2, "Status")
        basis_status_cb = ttk.Combobox(box, textvariable=self.basis_status_var,
                                       values=["ALL", "Open", "Closed"], state="readonly",
                                       style="Basis.TCombobox", width=14)
        basis_status_cb.pack(fill="x")

        box = filter_box(0, 3, "Date range")
        basis_date_cb = ttk.Combobox(box, textvariable=self.basis_date_range_var,
                                     values=["30D", "90D", "1Y", "All"], state="readonly",
                                     style="Basis.TCombobox", width=14)
        basis_date_cb.pack(fill="x")

        box = filter_box(1, 0, "Reference")
        basis_mode_cb = ttk.Combobox(
            box, textvariable=self.basis_mode_var,
            values=["Pricing Date", "Delivery Date", "Today / MTM"], state="readonly",
            style="Basis.TCombobox", width=16)
        basis_mode_cb.pack(fill="x")

        box = filter_box(1, 1, "Record type")
        basis_row_cb = ttk.Combobox(
            box, textvariable=self.basis_row_view_var,
            values=["Both", "Contracts only", "Market only", "Local purchases only"], state="readonly",
            style="Basis.TCombobox", width=16)
        basis_row_cb.pack(fill="x")

        cost_box = filter_box(1, 2, "Local costs EGP/MT")
        cost_inner = tk.Frame(cost_box, bg=CLR["surface"])
        cost_inner.pack(fill="x")
        _bexp = ttk.Entry(cost_inner, textvariable=self.basis_expenses_var, width=10)
        self.basis_cost_entry = _bexp
        _bexp.pack(side="left", fill="x", expand=True)
        self.basis_cost_apply_button = modern_button(
            cost_inner, "Apply", self._save_basis_expenses_from_ui)
        self.basis_cost_apply_button.pack(side="left", padx=(6, 0))
        attach_tooltip(
            _bexp,
            "Used for non-SBM implied Basis. SBM equivalent-price comparison excludes CBOT and this cost assumption.")

        options_box = filter_box(1, 3, "Display")
        ttk.Checkbutton(options_box, text="Missing data only",
                        variable=self.basis_missing_only_var,
                        command=self.refresh_basis_tracker,
                        style="Basis.TCheckbutton").pack(anchor="w")

        filter_footer = tk.Frame(filter_card, bg=CLR["surface"])
        filter_footer.grid(row=2, column=0, sticky="ew", pady=(9, 0))
        tk.Label(filter_footer, text="Tip: use Ctrl+F to jump to contract search",
                 bg=CLR["surface"], fg=CLR["muted"],
                 font=(FONT_FAMILY, 8)).pack(side="left")
        ttk.Button(filter_footer, text="Reset filters", command=self._basis_reset_filters,
                   style="Basis.Ghost.TButton").pack(side="right")

        for widget in (basis_comm_cb, self.basis_origin_combo, basis_status_cb,
                       basis_date_cb, basis_row_cb):
            widget.bind("<<ComboboxSelected>>", lambda _e: self.refresh_basis_tracker(), add="+")
            widget.bind("<Return>", lambda _e: self.refresh_basis_tracker(), add="+")
        basis_mode_cb.bind("<<ComboboxSelected>>", self._save_basis_reference_mode_from_ui, add="+")
        self.basis_search_var.trace_add("write", lambda *_: self.refresh_basis_tracker())
        self.basis_search_entry.bind("<Return>", lambda _e: self.refresh_basis_tracker(), add="+")
        _bexp.bind("<Return>", lambda _e: self._save_basis_expenses_from_ui(), add="+")
        self.bind_all("<Control-f>", self._basis_ctrl_f, add="+")

        # ── Modern KPI strip ──────────────────────────────────────────
        kpis = tk.Frame(p, bg=CLR["bg"])
        kpis.grid(row=2, column=0, sticky="ew", pady=(0, 8))
        for i in range(3):
            kpis.columnconfigure(i, weight=1, uniform="basis_kpi")

        def kpi(index, key, title, accent):
            row, col = divmod(index, 3)
            outer = tk.Frame(kpis, bg=accent, padx=0, pady=0)
            outer.grid(row=row, column=col, sticky="nsew",
                       padx=(0 if col == 0 else 6, 0),
                       pady=(0 if row == 0 else 6, 0))
            inner = tk.Frame(outer, bg=CLR["surface"], padx=11, pady=9,
                             highlightthickness=1, highlightbackground=CLR["border"])
            inner.pack(fill="both", expand=True, padx=(0, 0), pady=(4, 0))
            setattr(self, f"basis_kpi_{key}_var", tk.StringVar(value="—"))
            setattr(self, f"basis_kpi_{key}_sub_var", tk.StringVar(value=""))
            tk.Label(inner, text=title.upper(), bg=CLR["surface"], fg=CLR["muted"],
                     font=(FONT_FAMILY, 8, "bold")).pack(anchor="w")
            tk.Label(inner, textvariable=getattr(self, f"basis_kpi_{key}_var"),
                     bg=CLR["surface"], fg=CLR["text"],
                     font=(FONT_FAMILY, FS_KPI, "bold")).pack(anchor="w", pady=(3, 1))
            tk.Label(inner, textvariable=getattr(self, f"basis_kpi_{key}_sub_var"),
                     bg=CLR["surface"], fg=CLR["muted"],
                     font=(FONT_FAMILY, 8), wraplength=300,
                     justify="left").pack(anchor="w")

        kpi(0, "market", "Current market basis", "#2563eb")
        kpi(1, "avg90", "90-day average", "#0ea5e9")
        kpi(2, "contract", "Contract average", "#7c3aed")
        kpi(3, "edge", "Spread vs market", "#15803d")
        kpi(4, "origin", "Best origin", "#b45309")
        kpi(5, "quality", "Data gaps", "#b00020")

        # ── Portfolio signal strip ────────────────────────────────────
        self.basis_decision_var = tk.StringVar(value="")
        self.basis_selected_brief_var = tk.StringVar(
            value="Select a contract or local-market row for a point-specific conclusion.")
        signals = tk.Frame(p, bg=CLR["bg"])
        signals.grid(row=3, column=0, sticky="ew", pady=(0, 8))
