    def _basis_contract_row_values(self, r):
        return (
            r.get("date", "") or "Missing date",
            r.get("contract", "") or r.get("contract_id", ""),
            r.get("origin", ""),
            r.get("contract_status", ""),
            r.get("pricing_type", "PREMIUM"),
            fmt_num(r.get("qty_mt"), 0) if r.get("qty_mt") is not None else "",
            fmt_num(r.get("contract_price_egp_mt"), 2) if r.get("contract_price_egp_mt") is not None else "",
            fmt_num(r.get("contract_basis"), 2) if r.get("contract_basis") is not None else "",
            fmt_num(r.get("implied_basis"), 2) if r.get("implied_basis") is not None else "",
            f"{to_float(r.get('spread'), 0):+.2f}" if r.get("spread") is not None else "",
            fmt_num(r.get("current_local_basis"), 2) if r.get("current_local_basis") is not None else "",
            f"{to_float(r.get('current_spread'), 0):+.2f}" if r.get("current_spread") is not None else "",
            r.get("current_position", ""),
            self._basis_contract_display_status(r),
            r.get("data_status", ""),
        )

    def _basis_local_row_values(self, r):
        return (
            r.get("date", ""),
            r.get("commodity", ""),
            fmt_num(r.get("local_egp_mt"), 0) if r.get("local_egp_mt") is not None else "",
            fmt_num(r.get("transport_egp_mt") if r.get("comparison_metric") == "SBM_EQ_PRICE" else r.get("expenses_egp_mt"), 0)
            if (r.get("transport_egp_mt") if r.get("comparison_metric") == "SBM_EQ_PRICE" else r.get("expenses_egp_mt")) is not None else "",
            fmt_num(r.get("fx"), 4) if r.get("fx") is not None else "",
            fmt_num(r.get("cbot"), 2) if r.get("cbot") is not None else "",
            fmt_num(r.get("implied_basis"), 2) if r.get("implied_basis") is not None else "",
            r.get("data_status", ""),
        )

    def _basis_purchase_row_values(self, r):
        return (
            r.get("date", "") or "Missing date",
            r.get("purchase_id", "") if r.get("purchase_id") not in (None, "") else r.get("purchase_index", ""),
            r.get("supplier", ""),
            r.get("commodity", ""),
            fmt_num(r.get("qty_mt"), 0) if r.get("qty_mt") is not None else "",
            fmt_num(r.get("local_egp_mt"), 0) if r.get("local_egp_mt") is not None else "",
            fmt_num(r.get("fx"), 4) if r.get("fx") is not None else "",
            fmt_num(r.get("cbot"), 2) if r.get("cbot") is not None else "",
            fmt_num(r.get("implied_basis"), 2) if r.get("implied_basis") is not None else "",
            r.get("data_status", ""),
        )

    def _basis_row_values(self, r):
        """Backward-compatible row formatter used by extensions."""
        kind = (r.get("kind") or "").upper()
        if kind == "CONTRACT":
            return self._basis_contract_row_values(r)
        if kind == "LOCAL_PURCHASE":
            return self._basis_purchase_row_values(r)
        return self._basis_local_row_values(r)

    def _basis_set_metric_headings(self, base):
        """Make SBM equivalent-price semantics explicit in the existing tables."""
        is_sbm = (base or "").upper().split("-")[0] == "SBM"
        contract_headings = {
            "Pricing Date": "Comparison Date" if is_sbm else "Pricing Date",
            "Contract Basis": "Contract Eq USD/ST" if is_sbm else "Contract Basis",
            "Ref Local Basis": "Local Eq USD/ST" if is_sbm else "Ref Local Basis",
            "Ref Spread": "Price Spread USD/ST" if is_sbm else "Ref Spread",
            "Current Local Basis": "Current Local Eq" if is_sbm else "Current Local Basis",
            "Open vs Local": "Current Price Gap" if is_sbm else "Open vs Local",
        }
        try:
            for column, heading in contract_headings.items():
                self.basis_contract_tree.heading(column, text=heading)
            self.basis_local_tree.heading(
                "Local Costs", text="Transport EGP/MT" if is_sbm else "Local Costs")
            self.basis_local_tree.heading(
                "Implied Basis", text="Equivalent USD/ST" if is_sbm else "Implied Basis")
            self.basis_purchase_tree.heading(
                "Implied Basis", text="Equivalent USD/ST" if is_sbm else "Implied Basis")
            self._basis_records_nb.tab(
                self._basis_contract_records_tab,
                text="SBM contracts · equivalent price" if is_sbm else "Contracts · agreed basis")
            self._basis_records_nb.tab(
                self._basis_local_records_tab,
                text="SBM local · equivalent price" if is_sbm else "Local market · implied basis")
            self._basis_records_nb.tab(
                self._basis_purchase_records_tab,
                text="Local purchases · equivalent price" if is_sbm else "Local purchases · actual basis")
            if hasattr(self, "basis_contract_formula_label"):
                self.basis_contract_formula_label.configure(text=(
                    "SBM: final CIF ÷ 1.1023 versus local base ÷ contract FX ÷ 1.1023; "
                    "open unpriced premium = current CBOT + premium. Local CBOT is excluded."
                    if is_sbm else
                    "Contract EGP/MT = CIF USD/MT × contract FX used by Basis Tracker; local fees are excluded."
                ))
            if hasattr(self, "basis_cost_entry"):
                self.basis_cost_entry.configure(state="disabled" if is_sbm else "normal")
            if hasattr(self, "basis_cost_apply_button"):
                self.basis_cost_apply_button.configure(state="disabled" if is_sbm else "normal")
        except Exception:
            pass

    def refresh_basis_tracker(self):
        try:
            base = self.basis_comm_var.get()
            self._basis_set_metric_headings(base)
            origin_filter = self.basis_origin_var.get() if hasattr(self, "basis_origin_var") else "ALL"
            exp_preview = to_float(self.basis_expenses_var.get(), None) if hasattr(self, "basis_expenses_var") else None
            if exp_preview is not None and exp_preview >= 0:
                self.state_obj.setdefault("ui", {})["basis_expenses_egp_mt"] = float(exp_preview)
            _ref_mode, ref_label = self._basis_reference_mode()
            self.state_obj.setdefault("ui", {})["basis_reference_mode"] = ref_label

            previous = self._basis_selected_row()
            previous_key = ((previous or {}).get("contract_id"), (previous or {}).get("purchase_id"),
                            (previous or {}).get("contract"), (previous or {}).get("date"),
                            (previous or {}).get("kind"))
            raw_rows = self._basis_enriched_rows(base, origin_filter)
            rows = self._basis_apply_accessibility_filters(raw_rows)
            kind_order = {"CONTRACT": 2, "LOCAL_PURCHASE": 1, "MARKET": 0}
            rows.sort(key=lambda r: (r.get("plot_date") or r.get("date") or "0000-00-00",
                                     kind_order.get((r.get("kind") or "").upper(), 0),
                                     r.get("contract") or ""), reverse=True)
            self._basis_last_rows = rows
            self._basis_row_by_iid = {}
            contract_tv = self.basis_contract_tree
            local_tv = self.basis_local_tree
            purchase_tv = self.basis_purchase_tree
            for tv in (contract_tv, local_tv, purchase_tv):
                for iid in tv.get_children():
                    tv.delete(iid)

            contract_access_values = ["All visible contracts"]
            local_access_values = ["All visible local prices"]
            purchase_access_values = ["All visible local purchases"]
            self._basis_contract_access_map = {}
            self._basis_local_access_map = {}
            self._basis_purchase_access_map = {}
            contract_index = local_index = purchase_index = 0
            for r in rows:
                kind = (r.get("kind") or "").upper()
                status_txt = self._basis_contract_display_status(r)
                if kind == "CONTRACT":
                    iid = f"basis_contract_{contract_index}"
                    contract_index += 1
                    tree = contract_tv
                    values = self._basis_contract_row_values(r)
                    if "Needs data" in status_txt:
                        tag = "basis_missing"
                    elif "below local" in status_txt or "At/below" in status_txt:
                        tag = "basis_good"
                    else:
                        tag = "basis_bad" if ("above local" in status_txt or "Above" in status_txt) else "basis_market"
                    access_label = (f"{r.get('contract_id') or '?'} | {r.get('contract') or '?'} | "
                                    f"{r.get('date') or 'Missing date'} | {r.get('origin') or '?'}")
                    if access_label in self._basis_contract_access_map:
                        access_label += f" | row {contract_index}"
                    contract_access_values.append(access_label)
                    self._basis_contract_access_map[access_label] = iid
                elif kind == "LOCAL_PURCHASE":
                    iid = f"basis_purchase_{purchase_index}"
                    purchase_index += 1
                    tree = purchase_tv
                    values = self._basis_purchase_row_values(r)
                    tag = "basis_missing" if "MISSING" in str(r.get("data_status") or "").upper() else "basis_purchase"
                    pid = r.get("purchase_id") if r.get("purchase_id") not in (None, "") else r.get("purchase_index")
                    access_label = (f"#{pid} | {r.get('date') or 'Missing date'} | {r.get('supplier') or '?'} | "
                                    f"{fmt_num(r.get('local_egp_mt'),0)} EGP/MT | Basis {fmt_num(r.get('implied_basis'),1)}")
                    if access_label in self._basis_purchase_access_map:
                        access_label += f" | row {purchase_index}"
                    purchase_access_values.append(access_label)
                    self._basis_purchase_access_map[access_label] = iid
                else:
                    iid = f"basis_local_{local_index}"
                    local_index += 1
                    tree = local_tv
                    values = self._basis_local_row_values(r)
                    tag = "basis_missing" if "MISSING" in str(r.get("data_status") or "").upper() else "basis_market"
                    access_label = (f"{r.get('date') or 'Undated'} | {r.get('commodity') or '?'} | "
                                    f"Local {fmt_num(r.get('local_egp_mt'),0)} | Basis {fmt_num(r.get('implied_basis'),1)}")
                    if access_label in self._basis_local_access_map:
                        access_label += f" | row {local_index}"
                    local_access_values.append(access_label)
                    self._basis_local_access_map[access_label] = iid
                r["_iid"] = iid
                tree.insert("", "end", iid=iid, values=values, tags=(tag,))
                self._basis_row_by_iid[iid] = r

            self.basis_contract_access_combo["values"] = contract_access_values
            self.basis_local_access_combo["values"] = local_access_values
            self.basis_purchase_access_combo["values"] = purchase_access_values
            if self.basis_contract_access_var.get() not in contract_access_values:
                self.basis_contract_access_var.set("All visible contracts")
            if self.basis_local_access_var.get() not in local_access_values:
                self.basis_local_access_var.set("All visible local prices")
            if self.basis_purchase_access_var.get() not in purchase_access_values:
                self.basis_purchase_access_var.set("All visible local purchases")

            self._basis_update_decision_summary(rows, ref_label)
            contracts_visible = sum(1 for r in rows if (r.get("kind") or "").upper() == "CONTRACT")
            markets_visible = sum(1 for r in rows if (r.get("kind") or "").upper() == "MARKET")
            purchases_visible = sum(1 for r in rows if (r.get("kind") or "").upper() == "LOCAL_PURCHASE")
            missing_visible = sum(1 for r in rows if "MISSING" in str(r.get("data_status") or "").upper())
            metric_note = ("SBM equivalent price · local CBOT excluded · local costs assumption not used"
                           if (base or "").upper().split("-")[0] == "SBM"
                           else f"Mode {ref_label} · Expenses {fmt_num(self._basis_expenses_egp_mt(),0)} EGP/MT")
            self.basis_stats_var.set(
                f"Showing {len(rows)} row(s): {contracts_visible} contract, {markets_visible} market, "
                f"{purchases_visible} actual purchase point(s), {missing_visible} with missing data · "
                f"{metric_note}")
            self._draw_basis_chart(rows)
            target_iid = ""
            for iid, row in self._basis_row_by_iid.items():
                key = (row.get("contract_id"), row.get("purchase_id"), row.get("contract"),
                       row.get("date"), row.get("kind"))
                if previous and key == previous_key:
                    target_iid = iid
                    break
            if not target_iid:
                target_iid = next((iid for iid, row in self._basis_row_by_iid.items()
                                   if (row.get("kind") or "").upper() == "CONTRACT"), "")
            if not target_iid:
                target_iid = next((iid for iid, row in self._basis_row_by_iid.items()
                                   if (row.get("kind") or "").upper() == "LOCAL_PURCHASE"), "")
            if not target_iid:
                target_iid = next(iter(self._basis_row_by_iid), "")
            if target_iid:
                self._basis_select_iid(target_iid)
            self._basis_on_tree_select()
        except Exception as e:
            self._surface_error("refresh_basis_tracker", e)

    def _build_basis_excel_workbook(self, rows, report_title="Basis Tracker", filter_note=""):
        """Create one auditable Basis workbook from already-filtered rows."""
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from openpyxl.utils import get_column_letter

        wb = Workbook()
        ws = wb.active
        ws.title = "Basis Data"
        is_sbm_report = bool(rows) and all(
            (r.get("commodity") or "").upper().split("-")[0] == "SBM" for r in rows)
        hdrs = ["Date", "Kind", "Contract", "Commodity", "Origin",
                "Local Price EGP/MT", "Expenses EGP/MT", "FX Rate", "FX Source/Date",
                "CBOT Price", "CBOT Source/Date", "Conversion Factor",
                ("Contract Eq USD/ST" if is_sbm_report else "Contract Basis"),
                ("Local Eq USD/ST" if is_sbm_report else "Implied Basis"),
                ("Price Spread USD/ST" if is_sbm_report else "Spread"), "CIF USD/MT",
                "Own-After EGP/MT", "Data Status", "Notes", "Reference Mode"]
        thin = Side(style="thin", color="D9E1F2")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        header_fill = PatternFill("solid", fgColor="1F3864")

        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(hdrs))
        ws.cell(1, 1, report_title).font = Font(bold=True, size=14, color="1F3864")
        ws.cell(1, 1).alignment = Alignment(horizontal="center")
        ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=len(hdrs))
        ws.cell(2, 1, f"Generated {now_ts()}" + (f" · {filter_note}" if filter_note else ""))
        ws.cell(2, 1).font = Font(italic=True, color="64748B")
        ws.cell(2, 1).alignment = Alignment(horizontal="center")

        header_row = 4
        for ci, heading in enumerate(hdrs, 1):
            cell = ws.cell(row=header_row, column=ci, value=heading)
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal="center", wrap_text=True)
            cell.border = border

        for ri, row in enumerate(rows, header_row + 1):
            values = [
                row.get("date", ""), row.get("kind", ""), row.get("contract", ""),
                row.get("commodity", ""), row.get("origin", ""),
                row.get("local_egp_mt"), row.get("expenses_egp_mt"), row.get("fx"),
                f"{row.get('fx_source','')} {row.get('fx_date','')}".strip(),
                row.get("cbot"),
                f"{row.get('cbot_source','')} {row.get('cbot_date','')}".strip(),
                row.get("factor"), row.get("contract_basis"),
                row.get("implied_basis") if row.get("comparison_metric") == "SBM_EQ_PRICE" else None,
                row.get("spread") if row.get("comparison_metric") == "SBM_EQ_PRICE" else None,
                row.get("cif_usd_mt") if row.get("comparison_metric") == "SBM_EQ_PRICE" else None,
                row.get("own_after_egp_mt") if row.get("comparison_metric") == "SBM_EQ_PRICE" else None,
                row.get("data_status", ""), row.get("detail", ""), row.get("ref_mode", ""),
            ]
            for ci, value in enumerate(values, 1):
                cell = ws.cell(row=ri, column=ci, value=value)
                cell.border = border
                cell.alignment = Alignment(
                    horizontal="right" if isinstance(value, (int, float)) else "left",
                    vertical="top", wrap_text=ci in (9, 11, 18, 19, 20))
            # N: local comparison; O: spread; P: CIF; Q: own-after.
            if row.get("comparison_metric") != "SBM_EQ_PRICE":
                ws.cell(ri, 14, f'=IF(AND(ISNUMBER(F{ri}),ISNUMBER(G{ri}),ISNUMBER(H{ri}),ISNUMBER(J{ri}),ISNUMBER(L{ri})),((F{ri}-G{ri})/H{ri})/L{ri}-J{ri},"")')
                ws.cell(ri, 15, f'=IF(AND(ISNUMBER(M{ri}),ISNUMBER(N{ri})),M{ri}-N{ri},"")')
                ws.cell(ri, 16, f'=IF(AND(ISNUMBER(J{ri}),ISNUMBER(M{ri}),ISNUMBER(L{ri})),(J{ri}+M{ri})*L{ri},"")')
                ws.cell(ri, 17, f'=IF(AND(ISNUMBER(P{ri}),ISNUMBER(H{ri}),ISNUMBER(G{ri})),P{ri}*H{ri}+G{ri},"")')
            for ci in range(1, len(hdrs) + 1):
                ws.cell(ri, ci).border = border
            for ci in (6, 7, 10, 13, 14, 15, 16, 17):
                ws.cell(ri, ci).number_format = '#,##0.00'
            ws.cell(ri, 8).number_format = '#,##0.0000'
            ws.cell(ri, 12).number_format = '0.00000'

        ws.freeze_panes = f"A{header_row + 1}"
        ws.auto_filter.ref = f"A{header_row}:T{max(ws.max_row, header_row)}"
        for ci in range(1, len(hdrs) + 1):
            letter = get_column_letter(ci)
            max_len = max(len(str(ws.cell(row=r, column=ci).value or ""))
                          for r in range(1, ws.max_row + 1))
            ws.column_dimensions[letter].width = min(max(max_len + 2, 10), 36)

        assumptions = wb.create_sheet("Assumptions")
        assumptions["A1"] = "Comparison formulas and governance"
        assumptions["A1"].font = Font(bold=True, size=12)
        items = [
            ("SBM final-price comparison", "Contract Eq USD/ST = final CIF USD/MT / 1.1023; Local Eq USD/ST = local base / stored contract FX / 1.1023"),
            ("SBM open unpriced premium", "Contract Eq USD/ST = current CBOT + agreed premium; local CBOT is not subtracted"),
            ("Non-SBM implied basis", "'=((Local Price - Expenses) / FX) / Conversion Factor - CBOT"),
            ("Spread", "'=Contract Basis - Implied Basis"),
            ("CIF USD/MT", "'=(CBOT + Contract Basis) * Conversion Factor"),
            ("Own-After estimate", "'=CIF USD/MT * FX + Expenses"),
            ("Current editable expenses", self._basis_expenses_egp_mt()),
            ("Current contract reference mode", self._basis_reference_mode()[1]),
            ("Corn conversion factor", CORN_FACTOR),
            ("Soybean conversion factor", SOYBEAN_FACTOR),
            ("Wheat conversion factor", WHEAT_FACTOR),
            ("SBM conversion factor", SBM_ST_PER_MT),
            ("Export scope", filter_note or "Basis Tracker selection/all visible rows"),
        ]
        for row_no, (key, value) in enumerate(items, 3):
            assumptions.cell(row_no, 1, key).font = Font(bold=True)
            assumptions.cell(row_no, 2, value)
        assumptions.column_dimensions["A"].width = 32
        assumptions.column_dimensions["B"].width = 100
        return wb

    def _save_basis_rows_excel(self, rows, default_name, dialog_title, report_title, filter_note=""):
        if not rows:
            messagebox.showinfo(APP_NAME, "No Basis rows match the current selection.")
            return None
        workbook = self._build_basis_excel_workbook(rows, report_title, filter_note)
        out = filedialog.asksaveasfilename(
            title=dialog_title, defaultextension=".xlsx",
            initialdir=get_default_export_dir(), initialfile=default_name,
            filetypes=[("Excel Workbook", "*.xlsx")])
        if not out:
            return None
        workbook.save(out)
        messagebox.showinfo(APP_NAME, f"Basis data exported:\n{out}")
        return out

    def export_savings_basis_excel(self):
        """Export Basis audit data for the contracts visible in Savings Tracker.

        Contract rows respect Commodity/Supplier/Origin/Status filters. Local
        market quotations and actual local purchases for the same commodities are included as context.
        """
        if not _need_openpyxl():
            return
        try:
            f_comm, f_sup, f_orig, f_status = self._sv_current_filters()
            savings_rows, _totals = self._sv_collect_savings_rows(
                f_comm, f_sup, f_orig, f_status)
            contract_ids = {row.get("cid") for row in savings_rows if row.get("cid")}
            commodities = sorted({
                (row.get("commodity") or "").upper().split("-")[0]
                for row in savings_rows if row.get("commodity")})
            if not commodities:
                messagebox.showinfo(APP_NAME, "No Savings rows match the current filters.")
                return
            basis_rows = []
            for commodity in commodities:
                for row in self._basis_enriched_rows(commodity, f_orig):
                    kind = (row.get("kind") or "").upper()
                    if kind == "CONTRACT" and row.get("contract_id") not in contract_ids:
                        continue
                    basis_rows.append(row)
            basis_rows.sort(key=lambda r: (r.get("commodity", ""), r.get("date", ""),
                                           0 if (r.get("kind") or "").lower() == "market" else 1,
                                           r.get("contract", "")))
            filter_note = (f"Savings filters: commodity={f_comm}; supplier={f_sup}; "
                           f"origin={f_orig}; status={f_status}; "
                           f"{len(contract_ids)} contract(s) + local market and actual-purchase context")
            name = f"Savings_Basis_Data_{dt.date.today().isoformat()}.xlsx"
            self._save_basis_rows_excel(
                basis_rows, name, "Export Savings Basis Data",
                "CAIRO POULTRY GROUP — SAVINGS BASIS AUDIT", filter_note)
        except Exception as exc:
            self._surface_error("export_savings_basis_excel", exc, show=True)

    def export_basis_tracker_excel(self):
        """Export selected Basis Tracker rows, or all visible rows."""
        if not _need_openpyxl():
            return
        try:
            if not getattr(self, "_basis_last_rows", None):
                self.refresh_basis_tracker()
            active_tree = getattr(self, "_basis_active_tree", None) or getattr(self, "basis_tree", None)
            selected = list(active_tree.selection()) if active_tree is not None else []
            if selected:
                rows = [self._basis_row_by_iid.get(i) for i in selected
                        if self._basis_row_by_iid.get(i)]
                note = f"{len(rows)} selected Basis Tracker row(s)"
            else:
                if not messagebox.askyesno(
                        APP_NAME, "No Basis Tracker rows are selected. Export all rows?"):
                    return
                rows = list(getattr(self, "_basis_last_rows", []) or [])
                note = f"All {len(rows)} visible Basis Tracker row(s)"
            self._save_basis_rows_excel(
                rows, f"Basis_Tracker_{dt.date.today().isoformat()}.xlsx",
                "Export Basis Tracker to Excel", "BASIS TRACKER — AUDIT EXPORT", note)
        except Exception as exc:
            self._surface_error("export_basis_tracker_excel", exc, show=True)

    def _basis_chart_on_resize(self, event=None):
        """Redraw the Basis chart after its canvas actually changes size.

        Tk can emit many Configure events while the user drags the window, so
        debounce them.  This keeps the chart responsive without flickering or
        repeatedly rebuilding hundreds of canvas items.
        """
        try:
            if not hasattr(self, "basis_canvas"):
                return
            width = max(int(getattr(event, "width", self.basis_canvas.winfo_width()) or 0), 1)
            height = max(int(getattr(event, "height", self.basis_canvas.winfo_height()) or 0), 1)
            previous = getattr(self, "_basis_chart_last_size", (0, 0))
            # Ignore tiny configure noise that does not alter the usable plot.
            if abs(width - previous[0]) < 3 and abs(height - previous[1]) < 3:
                return
            self._basis_chart_last_size = (width, height)
            pending = getattr(self, "_basis_chart_resize_after", None)
            if pending:
                try:
                    self.after_cancel(pending)
                except Exception:
                    pass
            self._basis_chart_resize_after = self.after(
                80, lambda: self._draw_basis_chart(list(getattr(self, "_basis_last_rows", []) or []))
            )
        except Exception:
            pass

    def _toggle_basis_mpl(self):
        """Swap between the accessible canvas chart and the matplotlib one."""
        try:
            if self._basis_mpl_var.get():
                self.basis_canvas.grid_remove()
                if self._basis_mpl_frame is None:
                    fr = ttk.Frame(self._basis_chart_frame)
                    fig = _MplFigure(figsize=(10, 2.9), dpi=96,
                                     facecolor="#ffffff")
                    ax = fig.add_subplot(111)
                    cv = _MplCanvas(fig, master=fr)
                    cv.get_tk_widget().pack(fill="both", expand=True)
                    tb = _MplToolbar(cv, fr, pack_toolbar=False)
                    tb.update()
                    tb.pack(fill="x")
                    self._basis_mpl_frame = fr
                    self._basis_mpl = (fig, ax, cv)
                self._basis_mpl_frame.grid(row=0, column=0, sticky="nsew")
                self._draw_basis_chart_mpl(
                    getattr(self, "_basis_last_rows", None) or [])
            else:
                if self._basis_mpl_frame is not None:
                    self._basis_mpl_frame.grid_remove()
                self.basis_canvas.grid()
                self._draw_basis_chart(
                    getattr(self, "_basis_last_rows", None) or [])
        except Exception as e:
            log_exception(e, "_toggle_basis_mpl")

    def _draw_basis_chart_mpl(self, rows):
        """Pro chart with explicit open-contract versus local connectors."""
        try:
            fig, ax, cv = self._basis_mpl
            ax.clear()
            market = sorted([
                r for r in (rows or [])
                if (r.get("kind") or "").upper() == "MARKET"
                and r.get("date") and r.get("implied_basis") is not None
            ], key=lambda r: r["date"])
            purchases = sorted([
                r for r in (rows or [])
                if (r.get("kind") or "").upper() == "LOCAL_PURCHASE"
                and r.get("date") and r.get("implied_basis") is not None
            ], key=lambda r: r["date"])
            contracts = [
                r for r in (rows or [])
                if (r.get("kind") or "").upper() == "CONTRACT"
                and (r.get("plot_date") or r.get("date"))
                and (r.get("plot_basis") is not None or r.get("contract_basis") is not None)
            ]
            if market:
                ax.plot([r["date"] for r in market], [r["implied_basis"] for r in market],
                        color=self._BASIS_MARKET_COLOR, linewidth=1.8, marker="o",
                        markersize=3, label="Local market quotation")
            if purchases:
                ax.scatter([r["date"] for r in purchases], [r["implied_basis"] for r in purchases],
                           s=58, marker="D", color=self._BASIS_LOCAL_PURCHASE_COLOR,
                           label="Actual local purchase", zorder=4,
                           edgecolors="#ffffff", linewidths=0.8)

            closed_groups = {}
            open_groups = {}
            open_connector_label_used = False
            for r in contracts:
                is_open = (r.get("contract_status") or "Open").strip().upper() == "OPEN"
                groups = open_groups if is_open else closed_groups
                groups.setdefault(self._basis_origin_legend_label(r.get("origin")), []).append(r)
                if is_open and r.get("current_spread") is not None \
                        and r.get("current_local_basis") is not None:
                    x = r.get("plot_date") or r.get("date")
                    y_contract = to_float(r.get("plot_basis"), None)
                    y_local = to_float(r.get("current_local_basis"), None)
                    if x and y_contract is not None and y_local is not None:
                        connector_color = "#15803d" if r.get("current_spread") <= 0 else "#b00020"
                        ax.vlines(x, min(y_contract, y_local), max(y_contract, y_local),
                                  color=connector_color, linestyle="--", linewidth=1.2,
                                  alpha=0.85,
                                  label="Open contract gap vs latest local" if not open_connector_label_used else None,
                                  zorder=2)
                        open_connector_label_used = True

            for label, pts in sorted(closed_groups.items()):
                ax.scatter([r.get("plot_date") or r.get("date") for r in pts],
                           [r.get("plot_basis") if r.get("plot_basis") is not None else r.get("contract_basis") for r in pts],
                           s=46, color=self._basis_origin_color(pts[0].get("origin")),
                           label=f"Closed/history · {label}", zorder=3,
                           edgecolors="#ffffff", linewidths=0.8)
            for label, pts in sorted(open_groups.items()):
                ax.scatter([r.get("plot_date") or r.get("date") for r in pts],
                           [r.get("plot_basis") if r.get("plot_basis") is not None else r.get("contract_basis") for r in pts],
                           s=72, color=self._basis_origin_color(pts[0].get("origin")),
                           label=f"OPEN monitor · {label}", zorder=5,
                           edgecolors="#0f172a", linewidths=1.7)
            is_sbm_price = any(r.get("comparison_metric") == "SBM_EQ_PRICE" for r in (rows or []))
            ax.set_ylabel("Equivalent price USD/ST (no local CBOT)" if is_sbm_price else "Basis over futures")
            ax.grid(True, alpha=0.25)
            if market or purchases or contracts:
                ax.legend(loc="best", fontsize=8, framealpha=0.9)
            all_dates = sorted({
                r.get("plot_date") or r.get("date")
                for r in (rows or []) if (r.get("plot_date") or r.get("date"))
            })
            step = max(1, len(all_dates) // 8) if all_dates else 1
            ticks = all_dates[::step]
            if ticks:
                ax.set_xticks(ticks)
            ax.tick_params(axis="x", labelrotation=30, labelsize=7)
            ax.tick_params(axis="y", labelsize=8)
            fig.tight_layout()
            cv.draw_idle()
        except Exception as e:
            log_exception(e, "_draw_basis_chart_mpl")

    def _draw_basis_chart(self, rows):
        """Accessible chart with open-contract up/down gaps versus local basis."""
        if getattr(self, "_basis_mpl_var", None) is not None \
                and self._basis_mpl_var.get() \
                and getattr(self, "_basis_mpl_frame", None) is not None:
            self._draw_basis_chart_mpl(rows)
            return
        cv = self.basis_canvas
        cv.delete("all")
        self._basis_chart_item_rows = {}
        cv.update_idletasks()
        W = max(int(cv.winfo_width()), 1)
        H = max(int(cv.winfo_height()), 1)
        if W < 180 or H < 120:
            return
        pad_l = 62 if W >= 560 else 50
        pad_r = 28 if W >= 560 else 14
        pad_t, pad_b = 34, 42
        market_rows = sorted([
            r for r in (rows or []) if (r.get("kind") or "").upper() == "MARKET"
            and r.get("date") and r.get("implied_basis") is not None
        ], key=lambda r: r.get("date"))
        purchase_rows = sorted([
            r for r in (rows or []) if (r.get("kind") or "").upper() == "LOCAL_PURCHASE"
            and r.get("date") and r.get("implied_basis") is not None
        ], key=lambda r: r.get("date"))
        contract_rows = sorted([
            r for r in (rows or []) if (r.get("kind") or "").upper() == "CONTRACT"
            and (r.get("plot_date") or r.get("date"))
            and (r.get("plot_basis") is not None or r.get("contract_basis") is not None)
        ], key=lambda r: r.get("plot_date") or r.get("date"))

        vals = ([to_float(r.get("implied_basis"), None) for r in market_rows]
                + [to_float(r.get("implied_basis"), None) for r in purchase_rows]
                + [to_float(r.get("plot_basis") if r.get("plot_basis") is not None
                            else r.get("contract_basis"), None) for r in contract_rows]
                + [to_float(r.get("current_local_basis"), None) for r in contract_rows
                   if (r.get("contract_status") or "Open").strip().upper() == "OPEN"])
        vals = [v for v in vals if v is not None]
        dates = sorted({
            r.get("plot_date") or r.get("date")
            for r in (market_rows + purchase_rows + contract_rows)
            if (r.get("plot_date") or r.get("date"))
        })
        if len(vals) < 1 or not dates:
            cv.create_text(W // 2, H // 2, text="No chartable points match the current filters",
                           fill=CLR["muted"], font=(FONT_FAMILY, FS_BODY))
            return
        d0, d1 = dates[0], dates[-1]
        t0 = dt.date.fromisoformat(d0).toordinal()
        t1 = dt.date.fromisoformat(d1).toordinal()
        if t1 == t0:
            t1 = t0 + 1
        vmin, vmax = min(vals), max(vals)
        if abs(vmax - vmin) < 1e-9:
            vmin -= 1.0
            vmax += 1.0
        span = vmax - vmin
        vmin -= span * 0.12
        vmax += span * 0.12

        def X(ds):
            return pad_l + (dt.date.fromisoformat(ds).toordinal() - t0) / (t1 - t0) * (W - pad_l - pad_r)

        def Y(v):
            return pad_t + (vmax - v) / (vmax - vmin) * (H - pad_t - pad_b)

        for i in range(5):
            v = vmin + (vmax - vmin) * i / 4
            y = Y(v)
            cv.create_line(pad_l, y, W - pad_r, y, fill="#e5e7eb")
            cv.create_text(pad_l - 7, y, text=fmt_num(v, 0), anchor="e",
                           fill=CLR["muted"], font=(FONT_FAMILY, 8))
        tick_count = 2 if W < 850 else (4 if W < 1350 else 6)
        for i in range(tick_count):
            frac = i / max(tick_count - 1, 1)
            ordinal = int(round(t0 + (t1 - t0) * frac))
            label = dt.date.fromordinal(ordinal).isoformat()
            x = pad_l + frac * (W - pad_l - pad_r)
            anchor = "w" if i == 0 else ("e" if i == tick_count - 1 else "center")
            cv.create_line(x, H - pad_b, x, H - pad_b + 4, fill="#94a3b8")
            cv.create_text(x, H - 12, text=label, anchor=anchor,
                           fill=CLR["muted"], font=(FONT_FAMILY, 8))
        is_sbm_price = any(r.get("comparison_metric") == "SBM_EQ_PRICE" for r in (rows or []))
        cv.create_text(8, pad_t - 17,
                       text="Eq USD/ST" if is_sbm_price else "Basis", anchor="w",
                       fill=CLR["muted"], font=(FONT_FAMILY, 8, "bold"))

        if market_rows:
            coords = []
            for r in market_rows:
                coords.extend([X(r["date"]), Y(to_float(r.get("implied_basis"), 0))])
            if len(coords) >= 4:
                cv.create_line(*coords, fill=self._BASIS_MARKET_COLOR, width=2)
            for r in market_rows:
                x, y = X(r["date"]), Y(to_float(r.get("implied_basis"), 0))
                item = cv.create_oval(x - 3, y - 3, x + 3, y + 3,
                                      fill="#ffffff", outline=self._BASIS_MARKET_COLOR, width=2)
                self._basis_chart_item_rows[item] = r

        for r in purchase_rows:
            x, y = X(r["date"]), Y(to_float(r.get("implied_basis"), 0))
            size = 6
            item = cv.create_polygon(x, y - size, x + size, y, x, y + size, x - size, y,
                                     fill=self._BASIS_LOCAL_PURCHASE_COLOR,
                                     outline="#ffffff", width=1)
            self._basis_chart_item_rows[item] = r

        visible_groups = []
        group_origin = {}
        has_open = False
        for r in contract_rows:
            label = self._basis_origin_legend_label(r.get("origin"))
            if label not in visible_groups:
                visible_groups.append(label)
                group_origin[label] = r.get("origin")
            is_open = (r.get("contract_status") or "Open").strip().upper() == "OPEN"
            has_open = has_open or is_open
            plot_date = r.get("plot_date") or r.get("date")
            plot_basis = to_float(r.get("plot_basis") if r.get("plot_basis") is not None
                                  else r.get("contract_basis"), None)
            if not plot_date or plot_basis is None:
                continue
            x, y = X(plot_date), Y(plot_basis)
            if is_open and r.get("current_spread") is not None \
                    and r.get("current_local_basis") is not None:
                local_y = Y(to_float(r.get("current_local_basis"), 0))
                connector = "#15803d" if r.get("current_spread") <= 0 else "#b00020"
                cv.create_line(x, y, x, local_y, fill=connector, width=2, dash=(4, 3))
                arrow = "↓" if r.get("current_spread") <= 0 else "↑"
                cv.create_text(x + 9, (y + local_y) / 2, text=arrow,
                               fill=connector, font=(FONT_FAMILY, 11, "bold"))
            colr = self._basis_origin_color(r.get("origin"))
            outline = "#0f172a" if is_open else "#ffffff"
            width = 2 if is_open else 1
            radius = 7 if is_open else 5
            item = cv.create_oval(x - radius, y - radius, x + radius, y + radius,
                                  fill=colr, outline=outline, width=width)
            self._basis_chart_item_rows[item] = r

        lx = pad_l + 5
        cv.create_line(lx, 13, lx + 22, 13, fill=self._BASIS_MARKET_COLOR, width=2)
        cv.create_text(lx + 28, 13, text="Local quotation", anchor="w",
                       fill=CLR["text"], font=(FONT_FAMILY, 8))
        lx += 125
        cv.create_polygon(lx + 4, 8, lx + 9, 13, lx + 4, 18, lx - 1, 13,
                          fill=self._BASIS_LOCAL_PURCHASE_COLOR, outline="")
        cv.create_text(lx + 14, 13, text="Actual purchase", anchor="w",
                       fill=CLR["text"], font=(FONT_FAMILY, 8))
        lx += 115
        if has_open:
            cv.create_oval(lx, 8, lx + 10, 18, fill="#94a3b8", outline="#0f172a", width=2)
            cv.create_text(lx + 14, 13, text="OPEN monitor", anchor="w",
                           fill=CLR["text"], font=(FONT_FAMILY, 8))
            lx += 105
        for label in visible_groups[:4]:
            colr = self._basis_origin_color(group_origin.get(label))
            cv.create_oval(lx, 9, lx + 8, 17, fill=colr, outline="")
            cv.create_text(lx + 12, 13, text=label, anchor="w",
                           fill=CLR["text"], font=(FONT_FAMILY, 8))
            lx += max(82, 15 + len(label) * 7)

    # ══════════════════════════════════════════════════════════════════
    #  ALERTS ENGINE — CBOT move, FX vs break-even, unpriced near delivery,
    #  FX not secured near delivery. Thresholds editable in Data Management.
    # ══════════════════════════════════════════════════════════════════
    def _alert_cbot_move_pct(self):
        return to_float(self.state_obj.get("ui", {}).get("alert_cbot_move_pct"), 2.0) or 2.0

    def _alert_near_days(self):
        v = to_float(self.state_obj.get("ui", {}).get("alert_near_delivery_days"), 21)
        return int(v) if v else 21

    def _alert_fx_pricing_gap_pct(self):
        return to_float(self.state_obj.get("ui", {}).get("alert_fx_pricing_gap_pct"), 2.0) or 2.0

    def _alert_supplier_concentration_pct(self):
        return to_float(self.state_obj.get("ui", {}).get(
            "alert_supplier_concentration_pct"), 40.0) or 40.0

    def _resolve_pricing_fx(self, c):
        """Best-available FX 'at pricing time' for one contract: the
        qty-weighted FX across its pricing lots, falling back to an explicit
        contract-level pricing/contract FX field. Mirrors the priority used
        by the Basis Tracker's PRICING-mode FX resolver."""
        lots_fx = self._weighted_pricing_lot_value(c, "fx")
        if lots_fx is not None and lots_fx > 0:
            return lots_fx, "weighted pricing lots"
        for key in ("pricing_fx", "contract_fx", "fx_rate"):
            fx = to_float((c or {}).get(key), None)
            if fx is not None and fx > 0:
                return fx, f"contract {key}"
        return None, ""

    def evaluate_alerts(self):
        """Return list of dicts {priority, issue, action} for the Action
        Center + the Exposure & Risk tab."""
        alerts = []
        today = dt.date.today()
        s = self.state_obj

        # 1. CBOT day-over-day move ≥ threshold
        thr = self._alert_cbot_move_pct()
        by_comm = {}
        for e in s.get("cbot_history", []) or []:
            c = (e.get("commodity") or "").upper()
            px = to_float(e.get("close", e.get("price")), None)
            if c and px is not None and e.get("date"):
                by_comm.setdefault(c, []).append((e["date"], px))
        for comm, rows in by_comm.items():
            rows.sort()
            if len(rows) >= 2:
                (d0, p0), (d1, p1) = rows[-2], rows[-1]
                if p0:
                    move = (p1 - p0) / p0 * 100.0
                    if abs(move) >= thr:
                        direction = "up" if move > 0 else "down"
                        alerts.append({
                            "priority": "High",
                            "issue": f"CBOT {comm} moved {move:+.1f}% "
                                     f"({fmt_num(p0,2)} → {fmt_num(p1,2)}, {d1})",
                            "action": ("Unpriced lots got cheaper — consider pricing."
                                       if move < 0 else
                                       "Cost pressure on unpriced lots — review open slots.")})

        # 2. FX vs break-even per open contract (needs local price + own-after)
        fx_now = None
        fxh = sorted(((e.get("date",""), to_float(e.get("rate"), None))
                      for e in s.get("fx_history", []) or []), key=lambda t: t[0])
        if fxh:
            fx_now = fxh[-1][1]
        if fx_now:
            for cid, c in (s.get("contracts", {}) or {}).items():
                if (c.get("status") or "Open").strip().lower() != "open":
                    continue
                cif = to_float(c.get("cif_usd_mt"), None)
                if cif is None:
                    continue
                comm_keys = self._hd_local_keys_for_contract(c)
                local = None
                for ck in comm_keys:
                    pairs = self._local_price_map(ck)
                    if pairs:
                        local = pairs[-1][1]
                        break
                if not local:
                    continue
                fees = self._hd_resolve_fees(c) if hasattr(self, "_hd_resolve_fees") else None
                fees_egp = 0.0
                try:
                    if isinstance(fees, dict):
                        fees_egp = sum(to_float(fees.get(k), 0) or 0
                                       for k in ("discharge", "clearance", "freight"))
                except Exception:
                    pass
                be_fx = (local - fees_egp) / cif if cif else None
                if be_fx and be_fx > 0:
                    buf = (be_fx - fx_now) / be_fx * 100.0
                    if buf < 0:
                        alerts.append({"priority": "High",
                            "issue": f"{c.get('name', cid)}: FX {fmt_num(fx_now,2)} is ABOVE "
                                     f"break-even {fmt_num(be_fx,2)} — import now loses vs local",
                            "action": "Re-run the deal; consider local purchase or renegotiate."})
                    elif buf < 3.0:
                        alerts.append({"priority": "Medium",
                            "issue": f"{c.get('name', cid)}: FX buffer to break-even only "
                                     f"{buf:.1f}% (BE {fmt_num(be_fx,2)})",
                            "action": "Thin margin — consider securing FX (Form 4) now."})

        # 3. Unpriced / FX-unsecured near delivery
        near = self._alert_near_days()
        for cid, c in (s.get("contracts", {}) or {}).items():
            if (c.get("status") or "Open").strip().lower() != "open":
                continue
            dd = parse_date_flex(c.get("delivery_date"))
            if dd is None:
                continue
            days = (dd - today).days
            if 0 <= days <= near:
                if not c.get("priced", True):
                    alerts.append({"priority": "High",
                        "issue": f"{c.get('name', cid)}: UNPRICED with delivery in {days}d",
                        "action": "Price the open slots before the window closes."})
                if not to_float(c.get("form4_fx"), None):
                    alerts.append({"priority": "Medium",
                        "issue": f"{c.get('name', cid)}: no Form 4 FX, delivery in {days}d",
                        "action": "Bank FX not secured — issue Form 4 / confirm allocation."})

        # 4. Form 4 FX vs pricing-date FX — flags the cash-cost gap either way
        gap_thr = self._alert_fx_pricing_gap_pct()
        for cid, c in (s.get("contracts", {}) or {}).items():
            f4 = to_float(c.get("form4_fx"), None)
            if f4 is None:
                continue
            pfx, _src = self._resolve_pricing_fx(c)
            if not pfx:
                continue
            gap_pct = (f4 - pfx) / pfx * 100.0
            if abs(gap_pct) < gap_thr:
                continue
            cif = to_float(c.get("cif_usd_mt"), None)
            impact = (f4 - pfx) * cif if cif is not None else None
            impact_txt = (f" (~{impact:+,.0f} EGP/MT vs the pricing-date plan)"
                          if impact is not None else "")
            if gap_pct > 0:
                alerts.append({"priority": "Medium",
                    "issue": f"{c.get('name', cid)}: Form 4 FX {fmt_num(f4,2)} is "
                             f"{gap_pct:+.1f}% ABOVE pricing-date FX {fmt_num(pfx,2)}"
                             f"{impact_txt} — cash cost overran the plan",
                    "action": "Review the budgeted landed cost against the actual bank rate."})
            else:
                alerts.append({"priority": "Low",
                    "issue": f"{c.get('name', cid)}: Form 4 FX {fmt_num(f4,2)} is "
                             f"{gap_pct:+.1f}% BELOW pricing-date FX {fmt_num(pfx,2)}"
                             f"{impact_txt} — FX timing gain locked in",
                    "action": "No action needed — landed cost came in under the pricing-date plan."})

        # 5. Supplier concentration — too much open exposure with one supplier
        sup_thr = self._alert_supplier_concentration_pct()
        ex = self.portfolio_exposure()
        top = ex.get("top_supplier")
        if top and top["pct"] >= sup_thr:
            alerts.append({"priority": "Medium",
                "issue": f"Supplier concentration: {top['name']} holds "
                         f"{top['pct']:.0f}% of open MT ({top['mt']:,.0f} / "
                         f"{ex['open_mt']:,.0f} MT, ~${top['usd']:,.0f})",
                "action": "Diversify sourcing or confirm this supplier's "
                          "delivery/credit risk is acceptable at this size."})
        return alerts

    def refresh_risk_alerts(self):
        """Recompute alerts; feed Home Action Center + Exposure tab."""
        try:
            alerts = self.evaluate_alerts()
            # merge into Home Action Center (dedupe by issue text)
            if not hasattr(self, "_hd_action_alerts"):
                self._hd_action_alerts = []
            existing = {a.get("issue") for a in self._hd_action_alerts}
            for a in alerts:
                if a["issue"] not in existing:
                    self._hd_action_alerts.append(a)
            self._last_risk_alerts = alerts
            return alerts
        except Exception as e:
            self._surface_error("refresh_risk_alerts", e)
            return []

    # ══════════════════════════════════════════════════════════════════
    #  "SHOULD I BUY TODAY?" — fuses the three timing inputs into one call.
    #  Transparent scoring: each component votes +1 (favors buying now),
    #  −1 (favors waiting), 0 (neutral/no data). Reasons always shown.
    # ══════════════════════════════════════════════════════════════════
    def evaluate_buy_signal(self, base="CORN"):
        s = self.state_obj
        reasons = []
        score = 0
        hard_no = None

        # 1) CBOT movement (last two closes vs the alert threshold)
        rows = sorted(
            (e.get("date", ""), to_float(e.get("close", e.get("price")), None))
            for e in s.get("cbot_history", []) or []
            if (e.get("commodity") or "").upper() == base and e.get("date"))
        rows = [(d, v) for d, v in rows if v is not None]
        if len(rows) >= 2:
            p0, p1 = rows[-2][1], rows[-1][1]
            mv = (p1 - p0) / p0 * 100.0 if p0 else 0.0
            thr = self._alert_cbot_move_pct()
            if mv <= -thr:
                score += 1
                reasons.append(f"CBOT {base} {mv:+.1f}% — cheaper entry")
            elif mv >= thr:
                score -= 1
                reasons.append(f"CBOT {base} {mv:+.1f}% — rising cost")
            else:
                reasons.append(f"CBOT {base} steady ({mv:+.1f}%)")
        else:
            reasons.append("CBOT trend: needs ≥2 stored closes")

        # 2) FX vs the tightest break-even among open contracts
        fx_now = None
        fxh = sorted((e.get("date", ""), to_float(e.get("rate"), None))
                     for e in s.get("fx_history", []) or [] if e.get("date"))
        fxh = [(d, v) for d, v in fxh if v is not None]
        if fxh:
            fx_now = fxh[-1][1]
        min_buf = None
        min_name = None
        min_ctx = None
        if fx_now:
            for cid, c in (s.get("contracts", {}) or {}).items():
                if (c.get("status") or "Open").strip().lower() != "open":
                    continue
                if (c.get("commodity") or "").upper().split("-")[0] != base:
                    continue
                cif = to_float(c.get("cif_usd_mt"), None)
                if not cif:
                    continue
                local = None
                for ck in self._hd_local_keys_for_contract(c):
                    pairs = self._local_price_map(ck)
                    if pairs:
                        local = pairs[-1][1]
                        break
                if not local:
                    continue
                fees_egp = 0.0
                try:
                    fees = self._hd_resolve_fees(c)
                    if isinstance(fees, dict):
                        fees_egp = sum(to_float(fees.get(k), 0) or 0
                                       for k in ("discharge", "clearance", "freight"))
                except Exception:
                    pass
                be = (local - fees_egp) / cif
                if be > 0:
                    buf = (be - fx_now) / be * 100.0
                    if min_buf is None or buf < min_buf:
                        min_buf, min_name = buf, (c.get("name") or cid)
                        # remember this contract's economics for the
                        # stress-resilience component (4th input)
                        _bl = [l for l in (self._contract_pricing_lots(c)
                                           or [])
                               if to_float(l.get("premium_cents"), None)
                               is not None]
                        min_ctx = {"local": local, "fees": fees_egp,
                                   "qty": to_float(c.get("qty_mt"), None),
                                   "prem": to_float(c.get("premium_cents"), None),
                                   "cbot_locked": bool(_bl) and all(
                                       to_float(l.get("cbot"), None)
                                       is not None for l in _bl)}
        if min_buf is not None:
            if min_buf < 0:
                hard_no = (f"FX {fmt_num(fx_now,2)} is ABOVE break-even on "
                           f"{min_name} — import loses vs local today")
                reasons.append(hard_no)
            elif min_buf >= 5:
                score += 1
                reasons.append(f"FX buffer +{min_buf:.1f}% to nearest break-even")
            elif min_buf < 3:
                score -= 1
                reasons.append(f"FX buffer thin ({min_buf:.1f}%) on {min_name}")
            else:
                reasons.append(f"FX buffer {min_buf:.1f}% — adequate")
        else:
            reasons.append("FX vs break-even: needs open contract + logged local price")

        # 3) Current basis vs its 90-day average (physical cheap/expensive)
        try:
            _, ipts = self.basis_series(base)
        except Exception:
            ipts = []
        if ipts:
            cur = ipts[-1][1]
            cutoff = (dt.date.today() - dt.timedelta(days=90)).isoformat()
            win = [v for d, v in ipts if d >= cutoff]
            if win:
                avg = sum(win) / len(win)
                diff = cur - avg
                if diff <= -5:
                    score += 1
                    reasons.append(f"basis {fmt_num(cur,0)}¢ is {fmt_num(-diff,0)}¢ "
                                   f"below 90d avg — physical cheap")
                elif diff >= 5:
                    score -= 1
                    reasons.append(f"basis {fmt_num(cur,0)}¢ is {fmt_num(diff,0)}¢ "
                                   f"above 90d avg — physical expensive")
                else:
                    reasons.append(f"basis near its 90d avg ({fmt_num(cur,0)}¢)")
        else:
            reasons.append("basis: no implied series yet (log local prices + CBOT history)")

        # 4) Stress resilience — SAME engine as the Deal Evaluator.
        #    Pass → +1, High Risk → −1 (never a positive vote), missing
        #    inputs → 0 with the reason shown.
        stress_high_risk = False
        latest_cbot = rows[-1][1] if rows else None
        if (min_ctx and latest_cbot and fx_now
                and min_ctx.get("prem") is not None
                and min_ctx.get("qty")):
            _sig_inputs = {
                "commodity": base, "cbot": latest_cbot, "fx": fx_now,
                "premium_locked": True,
                "cbot_locked": bool(min_ctx.get("cbot_locked")),
                "premium_cents": min_ctx["prem"], "qty_mt": min_ctx["qty"],
                "local_egp_mt": min_ctx["local"],
                "fees_egp_mt": min_ctx["fees"],
                "marginal_egp_mt": to_float(
                    (s.get("ui", {}) or {}).get("marginal_threshold_egp_mt"),
                    200.0),
                "_name": min_name}
            self._hd_signal_ctx = _sig_inputs
            st = run_stress_test(_sig_inputs)
            if st.get("error"):
                reasons.append("stress: unavailable ("
                               + (", ".join(st.get("missing", [])[:2])
                                  or st["error"]) + ")")
            elif st["resilience"] == "High Risk":
                score -= 1
                stress_high_risk = True
                reasons.append(f"stress: HIGH RISK — adverse case "
                               f"{st['adverse']['saving_egp_mt']:+,.0f} EGP/MT")
            else:
                if st["base"]["saving_egp_mt"] > 0:
                    score += 1
                reasons.append(f"stress: Pass (adverse "
                               f"{st['adverse']['saving_egp_mt']:+,.0f} EGP/MT)")
        else:
            reasons.append("stress: unavailable (needs open contract with "
                           "local price + premium)")

        if hard_no:
            verdict, color = "🔴 DON'T BUY — local wins today", "#b00020"
        elif score >= 2:
            verdict, color = "🟢 BUY WINDOW", "#15803d"
        elif score == 1:
            verdict, color = "🟢 LEAN BUY", "#0f766e"
        elif score <= -1:
            verdict, color = "🟠 HOLD / WAIT", "#b45309"
        else:
            verdict, color = "⚪ WAIT — neutral", "#64748b"
        if stress_high_risk and verdict.startswith("🟢"):
            verdict += " — HIGH RISK"
            color = "#b45309"
        return {"verdict": verdict, "color": color, "reasons": reasons,
                "score": score, "stress_high_risk": stress_high_risk}

    def _refresh_hd_buy_signal(self):
        try:
            sig = self.evaluate_buy_signal("CORN")
            self.hd_buy_var.set(
                f"Should I buy today?   {sig['verdict']}    ·   "
                + "   ·   ".join(sig["reasons"][:4]))
            self._hd_buy_lbl.configure(fg=sig["color"])
            # Recommendation line: decision engine on the same flagship
            # contract the signal's stress component used
            try:
                ctx = getattr(self, "_hd_signal_ctx", None)
                if ctx:
                    rec = run_decision_engine(ctx)
                    if rec["action"] != "INSUFFICIENT_DATA":
                        self.hd_reco_var.set(
                            f"Recommendation ({ctx.get('_name','')}): "
                            f"{rec['headline']}   ·   base "
                            f"{rec['base_saving_mt']:+,.0f} / worst "
                            f"{rec['worst_mt']:+,.0f} EGP/MT   ·   "
                            f"confidence {rec['confidence']}/100")
                    else:
                        self.hd_reco_var.set("")
                else:
                    self.hd_reco_var.set("")
            except Exception as e:
                log_exception(e, "hd_recommendation")
        except Exception as e:
            log_exception(e, "_refresh_hd_buy_signal")

