    def _run_exposure_stress_test(self):
        try:
            fx_shock = to_float(self._stress_fx_var.get(), None)
            cbot_shock = to_float(self._stress_cbot_var.get(), None)
            if fx_shock is None or cbot_shock is None:
                self._stress_result_var.set("Enter numeric shocks for both FX and CBOT (e.g. 10 and -5).")
                return
            st = self.portfolio_stress_test(fx_shock, cbot_shock)
            if st["fx_now"] is None:
                self._stress_result_var.set("No FX history saved — can't run the stress test yet.")
                return
            parts = [f"FX {fx_shock:+.1f}% on ${st['fx_exposed_usd']:,.0f} FX-unsecured "
                     f"exposure: {st['fx_impact_egp']:+,.0f} EGP"]
            if st["cbot_impact_egp"] is not None:
                comms = ", ".join(f"{c} {q:,.0f}MT" for c, q in st["unpriced_by_comm"].items()
                                  if c not in st["cbot_gaps"])
                parts.append(f"CBOT {cbot_shock:+.1f}% on unpriced ({comms or 'none'}): "
                             f"{st['cbot_impact_egp']:+,.0f} EGP")
            elif st["unpriced_by_comm"]:
                parts.append("CBOT impact unavailable — missing CBOT history for the unpriced commodities.")
            if st["cbot_gaps"]:
                parts.append(f"(no CBOT price on file for: {', '.join(st['cbot_gaps'])})")
            parts.append(f"Combined landed-cost impact: {st['total_impact_egp']:+,.0f} EGP")
            self._stress_result_var.set("   ·   ".join(parts))
        except Exception as e:
            self._surface_error("_run_exposure_stress_test", e, show=True)

    def refresh_exposure_risk(self):
        try:
            ex = self.portfolio_exposure()
            self._exp_vars["open_usd"].set(f"${ex['open_usd']:,.0f}")
            self._exp_vars["open_mt"].set(f"{ex['open_mt']:,.0f} MT "
                                          f"({ex['contracts']} contracts)")
            self._exp_vars["priced"].set(
                f"{ex['priced_mt']:,.0f} / {ex['unpriced_mt']:,.0f}")
            self._exp_vars["fx_unsec"].set(
                f"${ex['fx_unsecured_usd']:,.0f}  ({ex['fx_unsecured_mt']:,.0f} MT)")
            self._exp_vars["wprem"].set(
                fmt_num(ex["wavg_premium"], 1) if ex["wavg_premium"] is not None else "—")
            b = ex["buckets"]
            self._exp_vars["near"].set(
                f"{sum(q for _, q in b['<7d']):,.0f} / "
                f"{sum(q for _, q in b['7-30d']):,.0f} / "
                f"{sum(q for _, q in b['>30d']):,.0f} MT")
            top = ex.get("top_supplier")
            self._exp_vars["top_supplier"].set(
                f"{top['pct']:.0f}%  {top['name']} ({top['mt']:,.0f} MT)"
                if top else "—")
            alerts = self.refresh_risk_alerts()
            tv = self.exp_alert_tree
            for i in tv.get_children():
                tv.delete(i)
            order = {"High": 0, "Medium": 1, "Low": 2}
            for a in sorted(alerts, key=lambda a: order.get(a["priority"], 3)):
                tv.insert("", "end", values=(a["priority"], a["issue"],
                                             a["action"]),
                          tags=(a["priority"],))
            if not alerts:
                tv.insert("", "end",
                          values=("—", "No active risk alerts.",
                                  "Thresholds in Data Management."))
        except Exception as e:
            self._surface_error("refresh_exposure_risk", e)

    def _get_default_lane_freight(self, commodity):
        """Return the freight rate for a commodity's fixed normal lane, if one is
        defined in COMMODITY_DEFAULT_FREIGHT_LANE and present in freight_rates.
        Falls back to None so callers can use the average instead."""
        comm = (commodity or "").strip().upper()
        comm_base = comm.split("-")[0] if "-" in comm else comm
        lane = COMMODITY_DEFAULT_FREIGHT_LANE.get(comm) or COMMODITY_DEFAULT_FREIGHT_LANE.get(comm_base)
        if not lane:
            return None
        port, dest = lane
        fr = self.state_obj.get("freight_rates", {}) or {}
        try:
            key = self._fr_key(comm_base, port, dest)
        except Exception:
            key = f"{comm_base}|{port}|{dest}"
        rec = fr.get(key)
        if not rec:
            # Tolerant fallback: match by fields in case the key format differs.
            for r in fr.values():
                if ((r.get("commodity") or "").upper() in (comm, comm_base)
                        and (r.get("port") or "") == port
                        and (r.get("destination") or "") == dest):
                    rec = r
                    break
        if rec:
            r = to_float(rec.get("rate"), None)
            if r and r > 0:
                return r
        return None

    def _get_preferred_freight_for_commodity(self, commodity):
        """Transport fee to auto-fill for a commodity: use the fixed normal lane
        if one is defined, otherwise the average across all lanes."""
        lane_rate = self._get_default_lane_freight(commodity)
        if lane_rate is not None:
            return lane_rate
        return self._get_avg_freight_for_commodity(commodity)

    def _get_avg_freight_for_commodity(self, commodity):
        """Return average freight rate for commodity across all port/dest combos."""
        comm = commodity.strip().upper()
        comm_base = comm.split("-")[0] if "-" in comm else comm
        fr = self.state_obj.get("freight_rates", {}) or {}
        rates = []
        for key, rec in fr.items():
            rec_comm = (rec.get("commodity") or "").upper()
            if rec_comm == comm or rec_comm == comm_base:
                r = to_float(rec.get("rate"), None)
                if r and r > 0:
                    rates.append(r)
        return sum(rates) / len(rates) if rates else None

    def edit_commodity_freight_defaults(self):
        """Small editor for the per-commodity local freight table. Writes
        user overrides into state['commodity_freight_defaults']."""
        try:
            win = tk.Toplevel(self)
            win.title("Per-commodity local freight (EGP/MT)")
            win.geometry("460x520")
            win.columnconfigure(0, weight=1); win.rowconfigure(1, weight=1)
            ttk.Label(win,
                      text="These rates auto-fill local prices per commodity and "
                           "drive the 'Fix Freight per Commodity' backfill. "
                           "Blank = use the seeded default.",
                      wraplength=430, foreground=CLR["muted"]).grid(
                          row=0, column=0, sticky="w", padx=10, pady=(10, 6))
            body = ttk.Frame(win); body.grid(row=1, column=0, sticky="nsew", padx=10)
            overrides = self.state_obj.setdefault("commodity_freight_defaults", {})
            comms = sorted(set(list(DEFAULT_COMMODITY_FREIGHT_EGP_MT)
                               + list((self.state_obj.get("commodities") or {}).keys())
                               + list(overrides.keys())))
            vars_ = {}
            ttk.Label(body, text="Commodity", font=(FONT_FAMILY, FS_BODY, "bold")).grid(
                row=0, column=0, sticky="w")
            ttk.Label(body, text="Freight EGP/MT", font=(FONT_FAMILY, FS_BODY, "bold")).grid(
                row=0, column=1, sticky="w", padx=(12, 0))
            ttk.Label(body, text="(seeded)", font=(FONT_FAMILY, FS_BODY),
                      foreground=CLR["muted"]).grid(row=0, column=2, sticky="w", padx=(12, 0))
            for i, comm in enumerate(comms, start=1):
                ttk.Label(body, text=comm).grid(row=i, column=0, sticky="w", pady=1)
                cur = overrides.get(comm)
                v = tk.StringVar(value=str(cur) if cur not in (None, "") else "")
                vars_[comm] = v
                ttk.Entry(body, textvariable=v, width=12).grid(
                    row=i, column=1, sticky="w", padx=(12, 0), pady=1)
                seed = DEFAULT_COMMODITY_FREIGHT_EGP_MT.get(comm)
                ttk.Label(body, text=f"{seed:,.2f}" if seed else "—",
                          foreground=CLR["muted"]).grid(row=i, column=2, sticky="w", padx=(12, 0))
            btns = ttk.Frame(win); btns.grid(row=2, column=0, sticky="ew", padx=10, pady=8)

            def _save():
                for comm, v in vars_.items():
                    val = to_float(v.get(), None)
                    if val is not None and val >= 0:
                        overrides[comm] = round(val, 2)
                    elif comm in overrides and not (v.get() or "").strip():
                        del overrides[comm]
                save_state(self.state_obj)
                try:
                    self._lp_refresh_avg_transport()
                except Exception as _e_16409:
                    log_exception(_e_16409, "edit_commodity_freight_defaults")
                win.destroy()
                messagebox.showinfo(APP_NAME, "Per-commodity freight saved.")
            ttk.Button(btns, text="Save", command=_save).pack(side="left", padx=(0, 8))
            ttk.Button(btns, text="Cancel", command=win.destroy).pack(side="left")
        except Exception as e:
            self._surface_error("edit_commodity_freight_defaults", e, show=True)

    def _lp_refresh_avg_transport(self):
        """Recalculate and display avg freight per commodity in Local Prices tab."""
        if not hasattr(self, "_lp_avg_transport_vars"):
            return
        for comm, var in self._lp_avg_transport_vars.items():
            avg = self._get_avg_freight_for_commodity(comm)
            var.set(f"{avg:,.2f}" if avg is not None else "—")

    def _local_price_map(self, commodity):
        """Returns sorted list of (date, all_in_price) for commodity.
        All-in = base price + transport fee."""
        rows = [r for r in self.state_obj.get("local_prices", [])
                if r.get("commodity") == commodity]
        pairs = []
        for r in rows:
            try:
                d = dt.date.fromisoformat(r.get("date", ""))
            except Exception:
                continue
            base  = to_float(r.get("price_egp_mt"), None)
            trans = to_float(r.get("transport_egp_mt"), None)
            if trans is None:
                trans = get_default_local_transport_egp_mt(self.state_obj)
            if base is None:
                continue
            pairs.append((d, base + trans))
        pairs.sort(key=lambda x: x[0])
        return pairs

    def avg_local_price_period(self, commodity, start_date, end_date):
        """Average local price between dates inclusive using last-known carry-forward."""
        pairs=self._local_price_map(commodity)
        if not pairs:
            return None
        # helper to find last known <= date
        def last_price(d):
            lp=None
            for dd,pp in pairs:
                if dd<=d:
                    lp=pp
                else:
                    break
            return lp
        days=0
        s=0.0
        d=start_date
        while d<=end_date:
            p=last_price(d)
            if p is not None:
                s += p
                days += 1
            d += dt.timedelta(days=1)
        if days==0:
            return None
        return s/days

