    # ── Consumption log helpers ────────────────────────────────────────────

    def _cons_log(self):
        """Return the consumption log list, creating it if absent."""
        return self.state_obj.setdefault("consumption_log", [])

    def refresh_consumption_full(self):
        """Refresh all three consumption zone: KPI cards, log table, stock table."""
        try:
            self._refresh_cons_log_tree()
            self._refresh_stock_table()
            self._refresh_cons_kpi_cards()
            self._refresh_cons_contract_combo()
        except Exception as e:
            log_exception(e, "refresh_consumption_full")

    def _refresh_cons_contract_combo(self):
        """Populate the source contract dropdown with open contracts."""
        try:
            contracts = self.state_obj.get("contracts", {}) or {}
            opts = [""] + [
                f"{cid} - {c.get('name', '')}"
                for cid, c in self._sorted_contract_items(contracts)
                if (c.get("status") or "Open").strip() != "Closed"
            ]
            if hasattr(self, "cl_contract_combo"):
                self.cl_contract_combo["values"] = opts
            if hasattr(self, "cons_commodity_combo"):
                comms = sorted(self.state_obj.get("commodities", {}).keys())
                self.cons_commodity_combo["values"] = comms
            if hasattr(self, "cl_comm_combo"):
                comms = sorted(self.state_obj.get("commodities", {}).keys())
                self.cl_comm_combo["values"] = comms
            if hasattr(self, "ss_comm_combo"):
                comms = sorted(self.state_obj.get("commodities", {}).keys())
                self.ss_comm_combo["values"] = comms
        except Exception as _e_16776:
            log_exception(_e_16776, "_refresh_cons_contract_combo")

    def _refresh_cons_log_tree(self):
        if not hasattr(self, "cl_tree"):
            return
        tv = self.cl_tree
        for x in tv.get_children():
            tv.delete(x)
        tv.tag_configure("adjustment", background="#fff3d6", foreground="#7a5500")
        log = self._cons_log()
        for idx, entry in enumerate(
                sorted(log, key=lambda e: e.get("date", ""), reverse=True)):
            is_adj = bool(entry.get("is_adjustment"))
            if is_adj:
                rec_disp  = f"📦 SET: {fmt_num(to_float(entry.get('adjusted_qty'),None),2)} MT"
                cons_disp = "—"
            else:
                rec_disp = (fmt_num(to_float(entry.get("received_mt"), None), 2)
                            if entry.get("received_mt") else "—")
                cons_disp = (fmt_num(to_float(entry.get("consumed_mt"), None), 2)
                             if entry.get("consumed_mt") else "—")
            tv.insert("", "end", iid=str(idx),
                tags=("adjustment",) if is_adj else (),
                values=(
                    entry.get("date", ""),
                    entry.get("commodity", ""),
                    rec_disp,
                    cons_disp,
                    entry.get("contract_id", ""),
                    entry.get("note", ""),
                ))

    def _refresh_stock_table(self):
        """Compute live stock per commodity from the consumption log
        (honoring manual physical-count adjustments as baseline)
        + open contract inbound."""
        if not hasattr(self, "stock_tree"):
            return
        tv = self.stock_tree
        for x in tv.get_children():
            tv.delete(x)

        contracts = self.state_obj.get("contracts", {}) or {}
        comms     = sorted(self.state_obj.get("commodities", {}).keys())
        today     = dt.date.today()

        # Build running stock per commodity — adjustment-aware
        stock_with_baseline = self._compute_stock_with_adjustments(comms)
        stock = {c: v[0] for c, v in stock_with_baseline.items()}
        self._cons_stock_baseline = {c: v[1] for c, v in stock_with_baseline.items()}

        # Open inbound: sum remaining_mt from open contracts per commodity
        inbound = {c: 0.0 for c in comms}
        for cid, c in contracts.items():
            if (c.get("status") or "Open").strip() == "Closed":
                continue
            comm = (c.get("commodity") or "").upper()
            if not comm:
                continue
            # Use remaining_mt if available, else full qty
            rem = to_float(
                c.get("remaining_mt") or c.get("qty_mt"), None)
            if rem and rem > 0:
                if comm not in inbound:
                    inbound[comm] = 0.0
                inbound[comm] += rem

        rows_added = 0
        for comm in comms:
            rate    = self.get_consumption_mt_day(comm)
            on_hand = stock.get(comm, 0.0)
            open_in = inbound.get(comm, 0.0)

            # Days left on hand only
            days_hand = None
            if rate and rate > 0 and on_hand >= 0:
                days_hand = on_hand / rate

            # Total covered including inbound
            total_covered = None
            if rate and rate > 0:
                total_covered = (on_hand + open_in) / rate

            # Stockout date
            stockout_date = "-"
            if days_hand is not None and rate and rate > 0:
                try:
                    stockout_date = (
                        today + dt.timedelta(days=int(days_hand))
                    ).isoformat()
                except Exception:
                    stockout_date = "-"

            # Signal
            if rate is None or rate <= 0:
                signal = "⚙ Set rate"
                tag    = "unknown"
            elif on_hand < 0:
                signal = "⚠ Log receipts"
                tag    = "warning"
            elif days_hand is not None and days_hand < 7:
                signal = "🔴 CRITICAL — < 7 days"
                tag    = "critical"
            elif days_hand is not None and days_hand < 14:
                signal = "🟡 LOW — < 14 days"
                tag    = "warning"
            else:
                signal = "🟢 OK"
                tag    = "ok"

            tv.insert("", "end", iid=comm, tags=(tag,), values=(
                comm,
                fmt_num(on_hand,      2) if on_hand  != 0 else "0",
                fmt_num(rate,         2) if rate              else "—",
                fmt_num(days_hand,    1) if days_hand is not None else "—",
                fmt_num(open_in,      0) if open_in  > 0   else "—",
                fmt_num(total_covered,1) if total_covered is not None else "—",
                stockout_date,
                signal,
            ))
            rows_added += 1

        n_critical = sum(
            1 for c in comms
            if self.get_consumption_mt_day(c) and (stock.get(c, 0) / self.get_consumption_mt_day(c)) < 7
        )
        self._cons_balance_summary_var.set(
            f"{rows_added} commodities tracked  ·  "
            f"{n_critical} critical (< 7 days)  ·  "
            f"Stock computed from {len(self._cons_log())} log entries + open contracts pipeline"
        )

    def _refresh_cons_kpi_cards(self):
        """Rebuild the KPI strip at the top with coloured 'days of stock' cards."""
        if not hasattr(self, "_cons_kpi_frame"):
            return
        f = self._cons_kpi_frame
        # destroy old cards
        for w in f.winfo_children():
            w.destroy()
        self._cons_kpi_cards = {}

        comms = sorted(self.state_obj.get("commodities", {}).keys())

        # running stock — honors manual physical-count adjustments
        stock_with_baseline = self._compute_stock_with_adjustments(comms)

        for i, comm in enumerate(comms):
            rate    = self.get_consumption_mt_day(comm)
            on_hand, baseline_date = stock_with_baseline.get(comm, (0.0, None))
            if rate and rate > 0:
                days = on_hand / rate
                if days < 7:
                    bg, fg, accent = "#3a0808", "#ffaaaa", "#e05050"
                elif days < 14:
                    bg, fg, accent = "#2a1800", "#ffd090", "#e67e22"
                else:
                    bg, fg, accent = "#001508", "#90e0a0", "#27ae60"
                days_txt = f"{days:.1f}d"
            else:
                bg, fg, accent = "#101820", "#5a7a9a", "#2a4a6a"
                days_txt = "—"

            card = tk.Frame(f, bg=bg, highlightthickness=1,
                             highlightbackground=accent)
            card.grid(row=0, column=i, sticky="nsew",
                      padx=(0 if i == 0 else 6, 0), pady=6)
            f.columnconfigure(i, weight=1)
            tk.Label(card, text=comm, bg=bg, fg="#8ab0cc",
                     font=("Segoe UI", 9)).pack(anchor="w", padx=10, pady=(6, 0))
            tk.Label(card, text=days_txt, bg=bg, fg=accent,
                     font=("Segoe UI", 14, "bold")).pack(anchor="w", padx=10)
            tk.Label(card,
                     text=f"{fmt_num(on_hand, 0)} MT on hand",
                     bg=bg, fg=fg,
                     font=("Segoe UI", 9)).pack(anchor="w", padx=10,
                     pady=(0, 2 if baseline_date else 6))
            if baseline_date:
                tk.Label(card,
                         text=f"📦 counted {baseline_date}",
                         bg=bg, fg="#5a7a9a",
                         font=("Segoe UI", 9)).pack(anchor="w", padx=10, pady=(0, 6))

    def save_consumption_log_entry(self):
        """Save a daily receipt/consumption entry to the log."""
        try:
            date_str  = (self.cl_date_var.get() or "").strip()
            comm      = (self.cl_comm_var.get() or "").strip().upper()
            received  = to_float(self.cl_received_var.get(), None)
            consumed  = to_float(self.cl_consumed_var.get(), None)
            note      = self.cl_note_var.get().strip()
            contract_label_raw = self.cl_contract_var.get().strip()
            contract_id = contract_label_raw.split(" - ", 1)[0].strip() \
                if contract_label_raw else ""

            if not date_str or not comm:
                messagebox.showerror(APP_NAME, "Date and Commodity are required.")
                return
            try:
                dt.date.fromisoformat(date_str)
            except Exception:
                messagebox.showerror(APP_NAME, "Date must be YYYY-MM-DD.")
                return
            if received is None and consumed is None:
                messagebox.showerror(APP_NAME,
                    "Enter at least one of MT Received or MT Consumed.")
                return

            log = self._cons_log()
            entry = {
                "date":        date_str,
                "commodity":   comm,
                "received_mt": received,
                "consumed_mt": consumed,
                "contract_id": contract_id,
                "note":        note,
                "ts":          now_ts(),
            }
            log.append(entry)
            save_state(self.state_obj)
            self._autosave_dirty = False
            # clear inputs for next entry
            self.cl_received_var.set("")
            self.cl_consumed_var.set("")
            self.cl_note_var.set("")
            self.cl_date_var.set(dt.date.today().isoformat())
            self._cl_status_var.set(
                f"✓ Saved — {comm}  "
                f"{'received '+fmt_num(received,1)+' MT  ' if received else ''}"
                f"{'consumed '+fmt_num(consumed,1)+' MT' if consumed else ''}"
            )
            self.refresh_consumption_full()
        except Exception as e:
            log_exception(e, "save_consumption_log_entry")
            messagebox.showerror(APP_NAME, str(e))

    def save_stock_adjustment(self):
        """Save a manual physical stock count. This becomes the new baseline:
        all log entries (receipts/consumption) before this date are ignored
        when computing running stock, preventing drift from missed entries."""
        try:
            date_str = (self.ss_date_var.get() or "").strip()
            comm     = (self.ss_comm_var.get() or "").strip().upper()
            qty      = to_float(self.ss_qty_var.get(), None)
            note     = self.ss_note_var.get().strip()

            if not date_str or not comm:
                messagebox.showerror(APP_NAME, "Date and Commodity are required.")
                return
            try:
                dt.date.fromisoformat(date_str)
            except Exception:
                messagebox.showerror(APP_NAME, "Date must be YYYY-MM-DD.")
                return
            if qty is None or qty < 0:
                messagebox.showerror(APP_NAME, "Enter the actual MT in stock (≥ 0).")
                return

            log = self._cons_log()

            # Warn if an adjustment already exists for this commodity/date
            existing = [e for e in log
                       if e.get("is_adjustment") and
                          (e.get("commodity") or "").upper() == comm and
                          e.get("date") == date_str]
            if existing:
                if not messagebox.askyesno(APP_NAME,
                        f"A stock count for {comm} on {date_str} already exists "
                        f"(EGP — {existing[0].get('adjusted_qty')} MT). Replace it?"):
                    return
                log.remove(existing[0])

            entry = {
                "date":          date_str,
                "commodity":     comm,
                "is_adjustment": True,
                "adjusted_qty":  qty,
                "received_mt":   None,
                "consumed_mt":   None,
                "note":          note or "Manual physical stock count",
                "ts":            now_ts(),
            }
            log.append(entry)
            save_state(self.state_obj)
            self._autosave_dirty = False

            self.ss_qty_var.set("")
            self.ss_note_var.set("")
            self.ss_date_var.set(dt.date.today().isoformat())
            self._ss_status_var.set(
                f"✓ Stock set — {comm}: {qty:,.0f} MT as of {date_str}. "
                f"Earlier log entries for {comm} are now ignored in stock calc.")
            self.refresh_consumption_full()
        except Exception as e:
            log_exception(e, "save_stock_adjustment")
            messagebox.showerror(APP_NAME, str(e))

    def _compute_stock_with_adjustments(self, comms=None):
        """Compute current stock per commodity, honoring the most recent
        manual stock-set adjustment (if any) as the baseline, then adding
        receipts/consuming forward from that date only.
        Returns: dict[commodity] -> (stock_mt, baseline_date_or_None)
        """
        log = self._cons_log()
        if comms is None:
            comms = sorted(self.state_obj.get("commodities", {}).keys())

        stock    = {c: 0.0 for c in comms}
        baseline = {c: None for c in comms}

        # Find the most recent adjustment per commodity
        latest_adj = {}
        for entry in log:
            if not entry.get("is_adjustment"):
                continue
            comm = (entry.get("commodity") or "").upper()
            d    = entry.get("date", "")
            if comm not in latest_adj or d > latest_adj[comm]["date"]:
                latest_adj[comm] = entry

        for comm in comms:
            adj = latest_adj.get(comm)
            if adj:
                stock[comm]    = to_float(adj.get("adjusted_qty"), 0.0) or 0.0
                baseline[comm] = adj.get("date")

        # Sum receipts/consumption — only entries strictly after the
        # baseline date (or all entries if no adjustment exists)
        for entry in log:
            if entry.get("is_adjustment"):
                continue
            comm = (entry.get("commodity") or "").upper()
            if comm not in stock:
                stock[comm]    = 0.0
                baseline[comm] = None
            d = entry.get("date", "")
            base_d = baseline.get(comm)
            if base_d and d <= base_d:
                continue   # superseded by the physical count
            rec  = to_float(entry.get("received_mt"), 0.0) or 0.0
            cons = to_float(entry.get("consumed_mt"), 0.0) or 0.0
            stock[comm] += rec - cons

        return {c: (stock[c], baseline[c]) for c in stock}

    def delete_consumption_log_entry(self):
        """Delete selected entries from the consumption log."""
        if not hasattr(self, "cl_tree"):
            return
        sels = self.cl_tree.selection()
        if not sels:
            messagebox.showinfo(APP_NAME, "Select rows to delete.")
            return
        if not messagebox.askyesno(APP_NAME,
                                    f"Delete {len(sels)} log entries?"):
            return
        indices = sorted([int(s) for s in sels], reverse=True)
        log = self._cons_log()
        # The tree is sorted by date desc, so iid == original index in
        # that sorted order — rebuild from sorted list
        sorted_log = sorted(log, key=lambda e: e.get("date", ""), reverse=True)
        to_remove = {sorted_log[i] for i in indices if i < len(sorted_log)}
        log[:] = [e for e in log if e not in to_remove]
        save_state(self.state_obj)
        self._autosave_dirty = False
        self.refresh_consumption_full()

    def _cl_on_select(self, event=None):
        """Pre-fill the entry form with the selected log row for editing."""
        if not hasattr(self, "cl_tree"):
            return
        sels = self.cl_tree.selection()
        if not sels:
            return
        log = self._cons_log()
        sorted_log = sorted(log, key=lambda e: e.get("date", ""), reverse=True)
        try:
            idx = int(sels[0])
            entry = sorted_log[idx]
            self.cl_date_var.set(entry.get("date", ""))
            self.cl_comm_var.set(entry.get("commodity", ""))
            self.cl_received_var.set(
                str(entry["received_mt"]) if entry.get("received_mt") is not None else "")
            self.cl_consumed_var.set(
                str(entry["consumed_mt"]) if entry.get("consumed_mt") is not None else "")
            self.cl_note_var.set(entry.get("note", ""))
        except Exception:
            pass

    # ── keep old contract balance table alive (used by Contracts tab) ─────
    def refresh_contract_balance_table(self):
        """Kept for backward-compat. Delegates to new stock table."""
        try:
            self._refresh_stock_table()
        except Exception as _e_17171:
            log_exception(_e_17171, "refresh_contract_balance_table")



    def on_consumption_select(self, event=None):
        try:
            sels = self.cons_tree.selection()
            if not sels:
                return
            comm = sels[0]
            self.cons_commodity_var.set(comm)
            val = self.state_obj.get("consumption", {}).get(comm)
            self.cons_mt_day_var.set("" if val is None else str(val))
        except Exception:
            pass

    def save_consumption_default(self):
        comm = (self.cons_commodity_var.get() or "").strip().upper()
        v = to_float(self.cons_mt_day_var.get(), None)
        if not comm or v is None or v <= 0:
            messagebox.showerror(APP_NAME, "Enter a valid Commodity and Consumption MT/day (>0).")
            return
        self.state_obj.setdefault("consumption", {})[comm] = v
        save_state(self.state_obj)
        self.refresh_consumption_table()
        messagebox.showinfo(APP_NAME, f"Saved consumption for {comm}.")

    def delete_consumption_default(self):
        comm = (self.cons_commodity_var.get() or "").strip().upper()
        if not comm:
            return
        if comm in (self.state_obj.get("consumption", {}) or {}):
            if not messagebox.askyesno(APP_NAME, f"Delete consumption default for {comm}?"):
                return
            self.state_obj["consumption"].pop(comm, None)
            save_state(self.state_obj)
            self.refresh_consumption_table()

    def _parse_date(self, s):
        s = (s or "").strip()
        if not s:
            return None
        try:
            return dt.date.fromisoformat(s)
        except Exception:
            return None

    def get_consumption_mt_day(self, commodity):
        comm = (commodity or "").strip().upper()
        v = (self.state_obj.get("consumption", {}) or {}).get(comm)
        return to_float(v, None)

    def estimate_finish_date(self, start_date, qty_mt, commodity):
        c = self.get_consumption_mt_day(commodity)
        if start_date is None or qty_mt is None or c is None or c <= 0:
            return None, None
        coverage_days = qty_mt / c
        days_int = int(math.ceil(coverage_days))
        return start_date + dt.timedelta(days=days_int), coverage_days

    def refresh_consumption_table(self):
        """Refresh the default rates treeview."""
        if not hasattr(self, "cons_tree"):
            return
        tv = self.cons_tree
        for x in tv.get_children():
            tv.delete(x)
        data = self.state_obj.get("consumption", {}) or {}
        for comm in sorted(data.keys()):
            tv.insert("", "end", iid=comm,
                      values=(comm, fmt_num(data.get(comm), 2)))

    def _calc_contract_balance_row(self, cid, contract, today=None):
        """Kept for Contracts tab detail panel. Returns a minimal balance dict."""
        today = today or dt.date.today()
        c = contract or {}
        comm = (c.get("commodity") or "").strip().upper()
        qty  = to_float(c.get("qty_mt"), None)
        start_d = self._parse_date(c.get("storage_start"))
        cons    = self.get_consumption_mt_day(comm)

        remaining_mt = qty
        est_finish   = None
        calc_status  = (c.get("status") or "Open").strip()

        if qty is not None and start_d and cons and cons > 0:
            days_elapsed = (today - start_d).days
            consumed     = max(days_elapsed * cons, 0.0)
            remaining_mt = max(qty - consumed, 0.0)
            est_finish, _ = self.estimate_finish_date(start_d, qty, comm)
            calc_status = "Finished" if remaining_mt <= 0 else "In progress"

        return {
            "ContractID":   cid,
            "Name":         c.get("name", ""),
            "Commodity":    comm,
            "Origin":       c.get("origin", ""),
            "StorageStart": start_d.isoformat() if isinstance(start_d, dt.date) else "-",
            "QtyMT":        qty,
            "ConsMTDay":    cons,
            "DaysElapsed":  (today - start_d).days if start_d else None,
            "ConsumedMT":   (qty - remaining_mt) if qty is not None else None,
            "RemainingMT":  remaining_mt,
            "EstFinishDate": est_finish.isoformat() if isinstance(est_finish, dt.date) else "-",
            "Status":       calc_status,
        }




    def _latest_snapshot_map(self):
        latest = {}
        for s in (self.state_obj.get("snapshots", []) or []):
            cid = s.get("contract_id", "")
            if cid:
                latest[cid] = s
        return latest

    def _slot_call_from_values(self, open_slots, saving_vs_local):
        slots = int(to_float(open_slots, 0) or 0)
        saving = to_float(saving_vs_local, None)
        thr = to_float((self.state_obj.get("ui", {}) or {}).get("marginal_threshold_egp_mt"), 200.0) or 200.0
        if saving is None:
            return "Need local price"
        if saving >= thr and slots > 0:
            return "Close slots"
        if saving >= thr and slots <= 0:
            return "Open slots"
        if saving > 0:
            return "Wait / weak edge"
        if slots > 0:
            return "Keep open"
        return "Wait"

    def _latest_local_price_for_commodity(self, commodity):
        pairs = self._local_price_map((commodity or "").upper())
        if not pairs:
            return None, ""
        d, p = pairs[-1]
        return p, d.isoformat()

    def _cbot_slot_size_mt(self, commodity):
        return to_float(CBOT_SLOT_SIZE_MT.get((commodity or "").upper()), None)

    def _slot_metrics(self, commodity, total_qty, open_slots):
        total_qty = to_float(total_qty, None)
        open_slots = int(to_float(open_slots, 0) or 0)
        slot_size_mt = self._cbot_slot_size_mt(commodity)
        if total_qty is None or total_qty <= 0 or open_slots <= 0 or slot_size_mt in (None, 0):
            return {
                "slot_size_mt": slot_size_mt,
                "total_slots_needed": int(math.ceil(total_qty / slot_size_mt)) if (total_qty not in (None, 0) and slot_size_mt not in (None, 0)) else 0,
                "slotted_qty_mt": 0.0,
                "unslotted_qty_mt": total_qty if total_qty is not None else None,
                "last_slot_qty_mt": None,
            }
        total_slots_needed = int(math.ceil(total_qty / slot_size_mt))
        slotted_qty_mt = min(total_qty, open_slots * slot_size_mt)
        unslotted_qty_mt = max(total_qty - slotted_qty_mt, 0.0)
        rem = total_qty - max((open_slots - 1), 0) * slot_size_mt
        last_slot_qty_mt = max(min(slot_size_mt, rem), 0.0) if open_slots > 0 else None
        return {
            "slot_size_mt": slot_size_mt,
            "total_slots_needed": total_slots_needed,
            "slotted_qty_mt": slotted_qty_mt,
            "unslotted_qty_mt": unslotted_qty_mt,
            "last_slot_qty_mt": last_slot_qty_mt,
        }

    def _build_equal_slot_lines(self, total_qty, open_slots, commodity=None):
        total_qty = to_float(total_qty, None)
        open_slots = int(to_float(open_slots, 0) or 0)
        metrics = self._slot_metrics(commodity, total_qty, open_slots)
        slot_size_mt = metrics.get("slot_size_mt")
        if total_qty is None or total_qty <= 0 or open_slots <= 0 or slot_size_mt in (None, 0):
            return []
        lines = []
        remaining = total_qty
        for idx in range(1, open_slots + 1):
            qty = min(slot_size_mt, remaining)
            if qty <= 0:
                break
            remaining = round(max(remaining - qty, 0.0), 3)
            lines.append({
                "slot_id": f"S{idx:02d}",
                "qty_mt": round(qty, 3),
                "status": "Open",
                "open_date": "",
                "close_date": "",
                "open_cbot": None,
                "close_cbot": None,
                "notes": f"Auto-generated | 1 slot ≈ {fmt_num(slot_size_mt, 3)} MT",
            })
        return lines

    def _slot_lines_for_contract(self, cid, c=None, row=None):
        c = c or (self.state_obj.get("contracts", {}) or {}).get(cid, {}) or {}
        row = row or self._slot_row_for_contract(cid, c, self._latest_snapshot_map().get(cid))
        store = self.state_obj.setdefault("slot_lines", {})
        lines = list(store.get(cid) or [])
        if not lines:
            return self._build_equal_slot_lines(row.get("QtyMT"), row.get("OpenSlots"), row.get("Commodity"))
        return lines

    def _slot_row_for_contract(self, cid, c, latest_snap):
        market = self._contract_market_view(cid, c)
        commodity = (c.get("commodity") or market.get("commodity") or (latest_snap or {}).get("commodity") or "").upper()
        origin = (c.get("origin") or (latest_snap or {}).get("origin") or "").strip()
        qty = to_float(c.get("qty_mt"), None)
        if qty is None:
            qty = to_float((latest_snap or {}).get("qty_mt"), None)

        fx = to_float(market.get("fx"), None)
        cbot = to_float(market.get("cbot"), None)
        premium = to_float(market.get("premium"), None)
        import_usd = to_float(market.get("import_usd_mt"), None)
        provisional_egp = to_float(market.get("provisional_egp_mt"), None)

        local = to_float((latest_snap or {}).get("local_egp_mt"), None)
        local_day = ""
        if local is None:
            local, local_day = self._latest_local_price_for_commodity(commodity)
        else:
            local_day = str((latest_snap or {}).get("ts", ""))[:10]

        saving_vs_local = None
        if local is not None and provisional_egp is not None:
            saving_vs_local = local - provisional_egp

        stored_open_slots = c.get("open_slots", None)
        total_slots_guess = None
        if qty not in (None, 0):
            slot_size_guess = self._cbot_slot_size_mt(commodity)
            if slot_size_guess not in (None, 0):
                total_slots_guess = int(math.ceil(qty / slot_size_guess))
        if stored_open_slots in (None, ""):
            open_slots = total_slots_guess or 0
        else:
            open_slots = int(to_float(stored_open_slots, 0) or 0)
        metrics = self._slot_metrics(commodity, qty, open_slots)
        slot_qty = metrics.get("slot_size_mt") if open_slots > 0 else None
        slotted_qty = metrics.get("slotted_qty_mt")
        unslotted_qty = metrics.get("unslotted_qty_mt")
        total_slots_needed = metrics.get("total_slots_needed")
        last_slot_qty = metrics.get("last_slot_qty_mt")
        call = self._slot_call_from_values(open_slots, saving_vs_local)

        return {
            "ContractID": cid,
            "Name": c.get("name", ""),
            "Commodity": commodity,
            "Origin": origin,
            "QtyMT": qty,
            "OpenSlots": open_slots,
            "SlotQtyMT": slot_qty,
            "SlottedQtyMT": slotted_qty,
            "UnslottedQtyMT": unslotted_qty,
            "TotalCBOTSlots": total_slots_needed,
            "LastSlotQtyMT": last_slot_qty,
            "LatestCBOT": cbot,
            "Premium": premium,
            "FX": fx,
            "CBOTCostUSD_MT": import_usd,
            "ProvisionalEGP_MT": provisional_egp,
            "LocalEGP_MT": local,
            "LocalPriceDay": local_day,
            "SavingVsLocalEGP_MT": saving_vs_local,
            "Call": call,
            "LatestSnapshotTS": (latest_snap or {}).get("ts", "") or market.get("fx_ts", ""),
            "LatestSnapshotID": (latest_snap or {}).get("snapshot_id", ""),
            "LatestSnapshot": latest_snap or {},
        }

    def _selected_slot_contract_id(self):
        if not hasattr(self, "slots_tree"):
            return None
        sel = self.slots_tree.selection()
        return sel[0] if sel else None


    # Rolling Premium Tracker
    def _refresh_roll_contract_picker(self, query=""):
        if not hasattr(self, "roll_contract_combo"):
            return []
        values = self._contract_picker_values(
            commodity=self.roll_contract_comm_var.get(),
            open_only=bool(self.roll_contract_open_only_var.get()),
            query=query)
        self.roll_contract_combo["values"] = values
        if not query and self.roll_contract_var.get() not in values:
            self.roll_contract_var.set("")
        return values

    def _on_roll_contract_picker_commit(self):
        self._roll_autofill()
        self._activate_contract_context_from_label(self.roll_contract_var.get())

