    def _roll_autofill(self, event=None):
        try:
            label = self.roll_contract_var.get()
            cid   = label.split(" - ", 1)[0].strip()
            c     = self.state_obj.get("contracts", {}).get(cid, {})
            if not c:
                return
            prem  = to_float(c.get("premium_cents"), None)
            month = c.get("futures_month", "")
            if prem:
                self.roll_old_prem_var.set(str(prem))
            if month:
                self.roll_old_month_var.set(month)
        except Exception as _e_17589:
            log_exception(_e_17589, "_roll_autofill")

    def _roll_implied_own_after(self, cbot_cents, premium_cents, fx):
        if not cbot_cents or not premium_cents or not fx:
            return None, None
        cif_usd   = (cbot_cents + premium_cents) * 0.3937
        own_after = cif_usd * fx
        return round(cif_usd, 2), round(own_after, 0)

    def _roll_save(self):
        try:
            label     = self.roll_contract_var.get().strip()
            roll_date = self.roll_date_var.get().strip()
            old_prem  = to_float(self.roll_old_prem_var.get(), None)
            old_month = self.roll_old_month_var.get().strip()
            new_prem  = to_float(self.roll_new_prem_var.get(), None)
            new_month = self.roll_new_month_var.get().strip()
            cbot      = to_float(self.roll_cbot_var.get(), None)
            notes     = self.roll_notes_var.get().strip()

            if not label:
                messagebox.showerror(APP_NAME, "Select a contract.")
                return
            if not roll_date or not new_prem or not new_month:
                messagebox.showerror(APP_NAME,
                    "Roll date, new premium and futures month are required.")
                return

            cid = label.split(" - ", 1)[0].strip()
            fx  = to_float(
                (self.state_obj.get("market_data", {})
                 .get("fx", {}) or {}).get("price"), None)

            cif_usd, own_egp = self._roll_implied_own_after(
                cbot, new_prem, fx)

            roll_record = {
                "contract_id":  cid,
                "roll_date":    roll_date,
                "old_premium":  old_prem,
                "old_month":    old_month,
                "new_premium":  new_prem,
                "new_month":    new_month,
                "cbot_at_roll": cbot,
                "fx_at_roll":   fx,
                "implied_cif_usd":       cif_usd,
                "implied_own_after_egp": own_egp,
                "notes":        notes,
                "ts":           now_ts(),
            }

            rolls = self.state_obj.setdefault("roll_history", [])
            rolls.append(roll_record)

            c = self.state_obj.get("contracts", {}).get(cid, {})
            if c:
                c["premium_cents"] = new_prem
                c["futures_month"] = new_month
                existing_note = c.get("premium_note", "") or ""
                c["premium_note"] = (existing_note + " | " if existing_note
                                     else "") + f"{new_prem} Over {new_month}"

            save_state(self.state_obj)
            self.refresh_slots_tab()
            self.roll_status_var.set(
                f"Saved: {new_prem}c Over {new_month}")

            self.roll_old_prem_var.set(str(new_prem))
            self.roll_old_month_var.set(new_month)
            self.roll_new_prem_var.set("")
            self.roll_new_month_var.set("")
            self.roll_cbot_var.set("")
            self.roll_notes_var.set("")
            self.roll_date_var.set(dt.date.today().isoformat())

        except Exception as e:
            log_exception(e, "_roll_save")
            messagebox.showerror(APP_NAME, str(e))

    def _roll_delete(self):
        sel = self.roll_tree.selection()
        if not sel:
            messagebox.showinfo(APP_NAME, "Select a row to delete.")
            return
        try:
            idx   = int(sel[0])
            rolls = self.state_obj.get("roll_history", [])
            if 0 <= idx < len(rolls):
                r = rolls[idx]
                if messagebox.askyesno(APP_NAME,
                        f"Delete roll: {r.get('new_premium')}c "
                        f"Over {r.get('new_month')} on {r.get('roll_date')}?"):
                    rolls.pop(idx)
                    save_state(self.state_obj)
                    self.refresh_slots_tab()
        except Exception as e:
            log_exception(e, "_roll_delete")

    def _roll_on_select(self, event=None):
        sel = self.roll_tree.selection()
        if not sel:
            return
        try:
            idx   = int(sel[0])
            rolls = self.state_obj.get("roll_history", [])
            if 0 <= idx < len(rolls):
                r     = rolls[idx]
                cid   = r.get("contract_id", "")
                c     = self.state_obj.get("contracts", {}).get(cid, {})
                ref   = c.get("contract_ref") or c.get("name", cid) if c else cid
                self.roll_contract_var.set(f"{cid} - {ref}")
                self.roll_date_var.set(r.get("roll_date", ""))
                self.roll_old_prem_var.set(str(r.get("old_premium", "") or ""))
                self.roll_old_month_var.set(r.get("old_month", "") or "")
                self.roll_new_prem_var.set(str(r.get("new_premium", "") or ""))
                self.roll_new_month_var.set(r.get("new_month", "") or "")
                self.roll_cbot_var.set(str(r.get("cbot_at_roll", "") or ""))
                self.roll_notes_var.set(r.get("notes", "") or "")
        except Exception as _e_17708:
            log_exception(_e_17708, "_roll_on_select")

    def refresh_slots_tab(self):
        if not hasattr(self, "roll_tree"):
            return
        try:
            contracts = self.state_obj.get("contracts", {}) or {}
            all_opts = self._refresh_roll_contract_picker("")

            for i in self.roll_tree.get_children():
                self.roll_tree.delete(i)

            rolls = self.state_obj.get("roll_history", []) or []
            prev_own = {}

            for idx, r in enumerate(
                    sorted(rolls,
                           key=lambda x: (x.get("contract_id", ""),
                                          x.get("roll_date", "")))):
                cid      = r.get("contract_id", "")
                c        = contracts.get(cid, {})
                ref      = (c.get("contract_ref") or
                            c.get("name", cid) if c else cid)
                old_prem = to_float(r.get("old_premium"), None)
                new_prem = to_float(r.get("new_premium"), None)
                old_mon  = r.get("old_month", "") or ""
                new_mon  = r.get("new_month", "") or ""
                cbot     = to_float(r.get("cbot_at_roll"), None)
                cif_usd  = to_float(r.get("implied_cif_usd"), None)
                own_egp  = to_float(r.get("implied_own_after_egp"), None)
                notes    = r.get("notes", "") or ""

                prev = prev_own.get(cid)
                if prev is not None and own_egp is not None:
                    roll_gain = prev - own_egp
                    tag       = ("gain" if roll_gain > 0
                                 else "cost" if roll_gain < 0
                                 else "flat")
                    gain_disp = fmt_num(roll_gain, 0)
                elif old_prem is None:
                    tag = "first"
                    gain_disp = "initial record"
                else:
                    tag = "flat"
                    gain_disp = "no CBOT data"

                if own_egp is not None:
                    prev_own[cid] = own_egp

                self.roll_tree.insert(
                    "", "end", iid=str(idx), tags=(tag,), values=(
                        ref,
                        r.get("roll_date", ""),
                        fmt_num(old_prem, 2) if old_prem else "",
                        old_mon,
                        fmt_num(new_prem, 2) if new_prem else "",
                        new_mon,
                        fmt_num(cbot, 1)    if cbot    else "",
                        fmt_num(cif_usd, 2) if cif_usd else "",
                        fmt_num(own_egp, 0) if own_egp else "",
                        gain_disp,
                        notes,
                    ))

            n_rolled = sum(
                1 for c in contracts.values()
                if not c.get("priced", True)
                or c.get("status", "Open") == "Open")
            self.roll_status_var.set(
                f"{len(rolls)} roll records  -  "
                f"{n_rolled} contracts still unpriced")

        except Exception as e:
            log_exception(e, "refresh_slots_tab")


