    def _activate_contract_context_from_label(self, label):
        """Select a contract in the hidden/main Contracts tree without
        navigating away from the caller's tab.  Slots and Pricing Lots use
        this to change working context locally.
        """
        cid = self._resolve_contract_id_from_label((label or "").strip())
        c = (self.state_obj.get("contracts", {}) or {}).get(cid)
        if not c:
            return ""
        try:
            if hasattr(self, "contract_tree") and self.contract_tree.exists(cid):
                self.contract_tree.selection_set(cid)
                self.contract_tree.see(cid)
                self.load_contract_from_tree()
                self.update_contract_detail_panel()
        except Exception as e:
            log_exception(e, "_activate_contract_context_from_label")
        return cid

    _CIF_LEGACY_WARNED = set()

    def _contract_cif_usd(self, c, cid=None):
        """THE one way to read a contract's CIF USD/MT.

        CIF = (CBOT + premium) × factor, goods-at-port, BEFORE FX, local
        costs and finance carry. own_after_usd_mt is a DIFFERENT figure
        (import cost + finance carry) and is never silently substituted:
        if a legacy record only has own_after_usd_mt, it is used as a last
        resort and flagged once in the data issues so the record gets fixed.
        """
        cif = to_float((c or {}).get("cif_usd_mt"), None)
        if cif is not None:
            return cif
        own = to_float((c or {}).get("own_after_usd_mt"), None)
        if own is not None:
            key = cid or c.get("name") or id(c)
            if key not in self._CIF_LEGACY_WARNED:
                self._CIF_LEGACY_WARNED.add(key)
                try:
                    record_data_issue(
                        self.state_obj, "cif_legacy",
                        f"Contract {c.get('name', key)}: no CIF stored; using "
                        f"own_after_usd_mt ({own}) as CIF. These are different "
                        f"figures — please re-enter the true CIF.",
                        severity="WARN")
                except Exception:
                    pass
            return own
        return None

    def on_select_contract(self):
        label = self.contract_filter_var.get()
        cid = "ALL"
        if label and not label.startswith("ALL"):
            cid = label.split(" - ",1)[0].strip()
        self.state_obj["ui"]["selected_contract_id"] = cid
        save_state(self.state_obj)
        self.refresh_all()
        # Propagate AFTER refresh_all: the refresh rebuilds the contracts
        # tree, which would wipe any selection set beforehand.
        self._propagate_selected_contract(cid)

    def _propagate_selected_contract(self, cid):
        """ONE selection, everywhere. Picking a contract in the top bar sets
        the same contract as the working context in Single Deal, Performance,
        the Contracts tree, Slots, Pricing Lots, and Consumption. Local tab
        pickers can still override the context afterwards.
        """
        if not cid or cid == "ALL":
            return
        c = (self.state_obj.get("contracts", {}) or {}).get(cid)
        if not c:
            return
        label = self._contract_display_label(cid, c)
        comm = (c.get("commodity") or "").strip().upper()
        comm_calc = "CORN" if comm.startswith("CORN") else comm
        is_open = self._contract_is_open(c)

        # Single Deal: align its filters first so the propagated contract is
        # never silently hidden by the default Open/commodity view.
        try:
            if hasattr(self, "sd_contract_var"):
                if comm_calc:
                    self.sd_commodity_var.set(comm_calc)
                self.sd_contract_status_var.set("Open" if is_open else "Closed")
                self._refresh_sd_contract_picker("")
                self.sd_contract_var.set(label)
                self.on_single_contract_change()
        except Exception:
            pass

        # Contract Performance
        try:
            if hasattr(self, "pf_contract_var"):
                self.pf_contract_comm_var.set(comm or "ALL")
                if not is_open:
                    self.pf_contract_open_only_var.set(False)
                self._refresh_pf_contract_picker("")
                self.pf_contract_var.set(label)
                self._pf_show_contract_detail()
        except Exception:
            pass

        # Slots / roll tracker
        try:
            if hasattr(self, "roll_contract_var"):
                self.roll_contract_comm_var.set(comm or "ALL")
                if not is_open:
                    self.roll_contract_open_only_var.set(False)
                self._refresh_roll_contract_picker("")
                self.roll_contract_var.set(label)
                self._roll_autofill()
        except Exception:
            pass

        # Pricing Lots inline picker
        try:
            if hasattr(self, "pricing_lot_contract_var"):
                self.pricing_lot_contract_comm_var.set(comm or "ALL")
                if not is_open:
                    self.pricing_lot_contract_open_only_var.set(False)
                self._refresh_pricing_lot_contract_picker("")
                self.pricing_lot_contract_var.set(label)
        except Exception:
            pass

        # Contracts tree selection drives editor/detail panels.
        try:
            if hasattr(self, "contract_tree") and self.contract_tree.exists(cid):
                self.contract_tree.selection_set(cid)
                self.contract_tree.see(cid)
                self.load_contract_from_tree()
                self.update_contract_detail_panel()
        except Exception:
            pass

        # Consumption source contract (open contracts only by design).
        try:
            if is_open and hasattr(self, "cl_contract_var"):
                cvals = list(self.cl_contract_combo["values"])
                hit = next((v for v in cvals if v.startswith(cid)), None)
                if hit:
                    self.cl_contract_var.set(hit)
        except Exception:
            pass


    def save_marginal_threshold(self):
        try:
            v = to_float(self.marginal_thr_var.get(), 200)
            if v is None or v < 0:
                raise ValueError
            self.state_obj.setdefault("ui", {})["marginal_threshold_egp_mt"] = float(v)
            save_state(self.state_obj)
            self.refresh_all()
        except Exception:
            messagebox.showwarning(APP_NAME, "Enter a valid non-negative number for marginal threshold.")


    def _read_csv_rows(self, title="Import CSV"):
        fp = filedialog.askopenfilename(filetypes=[("CSV", "*.csv")], title=title)
        if not fp:
            return None, []
        try:
            with open(fp, "r", encoding="utf-8-sig", newline="") as f:
                rows = list(csv.DictReader(f))
            return fp, rows
        except Exception as e:
            self._surface_error("CSV import failed", e, show=True)
            return None, []

    # ── Excel / CSV import with preview ───────────────────────────────
    # Reads .xlsx / .csv, detects date / commodity / price / transport
    # columns (English or Arabic headers), previews the parse, and upserts
    # on (date, commodity). Nothing enters the dataset without being seen.
    _IMP_HDR_KEYS = {
        "date":      ("date", "تاريخ", "day"),
        "commodity": ("commodity", "comm", "item", "صنف", "المادة", "خامة"),
        "price":     ("price", "egp", "سعر", "السعر"),
        "transport": ("transport", "freight", "نقل", "النقل"),
    }

    @staticmethod
    def _imp_parse_date(v):
        """Accept date objects, YYYY-MM-DD, DD/MM/YYYY, DD-MM-YYYY."""
        if v is None:
            return None
        if isinstance(v, dt.datetime):
            return v.date().isoformat()
        if isinstance(v, dt.date):
            return v.isoformat()
        s = str(v).strip().split(" ")[0]
        if not s:
            return None
        try:
            return dt.date.fromisoformat(s).isoformat()
        except Exception:
            pass
        m = re.match(r"^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})$", s)
        if m:
            d_, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                return dt.date(y, mo, d_).isoformat()
            except Exception:
                return None
        return None

    def _imp_read_rows(self, fp):
        """Return list-of-lists of raw cell values from .xlsx or .csv."""
        if fp.lower().endswith(".csv"):
            import csv
            rows = []
            with open(fp, "r", encoding="utf-8-sig", newline="") as f:
                for r in csv.reader(f):
                    rows.append(r)
            return rows
        if not _need_openpyxl():
            return None
        from openpyxl import load_workbook
        wb = load_workbook(fp, data_only=True, read_only=True)
        ws = wb.active
        return [list(r) for r in ws.iter_rows(values_only=True)]

    def _imp_map_columns(self, rows):
        for ri, row in enumerate(rows[:10]):
            cells = [str(c).strip().lower() if c is not None else ""
                     for c in row]
            mapping = {}
            for field, keys in self._IMP_HDR_KEYS.items():
                for ci, cell in enumerate(cells):
                    if cell and any(k in cell for k in keys):
                        mapping[field] = ci
                        break
            if "date" in mapping and "price" in mapping and "commodity" in mapping:
                return ri, mapping
        return None, None

    def import_local_prices_file(self):
        try:
            fp = filedialog.askopenfilename(
                title="Import local prices",
                filetypes=[("Excel / CSV", "*.xlsx *.xlsm *.csv"),
                           ("Excel", "*.xlsx *.xlsm"), ("CSV", "*.csv")])
            if not fp:
                return
            rows = self._imp_read_rows(fp)
            if rows is None:
                return
            hdr_i, colmap = self._imp_map_columns(rows)
            if colmap is None:
                messagebox.showerror(
                    APP_NAME,
                    "Could not find the header row.\n\n"
                    "The file needs columns for Date, Commodity and Price "
                    "(English or Arabic headers). Transport is optional.")
                return

            known_comms = {k.upper() for k in
                           (self.state_obj.get("commodities") or {})}
            default_trans = get_default_local_transport_egp_mt(self.state_obj)
            parsed, skipped = [], 0
            for row in rows[hdr_i + 1:]:
                def _cell(field):
                    ci = colmap.get(field)
                    if ci is None or ci >= len(row):
                        return None
                    return row[ci]
                d = self._imp_parse_date(_cell("date"))
                comm = str(_cell("commodity") or "").strip().upper()
                price = to_float(_cell("price"), None)
                trans = to_float(_cell("transport"), None)
                if not d or not comm or price is None or price <= 0:
                    if any(v is not None and str(v).strip() for v in row):
                        skipped += 1
                    continue
                parsed.append({
                    "date": d, "commodity": comm, "price_egp_mt": price,
                    "transport_egp_mt": trans if trans is not None else default_trans,
                    "_known": comm in known_comms,
                })
            if not parsed:
                messagebox.showerror(
                    APP_NAME, f"No importable rows found ({skipped} skipped).")
                return
            self._imp_show_preview(fp, parsed, skipped)
        except Exception as e:
            self._surface_error("import_local_prices_file", e, show=True)

    def _imp_show_preview(self, fp, parsed, skipped):
        """Preview window: nothing enters the dataset without being seen."""
        win = tk.Toplevel(self)
        win.title("Import preview — local prices")
        win.geometry("720x460")
        win.columnconfigure(0, weight=1)
        win.rowconfigure(1, weight=1)

        unknown = sum(1 for r in parsed if not r["_known"])
        head = (f"{len(parsed)} rows ready from {os.path.basename(fp)}"
                f"   ·   {skipped} skipped (missing/invalid data)")
        if unknown:
            head += (f"   ·   ⚠ {unknown} rows use a commodity code not in "
                     f"Setup → Commodities (they import, but check spelling)")
        ttk.Label(win, text=head, font=(FONT_FAMILY, FS_BODY, "bold"),
                  foreground=CLR["warning"] if unknown else CLR["success"],
                  wraplength=690).grid(row=0, column=0, sticky="w",
                                       padx=10, pady=(10, 6))

        frame = ttk.Frame(win)
        frame.grid(row=1, column=0, sticky="nsew", padx=10)
        frame.columnconfigure(0, weight=1)
        frame.rowconfigure(0, weight=1)
        cols = [("Date", 100, "w"), ("Commodity", 120, "w"),
                ("Price EGP/MT", 110, "e"), ("Transport EGP/MT", 120, "e"),
                ("Known?", 70, "w")]
        tv = ttk.Treeview(frame, columns=[c for c, _, _ in cols],
                          show="headings")
        for c, w, a in cols:
            tv.heading(c, text=c)
            tv.column(c, width=w, anchor=a)
        tv.tag_configure("unk", foreground=CLR["warning"])
        for r in parsed:
            tv.insert("", "end",
                      values=(r["date"], r["commodity"],
                              fmt_num(r["price_egp_mt"], 2),
                              fmt_num(r["transport_egp_mt"], 2),
                              "yes" if r["_known"] else "NEW"),
                      tags=() if r["_known"] else ("unk",))
        tv.grid(row=0, column=0, sticky="nsew")
        ysb = ttk.Scrollbar(frame, orient="vertical", command=tv.yview)
        tv.configure(yscrollcommand=ysb.set)
        ysb.grid(row=0, column=1, sticky="ns")

        btns = ttk.Frame(win)
        btns.grid(row=2, column=0, sticky="ew", padx=10, pady=8)

        def _do_import():
            lp = self.state_obj.setdefault("local_prices", [])
            added = updated = 0
            for r in parsed:
                hit = next((x for x in lp
                            if x.get("date") == r["date"]
                            and x.get("commodity") == r["commodity"]), None)
                if hit:
                    hit["price_egp_mt"] = r["price_egp_mt"]
                    hit["transport_egp_mt"] = r["transport_egp_mt"]
                    updated += 1
                else:
                    lp.append({k: r[k] for k in
                               ("date", "commodity", "price_egp_mt",
                                "transport_egp_mt")})
                    added += 1
            save_state(self.state_obj)
            try:
                self.refresh_local_prices_tree()
                self.refresh_all()
            except Exception as e:
                log_exception(e, "import_local_prices_file:refresh")
            win.destroy()
            messagebox.showinfo(
                APP_NAME,
                f"Import complete.\n\nAdded: {added}\nUpdated: {updated}")

        ttk.Button(btns, text=f"Import {len(parsed)} rows",
                   command=_do_import).pack(side="left", padx=(0, 8))
        ttk.Button(btns, text="Cancel", command=win.destroy).pack(side="left")

    def import_local_prices_csv(self):
        fp, rows = self._read_csv_rows("Import Local Prices CSV")
        if not rows:
            return
        required = {"date", "commodity", "price_egp_mt"}
        headers = {h.strip() for h in (rows[0].keys() if rows else []) if h}
        missing = required - headers
        if missing:
            messagebox.showerror(APP_NAME, "Missing CSV column(s): " + ", ".join(sorted(missing)))
            return
        imported = 0
        errors = []
        lp = self.state_obj.setdefault("local_prices", [])
        for i, r in enumerate(rows, start=2):
            try:
                d = (r.get("date") or "").strip()
                dt.date.fromisoformat(d)
                comm = (r.get("commodity") or "").strip().upper()
                price = to_float(r.get("price_egp_mt"), None)
                trans = to_float(r.get("transport_egp_mt"), get_default_local_transport_egp_mt(self.state_obj))
                if not comm or price is None:
                    raise ValueError("commodity and price_egp_mt are required")
                existing = next((x for x in lp if x.get("date") == d and x.get("commodity") == comm), None)
                payload = {
                    "date": d,
                    "commodity": comm,
                    "price_egp_mt": price,
                    "transport_egp_mt": trans,
                    "provenance": make_provenance(source="csv_import", as_of=d, confidence="user-supplied", note=os.path.basename(fp)),
                }
                if existing:
                    existing.update(payload)
                else:
                    lp.append(payload)
                imported += 1
            except Exception as e:
                errors.append(f"row {i}: {e}")
        append_audit_event(self.state_obj, "import_local_prices_csv", "local_prices", os.path.basename(fp), {"rows": imported, "errors": len(errors)})
        if errors:
            record_data_issue(self.state_obj, "import_local_prices_csv", " | ".join(errors[:10]), severity="WARN")
        save_state(self.state_obj)
        self.refresh_all()
        msg = f"Imported/updated {imported} local price row(s)."
        if errors:
            msg += f"\n\nSkipped {len(errors)} row(s). First issues:\n" + "\n".join(errors[:8])
        messagebox.showinfo(APP_NAME, msg)

    def import_contracts_csv(self):
        fp, rows = self._read_csv_rows("Import Contracts CSV")
        if not rows:
            return
        required = {"name", "supplier", "commodity"}
        headers = {h.strip() for h in (rows[0].keys() if rows else []) if h}
        missing = required - headers
        if missing:
            messagebox.showerror(APP_NAME, "Missing CSV column(s): " + ", ".join(sorted(missing)))
            return
        imported = 0
        errors = []
        contracts = self.state_obj.setdefault("contracts", {})
        for i, r in enumerate(rows, start=2):
            try:
                name = (r.get("name") or "").strip()
                supplier = (r.get("supplier") or "").strip()
                commodity = (r.get("commodity") or "").strip().upper()
                if not name or not supplier or not commodity:
                    raise ValueError("name, supplier and commodity are required")
                cid = (r.get("contract_id") or "").strip() or new_contract_id(self.state_obj)
                if cid in contracts:
                    cid = new_contract_id(self.state_obj)
                rec = {
                    "name": name,
                    "supplier": supplier,
                    "commodity": commodity,
                    "origin": normalize_origin(r.get("origin") or "OTHER"),
                    "status": (r.get("status") or "Open").strip() or "Open",
                    "qty_mt": to_float(r.get("qty_mt"), None),
                    "note": (r.get("note") or "").strip(),
                    "storage_start": (r.get("storage_start") or "").strip(),
                    "storage_end": (r.get("storage_end") or "").strip(),
                    "created_ts": now_ts(),
                    "provenance": make_provenance(source="csv_import", confidence="user-supplied", note=os.path.basename(fp)),
                }
                optional_float_fields = [
                    "cif_usd_mt", "delivery_fx", "discharge_egp_mt", "clearance_egp_mt",
                    "freight_egp_mt", "premium_cents", "own_after_usd_mt",
                ]
                for key in optional_float_fields:
                    val = to_float(r.get(key), None)
                    if val is not None:
                        rec[key] = val
                for key in ["delivery_date", "pricing_date", "contract_date", "form4_date", "loading_port", "destination", "futures_month"]:
                    val = (r.get(key) or "").strip()
                    if val:
                        rec[key] = iso_date_or_keep(val) if key.endswith("_date") else val
                contracts[cid] = rec
                append_audit_event(self.state_obj, "import_contract_csv_row", "contract", cid, {"name": name, "commodity": commodity})
                imported += 1
            except Exception as e:
                errors.append(f"row {i}: {e}")
        append_audit_event(self.state_obj, "import_contracts_csv", "contracts", os.path.basename(fp), {"rows": imported, "errors": len(errors)})
        if errors:
            record_data_issue(self.state_obj, "import_contracts_csv", " | ".join(errors[:10]), severity="WARN")
        save_state(self.state_obj)
        self.refresh_all()
        msg = f"Imported {imported} contract row(s)."
        if errors:
            msg += f"\n\nSkipped {len(errors)} row(s). First issues:\n" + "\n".join(errors[:8])
        messagebox.showinfo(APP_NAME, msg)

    def export_json(self):
        fp = filedialog.asksaveasfilename(defaultextension=".json", filetypes=[("JSON","*.json")], title="Export state to JSON")
        if not fp:
            return
        try:
            with open(fp,"w",encoding="utf-8") as f:
                json.dump(self.state_obj, f, indent=2, ensure_ascii=False)
            self.status_var.set(f"Exported: {fp}")
        except Exception as e:
            messagebox.showerror(APP_NAME, f"Export failed:\n{e}")

    def reset_data(self):
        """
        Wipe all saved user data (contracts, snapshots, suppliers) and start clean.
        Commodities list stays as the built-in defaults.
        A rolling backup is created automatically before wipe.
        """
        try:
            typed = simpledialog.askstring(
                APP_NAME,
                "This will DELETE all saved data (contracts, suppliers, snapshots).\n"
                "A backup will be saved automatically first.\n\n"
                "Type DELETE (in capitals) to confirm:",
                parent=self)
            if (typed or "").strip() != "DELETE":
                self.status_var.set("Reset cancelled — nothing was deleted.")
                return
            # backup current state file (if exists)
            try:
                backup_state_file()
            except Exception:
                pass

            # reset to clean defaults and persist
            self.state_obj = default_state()
            save_state(self.state_obj)

            # refresh UI
            self.refresh_all()
            messagebox.showinfo(APP_NAME, "Done. App is now clean (no contracts/snapshots/suppliers).")
        except Exception as e:
            messagebox.showerror(APP_NAME, str(e))


    def import_json(self):
        fp = filedialog.askopenfilename(filetypes=[("JSON","*.json")], title="Load state JSON")
        if not fp:
            return
        try:
            with open(fp,"r",encoding="utf-8") as f:
                s=json.load(f)
            self.state_obj = s
            save_state(self.state_obj)
            self.refresh_all()
            self.status_var.set(f"Loaded: {fp}")
        except Exception as e:
            messagebox.showerror(APP_NAME, f"Load failed:\n{e}")


    def _latest_snapshot(self, contract_id):
        """Return latest snapshot dict for given contract_id, or None."""
        best = None
        best_key = None
        for s in self.state_obj.get("history", []):
            if str(s.get("contract_id")) != str(contract_id):
                continue
            ts = s.get("ts") or s.get("timestamp") or ""
            key = ts
            if isinstance(ts, str):
                try:
                    key = dt.datetime.fromisoformat(ts.replace("Z","").strip())
                except Exception:
                    key = ts
            if best is None or (key is not None and key > (best_key or 0)):
                best = s
                best_key = key
        return best

    def _latest_contract_snapshot(self, contract_id):
        """Return latest snapshot from state_obj['snapshots'] for the contract."""
        best = None
        best_key = None
        for s in self.state_obj.get("snapshots", []):
            if str(s.get("contract_id")) != str(contract_id):
                continue
            ts = s.get("ts") or s.get("timestamp") or ""
            key = ts
            if isinstance(ts, str):
                try:
                    key = dt.datetime.fromisoformat(ts.replace("Z", "").strip())
                except Exception:
                    key = ts
            if best is None or (key is not None and key > (best_key or 0)):
                best = s
                best_key = key
        return best

    @staticmethod
    def _cbot_entry_as_dict(entry):
        """cbot_quotes entries are inconsistently stored: some writers save a
        bare number (the price), others save a full dict with a 'price' key.
        Normalise either shape to a dict so '.get(\"price\")' is always safe."""
        if isinstance(entry, dict):
            return entry
        if entry in (None, ""):
            return {}
        return {"price": entry}

    def _contract_market_view(self, cid, contract_obj=None):
        c = contract_obj or (self.state_obj.get("contracts", {}) or {}).get(cid, {}) or {}
        s = self._latest_contract_snapshot(cid) or {}
        comm = (c.get("commodity") or s.get("commodity") or "").strip().upper()
        comm_meta = (self.state_obj.get("commodities", {}) or {}).get(comm, {}) or {}
        market_data = self.state_obj.get("market_data", {}) or {}
        fx_quote = market_data.get("fx", {}) or {}
        cbot_quote = self._cbot_entry_as_dict((market_data.get("cbot_quotes", {}) or {}).get(comm))

        premium = to_float(s.get("premium_usd_mt"), None)
        fx = to_float(s.get("fx"), None)
        fx_ts = s.get("ts") or ""
        fx_source = "Latest Snapshot" if fx is not None else ""
        if fx is None:
            fx = to_float(fx_quote.get("price"), None)
            fx_ts = fx_quote.get("market_time_text") or fx_quote.get("fetched_at") or ""
            fx_source = fx_quote.get("source") or ("Yahoo delayed" if fx is not None else "")

        cbot = to_float(s.get("cbot"), None)
        cbot_ts = s.get("ts") or ""
        if cbot is None:
            cbot = to_float(cbot_quote.get("price"), None)
            cbot_ts = cbot_quote.get("market_time_text") or cbot_quote.get("fetched_at") or ""

        import_usd = to_float(s.get("import_usd_mt"), None)
        if import_usd is None and cbot is not None and premium is not None:
            try:
                import_usd = cbot_to_usd_mt(comm_meta, cbot, premium)
            except Exception:
                import_usd = None

        provisional_egp = None
        if import_usd is not None and fx is not None:
            provisional_egp = import_usd * fx

        fx_day = ""
        if fx_ts:
            fx_day = str(fx_ts)[:10]

        return {
            "snapshot": s,
            "commodity": comm,
            "premium": premium,
            "cbot": cbot,
            "cbot_ts": cbot_ts,
            "import_usd_mt": import_usd,
            "provisional_egp_mt": provisional_egp,
            "fx": fx,
            "fx_ts": fx_ts,
            "fx_day": fx_day,
            "fx_source": fx_source,
        }

    def _latest_snapshot_value(self, contract_id, key):
        s = self._latest_snapshot(contract_id)
        return s.get(key) if s else None



    def _snapshots_list(self):
        """Return the list object used for storing snapshots (backward compatible)."""
        if "snapshots" not in self.state_obj and "history" in self.state_obj:
            self.state_obj["snapshots"] = list(self.state_obj.get("history") or [])
        self.state_obj.setdefault("snapshots", [])
        # Keep alias
        self.state_obj["history"] = self.state_obj["snapshots"]
        return self.state_obj["snapshots"]

    def _get_history_tree(self):
        """Return the Treeview widget that shows History (Snapshots)."""
        for name in ("hist_tree", "history_tree", "snap_tree", "snapshot_tree"):
            tv = getattr(self, name, None)
            if tv is not None:
                return tv
        return None


    def _sort_treeview(self, tv, col):
        """Sort a ttk.Treeview by column (toggle asc/desc)."""
        # Track sort state per tree+col
        if not hasattr(self, "_tv_sort_state"):
            self._tv_sort_state = {}
        key = (id(tv), col)
        reverse = self._tv_sort_state.get(key, False)

        def parse(v):
            if v is None:
                return (1, "")
            s = str(v).strip()
            if s == "" or s == "-":
                return (1, "")
            # try numeric
            try:
                s2 = s.replace(",", "")
                return (0, float(s2))
            except Exception:
                return (0, s.lower())

        items = [(parse(tv.set(k, col)), k) for k in tv.get_children("")]
        items.sort(reverse=reverse, key=lambda x: x[0])

        for idx, (_, k) in enumerate(items):
            tv.move(k, "", idx)

        self._tv_sort_state[key] = not reverse
    def refresh_all(self, fetch_market=False):
        if fetch_market:
            try:
                self._pb_fetch_all(silent=False, reason="manual")
            except Exception:
                pass
        for _fn_name in ("refresh_contract_selector", "refresh_lists",
                         "refresh_contracts_tree", "refresh_suppliers_tree",
                         "refresh_commodities_tree", "refresh_history_tree"):
            try:
                getattr(self, _fn_name)()
            except Exception as _e:
                log_exception(_e, f"refresh_all:{_fn_name}")
        try:
            self.refresh_consumption_table()
        except Exception:
            pass
        try:
            self.refresh_consumption_full()
        except Exception:
            pass
        try:
            self.refresh_slots_tab()
        except Exception:
            pass
        try:
            # refresh per-contract roll panel if a contract is currently selected
            sel = self.contract_tree.selection() if hasattr(self, "contract_tree") else []
            if sel:
                self._refresh_contract_roll_panel(sel[0])
        except Exception:
            pass
        try:
            self.refresh_home_dashboard()
        except Exception:
            pass
        try:
            self.refresh_savings_tracker()
        except Exception as e:
            log_exception(e, "refresh_all→refresh_savings_tracker")
        try:
            self.refresh_local_purchases()
        except Exception:
            pass
        try:
            self._fr_refresh_apply_combos()
        except Exception:
            pass
        self.status_var.set(f"Saved: {self.state_obj.get('meta',{}).get('saved_ts','')}")
        try:
            self._set_statusbar(
                save_msg=self.state_obj.get("meta", {}).get("saved_ts", ""))
        except Exception:
            pass
        try:
            self.refresh_risk_alerts()
        except Exception:
            pass
        # Zebra-stripe the main tables (cheap, idempotent, applies to
        # whatever rows the refreshes above just inserted)
        for _tv_name in ("contract_tree", "lp_tree", "local_prices_tree",
                         "slots_tree", "hd_exposure_tree",
                         "exp_alert_tree", "cons_log_tree", "sup_tree"):
            _tv = getattr(self, _tv_name, None)
            if _tv is not None:
                self.stripe_tree(_tv)
        try:
            self._refresh_onboarding_strip()
        except Exception:
            pass

