    def refresh_contracts_tree(self):
        for i in self.contract_tree.get_children():
            self.contract_tree.delete(i)
        search = (self.contract_search_var.get().strip().lower() if hasattr(self, "contract_search_var") else "")
        commodity_filter = (self.contract_filter_commodity_var.get().strip() if hasattr(self, "contract_filter_commodity_var") else "ALL") or "ALL"
        status_filter = (self.contract_filter_status_var.get().strip() if hasattr(self, "contract_filter_status_var") else "ALL") or "ALL"
        origin_filter = (self.contract_filter_origin_var.get().strip() if hasattr(self, "contract_filter_origin_var") else "ALL") or "ALL"
        open_only = bool(self.contract_open_only_var.get()) if hasattr(self, "contract_open_only_var") else False
        rows = []
        total_qty = 0.0
        total_remaining = 0.0
        open_qty = 0.0
        open_count = 0
        closed_count = 0
        missing_count = 0
        open_value = 0.0
        open_edge = 0.0
        open_edge_has_value = False
        contracts = self.state_obj.get("contracts", {}) or {}
        market_data = self.state_obj.get("market_data", {}) or {}
        cbot_quotes = market_data.get("cbot_quotes", {}) or {}

        for cid, c in self._sorted_contract_items(contracts):
            bal = self._calc_contract_balance_row(cid, c)
            status = c.get("status", "Open")
            if open_only and status != "Open":
                continue
            if commodity_filter != "ALL" and c.get("commodity", "") != commodity_filter:
                continue
            origin = (c.get("origin") or "").strip()
            if origin_filter != "ALL" and origin != origin_filter:
                continue
            if status_filter != "ALL" and status != status_filter:
                continue
            hay = " ".join([
                cid, c.get("name", ""), c.get("supplier", ""), c.get("commodity", ""), origin,
                c.get("note", ""), c.get("delivery_date", ""), c.get("storage_start", ""), c.get("storage_end", ""),
                c.get("pricing_date", ""), c.get("contract_date", ""), c.get("deal_date", ""),
                " ".join(str(l.get("date", "")) for l in (c.get("pricing_lots", []) or []) if isinstance(l, dict))
            ]).lower()
            if search and search not in hay:
                continue

            qty = to_float(c.get("qty_mt"), None)
            rem = to_float(bal.get("RemainingMT"), None)
            mkt = self._contract_market_view(cid, c)
            comm = (c.get("commodity") or mkt.get("commodity") or "").strip().upper()
            comm_key = comm.split("-")[0] if "-" in comm else comm

            # Pricing shown in the redesigned table. For open CORN contracts,
            # show the live mark-to-market CIF when we have live CBOT + premium.
            premium = to_float(c.get("premium_cents"), None)
            if premium is None:
                premium = to_float(mkt.get("premium"), None)
            cif_val = to_float(c.get("cif_usd_mt") or c.get("own_after_usd_mt"), None)
            live_cbot = None
            try:
                live_cbot = to_float(self._cbot_entry_as_dict(
                    cbot_quotes.get(comm) or cbot_quotes.get(comm_key)).get("price"), None)
            except Exception:
                live_cbot = None
            if status == "Open" and live_cbot is not None and premium is not None and comm_key == "CORN":
                cif_val = (live_cbot + premium) * 0.3937
            elif cif_val is None:
                cif_val = to_float(mkt.get("import_usd_mt"), None)

            fx_val = to_float(c.get("delivery_fx"), None)
            if fx_val is None:
                fx_val = to_float(mkt.get("fx"), None)
            dis = to_float(c.get("discharge_egp_mt"), 0) or 0
            clr = to_float(c.get("clearance_egp_mt"), 0) or 0
            frt = to_float(c.get("freight_egp_mt"), None)
            own_after = None
            if cif_val is not None and fx_val is not None:
                own_after = (cif_val * fx_val) + dis + clr + (frt or 0)

            row_missing = False
            if status == "Open":
                if qty is not None:
                    open_qty += qty
                open_count += 1
                if rem is not None and own_after is not None:
                    open_value += own_after * rem
                latest_local, _lday = self._latest_local_price_for_commodity(comm)
                if latest_local is not None and own_after is not None and rem is not None:
                    open_edge += (latest_local - own_after) * rem
                    open_edge_has_value = True
                if cif_val is None or fx_val is None or c.get("freight_egp_mt") in (None, ""):
                    row_missing = True
                    missing_count += 1
            else:
                closed_count += 1

            if qty is not None:
                total_qty += qty
            if rem is not None:
                total_remaining += rem
            rows.append((cid, c, bal))

            tags = ["open" if status == "Open" else "closed"]
            if row_missing:
                tags.append("missing")
            latest_local_for_tag, _ = self._latest_local_price_for_commodity(comm)
            if status == "Open" and latest_local_for_tag is not None and own_after is not None:
                tags.append("gain" if latest_local_for_tag - own_after >= 0 else "loss")

            delivery_date = (c.get("delivery_date") or c.get("storage_start") or "")
            self.contract_tree.insert("", "end", iid=cid, tags=tuple(tags), values=(
                cid,
                delivery_date,
                c.get("name", ""),
                status,
                c.get("supplier", ""),
                comm,
                origin,
                fmt_num(qty, 0) if qty is not None else "",
                fmt_num(rem, 0) if rem is not None else "",
                fmt_num(cif_val, 2) if cif_val is not None else "",
                fmt_num(premium, 2) if premium is not None else "",
                c.get("pricing_date", ""),
                str(len(self._contract_pricing_lots(c))) if self._contract_pricing_lots(c) else "",
                fmt_num(frt, 2) if frt is not None else "",
                fmt_num(own_after, 2) if own_after is not None else "",
                fmt_num(fx_val, 4) if fx_val is not None else "",
                mkt.get("fx_day", ""),
                (fmt_num(to_float(c.get("form4_fx"), None), 4)
                 if c.get("form4_fx") not in (None, "") else ""),
            ))

        fx_quote = (self.state_obj.get("market_data", {}) or {}).get("fx", {}) or {}
        fx_txt = "-"
        if fx_quote.get("price") not in (None, ""):
            fx_txt = f"{fmt_num(to_float(fx_quote.get('price'), None),4)} ({str(fx_quote.get('market_time_text') or fx_quote.get('fetched_at') or '')[:16]})"
        self.contracts_summary_var.set(
            f"Contracts: {len(rows)} | Open: {open_count} | Closed: {closed_count} | Qty: {fmt_num(total_qty,0)} MT | Remaining: {fmt_num(total_remaining,0)} MT | Current FX: {fx_txt}"
        )

        if hasattr(self, "ct_kpi_total_var"):
            self.ct_kpi_total_var.set(str(len(rows)))
            self.ct_kpi_open_var.set(str(open_count))
            self.ct_kpi_closed_var.set(str(closed_count))
            self.ct_kpi_open_qty_var.set(f"{fmt_num(open_qty,0)} MT")
            self.ct_kpi_remaining_var.set(f"{fmt_num(total_remaining,0)} MT")
            self.ct_kpi_open_edge_var.set(("EGP " + fmt_num(open_edge,0)) if open_edge_has_value else "Need local")
            self.ct_kpi_missing_var.set(str(missing_count))
        self.update_contract_detail_panel()

