    def refresh_history_tree(self):
        for i in self.hist_tree.get_children():
            self.hist_tree.delete(i)
        selected = self.state_obj["ui"].get("selected_contract_id","ALL")
        search = self.hist_search_var.get().strip().lower() if hasattr(self, "hist_search_var") else ""
        commodity_filter = (self.hist_filter_commodity_var.get().strip() if hasattr(self, "hist_filter_commodity_var") else "ALL") or "ALL"
        origin_filter = (self.hist_filter_origin_var.get().strip() if hasattr(self, "hist_filter_origin_var") else "ALL") or "ALL"
        result_filter = (self.hist_filter_result_var.get().strip() if hasattr(self, "hist_filter_result_var") else "ALL") or "ALL"
        shown = []
        best = None
        worst = None
        for idx, s in enumerate(self.state_obj.get("snapshots", [])):
            if selected != "ALL" and s.get("contract_id") != selected:
                continue
            cid = s.get("contract_id","")
            c = self.state_obj["contracts"].get(cid, {})
            label = f"{cid} - {c.get('name','')}" if cid else s.get("contract_name", "")
            origin = s.get("origin") or c.get("origin","")
            commodity = s.get("commodity","")
            if commodity_filter != "ALL" and commodity != commodity_filter:
                continue
            if origin_filter != "ALL" and origin != origin_filter:
                continue
            direct = to_float(s.get("direct_saving_egp_mt"), None)
            decision = self._snapshot_decision_label(s)
            if result_filter == "Positive" and not (direct is not None and direct > 0):
                continue
            if result_filter == "Negative" and not (direct is not None and direct < 0):
                continue
            if result_filter == "Neutral" and not (direct is not None and abs(direct) < 0.000001):
                continue
            hay = " ".join([
                str(s.get("snapshot_id") or s.get("id") or ""), s.get("ts", ""), label, commodity, origin,
                fmt_num(to_float(s.get("fx"), None), 2), fmt_num(direct, 2), decision
            ]).lower()
            if search and search not in hay:
                continue
            sid = str(s.get("snapshot_id") or s.get("id") or f"row_{idx}")
            shown.append(s)
            if direct is not None:
                best = direct if best is None else max(best, direct)
                worst = direct if worst is None else min(worst, direct)
            self.hist_tree.insert("", "end", iid=sid, values=(
                sid,
                s.get("ts", ""),
                label,
                commodity,
                origin,
                fmt_num(to_float(s.get("qty_mt"), None), 0),
                fmt_num(to_float(s.get("fx"), None), 2),
                fmt_num(to_float(s.get("cbot_price"), None), 2),
                fmt_num(to_float(s.get("premium_basis"), None), 2),
                fmt_num(direct, 2),
                fmt_num(to_float(s.get("indirect_saving_egp_mt"), None), 2),
                decision,
            ))
        self.history_summary_var.set(
            f"Snapshots: {len(shown)} | Best Direct Saving: {fmt_num(best,2)} | Worst Direct Saving: {fmt_num(worst,2)}"
        )
        self.update_history_detail_panel()

    def apply_bulk_fx_market_update(self):
        """Create a 'market update' snapshot per OPEN contract using a new FX, respecting current dashboard commodity filter."""
        new_fx = to_float(self.bulk_fx_var.get() if hasattr(self, "bulk_fx_var") else "", None)
        if new_fx is None or new_fx <= 0:
            messagebox.showwarning(APP_NAME, "Enter a valid FX > 0.")
            return

        # Write FX to market_data AND directly to every open contract
        md = self.state_obj.setdefault("market_data", {})
        md.setdefault("fx", {})
        md["fx"]["price"]      = new_fx
        md["fx"]["fetched_at"] = dt.date.today().isoformat()
        today = dt.date.today().isoformat()
        for c in self.state_obj.get("contracts", {}).values():
            if (c.get("status", "Open") or "Open") == "Open":
                c["delivery_fx"] = new_fx
                if not c.get("delivery_date"):
                    c["delivery_date"] = today

        # latest snapshot per contract
        latest = {}
        for s in self.state_obj.get("snapshots", []):
            cid = s.get("contract_id","")
            if cid:
                latest[cid] = s

        open_ids = [cid for cid,c in (self.state_obj.get("contracts", {}) or {}).items() if c.get("status","Open")=="Open"]

        # dashboard commodity filter (already used in dashboard view)
        flt = (self.state_obj.get("ui", {}).get("dashboard_commodity_filter") or "ALL")
        if flt and flt != "ALL":
            open_ids = [cid for cid in open_ids if ((self.state_obj["contracts"].get(cid, {}) or {}).get("commodity","") or (latest.get(cid, {}) or {}).get("commodity","") or "UNKNOWN") == flt]

        if not open_ids:
            messagebox.showinfo(APP_NAME, "No OPEN contracts found for current filter.")
            return

        created = 0
        for cid in open_ids:
            c = self.state_obj["contracts"].get(cid, {}) or {}
            s0 = latest.get(cid, {}) or {}

            comm = (c.get("commodity","") or s0.get("commodity","") or "UNKNOWN").upper()
            comm_meta = (self.state_obj.get("commodities", {}) or {}).get(comm, {"type":"NONCBOT","conversion_type":"none","conversion_value":1.0})

            # Supplier intake from Suppliers tab
            supplier = c.get("supplier","")
            sup_costs = (self.state_obj.get("suppliers", {}).get(supplier, {}) or {}).get(comm, {}) or {}
            direct = to_float(sup_costs.get("direct_egp_mt"), None)
            indirect = to_float(sup_costs.get("indirect_egp_mt"), None)

            inp = {
                "comm_meta": comm_meta,
                "fx": new_fx,
                "qty_mt": to_float(s0.get("qty_mt"), None) if s0.get("qty_mt") not in (None,"") else c.get("qty_mt"),
                "local_egp_mt": to_float(s0.get("local_egp_mt"), None),
                "finance_days": to_float(s0.get("finance_days"), None),
                "interest_rate": to_float(s0.get("interest_rate"), None),
                "supplier_direct_egp_mt": direct,
                "supplier_indirect_egp_mt": indirect,
            }

            if comm_meta.get("type") == "CBOT":
                inp["cbot"] = to_float(s0.get("cbot"), 0.0)
                inp["premium_usd_mt"] = to_float(s0.get("premium_usd_mt"), 0.0)
            else:
                if s0.get("import_usd_mt") not in (None,""):
                    inp["import_usd_mt"] = to_float(s0.get("import_usd_mt"), 0.0)
                else:
                    inp["import_egp_mt"] = to_float(s0.get("import_egp_mt"), 0.0)

            ok, _ = validate_single_inputs(comm_meta, inp)
            if not ok:
                continue

            out = compute_decision(inp)

            snap = {
                "snapshot_id": new_snapshot_id(self.state_obj),
                "ts": now_ts(),
                "contract_id": cid,
                "contract_label": contract_label(self.state_obj, cid),
                "commodity": comm,
                "supplier": supplier,
                "origin": c.get("origin", "") or s0.get("origin", ""),
                "fx": new_fx,
                "qty_mt": inp.get("qty_mt"),
                "local_egp_mt": inp.get("local_egp_mt"),
                "finance_days": inp.get("finance_days"),
                "interest_rate": inp.get("interest_rate"),
                "cbot": inp.get("cbot") if comm_meta.get("type")=="CBOT" else None,
                "premium_usd_mt": inp.get("premium_usd_mt") if comm_meta.get("type")=="CBOT" else None,
                "import_usd_mt": inp.get("import_usd_mt") if comm_meta.get("type")!="CBOT" else None,
                "import_egp_mt": inp.get("import_egp_mt") if comm_meta.get("type")!="CBOT" else None,
                "supplier_direct_egp_mt": direct,
                "supplier_indirect_egp_mt": indirect,

                "import_usd_mt_calc": out.get("import_usd_mt"),
                "carry_usd_mt": out.get("carry_usd_mt"),
                "own_after_usd_mt": out.get("own_after_usd_mt"),
                "own_after_egp_mt": out.get("own_after_egp_mt"),
                "saving_egp_mt": out.get("saving_egp_mt"),
                "direct_own_after_egp_mt": out.get("direct_own_after_egp_mt"),
                "indirect_own_after_egp_mt": out.get("indirect_own_after_egp_mt"),
                "direct_saving_egp_mt": out.get("direct_saving_egp_mt"),
                "indirect_saving_egp_mt": out.get("indirect_saving_egp_mt"),
                "break_even_fx_direct": out.get("break_even_fx_direct"),
                "break_even_fx_indirect": out.get("break_even_fx_indirect"),
                "note": f"Market FX update to {new_fx}",
            }

            self.state_obj["snapshots"].append(snap)
            created += 1

        save_state(self.state_obj)
        self.refresh_all()
        messagebox.showinfo(APP_NAME, f"Created {created} market-update snapshots with FX={new_fx}.")


    def _on_contract_tree_selection(self, _event=None):
        """Keep the editor/detail workspace stable during multi-selection."""
        try:
            sels = list(self.contract_tree.selection()) if hasattr(self, "contract_tree") else []
            if sels:
                self.load_contract_from_tree()
                self.update_contract_detail_panel()
            if hasattr(self, "contracts_summary_var") and len(sels) == 2:
                base = self.contracts_summary_var.get().split("  |  Selected:", 1)[0]
                self.contracts_summary_var.set(base + "  |  Selected: 2 · Compare ready")
        except Exception as exc:
            log_exception(exc, "_on_contract_tree_selection")

    def _contracts_table_items(self, contracts=None):
        """Return Contracts-tab rows in the selected, deterministic order.

        The operational default is delivery date newest-first.  Missing dates
        always fall behind dated contracts so legacy records never jump above
        current deliveries.
        """
        contracts = contracts if contracts is not None else (
            self.state_obj.get("contracts", {}) or {})
        items = list(contracts.items())
        mode = (self.contract_sort_var.get() if hasattr(self, "contract_sort_var")
                else "Delivery Date · Newest First")

        if mode == "Delivery Date · Oldest First":
            dated = [it for it in items if self._contract_sort_key(it)[0] > dt.date.min.toordinal()]
            missing = [it for it in items if self._contract_sort_key(it)[0] <= dt.date.min.toordinal()]
            dated.sort(key=self._contract_sort_key)
            missing.sort(key=lambda it: (self._contract_numeric_id_key(it[0]), str(it[0]).upper()), reverse=True)
            return dated + missing
        if mode == "Contract ID · Newest First":
            return sorted(items, key=lambda it: (self._contract_numeric_id_key(it[0]), str(it[0]).upper()), reverse=True)
        if mode == "Commodity · A–Z":
            return sorted(items, key=lambda it: (
                str((it[1] or {}).get("commodity") or "").upper(),
                -self._contract_sort_key(it)[0],
                tuple(-n for n in self._contract_numeric_id_key(it[0]))))
        if mode == "Supplier · A–Z":
            return sorted(items, key=lambda it: (
                str((it[1] or {}).get("supplier") or "").upper(),
                -self._contract_sort_key(it)[0],
                tuple(-n for n in self._contract_numeric_id_key(it[0]))))
        if mode == "Status · Open First":
            return sorted(items, key=lambda it: (
                0 if self._contract_is_open(it[1]) else 1,
                -self._contract_sort_key(it)[0],
                tuple(-n for n in self._contract_numeric_id_key(it[0]))))
        return self._sorted_contract_items(contracts)

    def _contract_priced_and_unpriced_qty(self, c):
        # Same "priced" definition as _home_contract_pricing_split(): without
        # pricing lots, a CBOT contract needs an agreed premium_cents to
        # count as priced (a CIF from a live/floating CBOT preview is not a
        # locked price); a non-CBOT contract has no premium step, so a
        # stored CIF is the final price.
        qty = to_float((c or {}).get("qty_mt"), None)
        lots = self._contract_pricing_lots(c or {})
        priced_qty = sum((to_float(lot.get("qty_mt"), 0) or 0)
                         for lot in lots if isinstance(lot, dict))
        if not lots and qty is not None:
            comm = ((c or {}).get("commodity") or "").strip().upper()
            comm_meta = self.state_obj.get("commodities", {}).get(comm, {}) or {}
            if (comm_meta.get("type") or "").upper() == "CBOT":
                if to_float((c or {}).get("premium_cents"), None) is not None:
                    priced_qty = qty
            elif self._contract_cif_usd(c or {}) is not None:
                priced_qty = qty
        if qty is None:
            return priced_qty or None, None
        return min(priced_qty, qty), max(qty - priced_qty, 0.0)

    def _contract_export_row(self, cid, c):
        """Build one auditable management row used by screen comparison/export."""
        c = c or {}
        status = (c.get("status") or "Open").strip() or "Open"
        is_open = self._contract_is_open(c)
        economics = self._hd_cost_for_contract(
            cid, c, use_latest_fx=is_open,
            fx_mode="live" if is_open else "locked")
        bal = self._calc_contract_balance_row(cid, c)
        qty = to_float(c.get("qty_mt"), None)
        remaining = to_float(bal.get("RemainingMT"), None)
        cif = to_float(economics.get("cif"), None)
        fx = to_float(economics.get("fx"), None)
        goods_egp = cif * fx if cif is not None and fx is not None else None
        lots = self._contract_pricing_lots(c)
        lot_dates = sorted({str(lot.get("date") or "") for lot in lots
                            if isinstance(lot, dict) and str(lot.get("date") or "").strip()})
        priced_qty, unpriced_qty = self._contract_priced_and_unpriced_qty(c)
        data_gaps = []
        if not (c.get("delivery_date") or c.get("storage_start")):
            data_gaps.append("Missing delivery date")
        if cif is None:
            data_gaps.append("Missing/estimated CIF")
        if fx is None:
            data_gaps.append("Missing FX")
        if economics.get("local") is None:
            data_gaps.append("Missing local comparison")
        if is_open and c.get("freight_egp_mt") in (None, ""):
            data_gaps.append("Missing freight")
        return {
            "contract_id": cid,
            "delivery_date": c.get("delivery_date") or c.get("storage_start") or "",
            "contract": c.get("name") or cid,
            "supplier": c.get("supplier") or "",
            "commodity": c.get("commodity") or "",
            "origin": c.get("origin") or "",
            "status": status,
            "result_type": "Indicative" if is_open else "Realised",
            "qty_mt": qty,
            "remaining_mt": remaining,
            "priced_qty_mt": priced_qty,
            "unpriced_qty_mt": unpriced_qty,
            "cif_usd_mt": cif,
            "premium": to_float(c.get("premium_cents"), None),
            "pricing_date": c.get("pricing_date") or "",
            "pricing_lot_dates": ", ".join(lot_dates),
            "pricing_lots": len(lots),
            "contract_fx": fx,
            "contract_fx_saved": to_float(c.get("delivery_fx"), None),
            "fx_reference_date": economics.get("local_date") or "",
            "form4_fx": to_float(c.get("form4_fx"), None),
            "discharge_egp_mt": to_float(economics.get("disc"), 0) or 0.0,
            "clearance_egp_mt": to_float(economics.get("clr"), 0) or 0.0,
            "freight_egp_mt": to_float(economics.get("freight"), 0) or 0.0,
            "contract_goods_egp_mt": goods_egp,
            "own_after_egp_mt": to_float(economics.get("own_after"), None),
            "local_egp_mt": to_float(economics.get("local"), None),
            "local_date": economics.get("local_date") or "",
            "saving_egp_mt": to_float(economics.get("sav_mt"), None),
            "total_saving_egp": to_float(economics.get("total_sav"), None),
            "notes": c.get("note") or "",
            "data_quality": "; ".join(data_gaps) if data_gaps else "Complete",
        }

    def _contract_export_items(self, scope="all"):
        contracts = self.state_obj.get("contracts", {}) or {}
        if scope == "visible" and hasattr(self, "contract_tree"):
            items = []
            for cid in self.contract_tree.get_children(""):
                c = contracts.get(cid)
                if c is not None:
                    items.append((cid, c))
            return items
        return self._sorted_contract_items(contracts)

    def _build_contracts_workbook(self, items, scope_label="All contracts"):
        """Create the Contracts-tab Excel workbook without opening dialogs."""
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter

        rows = [self._contract_export_row(cid, c) for cid, c in items]
        wb = Workbook()
        ws = wb.active
        ws.title = "Contracts"
        summary = wb.create_sheet("Summary", 0)
        lots_ws = wb.create_sheet("Pricing Lots")

        navy = "0B1F3A"; blue = "2563EB"; pale = "EAF2FF"
        green = "E8F7E8"; red = "FDECEA"; amber = "FFF7E6"; grey = "64748B"
        thin = Side(style="thin", color="D8E1EC")
        border = Border(left=thin, right=thin, top=thin, bottom=thin)
        header_fill = PatternFill("solid", fgColor=navy)
        sub_fill = PatternFill("solid", fgColor=pale)
        title_font = Font(name="Calibri", bold=True, size=16, color=navy)
        header_font = Font(name="Calibri", bold=True, color="FFFFFF", size=9)
        body_font = Font(name="Calibri", size=9, color="1E293B")

        summary["A1"] = "PROMETHEUS PROCUREMENT — CONTRACT PORTFOLIO"
        summary["A1"].font = title_font
        summary["A2"] = f"Scope: {scope_label}"
        summary["A3"] = f"Generated: {now_ts()}"
        summary["A5"] = "Contracts"; summary["B5"] = len(rows)
        summary["A6"] = "Open"; summary["B6"] = sum(1 for r in rows if r["status"] != "Closed")
        summary["A7"] = "Closed"; summary["B7"] = sum(1 for r in rows if r["status"] == "Closed")
        summary["A8"] = "Total Qty MT"; summary["B8"] = sum(r["qty_mt"] or 0 for r in rows)
        summary["A9"] = "Remaining MT"; summary["B9"] = sum(r["remaining_mt"] or 0 for r in rows)
        summary["A10"] = "Unpriced MT"; summary["B10"] = sum(r["unpriced_qty_mt"] or 0 for r in rows)
        summary["A11"] = "Realised Savings EGP"; summary["B11"] = sum(r["total_saving_egp"] or 0 for r in rows if r["result_type"] == "Realised")
        summary["A12"] = "Indicative Open Position EGP"; summary["B12"] = sum(r["total_saving_egp"] or 0 for r in rows if r["result_type"] == "Indicative")
        for row in range(5, 13):
            summary.cell(row, 1).font = Font(name="Calibri", bold=True, color=grey)
            summary.cell(row, 1).fill = sub_fill
            summary.cell(row, 1).border = summary.cell(row, 2).border = border
        for cell in (summary["B8"], summary["B9"], summary["B10"]):
            cell.number_format = "#,##0"
        for cell in (summary["B11"], summary["B12"]):
            cell.number_format = "#,##0;[Red]-#,##0"
        summary.column_dimensions["A"].width = 31
        summary.column_dimensions["B"].width = 22

        # Commodity summary.
        summary["D5"] = "Commodity"; summary["E5"] = "Contracts"; summary["F5"] = "Qty MT"; summary["G5"] = "Open MT"; summary["H5"] = "Saving / Position EGP"
        for col in range(4, 9):
            c = summary.cell(5, col); c.fill = header_fill; c.font = header_font; c.alignment = Alignment(horizontal="center"); c.border = border
        comms = sorted({str(r["commodity"] or "UNKNOWN") for r in rows})
        for idx, comm in enumerate(comms, 6):
            group = [r for r in rows if str(r["commodity"] or "UNKNOWN") == comm]
            vals = [comm, len(group), sum(r["qty_mt"] or 0 for r in group),
                    sum(r["remaining_mt"] or 0 for r in group if r["status"] != "Closed"),
                    sum(r["total_saving_egp"] or 0 for r in group)]
            for offset, val in enumerate(vals, 4):
                c = summary.cell(idx, offset, val); c.border = border; c.font = body_font
                if offset >= 6: c.number_format = "#,##0;[Red]-#,##0"
        for col, width in zip(range(4, 9), [16, 12, 14, 14, 23]):
            summary.column_dimensions[get_column_letter(col)].width = width

        headers = [
            ("delivery_date", "Delivery Date", 13), ("contract_id", "Contract ID", 13),
            ("contract", "Contract", 22), ("status", "Status", 10),
            ("result_type", "Result Type", 12), ("supplier", "Supplier", 18),
            ("commodity", "Commodity", 13), ("origin", "Origin", 14),
            ("qty_mt", "Qty MT", 12), ("remaining_mt", "Remaining MT", 14),
            ("priced_qty_mt", "Priced MT", 12), ("unpriced_qty_mt", "Unpriced MT", 12),
            ("cif_usd_mt", "CIF USD/MT", 13), ("premium", "Basis / Premium", 15),
            ("pricing_date", "Header Pricing Date", 16), ("pricing_lot_dates", "Lot Pricing Dates", 28),
            ("pricing_lots", "Lots", 8), ("contract_fx_saved", "Stored Contract FX", 16),
            ("contract_fx", "FX Used", 12), ("fx_reference_date", "FX / Local Ref Date", 17),
            ("form4_fx", "Form 4 FX", 12), ("discharge_egp_mt", "Discharge EGP/MT", 17),
            ("clearance_egp_mt", "Clearance EGP/MT", 17), ("freight_egp_mt", "Freight EGP/MT", 16),
            ("contract_goods_egp_mt", "Contract Goods EGP/MT", 20),
            ("own_after_egp_mt", "Own-After EGP/MT", 18),
            ("local_egp_mt", "Matched Local EGP/MT", 20), ("local_date", "Local Date", 13),
            ("saving_egp_mt", "Saving / Position EGP/MT", 23),
            ("total_saving_egp", "Total Saving / Position EGP", 26),
            ("data_quality", "Data Quality", 30), ("notes", "Notes", 35),
        ]
        ws["A1"] = "PROMETHEUS PROCUREMENT — CONTRACTS"
        ws["A1"].font = title_font
        ws["A2"] = scope_label
        for col, (_key, label, width) in enumerate(headers, 1):
            c = ws.cell(4, col, label); c.fill = header_fill; c.font = header_font; c.border = border; c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            ws.column_dimensions[get_column_letter(col)].width = width
        ws.row_dimensions[4].height = 34
        numeric_keys = {"qty_mt", "remaining_mt", "priced_qty_mt", "unpriced_qty_mt", "cif_usd_mt", "premium", "contract_fx_saved", "contract_fx", "form4_fx", "discharge_egp_mt", "clearance_egp_mt", "freight_egp_mt", "contract_goods_egp_mt", "own_after_egp_mt", "local_egp_mt", "saving_egp_mt", "total_saving_egp"}
        for ridx, row in enumerate(rows, 5):
            for cidx, (key, _label, _width) in enumerate(headers, 1):
                val = row.get(key)
                cell = ws.cell(ridx, cidx, val); cell.border = border; cell.font = body_font
                cell.alignment = Alignment(horizontal="right" if key in numeric_keys else "left", vertical="center", wrap_text=key in {"data_quality", "notes", "pricing_lot_dates"})
                if key in {"qty_mt", "remaining_mt", "priced_qty_mt", "unpriced_qty_mt", "pricing_lots"}:
                    cell.number_format = "#,##0"
                elif key in {"cif_usd_mt", "premium", "contract_fx_saved", "contract_fx", "form4_fx"}:
                    cell.number_format = "#,##0.0000"
                elif key in numeric_keys:
                    cell.number_format = "#,##0.00;[Red]-#,##0.00"
            sav = row.get("saving_egp_mt")
            if sav is not None:
                fill = PatternFill("solid", fgColor=green if sav >= 0 else red)
                ws.cell(ridx, 29).fill = fill; ws.cell(ridx, 30).fill = fill
            if row.get("data_quality") != "Complete":
                ws.cell(ridx, 31).fill = PatternFill("solid", fgColor=amber)
        ws.freeze_panes = "A5"
        ws.auto_filter.ref = f"A4:{get_column_letter(len(headers))}{max(4, 4 + len(rows))}"

        lot_headers = ["Contract ID", "Contract", "Commodity", "Delivery Date", "Lot #", "Pricing Date", "Qty MT", "Premium", "CBOT", "FX", "Futures Month", "Notes"]
        for cidx, label in enumerate(lot_headers, 1):
            c = lots_ws.cell(1, cidx, label); c.fill = header_fill; c.font = header_font; c.border = border; c.alignment = Alignment(horizontal="center")
        lot_row = 2
        for cid, c in items:
            for idx, lot in enumerate(self._contract_pricing_lots(c), 1):
                values = [cid, c.get("name") or cid, c.get("commodity") or "", c.get("delivery_date") or c.get("storage_start") or "", idx,
                          lot.get("date") or "", to_float(lot.get("qty_mt"), None), to_float(lot.get("premium_cents"), None),
                          to_float(lot.get("cbot"), None), to_float(lot.get("fx"), None), lot.get("futures_month") or "", lot.get("notes") or ""]
                for cidx, val in enumerate(values, 1):
                    cell = lots_ws.cell(lot_row, cidx, val); cell.border = border; cell.font = body_font
                    if cidx in (7, 8, 9, 10): cell.number_format = "#,##0.00"
                lot_row += 1
        for idx, width in enumerate([13, 22, 13, 13, 8, 13, 12, 12, 12, 12, 15, 35], 1):
            lots_ws.column_dimensions[get_column_letter(idx)].width = width
        lots_ws.freeze_panes = "A2"
        lots_ws.auto_filter.ref = f"A1:L{max(1, lot_row - 1)}"
        return wb, rows

    def _export_contracts_excel(self, scope="all"):
        if not _need_openpyxl():
            return
        try:
            items = self._contract_export_items(scope)
            if not items:
                messagebox.showinfo(APP_NAME, "No contracts match the current filters.")
                return
            if scope == "visible":
                comm = (self.contract_filter_commodity_var.get() if hasattr(self, "contract_filter_commodity_var") else "ALL") or "ALL"
                status = (self.contract_filter_status_var.get() if hasattr(self, "contract_filter_status_var") else "ALL") or "ALL"
                origin = (self.contract_filter_origin_var.get() if hasattr(self, "contract_filter_origin_var") else "ALL") or "ALL"
                scope_label = f"Visible contracts · Commodity={comm} · Status={status} · Origin={origin}"
                file_scope = comm if comm != "ALL" else "Filtered"
            else:
                scope_label = "All contracts · delivery date newest first"
                file_scope = "All"
            fp = filedialog.asksaveasfilename(
                initialdir=get_default_export_dir(),
                initialfile=f"Contracts_{file_scope}_{dt.date.today().isoformat()}.xlsx",
                defaultextension=".xlsx", filetypes=[("Excel", "*.xlsx")],
                title="Export Contracts")
            if not fp:
                return
            wb, rows = self._build_contracts_workbook(items, scope_label)
            wb.save(fp)
            append_audit_event(self.state_obj, "export_contracts_excel", "contracts", scope, {"count": len(rows), "file": os.path.basename(fp)})
            messagebox.showinfo(APP_NAME, f"Exported {len(rows)} contract(s):\n{fp}")
        except Exception as exc:
            self._surface_error("_export_contracts_excel", exc, show=True)

    def _contract_comparison_rows(self, cid_a, cid_b):
        contracts = self.state_obj.get("contracts", {}) or {}
        if cid_a not in contracts or cid_b not in contracts:
            raise ValueError("Choose two valid contracts.")
        a = self._contract_export_row(cid_a, contracts[cid_a])
        b = self._contract_export_row(cid_b, contracts[cid_b])

        def fmt(value, digits=2, suffix=""):
            if value is None or value == "":
                return "—"
            if isinstance(value, (int, float)):
                return f"{value:,.{digits}f}{suffix}"
            return str(value)

        def compare_numeric(key, lower_is_better=False, suffix=""):
            av = to_float(a.get(key), None); bv = to_float(b.get(key), None)
            if av is None or bv is None:
                return "Need data"
            delta = bv - av
            if abs(delta) < 0.005:
                return "Equal"
            if lower_is_better:
                winner = "A" if av < bv else "B"
            else:
                winner = "A" if av > bv else "B"
            return f"{winner} better by {abs(delta):,.2f}{suffix}"

        rows = [
            ("IDENTITY", "Contract", a["contract"], b["contract"], ""),
            ("IDENTITY", "Commodity", a["commodity"], b["commodity"], "Same commodity" if a["commodity"] == b["commodity"] else "Different commodities"),
            ("IDENTITY", "Supplier", a["supplier"], b["supplier"], ""),
            ("IDENTITY", "Origin", a["origin"], b["origin"], ""),
            ("DATES", "Delivery Date", a["delivery_date"], b["delivery_date"], ""),
            ("DATES", "Pricing Date(s)", a["pricing_lot_dates"] or a["pricing_date"], b["pricing_lot_dates"] or b["pricing_date"], ""),
            ("VOLUME", "Quantity MT", fmt(a["qty_mt"], 0), fmt(b["qty_mt"], 0), compare_numeric("qty_mt", suffix=" MT")),
            ("VOLUME", "Remaining MT", fmt(a["remaining_mt"], 0), fmt(b["remaining_mt"], 0), compare_numeric("remaining_mt", lower_is_better=True, suffix=" MT")),
            ("VOLUME", "Unpriced MT", fmt(a["unpriced_qty_mt"], 0), fmt(b["unpriced_qty_mt"], 0), compare_numeric("unpriced_qty_mt", lower_is_better=True, suffix=" MT")),
            ("PRICE", "CIF USD/MT", fmt(a["cif_usd_mt"]), fmt(b["cif_usd_mt"]), compare_numeric("cif_usd_mt", lower_is_better=True, suffix=" USD/MT")),
            ("PRICE", "Basis / Premium", fmt(a["premium"]), fmt(b["premium"]), compare_numeric("premium", lower_is_better=True)),
            ("PRICE", "Contract FX", fmt(a["contract_fx"], 4), fmt(b["contract_fx"], 4), compare_numeric("contract_fx", lower_is_better=True)),
            ("PRICE", "Freight EGP/MT", fmt(a["freight_egp_mt"]), fmt(b["freight_egp_mt"]), compare_numeric("freight_egp_mt", lower_is_better=True, suffix=" EGP/MT")),
            ("PRICE", "Contract Goods EGP/MT", fmt(a["contract_goods_egp_mt"]), fmt(b["contract_goods_egp_mt"]), compare_numeric("contract_goods_egp_mt", lower_is_better=True, suffix=" EGP/MT")),
            ("PRICE", "Own-After EGP/MT", fmt(a["own_after_egp_mt"]), fmt(b["own_after_egp_mt"]), compare_numeric("own_after_egp_mt", lower_is_better=True, suffix=" EGP/MT")),
            ("MARKET", "Matched Local EGP/MT", fmt(a["local_egp_mt"]), fmt(b["local_egp_mt"]), "Context only"),
            ("OUTCOME", "Saving / Position EGP/MT", fmt(a["saving_egp_mt"]), fmt(b["saving_egp_mt"]), compare_numeric("saving_egp_mt", suffix=" EGP/MT")),
            ("OUTCOME", "Total Saving / Position EGP", fmt(a["total_saving_egp"], 0), fmt(b["total_saving_egp"], 0), compare_numeric("total_saving_egp", suffix=" EGP")),
            ("QUALITY", "Data Quality", a["data_quality"], b["data_quality"], ""),
        ]
        return a, b, rows

    def _build_contract_comparison_workbook(self, cid_a, cid_b):
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
        a, b, rows = self._contract_comparison_rows(cid_a, cid_b)
        wb = Workbook(); ws = wb.active; ws.title = "Contract Comparison"
        navy = "0B1F3A"; blue = "2563EB"; pale = "EAF2FF"
        thin = Side(style="thin", color="D8E1EC"); border = Border(left=thin, right=thin, top=thin, bottom=thin)
        ws["A1"] = "PROMETHEUS PROCUREMENT — CONTRACT COMPARISON"; ws["A1"].font = Font(bold=True, size=15, color=navy)
        ws["A2"] = f"Generated: {now_ts()}"
        headers = ["Section", "Metric", f"A · {cid_a}", f"B · {cid_b}", "Comparison"]
        for col, label in enumerate(headers, 1):
            c = ws.cell(4, col, label); c.fill = PatternFill("solid", fgColor=navy); c.font = Font(bold=True, color="FFFFFF"); c.border = border; c.alignment = Alignment(horizontal="center")
        for ridx, row in enumerate(rows, 5):
            for cidx, value in enumerate(row, 1):
                c = ws.cell(ridx, cidx, value); c.border = border; c.alignment = Alignment(vertical="center", wrap_text=True)
            if ridx == 5 or rows[ridx-5][0] != rows[ridx-6][0]:
                for cidx in range(1, 6): ws.cell(ridx, cidx).fill = PatternFill("solid", fgColor=pale)
                ws.cell(ridx, 1).font = Font(bold=True, color=blue)
        for col, width in enumerate([14, 27, 28, 28, 30], 1): ws.column_dimensions[get_column_letter(col)].width = width
        ws.freeze_panes = "A5"
        return wb, (a, b, rows)

    def _export_contract_comparison_excel(self, cid_a, cid_b, parent=None):
        if not _need_openpyxl():
            return
        try:
            fp = filedialog.asksaveasfilename(
                parent=parent, initialdir=get_default_export_dir(),
                initialfile=f"Contract_Comparison_{cid_a}_vs_{cid_b}_{dt.date.today().isoformat()}.xlsx",
                defaultextension=".xlsx", filetypes=[("Excel", "*.xlsx")],
                title="Export Contract Comparison")
            if not fp:
                return
            wb, _payload = self._build_contract_comparison_workbook(cid_a, cid_b)
            wb.save(fp)
            messagebox.showinfo(APP_NAME, f"Comparison saved:\n{fp}", parent=parent)
        except Exception as exc:
            self._surface_error("_export_contract_comparison_excel", exc, show=True)

    def _open_contract_comparison(self):
        contracts = self.state_obj.get("contracts", {}) or {}
        if len(contracts) < 2:
            messagebox.showinfo(APP_NAME, "At least two contracts are required.")
            return
        try:
            existing = getattr(self, "_contract_compare_window", None)
            if existing is not None and existing.winfo_exists():
                existing.lift(); existing.focus_force(); return
        except Exception:
            pass

        win = tk.Toplevel(self)
        self._contract_compare_window = win
        win.title("Compare Two Contracts")
        win.geometry("1120x760")
        win.minsize(900, 620)
        win.configure(bg="#1b2036")
        win.transient(self)
        win.columnconfigure(0, weight=1); win.rowconfigure(2, weight=1)

        hero = tk.Frame(win, bg="#1b2036", highlightthickness=1, highlightbackground="#2e3550")
        hero.grid(row=0, column=0, sticky="ew")
        tk.Label(hero, text="Contract Comparison", bg="#1b2036", fg="white", font=(FONT_FAMILY, 18, "bold")).pack(anchor="w", padx=18, pady=(14, 2))
        tk.Label(hero, text="Compare two contracts side by side using the same saved pricing, cost and local-market logic.", bg="#1b2036", fg="#a9c2de", font=(FONT_FAMILY, FS_BODY)).pack(anchor="w", padx=18, pady=(0, 14))

        picker = ttk.Frame(win, padding=12)
        picker.grid(row=1, column=0, sticky="ew")
        picker.columnconfigure(1, weight=1); picker.columnconfigure(3, weight=1)
        labels = self._contract_picker_values()
        sel = list(self.contract_tree.selection()) if hasattr(self, "contract_tree") else []
        a_var = tk.StringVar(value=self._contract_display_label(sel[0], contracts[sel[0]]) if len(sel) >= 1 and sel[0] in contracts else labels[0])
        b_default = self._contract_display_label(sel[1], contracts[sel[1]]) if len(sel) >= 2 and sel[1] in contracts else (labels[1] if len(labels) > 1 else labels[0])
        b_var = tk.StringVar(value=b_default)
        ttk.Label(picker, text="Contract A").grid(row=0, column=0, sticky="w", padx=(0, 6))
        a_combo = ttk.Combobox(picker, textvariable=a_var, values=labels, state="readonly")
        a_combo.grid(row=0, column=1, sticky="ew", padx=(0, 14))
        ttk.Label(picker, text="Contract B").grid(row=0, column=2, sticky="w", padx=(0, 6))
        b_combo = ttk.Combobox(picker, textvariable=b_var, values=labels, state="readonly")
        b_combo.grid(row=0, column=3, sticky="ew", padx=(0, 10))

        table_wrap = ttk.Frame(win, padding=(12, 0, 12, 8))
        table_wrap.grid(row=2, column=0, sticky="nsew")
        table_wrap.columnconfigure(0, weight=1); table_wrap.rowconfigure(0, weight=1)
        tv = ttk.Treeview(table_wrap, columns=["Metric", "A", "B", "Comparison"], show="headings", style="Contracts.Treeview")
        for col, width, anchor in [("Metric", 220, "w"), ("A", 260, "w"), ("B", 260, "w"), ("Comparison", 270, "w")]:
            tv.heading(col, text=col); tv.column(col, width=width, anchor=anchor)
        tv.grid(row=0, column=0, sticky="nsew")
        sb = ttk.Scrollbar(table_wrap, orient="vertical", command=tv.yview); sb.grid(row=0, column=1, sticky="ns"); tv.configure(yscrollcommand=sb.set)
        tv.tag_configure("section", background="#dbeafe", foreground="#1b2036", font=(FONT_FAMILY, FS_BODY, "bold"))
        tv.tag_configure("warn", background="#fff7ed")

        current = {"a": "", "b": ""}
        def render(*_args):
            for iid in tv.get_children(""): tv.delete(iid)
            cid_a = self._resolve_contract_id_from_label(a_var.get()); cid_b = self._resolve_contract_id_from_label(b_var.get())
            current["a"], current["b"] = cid_a, cid_b
            if not cid_a or not cid_b or cid_a == cid_b:
                tv.insert("", "end", values=("Choose two different contracts", "", "", ""), tags=("warn",)); return
            _a, _b, rows = self._contract_comparison_rows(cid_a, cid_b)
            prior = None
            for section, metric, av, bv, result in rows:
                if section != prior:
                    tv.insert("", "end", values=(section.title(), "", "", ""), tags=("section",))
                    prior = section
                tag = ("warn",) if ("Need data" in str(result) or "Different commodities" in str(result)) else ()
                tv.insert("", "end", values=(metric, av, bv, result), tags=tag)
        a_combo.bind("<<ComboboxSelected>>", render); b_combo.bind("<<ComboboxSelected>>", render)
        render()

        actions = ttk.Frame(win, padding=(12, 0, 12, 12))
        actions.grid(row=3, column=0, sticky="ew")
        ttk.Label(actions, text="Lower cost is favorable; higher saving is favorable. Open-contract values are indicative.", foreground="#64748b").pack(side="left")
        ttk.Button(actions, text="Export Comparison Excel", command=lambda: self._export_contract_comparison_excel(current["a"], current["b"], win)).pack(side="right", padx=(8, 0))
        ttk.Button(actions, text="Close", command=win.destroy).pack(side="right")


    def clear_contract_filters(self):
        if hasattr(self, "contract_search_var"):
            self.contract_search_var.set("")
        if hasattr(self, "contract_filter_commodity_var"):
            self.contract_filter_commodity_var.set("ALL")
        if hasattr(self, "contract_filter_status_var"):
            self.contract_filter_status_var.set("ALL")
        if hasattr(self, "contract_filter_origin_var"):
            self.contract_filter_origin_var.set("ALL")
        if hasattr(self, "contract_open_only_var"):
            self.contract_open_only_var.set(False)
        if hasattr(self, "contract_sort_var"):
            self.contract_sort_var.set("Delivery Date · Newest First")
        self.refresh_contracts_tree()

    def clear_history_filters(self):
        if hasattr(self, "hist_search_var"):
            self.hist_search_var.set("")
        if hasattr(self, "hist_filter_commodity_var"):
            self.hist_filter_commodity_var.set("ALL")
        if hasattr(self, "hist_filter_origin_var"):
            self.hist_filter_origin_var.set("ALL")
        if hasattr(self, "hist_filter_result_var"):
            self.hist_filter_result_var.set("ALL")
        self.refresh_history_tree()

    def _set_text_widget(self, widget, content):
        if widget is None:
            return
        widget.configure(state="normal")
        widget.delete("1.0", "end")
        widget.insert("1.0", content or "")
        widget.configure(state="disabled")

    def _snapshot_decision_label(self, snap):
        direct = to_float((snap or {}).get("direct_saving_egp_mt"), None)
        if direct is None:
            return "-"
        if direct > 0:
            return "IMPORT"
        if direct < 0:
            return "LOCAL"
        return "WAIT"

    def _find_snapshot_by_id(self, sid):
        sid = str(sid)
        for idx, s in enumerate(self.state_obj.get("snapshots", [])):
            candidate = str(s.get("snapshot_id") or s.get("id") or f"row_{idx}")
            if candidate == sid:
                return s
        return None

    @staticmethod
    def _fx_move_line(c):
        """One-line insight: how much the EGP moved between the bank
        allocating the currency (Form 4) and delivery, and what that move
        cost/saved per MT on this contract's CIF."""
        f4 = to_float(c.get("form4_fx"), None)
        dl = to_float(c.get("delivery_fx"), None)
        if f4 is None or dl is None:
            return ""
        delta = dl - f4
        line = f"FX move Form 4 → Delivery: {'+' if delta >= 0 else ''}{fmt_num(delta, 4)}"
        cif = to_float(c.get("cif_usd_mt"), None)
        if cif is not None:
            impact = delta * cif
            line += (f"  ({'+' if impact >= 0 else ''}{fmt_num(impact, 0)} EGP/MT "
                     f"on landed cost)")
        return line + "\n"

    def _fx_move_line_pricing(self, c):
        """One-line insight: how much the EGP moved between the pricing-date
        FX assumption (qty-weighted across pricing lots) and the bank
        allocating the currency at Form 4 — the actual FX timing gain/loss
        against the deal's original pricing-date plan."""
        f4 = to_float(c.get("form4_fx"), None)
        pfx, src = self._resolve_pricing_fx(c)
        if f4 is None or not pfx:
            return ""
        delta = f4 - pfx
        line = (f"FX move Pricing → Form 4: {'+' if delta >= 0 else ''}"
                f"{fmt_num(delta, 4)}  ({src})")
        cif = to_float(c.get("cif_usd_mt"), None)
        if cif is not None:
            impact = delta * cif
            verdict = "cost overrun" if impact > 0 else "timing gain" if impact < 0 else "flat"
            line += (f"  ({'+' if impact >= 0 else ''}{fmt_num(impact, 0)} EGP/MT "
                     f"vs the pricing-date plan — {verdict})")
        return line + "\n"

    def update_contract_detail_panel(self):
        if not hasattr(self, "contract_details_text"):
            return
        sel = self.contract_tree.selection()
        if not sel:
            self._set_text_widget(self.contract_details_text, "Select a contract to view details.")
            return
        cid = sel[0]
        c = (self.state_obj.get("contracts", {}) or {}).get(cid, {})
        bal = self._calc_contract_balance_row(cid, c)
        related = [s for s in (self.state_obj.get("snapshots", []) or []) if s.get("contract_id") == cid]
        latest = related[-1] if related else {}
        content = (
            f"Contract ID: {cid}\n"
            f"Name: {c.get('name','-')}\n"
            f"Supplier: {c.get('supplier','-')}\n"
            f"Commodity: {c.get('commodity','-')}\n"
            f"Origin: {c.get('origin','-')}\n"
            f"Status: {c.get('status','-')}\n"
            f"Qty MT: {fmt_num(to_float(c.get('qty_mt'), None), 0)}\n"
            f"Delivery Date: {c.get('delivery_date','-') or c.get('storage_start','-')}\n"
            f"Storage Start: {c.get('storage_start','-')}\n"
            f"Storage End: {c.get('storage_end','-')}\n"
            f"Basis/Premium Pricing Date: {c.get('pricing_date','-') or '-'}\n"
            f"Pricing Lots: {len(self._contract_pricing_lots(c))} lot(s)\n"
            f"Weighted Lot Basis: {fmt_num(self._weighted_pricing_lot_value(c, 'premium_cents'), 2)} ¢/bu\n"
            f"Futures Month: {c.get('futures_month','-') or '-'}\n"
            f"Premium/Basis: {fmt_num(to_float(c.get('premium_cents'), None), 2)} ¢/bu\n"
            f"Form 4 Date: {c.get('form4_date','-') or '-'}\n"
            f"FX at Form 4: {fmt_num(to_float(c.get('form4_fx'), None), 4)}\n"
            f"FX at Delivery: {fmt_num(to_float(c.get('delivery_fx'), None), 4)}\n"
            f"{self._fx_move_line(c)}"
            f"{self._fx_move_line_pricing(c)}"
            f"Estimated Remaining MT: {fmt_num(to_float(bal.get('RemainingMT'), None), 0)}\n"
            f"Estimated Finish Date: {bal.get('EstFinishDate','-')}\n"
            f"Balance Status: {bal.get('Status','-')}\n"
            f"Snapshots Logged: {len(related)}\n"
            f"Latest Direct Saving: {fmt_num(to_float(latest.get('direct_saving_egp_mt'), None), 2)}\n"
            f"Latest FX: {fmt_num(to_float(latest.get('fx'), None), 2)}\n"
            f"Note: {c.get('note','-')}"
        )
        self._set_text_widget(self.contract_details_text, content)
        # refresh notes log for this contract
        self._cn_current_cid = cid
        self._cn_refresh_log(cid)
        # refresh roll history panel
        self._refresh_contract_roll_panel(cid)
        self._refresh_contract_pricing_lots_panel(cid)

    # ── Contract Notes Log helpers ─────────────────────────────────────────

    def _cn_refresh_log(self, cid):
        """Populate the notes log Text widget from state."""
        if not hasattr(self, "_cn_text"):
            return
        c = (self.state_obj.get("contracts", {}) or {}).get(cid, {})
        notes = c.get("notes_log", [])  # list of {"ts":..., "text":...}
        self._cn_text.config(state="normal")
        self._cn_text.delete("1.0", "end")
        if not notes:
            self._cn_text.insert("end", "No notes yet. Type below and click Add Note.\n",
                                  "hint")
            self._cn_text.tag_config("hint", foreground="#aaa")
        for entry in notes:
            ts   = entry.get("ts", "")
            text = entry.get("text", "")
            self._cn_text.insert("end", f"[{ts}]  ", "ts")
            self._cn_text.insert("end", f"{text}\n")
        self._cn_text.tag_config("ts", foreground="#6a8aaa",
                                  font=("Segoe UI", 9))
        self._cn_text.config(state="disabled")
        self._cn_text.see("end")

    def _cn_add_note(self):
        """Append a timestamped note to the current contract."""
        cid  = self._cn_current_cid
        text = self._cn_entry_var.get().strip()
        if not cid or not text:
            return
        contracts = self.state_obj.get("contracts", {}) or {}
        c = contracts.get(cid)
        if c is None:
            return
        c.setdefault("notes_log", []).append(
            {"ts": now_ts(), "text": text})
        self._cn_entry_var.set("")
        save_state(self.state_obj)
        self._autosave_dirty = False
        self._cn_refresh_log(cid)

    # ── Per-contract Roll History panel ───────────────────────────────────

    def _refresh_contract_roll_panel(self, cid):
        """Populate the Roll History mini-tree for the selected contract."""
        if not hasattr(self, "_cdet_roll_tree"):
            return
        tv = self._cdet_roll_tree
        for row in tv.get_children():
            tv.delete(row)

        if not cid:
            self._cdet_roll_summary_var.set("")
            return

        all_rolls = self.state_obj.get("roll_history", []) or []
        contract_rolls = [r for r in all_rolls
                          if str(r.get("contract_id", "")) == str(cid)]
        contract_rolls = sorted(contract_rolls,
                                key=lambda r: r.get("roll_date", ""))

        prev_own = None
        total_gain = 0.0
        for r in contract_rolls:
            old_p  = to_float(r.get("old_premium"), None)
            new_p  = to_float(r.get("new_premium"), None)
            cbot   = to_float(r.get("cbot_at_roll"), None)
            fx     = to_float(r.get("fx_at_roll"), None)

            # implied own-after for this roll
            own_egp = None
            if new_p is not None and cbot is not None and fx is not None:
                own_egp = (cbot + new_p) * 0.3937 * fx

            gain_disp = ""
            tag = "flat"
            if own_egp is not None and prev_own is not None:
                gain = prev_own - own_egp
                total_gain += gain
                gain_disp = f"{gain:+,.0f}"
                tag = "gain" if gain > 0 else ("cost" if gain < 0 else "flat")
            elif own_egp is not None:
                gain_disp = "—"
            prev_own = own_egp

            tv.insert("", "end", tags=(tag,), values=(
                r.get("roll_date", ""),
                f"{old_p:.2f}" if old_p is not None else "",
                f"{new_p:.2f}" if new_p is not None else "",
                r.get("old_month", ""),
                r.get("new_month", ""),
                f"{cbot:.2f}" if cbot is not None else "",
                gain_disp,
                r.get("notes", ""),
            ))

        n = len(contract_rolls)
        if n == 0:
            self._cdet_roll_summary_var.set("No rolls recorded for this contract.")
        else:
            gain_txt = (f"  |  Net roll gain: EGP {total_gain:+,.0f}/MT"
                        if total_gain != 0 else "")
            self._cdet_roll_summary_var.set(
                f"{n} roll(s) recorded{gain_txt}")

    # ── Contract Pricing Lots helpers ─────────────────────────────────────

    def _contract_pricing_lots(self, c):
        """Return normalized pricing lots for one contract.

        Each lot is one basis/premium agreement tranche.  Basis Tracker Pricing
        Date mode uses these rows instead of forcing the whole contract onto one
        date.  Stored format: c["pricing_lots"] = [{date, qty_mt,
        premium_cents, cbot, fx, futures_month, notes, lot_id}].
        """
        raw_lots = (c or {}).get("pricing_lots", []) or []
        if not isinstance(raw_lots, list):
            return []
        lots = []
        for i, lot in enumerate(raw_lots):
            if not isinstance(lot, dict):
                continue
            d = parse_date_flex(lot.get("date") or lot.get("pricing_date"))
            ds = d.isoformat() if d is not None else ""
            rec = dict(lot)
            rec["date"] = ds
            rec["qty_mt"] = to_float(lot.get("qty_mt"), None)
            rec["premium_cents"] = to_float(lot.get("premium_cents"), None)
            rec["cbot"] = to_float(lot.get("cbot"), None)
            rec["fx"] = to_float(lot.get("fx"), None)
            rec["futures_month"] = (lot.get("futures_month") or "").strip()
            rec["notes"] = (lot.get("notes") or "").strip()
            rec["lot_id"] = lot.get("lot_id") or f"lot_{i+1}"
            lots.append(rec)
        lots.sort(key=lambda r: (r.get("date") or "9999-12-31", r.get("lot_id") or ""))
        return lots

    def _weighted_pricing_lot_value(self, c, key):
        """Weighted average of a numeric lot field by qty_mt.

        If quantities are missing, it falls back to a simple average of the
        available values.  Used for Delivery/MTM views and summaries.
        """
        lots = self._contract_pricing_lots(c)
        vals = [(to_float(l.get(key), None), to_float(l.get("qty_mt"), None)) for l in lots]
        vals = [(v, q) for v, q in vals if v is not None]
        if not vals:
            return None
        with_qty = [(v, q) for v, q in vals if q is not None and q > 0]
        if with_qty:
            total_q = sum(q for _, q in with_qty)
            if total_q > 0:
                return sum(v * q for v, q in with_qty) / total_q
        return sum(v for v, _ in vals) / len(vals)

    def _refresh_pricing_lot_contract_picker(self, query=""):
        if not hasattr(self, "pricing_lot_contract_combo"):
            return []
        values = self._contract_picker_values(
            commodity=self.pricing_lot_contract_comm_var.get(),
            open_only=bool(self.pricing_lot_contract_open_only_var.get()),
            query=query)
        self.pricing_lot_contract_combo["values"] = values
        if not query and self.pricing_lot_contract_var.get() not in values:
            self.pricing_lot_contract_var.set("")
        return values

    def _on_pricing_lot_contract_picker_commit(self):
        cid = self._activate_contract_context_from_label(
            self.pricing_lot_contract_var.get())
        if cid:
            self._refresh_contract_pricing_lots_panel(cid)

    def _selected_contract_id_for_lots(self):
        sels = list(self.contract_tree.selection()) if hasattr(self, "contract_tree") else []
        if sels:
            return sels[0]
        cid = (self.c_id_var.get() or "").strip() if hasattr(self, "c_id_var") else ""
        return cid

    def _refresh_contract_pricing_lots_panel(self, cid=None):
        if not hasattr(self, "_cdet_lot_tree"):
            return
        tv = self._cdet_lot_tree
        for row in tv.get_children():
            tv.delete(row)
        cid = cid or self._selected_contract_id_for_lots()
        c = (self.state_obj.get("contracts", {}) or {}).get(cid, {}) if cid else {}
        if cid and hasattr(self, "pricing_lot_contract_var"):
            if (not self._contract_is_open(c)
                    and bool(self.pricing_lot_contract_open_only_var.get())):
                self.pricing_lot_contract_open_only_var.set(False)
            self._refresh_pricing_lot_contract_picker("")
            self.pricing_lot_contract_var.set(
                self._contract_display_label(cid, c))
        lots = self._contract_pricing_lots(c)
        for idx, lot in enumerate(lots):
            tv.insert("", "end", iid=f"lotidx_{idx}", values=(
                lot.get("date", ""),
                fmt_num(lot.get("qty_mt"), 0) if lot.get("qty_mt") is not None else "",
                fmt_num(lot.get("premium_cents"), 2) if lot.get("premium_cents") is not None else "",
                fmt_num(lot.get("cbot"), 2) if lot.get("cbot") is not None else "",
                fmt_num(lot.get("fx"), 4) if lot.get("fx") is not None else "",
                lot.get("futures_month", ""),
                lot.get("notes", ""),
            ))
        if hasattr(self, "_cdet_lot_summary_var"):
            if not cid:
                self._cdet_lot_summary_var.set("Select a contract to manage pricing lots.")
            elif not lots:
                self._cdet_lot_summary_var.set("No pricing lots yet. Add one row per pricing tranche.")
            else:
                total_q = sum((to_float(l.get("qty_mt"), 0) or 0) for l in lots)
                w_basis = self._weighted_pricing_lot_value(c, "premium_cents")
                self._cdet_lot_summary_var.set(
                    f"{len(lots)} lot(s) | Qty {fmt_num(total_q,0)} MT | Weighted basis {fmt_num(w_basis,2)} ¢/bu")

    def _lot_autofill(self, base_comm, date_str):
        """Resolve (cbot, cbot_note, fx, fx_note) from stored history for a
        lot date — the app should never ask for numbers it already knows."""
        base = (base_comm or "CORN").upper().split("-")[0]
        d = parse_date_flex(date_str)
        ds = d.isoformat() if d else ""
        ch = sorted(((e.get("date", ""), to_float(e.get("close", e.get("price")), None))
                     for e in self.state_obj.get("cbot_history", []) or []
                     if (e.get("commodity") or "").upper() == base and e.get("date")))
        fxh = sorted(((e.get("date", ""), to_float(e.get("rate"), None))
                      for e in self.state_obj.get("fx_history", []) or []
                      if e.get("date")))
        def _near(series):
            best = (None, None)
            for dd, v in series:
                if ds and dd <= ds and v is not None:
                    best = (v, dd)
                elif ds and dd > ds:
                    break
            return best
        cbot, cbot_d = _near(ch)
        fx, fx_d = _near(fxh)
        return (cbot, f"from CBOT history {cbot_d}" if cbot is not None else "no history ≤ date",
                fx, f"from FX history {fx_d}" if fx is not None else "no history ≤ date")

    def _ask_pricing_lot_values(self, c, defaults=None):
        """One form instead of 6-7 chained popups. Date drives auto-fill of
        CBOT + FX from stored history (editable); futures month prefills from
        the contract. Returns the same dict shape as before, or None."""
        defaults = defaults or {}
        win = tk.Toplevel(self)
        win.title("Pricing lot")
        win.transient(self); win.grab_set()
        frm = ttk.Frame(win, padding=12)
        frm.grid(row=0, column=0, sticky="nsew")
        vars_ = {
            "date": tk.StringVar(value=defaults.get("date") or c.get("pricing_date", "")),
            "qty_mt": tk.StringVar(value="" if defaults.get("qty_mt") in (None, "")
                                   else str(defaults.get("qty_mt"))),
            "premium_cents": tk.StringVar(value="" if defaults.get("premium_cents") in (None, "")
                                          else str(defaults.get("premium_cents"))),
            "cbot": tk.StringVar(value="" if defaults.get("cbot") in (None, "")
                                 else str(defaults.get("cbot"))),
            "fx": tk.StringVar(value="" if defaults.get("fx") in (None, "")
                               else str(defaults.get("fx"))),
            "futures_month": tk.StringVar(value=defaults.get("futures_month")
                                          or c.get("futures_month", "")),
            "notes": tk.StringVar(value=defaults.get("notes") or ""),
        }
        cbot_note = tk.StringVar(value=""); fx_note = tk.StringVar(value="")
        rows = [("Lot date (YYYY-MM-DD)", "date", None),
                ("Quantity MT (optional)", "qty_mt", None),
                ("Premium ¢/bu", "premium_cents", None),
                ("CBOT at pricing", "cbot", cbot_note),
                ("FX at pricing", "fx", fx_note),
                ("Futures month", "futures_month", None),
                ("Notes", "notes", None)]
        ents = {}
        for r, (lbl, key, note) in enumerate(rows):
            ttk.Label(frm, text=lbl).grid(row=r, column=0, sticky="w",
                                          pady=3, padx=(0, 10))
            e = ttk.Entry(frm, textvariable=vars_[key],
                          width=34 if key == "notes" else 16)
            e.grid(row=r, column=1, sticky="w", pady=3)
            ents[key] = e
            if note is not None:
                ttk.Label(frm, textvariable=note, foreground=CLR["muted"]
                          ).grid(row=r, column=2, sticky="w", padx=(8, 0))
        wire_date_validation(ents["date"], vars_["date"])

        def _autofill(*_):
            cbot, cn, fx, fn = self._lot_autofill(c.get("commodity"),
                                                  vars_["date"].get())
            # only fill fields the user hasn't typed into
            if cbot is not None and not vars_["cbot"].get().strip():
                vars_["cbot"].set(fmt_num(cbot, 2))
            if fx is not None and not vars_["fx"].get().strip():
                vars_["fx"].set(fmt_num(fx, 4))
            cbot_note.set(cn); fx_note.set(fn)
        vars_["date"].trace_add("write", _autofill)
        _autofill()

        result = {"rec": None}

        def _ok():
            d = parse_date_flex(vars_["date"].get())
            if d is None:
                messagebox.showwarning(APP_NAME, "Invalid lot date. Use "
                                       "YYYY-MM-DD, e.g. 2026-02-17.",
                                       parent=win)
                return
            prem = to_float(vars_["premium_cents"].get(), None)
            if prem is None:
                messagebox.showwarning(APP_NAME, "Premium (¢/bu) is required.",
                                       parent=win)
                return
            def _optf(key, label):
                s = vars_[key].get().strip()
                if not s:
                    return None, True
                v = to_float(s, None)
                if v is None:
                    messagebox.showwarning(APP_NAME, f"Invalid {label}.",
                                           parent=win)
                    return None, False
                return v, True
            qty, ok1 = _optf("qty_mt", "quantity")
            cbot, ok2 = _optf("cbot", "CBOT value")
            fx, ok3 = _optf("fx", "FX value")
            if not (ok1 and ok2 and ok3):
                return
            rec = {
                "lot_id": defaults.get("lot_id")
                          or f"lot_{dt.datetime.now().strftime('%Y%m%d%H%M%S')}",
                "date": d.isoformat(), "qty_mt": qty, "premium_cents": prem,
                "cbot": cbot, "fx": fx,
                "futures_month": vars_["futures_month"].get().strip(),
                "notes": vars_["notes"].get().strip(),
            }
            result["rec"] = {k: v for k, v in rec.items() if v not in (None, "")}
            win.destroy()

        btns = ttk.Frame(frm)
        btns.grid(row=len(rows), column=0, columnspan=3, sticky="w",
                  pady=(10, 0))
        ttk.Button(btns, text="Save lot", command=_ok).pack(side="left",
                                                            padx=(0, 8))
        ttk.Button(btns, text="Cancel", command=win.destroy).pack(side="left")
        ents["date"].focus_set()
        self.wait_window(win)
        return result["rec"]

    def _ask_pricing_lot_values_LEGACY(self, c, defaults=None):
        """Ask the user for one pricing lot using small sequential dialogs."""
        defaults = defaults or {}
        raw_date = simpledialog.askstring(
            APP_NAME, "Pricing lot date (YYYY-MM-DD):",
            initialvalue=defaults.get("date") or c.get("pricing_date", ""), parent=self)
        if raw_date is None:
            return None
        d = parse_date_flex(raw_date.strip())
        if d is None:
            messagebox.showwarning(APP_NAME, "Invalid lot date. Use YYYY-MM-DD, for example 2026-02-17.")
            return None
        qty_raw = simpledialog.askstring(
            APP_NAME, "Lot quantity MT (optional, but recommended for weighted average):",
            initialvalue="" if defaults.get("qty_mt") in (None, "") else str(defaults.get("qty_mt")), parent=self)
        if qty_raw is None:
            return None
        qty = to_float(qty_raw, None) if str(qty_raw).strip() else None
        if str(qty_raw).strip() and qty is None:
            messagebox.showwarning(APP_NAME, "Invalid quantity.")
            return None
        prem_default = defaults.get("premium_cents")
        if prem_default in (None, ""):
            prem_default = c.get("premium_cents", "")
        prem_raw = simpledialog.askstring(
            APP_NAME, "Premium / basis for this lot (¢/bu):",
            initialvalue="" if prem_default in (None, "") else str(prem_default), parent=self)
        if prem_raw is None:
            return None
        prem = to_float(prem_raw, None)
        if prem is None:
            messagebox.showwarning(APP_NAME, "Invalid premium/basis.")
            return None
        cbot_raw = simpledialog.askstring(
            APP_NAME, "CBOT used for this lot (optional; blank = resolve from history):",
            initialvalue="" if defaults.get("cbot") in (None, "") else str(defaults.get("cbot")), parent=self)
        if cbot_raw is None:
            return None
        cbot = to_float(cbot_raw, None) if str(cbot_raw).strip() else None
        if str(cbot_raw).strip() and cbot is None:
            messagebox.showwarning(APP_NAME, "Invalid CBOT value.")
            return None
        fx_raw = simpledialog.askstring(
            APP_NAME, "FX for this lot (optional; blank = resolve from FX history):",
            initialvalue="" if defaults.get("fx") in (None, "") else str(defaults.get("fx")), parent=self)
        if fx_raw is None:
            return None
        fx = to_float(fx_raw, None) if str(fx_raw).strip() else None
        if str(fx_raw).strip() and fx is None:
            messagebox.showwarning(APP_NAME, "Invalid FX value.")
            return None
        fut = simpledialog.askstring(
            APP_NAME, "Futures month (optional, e.g. JUL-26):",
            initialvalue=defaults.get("futures_month") or c.get("futures_month", ""), parent=self)
        if fut is None:
            return None
        notes = simpledialog.askstring(
            APP_NAME, "Notes (optional):",
            initialvalue=defaults.get("notes") or "", parent=self)
        if notes is None:
            return None
        rec = {
            "lot_id": defaults.get("lot_id") or f"lot_{dt.datetime.now().strftime('%Y%m%d%H%M%S')}",
            "date": d.isoformat(),
            "qty_mt": qty,
            "premium_cents": prem,
            "cbot": cbot,
            "fx": fx,
            "futures_month": (fut or "").strip(),
            "notes": (notes or "").strip(),
            "updated_ts": now_ts(),
        }
        # Keep JSON clean: remove blank optional numeric fields.
        return {k: v for k, v in rec.items() if v not in (None, "")}

    def add_pricing_lot_to_selected_contract(self):
        try:
            cid = self._selected_contract_id_for_lots()
            if not cid or cid not in self.state_obj.get("contracts", {}):
                messagebox.showinfo(APP_NAME, "Select a contract first.")
                return
            c = self.state_obj["contracts"][cid]
            rec = self._ask_pricing_lot_values(c)
            if not rec:
                return
            c.setdefault("pricing_lots", []).append(rec)
            # Keep first lot date visible in the old single pricing date field,
            # without overwriting if the user already set one manually.
            if not c.get("pricing_date"):
                c["pricing_date"] = rec.get("date", "")
            c["updated_ts"] = now_ts()
            append_audit_event(self.state_obj, "add_pricing_lot", "contract", cid, rec)
            save_state(self.state_obj)
            self.refresh_all()
            self._refresh_contract_pricing_lots_panel(cid)
        except Exception as e:
            self._surface_error("add_pricing_lot_to_selected_contract", e, show=True)

    def edit_selected_pricing_lot(self):
        try:
            cid = self._selected_contract_id_for_lots()
            if not cid or cid not in self.state_obj.get("contracts", {}):
                messagebox.showinfo(APP_NAME, "Select a contract first.")
                return
            sel = list(self._cdet_lot_tree.selection()) if hasattr(self, "_cdet_lot_tree") else []
            if not sel:
                messagebox.showinfo(APP_NAME, "Select a pricing lot row first.")
                return
            idx = int(str(sel[0]).split("_", 1)[1])
            c = self.state_obj["contracts"][cid]
            lots = c.setdefault("pricing_lots", [])
            current = self._contract_pricing_lots(c)[idx]
            rec = self._ask_pricing_lot_values(c, current)
            if not rec:
                return
            # Map sorted index back by lot_id where possible.
            lot_id = current.get("lot_id")
            target_i = next((i for i, l in enumerate(lots) if isinstance(l, dict) and (l.get("lot_id") or f"lot_{i+1}") == lot_id), idx)
            if 0 <= target_i < len(lots):
                lots[target_i] = rec
            c["updated_ts"] = now_ts()
            append_audit_event(self.state_obj, "edit_pricing_lot", "contract", cid, rec)
            save_state(self.state_obj)
            self.refresh_all()
            self._refresh_contract_pricing_lots_panel(cid)
        except Exception as e:
            self._surface_error("edit_selected_pricing_lot", e, show=True)

    def delete_selected_pricing_lot(self):
        try:
            cid = self._selected_contract_id_for_lots()
            if not cid or cid not in self.state_obj.get("contracts", {}):
                messagebox.showinfo(APP_NAME, "Select a contract first.")
                return
            sel = list(self._cdet_lot_tree.selection()) if hasattr(self, "_cdet_lot_tree") else []
            if not sel:
                messagebox.showinfo(APP_NAME, "Select one or more pricing lot rows first.")
                return
            if not messagebox.askyesno(APP_NAME, f"Delete {len(sel)} pricing lot(s)?"):
                return
            c = self.state_obj["contracts"][cid]
            sorted_lots = self._contract_pricing_lots(c)
            lot_ids = set()
            for iid in sel:
                try:
                    idx = int(str(iid).split("_", 1)[1])
                    if 0 <= idx < len(sorted_lots):
                        lot_ids.add(sorted_lots[idx].get("lot_id"))
                except Exception:
                    pass
            c["pricing_lots"] = [l for l in (c.get("pricing_lots", []) or [])
                                  if not isinstance(l, dict) or (l.get("lot_id") not in lot_ids)]
            c["updated_ts"] = now_ts()
            append_audit_event(self.state_obj, "delete_pricing_lot", "contract", cid, {"deleted_lot_ids": list(lot_ids)})
            save_state(self.state_obj)
            self.refresh_all()
            self._refresh_contract_pricing_lots_panel(cid)
        except Exception as e:
            self._surface_error("delete_selected_pricing_lot", e, show=True)

    # ── Push premium from contract form → Calculate tab ───────────────────

    def _fill_delivery_fx_from_history(self):
        """Auto-fill the delivery FX from stored FX history — the app should
        never make you re-type a rate it already has. Uses the nearest rate
        at-or-before the delivery date (or the latest rate if no date)."""
        try:
            fxh = sorted(((e.get("date", ""), to_float(e.get("rate"), None))
                          for e in self.state_obj.get("fx_history", []) or []
                          if e.get("date")))
            fxh = [(d, v) for d, v in fxh if v is not None]
            if not fxh:
                messagebox.showinfo(APP_NAME, "No FX history stored yet — log "
                                    "a rate on Home or in Setup → FX & CBOT "
                                    "History first.")
                return
            dd = parse_date_flex(self.c_delivery_date_var.get())
            pick = None
            if dd is not None:
                ds = dd.isoformat()
                for d, v in fxh:
                    if d <= ds:
                        pick = (d, v)
                    else:
                        break
            if pick is None:
                pick = fxh[-1]
            self.c_delivery_fx_var.set(fmt_num(pick[1], 4))
            self.status_var.set(f"Delivery FX filled from FX history {pick[0]}.")
        except Exception as e:
            self._surface_error("_fill_delivery_fx_from_history", e)

    def _prefill_supplier_fees(self, *_):
        """When a supplier is picked and discharge/clearance are still empty,
        pre-fill them from Setup → Suppliers for the selected commodity —
        instead of making the user re-type numbers already configured."""
        try:
            sup = (self.c_supplier_var.get() or "").strip()
            comm = (self.c_commodity_var.get() or "").strip().upper()
            if not sup or not comm:
                return
            rec = ((self.state_obj.get("suppliers", {}) or {}).get(sup, {})
                   or {}).get(comm) or {}
            filled = []
            if not self.c_discharge_var.get().strip():
                v = to_float(rec.get("direct_egp_mt"), None)
                if v is not None:
                    self.c_discharge_var.set(fmt_num(v, 2))
                    filled.append("discharge")
            if not self.c_clearance_var.get().strip():
                v = to_float(rec.get("indirect_egp_mt"), None)
                if v is not None:
                    self.c_clearance_var.set(fmt_num(v, 2))
                    filled.append("clearance")
            if filled:
                self.status_var.set(
                    f"Pre-filled {' + '.join(filled)} from supplier defaults "
                    f"({sup} / {comm}) — edit if this contract differs.")
        except Exception as e:
            log_exception(e, "_prefill_supplier_fees")

    def _push_contract_premium_to_calc(self):
        """Copy the premium & key fields from the contract form into the Calculate tab."""
        prem = self.c_premium_var.get().strip()
        comm = self.c_commodity_var.get().strip()
        sup  = self.c_supplier_var.get().strip()
        cid  = self.c_id_var.get().strip()
        fx   = self.c_delivery_fx_var.get().strip()

        if not prem:
            messagebox.showwarning(APP_NAME, "Enter a Premium (¢/bu) in the Premium Box first.")
            return

        # set fields in the Calculate tab
        try:
            if hasattr(self, "sd_premium_var"):
                self.sd_premium_var.set(prem)
            if comm and hasattr(self, "sd_commodity_var"):
                self.sd_commodity_var.set(comm)
            if sup and hasattr(self, "sd_supplier_var"):
                self.sd_supplier_var.set(sup)
                self.update_single_supplier_preview()
            if cid and hasattr(self, "sd_contract_var"):
                # find the label for this contract
                label = f"{cid} - {self.state_obj['contracts'].get(cid, {}).get('name', '')}"
                self.sd_contract_var.set(label)
                self.on_single_contract_change()
            if fx and hasattr(self, "sd_fx_var"):
                self.sd_fx_var.set(fx)
            # switch to Calculate tab
            self.nb.select(self.tab_single_outer)
            messagebox.showinfo(
                APP_NAME,
                f"Premium {prem}¢/bu pushed to Calculate tab.\n"
                f"Review inputs then click Calculate or Save Snapshot.")
        except Exception as e:
            log_exception(e, "_push_contract_premium_to_calc")
            messagebox.showerror(APP_NAME, f"Push failed: {e}")

    def update_history_detail_panel(self):
        if not hasattr(self, "history_details_text"):
            return
        sel = self.hist_tree.selection()
        if not sel:
            self._set_text_widget(self.history_details_text, "Select a snapshot to view details.")
            return
        sid = sel[0]
        s = self._find_snapshot_by_id(sid) or {}
        cid = s.get("contract_id", "")
        c = (self.state_obj.get("contracts", {}) or {}).get(cid, {})
        content = (
            f"Snapshot ID: {sid}\n"
            f"Timestamp: {s.get('ts','-')}\n"
            f"Contract: {cid} - {c.get('name','')}\n"
            f"Commodity: {s.get('commodity','-')}\n"
            f"Origin: {s.get('origin') or c.get('origin','-')}\n"
            f"Qty MT: {fmt_num(to_float(s.get('qty_mt'), None), 0)}\n"
            f"FX: {fmt_num(to_float(s.get('fx'), None), 2)}\n"
            f"CBOT: {fmt_num(to_float(s.get('cbot_price'), None), 2)}\n"
            f"Premium/Basis: {fmt_num(to_float(s.get('premium_basis'), None), 2)}\n"
            f"Import USD/MT: {fmt_num(to_float(s.get('import_usd_mt'), None), 2)}\n"
            f"Carry USD/MT: {fmt_num(to_float(s.get('carry_usd_mt'), None), 2)}\n"
            f"Own After EGP/MT: {fmt_num(to_float(s.get('own_after_egp_mt'), None), 2)}\n"
            f"Direct Saving EGP/MT: {fmt_num(to_float(s.get('direct_saving_egp_mt'), None), 2)}\n"
            f"Indirect Saving EGP/MT: {fmt_num(to_float(s.get('indirect_saving_egp_mt'), None), 2)}\n"
            f"Decision: {self._snapshot_decision_label(s)}\n"
            f"Supplier: {s.get('supplier') or c.get('supplier','-')}"
        )
        self._set_text_widget(self.history_details_text, content)

    def _sync_premium_from_lots(self, c):
        """Single source of truth: if a contract has pricing lots, its
        premium is DERIVED (qty-weighted average of lots) — the editor field
        goes read-only and says so. No lots → manual entry as before.
        Prevents the double-truth where the Premium Box and the lots
        disagree silently."""
        try:
            lots = self._contract_pricing_lots(c) if c else []
            lots = [l for l in lots if to_float(l.get("premium_cents"), None) is not None]
            if lots:
                w = self._weighted_pricing_lot_value(c, "premium_cents")
                if w is not None:
                    self.c_premium_var.set(fmt_num(w, 2))
                self._c_prem_entry.configure(state="readonly")
                self._c_prem_src_var.set(
                    f"derived: qty-weighted avg of {len(lots)} pricing lot(s) — "
                    f"edit the lots, not this field")
            else:
                self._c_prem_entry.configure(state="normal")
                self._c_prem_src_var.set("")
        except Exception as e:
            log_exception(e, "_sync_premium_from_lots")

    def load_contract_from_tree(self):
        sel = self.contract_tree.selection()
        if not sel:
            return
        cid = sel[0]
        c = self.state_obj["contracts"].get(cid, {})
        self.c_id_var.set(cid)
        self.c_name_var.set(c.get("name",""))
        self.c_supplier_var.set(c.get("supplier",""))
        self.c_commodity_var.set(c.get("commodity",""))
        self.c_origin_var.set(c.get("origin",""))
        self.c_status_var.set(c.get("status","Open"))
        self.c_qty_var.set("" if c.get("qty_mt") in (None,"") else str(c.get("qty_mt")))
        self.c_note_var.set(c.get("note",""))
        self.c_start_var.set(c.get("storage_start",""))
        self.c_end_var.set(c.get("storage_end",""))
        # Pricing fields
        def _sv(var, key):
            val = c.get(key)
            var.set("" if val in (None, "") else str(val))
        _sv(self.c_cif_var,           "cif_usd_mt")
        _sv(self.c_delivery_fx_var,   "delivery_fx")
        _sv(self.c_delivery_date_var, "delivery_date")
        _sv(self.c_form4_date_var,    "form4_date")
        _sv(self.c_form4_fx_var,      "form4_fx")
        _sv(self.c_discharge_var,     "discharge_egp_mt")
        _sv(self.c_clearance_var,     "clearance_egp_mt")
        # Freight fields
        _sv(self.c_loading_port_var,  "loading_port")
        _sv(self.c_destination_var,   "destination")
        _sv(self.c_freight_var,       "freight_egp_mt")
        # Premium box
        _sv(self.c_premium_var,       "premium_cents")
        self._sync_premium_from_lots(c)
        _sv(self.c_futures_month_var, "futures_month")
        _sv(self.c_pricing_date_var,  "pricing_date")
        # Programmatic StringVar changes do not fire ComboboxSelected. Trigger
        # the same commodity-aware freight refresh used for manual selection.
        try:
            self.c_commodity_combo.event_generate("<<ComboboxSelected>>")
        except Exception:
            pass
        # Refresh the per-contract roll history and pricing-lots panels
        self._refresh_contract_roll_panel(cid)
        self._refresh_contract_pricing_lots_panel(cid)

    def _pricing_fields_from_form(self):
        """
        Extract pricing data from the contract form fields.
        Only includes fields that have a value — blank fields are skipped
        so they don't overwrite existing data on the contract record.
        """
        fields = {}

        def _add(key, raw_val, is_float=True):
            if raw_val is None:
                return
            val = raw_val.strip() if isinstance(raw_val, str) else raw_val
            if val == "" or val is None:
                return
            if is_float:
                v = to_float(val, None)
                if v is not None:
                    fields[key] = v
            else:
                fields[key] = val

        _add("cif_usd_mt",       self.c_cif_var.get())
        _add("delivery_fx",      self.c_delivery_fx_var.get())
        _add("delivery_date",    iso_date_or_keep(self.c_delivery_date_var.get()), is_float=False)
        _add("form4_date",       iso_date_or_keep(self.c_form4_date_var.get()),    is_float=False)
        _add("form4_fx",         self.c_form4_fx_var.get())
        _add("discharge_egp_mt", self.c_discharge_var.get())
        _add("clearance_egp_mt", self.c_clearance_var.get())
        # Freight fields
        _add("loading_port",     self.c_loading_port_var.get(),  is_float=False)
        _add("destination",      self.c_destination_var.get(),   is_float=False)
        _add("freight_egp_mt",   self.c_freight_var.get())
        # Premium box
        # Lots are the single truth: when they exist, the saved premium is
        # always the weighted derivation, never a stale manual number.
        _c_now = (self.state_obj.get("contracts", {}) or {}).get(
            (self.c_id_var.get() or "").strip())
        if _c_now and self._contract_pricing_lots(_c_now):
            _w = self._weighted_pricing_lot_value(_c_now, "premium_cents")
            if _w is not None:
                self.c_premium_var.set(fmt_num(_w, 2))
        _add("premium_cents",    self.c_premium_var.get())
        _add("futures_month",    self.c_futures_month_var.get(), is_float=False)
        _add("pricing_date",     iso_date_or_keep(self.c_pricing_date_var.get()), is_float=False)

        # CIF and Own-After are DIFFERENT figures (own-after adds finance
        # carry). The old mirror wrote cif into own_after_usd_mt on every
        # save, which is why the two fields became interchangeable. A priced
        # contract is simply one with a CIF; own_after_usd_mt is only ever
        # written by an actual calculation (snapshot push-back).
        if "cif_usd_mt" in fields:
            fields["priced"] = True

        return fields

    def add_contract(self):
        name = self.c_name_var.get().strip()
        sup = self.c_supplier_var.get().strip()
        comm = self.c_commodity_var.get().strip()
        if not name:
            messagebox.showwarning(APP_NAME, "Please enter Contract Name.")
            return
        if not sup:
            messagebox.showwarning(APP_NAME, "Please select Supplier.")
            return
        if not comm:
            messagebox.showwarning(APP_NAME, "Please select Commodity.")
            return
        cid = new_contract_id(self.state_obj)
        record = {
            "name": name,
            "supplier": sup,
            "commodity": comm,
            "origin": normalize_origin(self.c_origin_var.get()),
            "status": self.c_status_var.get() or "Open",
            "qty_mt": to_float(self.c_qty_var.get(), None),
            "note": self.c_note_var.get().strip(),
            "storage_start": self.c_start_var.get().strip(),
            "storage_end": self.c_end_var.get().strip(),
            "created_ts": now_ts(),
            "provenance": make_provenance(source="manual", confidence="manual")
        }
        record.update(self._pricing_fields_from_form())
        if record.get("status") == "Closed":
            record["closed_date"] = dt.date.today().isoformat()
        # Keep freight fields normalized on first save too.
        record["loading_port"] = self.c_loading_port_var.get().strip()
        record["destination"] = self.c_destination_var.get().strip()
        freight_raw = self.c_freight_var.get().strip()
        if freight_raw:
            freight_val = to_float(freight_raw, None)
            if freight_val is None:
                messagebox.showwarning(APP_NAME, "Enter a valid Freight Rate (EGP/MT).")
                return
            record["freight_egp_mt"] = freight_val
        self.state_obj["contracts"][cid] = record
        append_audit_event(self.state_obj, "add_contract", "contract", cid, {"name": name, "commodity": comm, "origin": record.get("origin")})
        prev_sel = self.state_obj["ui"].get("selected_contract_id", "ALL")
        self.state_obj["ui"]["selected_contract_id"] = prev_sel
        save_state(self.state_obj)
        self.refresh_all()
        self.c_name_var.set("")
        self.c_origin_var.set("")
        self.c_note_var.set("")
        self.c_pricing_date_var.set("")

    def duplicate_contract(self):
        """Copy the selected contract into a new one — the fast path for
        repeat shipments (same supplier / commodity / fees, new vessel).
        Pricing lots are NOT copied: each shipment prices its own lots."""
        try:
            sel = self.contract_tree.selection()
            if not sel:
                messagebox.showinfo(APP_NAME, "Select a contract to duplicate.")
                return
            src_c = (self.state_obj.get("contracts", {}) or {}).get(sel[0])
            if not src_c:
                return
            new = {k: v for k, v in src_c.items()
                   if k not in ("pricing_lots", "slots", "closed_date", "realized_date")}
            new["name"] = f"{src_c.get('name', '')}-COPY"
            new["status"] = "Open"
            cid = new_contract_id(self.state_obj)
            self.state_obj["contracts"][cid] = new
            save_state(self.state_obj)
            self.refresh_all()
            try:
                self.contract_tree.selection_set(cid)
                self.contract_tree.see(cid)
                self.load_contract_from_tree()
            except Exception:
                pass
            self.status_var.set(f"Duplicated into {cid} — rename it and set "
                                f"the new delivery details.")
        except Exception as e:
            self._surface_error("duplicate_contract", e, show=True)

    def update_contract(self):
        cid = self.c_id_var.get().strip()
        if not cid or cid not in self.state_obj["contracts"]:
            messagebox.showwarning(APP_NAME, "Select a contract from the list first.")
            return
        c = self.state_obj["contracts"][cid]
        old_status = (c.get("status") or "Open").strip() or "Open"
        c["name"]          = self.c_name_var.get().strip()
        c["supplier"]      = self.c_supplier_var.get().strip()
        c["commodity"]     = self.c_commodity_var.get().strip()
        old_origin = c.get("origin", "")
        c["origin"]        = normalize_origin(self.c_origin_var.get())
        c["status"]        = self.c_status_var.get() or "Open"
        c["qty_mt"]        = to_float(self.c_qty_var.get(), None)
        c["note"]          = self.c_note_var.get().strip()
        c["storage_start"] = self.c_start_var.get().strip()
        c["storage_end"]   = self.c_end_var.get().strip()
        c["updated_ts"]    = now_ts()
        c["provenance"]    = make_provenance(source="manual_update", confidence="manual")
        c.update(self._pricing_fields_from_form())

        # Pricing date is an explicit overwrite: blank means clear it.
        pricing_date_raw = (self.c_pricing_date_var.get() or "").strip()
        if pricing_date_raw:
            c["pricing_date"] = iso_date_or_keep(pricing_date_raw)
        else:
            c.pop("pricing_date", None)

        # Freight must be an explicit overwrite on update, not a "skip blanks" field.
        # This makes the Savings tab immediately follow edits made in Contracts.
        c["loading_port"] = self.c_loading_port_var.get().strip()
        c["destination"] = self.c_destination_var.get().strip()
        freight_raw = self.c_freight_var.get().strip()
        if freight_raw == "":
            c.pop("freight_egp_mt", None)
        else:
            freight_val = to_float(freight_raw, None)
            if freight_val is None:
                messagebox.showwarning(APP_NAME, "Enter a valid Freight Rate (EGP/MT).")
                return
            c["freight_egp_mt"] = freight_val

        # Sync delivery_date = storage_start so Savings can select the
        # comparable local price at discharge/delivery.
        if c.get("storage_start"):
            c["delivery_date"] = c["storage_start"]

        # Realized-period KPIs need the date the contract actually became
        # Closed, which is different from its delivery date.
        if c["status"] == "Closed" and old_status != "Closed":
            c["closed_date"] = dt.date.today().isoformat()
        elif c["status"] != "Closed" and old_status == "Closed":
            if c.get("closed_date"):
                c["last_closed_date"] = c["closed_date"]
            c.pop("closed_date", None)

        # Auto-mark priced when closing a contract that has pricing data
        if c["status"] == "Closed" and (c.get("cif_usd_mt") or c.get("own_after_usd_mt")) and c.get("delivery_fx"):
            c["priced"] = True
        append_audit_event(self.state_obj, "update_contract", "contract", cid, {
            "origin_from": old_origin, "origin_to": c.get("origin"),
            "status_from": old_status, "status_to": c.get("status"),
            "closed_date": c.get("closed_date", "")})
        save_state(self.state_obj)
        self.refresh_all()

    def set_pricing_date_for_selected_contracts(self):
        """Bulk-set the true Basis/Premium Pricing Date for selected contracts.

        This is intentionally separate from delivery/Form 4 dates. Basis Tracker
        Pricing Date mode uses this field to judge whether the agreed basis was
        good on the deal date.
        """
        try:
            sels = list(self.contract_tree.selection()) if hasattr(self, "contract_tree") else []
            if not sels:
                messagebox.showinfo(APP_NAME, "Select one or more contracts first.")
                return
            raw = simpledialog.askstring(
                APP_NAME,
                "Enter Basis/Premium Pricing Date for selected contract(s):\nYYYY-MM-DD",
                parent=self,
            )
            if raw is None:
                return
            raw = raw.strip()
            if not raw:
                if not messagebox.askyesno(APP_NAME, "Clear pricing date for selected contract(s)?"):
                    return
                ds = ""
            else:
                d = parse_date_flex(raw)
                if d is None:
                    messagebox.showwarning(APP_NAME, "Invalid date. Use YYYY-MM-DD, for example 2026-02-17.")
                    return
                ds = d.isoformat()
            changed = 0
            for cid in sels:
                c = self.state_obj.get("contracts", {}).get(cid)
                if not c:
                    continue
                if ds:
                    c["pricing_date"] = ds
                else:
                    c.pop("pricing_date", None)
                c["updated_ts"] = now_ts()
                append_audit_event(self.state_obj, "set_pricing_date", "contract", cid, {"pricing_date": ds})
                changed += 1
            save_state(self.state_obj)
            self.refresh_all()
            messagebox.showinfo(APP_NAME, f"Updated pricing date for {changed} contract(s).")
        except Exception as e:
            self._surface_error("set_pricing_date_for_selected_contracts", e, show=True)

    def delete_contract(self):
        sel = self.contract_tree.selection()
        if not sel:
            return
        cid = sel[0]
        if not messagebox.askyesno(APP_NAME, f"Delete contract {cid}?"):
            return
        self.state_obj["contracts"].pop(cid, None)
        self.state_obj["ui"]["selected_contract_id"] = "ALL"
        save_state(self.state_obj)
        self.refresh_all()

    def delete_snapshot(self):
        sel = self.hist_tree.selection()
        if not sel:
            return
        sid = sel[0]
        if not messagebox.askyesno(APP_NAME, f"Delete snapshot {sid}?"):
            return
        self.state_obj["snapshots"] = [s for s in self.state_obj["snapshots"] if s.get("snapshot_id") != sid]
        self.state_obj["history"] = self.state_obj["snapshots"]
        append_audit_event(self.state_obj, "snapshot_delete", "snapshot", sid)
        save_state(self.state_obj)
        self.refresh_all()

    def _resolve_contract_id_from_label(self, label):
        if not label:
            return ""
        return label.split(" - ",1)[0].strip()


    
    def update_single_supplier_preview(self):
        """Update Single Deal supplier intake preview for current supplier + commodity."""
        try:
            comm = (self.sd_commodity_var.get() or "").strip().upper()
            supplier = (self.sd_supplier_var.get() or "").strip()
            if not supplier or not comm:
                self.sd_supplier_name_var.set(supplier or "-")
                self.sd_supplier_direct_var.set("-")
                self.sd_supplier_indirect_var.set("-")
                return
            self.sd_supplier_name_var.set(supplier)
            sup_costs = (self.state_obj.get("suppliers", {}).get(supplier, {}) or {}).get(comm, {}) or {}
            d = sup_costs.get("direct_egp_mt")
            i = sup_costs.get("indirect_egp_mt")
            self.sd_supplier_direct_var.set(fmt_num(d, 2) if d is not None else "-")
            self.sd_supplier_indirect_var.set(fmt_num(i, 2) if i is not None else "-")
        except Exception:
            return

    def on_single_commodity_change(self, *_):
        try:
            self.update_single_supplier_preview()
        except Exception:
            pass
        try:
            comm = (self.sd_commodity_var.get() or "").strip().upper()
            comm_meta = self.state_obj.get("commodities", {}).get(comm, {}) or {}
            if comm_meta.get("type", "NONCBOT") == "CBOT" and comm in CME_QUOTE_URLS:
                self.sd_market_status_var.set(f"Market data: ready for {comm} (multi-source quote)")
            elif comm_meta.get("type", "NONCBOT") == "CBOT":
                self.sd_market_status_var.set(f"Market data: no quote source configured for {comm or 'this commodity'}")
            else:
                self.sd_market_status_var.set(f"Market data: ready for {comm or 'this commodity'}")
        except Exception:
            pass


    def fetch_single_cbot_price(self):
        comm = (self.sd_commodity_var.get() or "").strip().upper()
        if not comm:
            messagebox.showwarning(APP_NAME, "Select Commodity first.")
            return

        comm_meta = self.state_obj.get("commodities", {}).get(comm, {}) or {}
        if comm_meta.get("type", "NONCBOT") != "CBOT":
            messagebox.showinfo(APP_NAME, f"{comm} is configured as a Non-CBOT commodity in this app.")
            return

        self.sd_market_status_var.set(f"Market data: fetching {comm} from best available source...")
        try:
            self.update_idletasks()
        except Exception as _e_19368:
            log_exception(_e_19368, "fetch_single_cbot_price")

        try:
            quote = fetch_best_commodity_quote(comm)

            self.sd_cbot_var.set(f"{quote['price']:.2f}")

            market_stamp = (quote.get("market_time_text") or "").strip()
            fetched_stamp = (quote.get("fetched_at") or now_ts()).strip()
            source_name = quote.get("source") or quote.get("exchange_name") or "SOURCE"
            confidence = quote.get("confidence") or "LOW"

            if market_stamp:
                stamp_text = f"market {market_stamp}"
            else:
                stamp_text = f"fetched {fetched_stamp}"

            self.sd_market_status_var.set(
                f"Market data: {source_name} | {comm} {quote.get('display_price_text', quote['price'])} | {stamp_text} | confidence {confidence}"
            )

            md = self.state_obj.setdefault("market_data", {})
            cbot_quotes = md.setdefault("cbot_quotes", {})
            q = dict(quote)
            q["fetched_at"] = fetched_stamp
            q["source"] = source_name
            q["confidence"] = confidence
            q["time_display"] = stamp_text
            cbot_quotes[comm] = q
            try:
                md.setdefault("market_movement", {})[comm] = fetch_public_market_movement(comm, timeout=8)
            except Exception as _e:
                record_data_issue(self.state_obj, "market_movement", f"{comm}: {_e}", severity="WARN")
            try:
                md.setdefault("futures_curves", {})[comm] = fetch_public_futures_curve(comm, count=5, timeout=8)
            except Exception as _e:
                record_data_issue(self.state_obj, "futures_curve", f"{comm}: {_e}", severity="WARN")
            md["feed_policy"] = PUBLIC_MARKET_FEED_POLICY

            dq = md.setdefault("data_quality", {})
            dq[comm] = {
                "source": source_name,
                "confidence": confidence,
                "market_time_text": market_stamp,
                "fetched_at": fetched_stamp,
                "time_note": quote.get("time_note") or "",
            }

            save_state(self.state_obj)
            try:
                self.refresh_contracts_tree()
                self.refresh_slots_tab()
            except Exception as _e_19421:
                log_exception(_e_19421, "fetch_single_cbot_price")

            self.status_var.set(
                f"Fetched {comm} from {source_name}: {quote.get('display_price_text', quote['price'])} | {stamp_text} | confidence {confidence}"
            )
        except urllib.error.URLError as e:
            self.sd_market_status_var.set(f"Market data: quote fetch failed for {comm}")
            messagebox.showerror(APP_NAME, f"Could not fetch delayed commodity quote.\n\n{e}")
        except Exception as e:
            log_exception(e, "fetch_single_cbot_price")
            self.sd_market_status_var.set(f"Market data: quote fetch failed for {comm}")
            messagebox.showerror(APP_NAME, f"Could not fetch delayed commodity quote.\n\n{e}")

    def fetch_single_fx_rate(self):
        self.sd_market_status_var.set("Market data: fetching USD/EGP...")
        try:
            self.update_idletasks()
        except Exception as _e_19439:
            log_exception(_e_19439, "fetch_single_fx_rate")

        try:
            quote = fetch_best_fx_rate()
            self.sd_fx_var.set(f"{quote['price']:.4f}")
            if not (self.sd_hedge_fx_var.get() or '').strip():
                self.sd_hedge_fx_var.set(f"{quote['price']:.4f}")
            stamp = quote.get("market_time_text") or "time unavailable"
            self.sd_market_status_var.set(
                f"Market data: {(quote.get('source') or quote.get('exchange_name') or 'FX source')} | USD/EGP {quote['price']:.4f} | {stamp}"
            )
            md = self.state_obj.setdefault("market_data", {})
            q = dict(quote)
            q["fetched_at"] = now_ts()
            q["source"] = q.get("source") or q.get("exchange_name") or "FX source"
            md["fx"] = q
            save_state(self.state_obj)
            try:
                self.refresh_contracts_tree()
                self.refresh_slots_tab()
            except Exception as _e_19460:
                log_exception(_e_19460, "fetch_single_fx_rate")
            self.status_var.set(f"Fetched FX rate from {quote.get('exchange_name', 'source')}: USD/EGP {quote['price']:.4f}")
        except urllib.error.URLError as e:
            self.sd_market_status_var.set("Market data: FX fetch failed")
            messagebox.showerror(APP_NAME, f"Could not fetch FX rate.\n\n{e}")
        except Exception as e:
            log_exception(e, "fetch_single_fx_rate")
            self.sd_market_status_var.set("Market data: FX fetch failed")
            messagebox.showerror(APP_NAME, f"Could not fetch FX rate.\n\n{e}")

    def _sd_set_premium_lock(self, c, cid=None):
        """One-truth rule in the evaluator: when the selected contract has a
        premium (weighted from its pricing lots, or stored), the evaluator's
        premium field takes that value and goes READ-ONLY — evaluating a
        contract at a premium it doesn't have would be fiction. Clearing the
        contract unlocks the field for hypothetical deals."""
        try:
            prem = None
            src_note = ""
            if c:
                lots = [l for l in (self._contract_pricing_lots(c) or [])
                        if to_float(l.get("premium_cents"), None) is not None]
                if lots:
                    prem = self._weighted_pricing_lot_value(c, "premium_cents")
                    src_note = (f"🔒 locked by contract — qty-weighted avg of "
                                f"{len(lots)} pricing lot(s)")
                elif to_float(c.get("premium_cents"), None) is not None:
                    prem = to_float(c.get("premium_cents"), None)
                    src_note = "🔒 locked by contract"
            if prem is not None:
                self.sd_premium_var.set(fmt_num(prem, 2))
                self._sd_prem_entry.configure(state="readonly")
                self._sd_prem_note_var.set(src_note + " · edit the contract's "
                                                      "lots to change it")
                self._sd_prem_note.configure(foreground="#1a6ebd")
            else:
                self._sd_prem_entry.configure(state="normal")
                self._sd_prem_note_var.set("CORN: cents/bu | Others: USD/MT")
                self._sd_prem_note.configure(foreground="#666666")
        except Exception as e:
            log_exception(e, "_sd_set_premium_lock")

    def on_single_contract_change(self, *_):
        """Auto-fill single deal from selected contract + supplier costs."""
        try:
            clabel = (self.sd_contract_var.get() or "").strip()
            if not clabel:
                self._sd_set_premium_lock(None)
                return
            cid = self._resolve_contract_id_from_label(clabel)
            c = self.state_obj.get("contracts", {}).get(cid) or {}
            if not c:
                return

            comm = (c.get("commodity", "") or self.sd_commodity_var.get() or "CORN").upper()
            # Normalise CORN-ARG / CORN-UKR to CORN for the calculator
            comm_calc = "CORN" if comm.startswith("CORN") else comm
            self.sd_commodity_var.set(comm_calc)
            self.on_single_commodity_change()

            if (self.sd_qty_var.get() or "").strip() == "" and c.get("qty_mt") is not None:
                self.sd_qty_var.set(str(c.get("qty_mt")))

            supplier = c.get("supplier", "") or ""
            self.sd_supplier_var.set(supplier)
            self.sd_origin_var.set(c.get("origin", "") or "")
            self.sd_supplier_name_var.set(supplier or "-")
            self._sd_set_premium_lock(c, cid)

            # ── Auto-fill pricing fields from contract record ──────────
            # CIF / import USD
            cif = self._contract_cif_usd(c, cid)
            if cif is not None:
                self.sd_import_usd_var.set(f"{cif:.2f}")

            # FX — use delivery_fx (historical) for closed contracts
            fx = to_float(c.get("delivery_fx"), None)
            if fx is not None:
                self.sd_fx_var.set(f"{fx:.4f}")
            else:
                # Fall back to current market FX if no delivery FX stored
                cur_fx = to_float((self.state_obj.get("market_data", {})
                                   .get("fx", {}) or {}).get("price"), None)
                if cur_fx and not self.sd_fx_var.get():
                    self.sd_fx_var.set(f"{cur_fx:.4f}")

            # Local price — carry-forward from logged prices on delivery date
            delivery_date_str = c.get("delivery_date") or ""
            if delivery_date_str:
                try:
                    del_date = dt.date.fromisoformat(delivery_date_str)
                    comm_keys = self._hd_local_keys_for_contract(c)
                    local = None
                    for ck in comm_keys:
                        pairs = self._local_price_map(ck)
                        if pairs:
                            local = next((p for d, p in reversed(pairs)
                                          if d <= del_date), None)
                            if local:
                                break
                    if local:
                        self.sd_local_var.set(str(int(local)))
                except Exception as _e_19529:
                    log_exception(_e_19529, "on_single_contract_change")

            # Supplier intake fees
            sup_costs = (self.state_obj.get("suppliers", {})
                         .get(c.get("supplier", ""), {}) or {}).get(comm_calc, {}) or {}
            d = sup_costs.get("direct_egp_mt")
            i = sup_costs.get("indirect_egp_mt")
            # Also check per-contract fees
            if d is None:
                d = to_float(c.get("discharge_egp_mt"), None)
            if i is None:
                i = to_float(c.get("clearance_egp_mt"), None)
            self.sd_supplier_direct_var.set(fmt_num(d, 2) if d is not None else "-")
            self.sd_supplier_indirect_var.set(fmt_num(i, 2) if i is not None else "-")

        except Exception:
            return

    def load_last_snapshot_into_single(self):
        """Load the most recent snapshot for selected contract into Single Deal."""
        clabel = (self.sd_contract_var.get() or "").strip()
        if not clabel:
            messagebox.showwarning(APP_NAME, "Select Contract first.")
            return
        cid = self._resolve_contract_id_from_label(clabel)

        snaps = self.state_obj.get("snapshots", []) or []
        last = None
        for s in reversed(snaps):
            if s.get("contract_id") == cid:
                last = s
                break
        if not last:
            messagebox.showinfo(APP_NAME, "No snapshots found for this contract yet.")
            return

        comm = (last.get("commodity") or "").upper()
        if comm:
            self.sd_commodity_var.set(comm)

        for var, key in [
            (self.sd_qty_var, "qty_mt"),
            (self.sd_origin_var, "origin"),
            (self.sd_fx_var, "fx"),
            (self.sd_local_var, "local_egp_mt"),
            (self.sd_fin_days_var, "finance_days"),
            (self.sd_rate_var, "interest_rate"),
            (self.sd_cbot_var, "cbot"),
            (self.sd_premium_var, "premium_usd_mt"),
            (self.sd_import_usd_var, "import_usd_mt"),
            (self.sd_import_egp_var, "import_egp_mt"),
        ]:
            v = last.get(key)
            if v is not None and v != "":
                var.set(str(v))

        self.on_single_contract_change()
        self.status_var.set(f"Loaded last snapshot: {last.get('snapshot_id','')}")
        try:
            self.nb.select(self.tab_single_outer)
        except Exception:
            pass

    def quick_snapshot(self):
        """Calculate + Save snapshot + optional exports."""
        self.calculate_single()
        if not self._last_single_outputs:
            return

        self.add_snapshot_from_single()
        snaps = self.state_obj.get("snapshots", []) or []
        if not snaps:
            return
        snap = snaps[-1]

        export_dir = get_default_export_dir()
        ts = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        base = f"{snap.get('contract_id','')}_{snap.get('commodity','')}_{ts}"

        done = []
        if getattr(self, "qs_export_snapshot_xlsx_var", None) and self.qs_export_snapshot_xlsx_var.get():
            fp = os.path.join(export_dir, f"{base}_SNAPSHOT.xlsx")
            try:
                export_snapshot_excel(fp, snap)
                done.append(os.path.basename(fp))
            except Exception as e:
                messagebox.showerror(APP_NAME, f"Snapshot Excel export failed:\n{e}")

        if getattr(self, "qs_export_pdf_var", None) and self.qs_export_pdf_var.get():
            fp = os.path.join(export_dir, f"{base}_SNAPSHOT.pdf")
            try:
                export_snapshot_pdf(fp, snap, None)
                done.append(os.path.basename(fp))
            except Exception as e:
                messagebox.showerror(APP_NAME, f"Snapshot PDF export failed:\n{e}")

        if done:
            self.status_var.set("Quick Snapshot: " + ", ".join(done))
            if getattr(self, "qs_open_folder_var", None) and self.qs_open_folder_var.get():
                open_folder(export_dir)
        else:
            self.status_var.set("Quick Snapshot saved to History (no exports selected).")

    def _bump_single_var(self, var: tk.StringVar, delta: float):
        """Small meeting-friendly tweak: bump a numeric field and re-calc."""
        try:
            cur = to_float(var.get(), 0.0)
            cur = 0.0 if cur is None else cur
            var.set(str(round(cur + float(delta), 4)))
        except Exception:
            # if the field is empty or non-numeric, just set delta as the value
            try:
                var.set(str(delta))
            except Exception:
                pass
        try:
            self.calculate_single()
        except Exception:
            pass

    def _refresh_single_styles(self):
        """Update the decision banner + color coding based on latest outputs."""
        out = self._last_single_outputs["outputs"] if self._last_single_outputs else {}
        if not out:
            return

        thr = to_float(self.state_obj.get("ui", {}).get("marginal_threshold_egp_mt"), 200.0) or 200.0
        d = out.get("direct_saving_egp_mt")
        i = out.get("indirect_saving_egp_mt")
        be_d = out.get("break_even_fx_direct")
        be_i = out.get("break_even_fx_indirect")
        fx = out.get("fx")

        # Banner message (what your boss actually cares about)
        banner = "-"
        bg = "#f0f0f0"
        fg = "#000000"
        try:
            if d is not None:
                if d < 0:
                    banner = f"RECOMMENDATION: PREFER LOCAL (Direct saving {fmt_num(d,2)} EGP/MT)"
                    bg = "#f8d7da"  # light red
                    fg = "#721c24"
                elif d < thr:
                    banner = f"RECOMMENDATION: MARGINAL (Direct saving {fmt_num(d,2)} EGP/MT)"
                    bg = "#fff3cd"  # light amber
                    fg = "#856404"
                else:
                    banner = f"RECOMMENDATION: BUY IMPORT (Direct saving {fmt_num(d,2)} EGP/MT)"
                    bg = "#d4edda"  # light green
                    fg = "#155724"
        except Exception:
            pass

        try:
            self.decision_banner_var.set(banner)
            self.decision_banner_lbl.configure(bg=bg, fg=fg)
        except Exception:
            pass

        # Traffic-light coloring for key numbers
        def set_color(key, color_hex):
            try:
                lbl = (self.out_value_labels or {}).get(key)
                if lbl is not None:
                    lbl.configure(fg=color_hex)
            except Exception:
                pass

        # Savings: green if positive, red if negative
        for key, val in [("DirectSavingEGP_MT", d), ("IndirectSavingEGP_MT", i), ("SavingEGP_MT", out.get("saving_egp_mt"))]:
            if val is None:
                continue
            set_color(key, "#0a7a0a" if val >= 0 else "#b00020")

        # Break-even: green if BE > current FX, red if already passed
        try:
            if be_d not in (None, 0) and fx is not None:
                set_color("BreakEvenFX_D", "#0a7a0a" if be_d >= fx else "#b00020")
            if be_i not in (None, 0) and fx is not None:
                set_color("BreakEvenFX_I", "#0a7a0a" if be_i >= fx else "#b00020")
        except Exception:
            pass

        # FX Risk and Deal Status text coloring
        risk = (self.out_vars.get("FXRisk").get() if self.out_vars.get("FXRisk") else "").upper()
        if risk == "SAFE":
            set_color("FXRisk", "#0a7a0a")
        elif risk == "TIGHT":
            set_color("FXRisk", "#856404")
        elif risk == "RISK":
            set_color("FXRisk", "#b00020")

        status = (self.out_vars.get("DealStatus").get() if self.out_vars.get("DealStatus") else "").upper()
        if status == "GOOD":
            set_color("DealStatus", "#0a7a0a")
        elif status == "MARGINAL":
            set_color("DealStatus", "#856404")
        elif status == "LOSS":
            set_color("DealStatus", "#b00020")

    def _sd_flash_error(self, msg):
        """Flash the relevant input field red briefly."""
        FIELD_MAP = {
            "FX": self.sd_fx_var,
            "CBOT": self.sd_cbot_var,
            "Premium": self.sd_premium_var,
            "Qty": self.sd_qty_var,
            "Local": self.sd_local_var,
            "Import USD": self.sd_import_usd_var,
            "Import EGP": self.sd_import_egp_var,
        }
        try:
            # Find the first matching entry widget by var
            for keyword, var in FIELD_MAP.items():
                if keyword.lower() in msg.lower():
                    # find the Entry bound to this var
                    for w in self.tab_single.winfo_children():
                        try:
                            if hasattr(w, "cget") and w.cget("textvariable") == str(var):
                                orig = w.cget("highlightbackground")
                                w.config(highlightbackground="#cc2222",
                                         highlightthickness=2)
                                self.after(3000, lambda ww=w, o=orig:
                                           ww.config(highlightbackground=o,
                                                     highlightthickness=1))
                                break
                        except Exception:
                            pass
                    break
        except Exception:
            pass

    def calculate_single(self):
        """
        Calculate single deal without requiring a contract.
        - If a contract is selected: use its supplier/qty defaults.
        - If no contract: use manual inputs on the form and treat as a "future snapshot".
        """
        clabel = (self.sd_contract_var.get() or "").strip()
        cid = None
        c = {}
        if clabel:
            cid = self._resolve_contract_id_from_label(clabel)
            c = self.state_obj.get("contracts", {}).get(cid) or {}
            if not c:
                messagebox.showwarning(APP_NAME, "Selected contract not found.")
                return
        else:
            cid = None
            c = {}

        comm = (self.sd_commodity_var.get().strip() or c.get("commodity","")).upper()
        if not comm:
            messagebox.showwarning(APP_NAME, "Select Commodity first.")
            return
        comm_meta = self.state_obj["commodities"].get(comm, {"type":"NONCBOT","conversion_type":"none","conversion_value":1.0})

        fx = to_float(self.sd_fx_var.get(), None)
        qty = to_float(self.sd_qty_var.get(), None)
        qty_final = qty if qty is not None else c.get("qty_mt")
        if qty_final is None:
            messagebox.showwarning(APP_NAME, "Enter Qty MT (or select a contract with Qty).")
            return
        local = to_float(self.sd_local_var.get(), None)
        if local is None:
            messagebox.showwarning(APP_NAME, "Enter Local Price (EGP/MT).")
            return

        supplier = c.get("supplier","") if cid else (self.sd_supplier_var.get() or "")
        # update preview for manual supplier mode
        if not cid:
            self.update_single_supplier_preview()

        # Read fees directly from the editable entry fields —
        # they were pre-filled from the supplier table but can be overridden
        direct   = to_float(self.sd_supplier_direct_var.get(),   0.0) or 0.0
        indirect = to_float(self.sd_supplier_indirect_var.get(), 0.0) or 0.0

        # If still empty (user cleared them), fall back to supplier table
        if direct == 0.0 and indirect == 0.0:
            sup_costs = (self.state_obj["suppliers"].get(supplier, {}) or {}).get(comm, {}) or {}
            direct   = to_float(sup_costs.get("direct_egp_mt"),   0.0) or 0.0
            indirect = to_float(sup_costs.get("indirect_egp_mt"), 0.0) or 0.0

        inp = {
            "comm_meta": comm_meta,
            "fx": fx,
            "qty_mt": qty_final,
            "local_egp_mt": local,
            "finance_days": self.sd_fin_days_var.get(),
            "interest_rate": self.sd_rate_var.get(),
            "supplier_direct_egp_mt": direct,
            "supplier_indirect_egp_mt": indirect,
            "hedge_pct": self.sd_hedge_pct_var.get(),
            "hedge_fx": self.sd_hedge_fx_var.get(),
            "sell_price_egp_mt": self.sd_sell_price_var.get()
        }
        if comm_meta.get("type") == "CBOT":
            inp["cbot"] = self.sd_cbot_var.get()
            inp["premium_usd_mt"] = self.sd_premium_var.get()
        else:
            inp["import_usd_mt"] = self.sd_import_usd_var.get()
            inp["import_egp_mt"] = self.sd_import_egp_var.get()

        ok, msg = validate_single_inputs(comm_meta, inp)
        if not ok:
            # Show in status bar AND a brief inline highlight — no blocking dialog
            self.status_var.set(f"⚠ {msg}")
            # Highlight the offending field by setting it red for 3 s
            self._sd_flash_error(msg)
            return

        out = compute_decision(inp)
        self._last_single_outputs = {"cid": cid, "commodity": comm, "inputs": inp, "outputs": out, "comm_meta": comm_meta}

        self.out_vars["ImportUSD_MT"].set(fmt_num(out["import_usd_mt"],2))
        self.out_vars["CarryUSD_MT"].set(fmt_num(out["carry_usd_mt"],2))
        self.out_vars["OwnAfterUSD_MT"].set(fmt_num(out["own_after_usd_mt"],2))
        self.out_vars["OwnAfterEGP_MT"].set(fmt_num(out["own_after_egp_mt"],2))
        self.out_vars["SavingEGP_MT"].set(fmt_num(out["saving_egp_mt"],2))
        self.out_vars["DirectOwnAfterEGP_MT"].set(fmt_num(out["direct_own_after_egp_mt"],2))
        self.out_vars["IndirectOwnAfterEGP_MT"].set(fmt_num(out["indirect_own_after_egp_mt"],2))
        self.out_vars["DirectSavingEGP_MT"].set(fmt_num(out["direct_saving_egp_mt"],2))
        self.out_vars["IndirectSavingEGP_MT"].set(fmt_num(out["indirect_saving_egp_mt"],2))
        # Break-even FX outputs
        self.out_vars["BreakEvenFX_D"].set(fmt_num(out.get("break_even_fx_direct"), 2))
        self.out_vars["BreakEvenFX_I"].set(fmt_num(out.get("break_even_fx_indirect"), 2))

        # FX Risk badge based on Direct break-even buffer
        fx_now = out.get("fx")
        be = out.get("break_even_fx_direct")
        risk = "-"
        try:
            if be not in (None, 0) and fx_now is not None:
                buffer_ratio = (be - fx_now) / be
                if buffer_ratio >= 0.05:
                    risk = "SAFE"
                elif buffer_ratio >= 0.0:
                    risk = "TIGHT"
                else:
                    risk = "RISK"
        except Exception:
            pass
        self.out_vars["FXRisk"].set(risk)

        # Deal status based on marginal threshold and Direct saving
        thr = to_float(self.state_obj.get("ui", {}).get("marginal_threshold_egp_mt"), 200.0)
        ds = out.get("direct_saving_egp_mt")
        status = "-"
        try:
            if ds is not None:
                if ds < 0:
                    status = "LOSS"
                elif ds < thr:
                    status = "MARGINAL"
                else:
                    status = "GOOD"
        except Exception:
            pass
        self.out_vars["DealStatus"].set(status)

        # ── Stress test (Feature #2): same engine as Home ─────────────
        try:
            if comm_meta.get("type") == "CBOT":
                # PREMIUM IS ALWAYS LOCKED by default. On this desk a
                # premium is a quoted/agreed number — signed or on the
                # table — never a market variable that drifts ±20¢. The
                # only legitimate premium what-if is "if I WAIT, the market
                # basis may move": that is the explicit opt-in checkbox,
                # OFF by default, and it models the cost of waiting, not a
                # risk of the deal itself.
                _c_sel = c or {}
                _lots = [l for l in (self._contract_pricing_lots(_c_sel)
                                     or [])
                         if to_float(l.get("premium_cents"), None) is not None]
                _whatif_ready = bool(
                    getattr(self, "_stress_whatif_prem_var", None)
                    and self._stress_whatif_prem_var.get()
                    and getattr(self, "_stress_whatif_ready", False))
                _prem_locked = not _whatif_ready
                _cbot_locked = bool(_lots) and all(
                    to_float(l.get("cbot"), None) is not None for l in _lots)
                stress_inputs = {
                    "commodity": comm,
                    "premium_locked": _prem_locked,
                    "prem_shocks_custom": (self._stress_whatif_custom
                                           if _whatif_ready else None),
                    "cbot_locked": _cbot_locked,
                    "cbot": to_float(inp.get("cbot"), None),
                    "fx": to_float(inp.get("fx"), None),
                    "premium_cents": to_float(inp.get("premium_usd_mt"), None),
                    "qty_mt": to_float(inp.get("qty_mt"), None),
                    "local_egp_mt": to_float(inp.get("local_egp_mt"), None),
                    "fees_egp_mt": to_float(inp.get("supplier_direct_egp_mt"), None),
                    "marginal_egp_mt": to_float(
                        (self.state_obj.get("ui", {}) or {})
                        .get("marginal_threshold_egp_mt"), 200.0),
                }
                self._last_stress = run_stress_test(stress_inputs)
            else:
                self._last_stress = {"error": "Flat-price contract — CBOT "
                                     "stress shocks do not apply",
                                     "missing": [],
                                     "resilience": "Unavailable",
                                     "version": STRESS_ENGINE_VERSION}
            self._refresh_stress_section()
            st = self._last_stress
            if st and not st.get("error") and st.get("high_risk"):
                # The verdict itself is unchanged; the tag warns that the
                # profit does not survive the adverse combination.
                self.out_vars["DealStatus"].set(status + "  —  HIGH RISK")
                lbl = self.out_value_labels.get("DealStatus")
                if lbl is not None:
                    attach_tooltip(lbl, "The base case is profitable, but the "
                                   "adverse stress scenario produces a "
                                   "material loss.")
            if st and not st.get("error"):
                append_audit_event(
                    self.state_obj, "stress_test", "evaluation",
                    cid or "", {
                        "commodity": st["inputs"]["commodity"],
                        "cbot": st["inputs"]["cbot"],
                        "fx": st["inputs"]["fx"],
                        "premium": st["inputs"]["premium_cents"],
                        "qty_mt": st["inputs"]["qty_mt"],
                        "local": st["inputs"]["local_egp_mt"],
                        "best": st["best"]["saving_egp_mt"],
                        "base": st["base"]["saving_egp_mt"],
                        "adverse": st["adverse"]["saving_egp_mt"],
                        "be_cbot": st["be_cbot"], "be_fx": st["be_fx"],
                        "high_risk": st["high_risk"],
                        "engine": st["version"]})
        except Exception as e:
            log_exception(e, "calculate_single:stress")

        # ── Decision engine (Feature #3): recommendation from the same
        #    stress inputs + contract context ─────────────────────────
        try:
            st = self._last_stress
            if st is not None and comm_meta.get("type") == "CBOT":
                dec_inputs = dict(stress_inputs)
                dec_inputs.update(self._deal_decision_context(cid, c))
                rec = run_decision_engine(dec_inputs)
                self._last_decision = rec
                self._refresh_decision_card(rec)
                if not st.get("error"):
                    append_audit_event(
                        self.state_obj, "recommendation", "evaluation",
                        cid or "", {
                            "action": rec["action"], "pct": rec["pct"],
                            "headline": rec["headline"],
                            "confidence": rec["confidence"],
                            "base": rec.get("base_saving_mt"),
                            "worst": rec.get("worst_mt"),
                            "engine": rec["version"]})
            else:
                self._last_decision = None
                self._refresh_decision_card(
                    {"action": "INSUFFICIENT_DATA", "high_risk": False,
                     "headline": "Insufficient reliable data",
                     "reasons": ["Flat-price contract — CBOT decision "
                                 "engine does not apply"],
                     "confidence": 0})
        except Exception as e:
            log_exception(e, "calculate_single:decision")

        # Hedge + Margin outputs
        self.out_vars["BlendedFX"].set(fmt_num(out.get("blended_fx"), 2))
        self.out_vars["HedgedDirectSavingEGP_MT"].set(fmt_num(out.get("hedged_direct_saving_egp_mt"), 2))
        self.out_vars["HedgedIndirectSavingEGP_MT"].set(fmt_num(out.get("hedged_indirect_saving_egp_mt"), 2))
        self.out_vars["DirectMarginEGP_MT"].set(fmt_num(out.get("direct_margin_egp_mt"), 2))
        self.out_vars["IndirectMarginEGP_MT"].set(fmt_num(out.get("indirect_margin_egp_mt"), 2))
        self.out_vars["HedgedDirectMarginEGP_MT"].set(fmt_num(out.get("hedged_direct_margin_egp_mt"), 2))
        self.out_vars["HedgedIndirectMarginEGP_MT"].set(fmt_num(out.get("hedged_indirect_margin_egp_mt"), 2))

        # === Consumption / Storage analytics (optional) ===
        cons = self.get_consumption_mt_day(comm)
        self.out_vars["ConsMT_Day"].set(fmt_num(cons, 2) if cons is not None else "-")

        start_d = None
        end_d = None
        coverage_days = None
        avg_holding_days = None

        if cid:
            start_d = self._parse_date(c.get("storage_start"))
            end_d = self._parse_date(c.get("storage_end"))

        # estimate finish date from qty/consumption if end date is not set
        if start_d and (end_d is None):
            end_est, cov = self.estimate_finish_date(start_d, qty_final, comm)
            end_d = end_est
            coverage_days = cov
        elif start_d and end_d and cons and cons > 0:
            # If both dates exist, coverage days can still be derived from qty/consumption
            coverage_days = qty_final / cons

        if coverage_days is not None:
            avg_holding_days = coverage_days / 2.0

        self.out_vars["CoverageDays"].set(fmt_num(coverage_days, 2) if coverage_days is not None else "-")
        self.out_vars["AvgHoldingDays"].set(fmt_num(avg_holding_days, 2) if avg_holding_days is not None else "-")
        self.out_vars["EstFinishDate"].set(end_d.isoformat() if isinstance(end_d, dt.date) else "-")

        avg_local = None
        if start_d and end_d:
            try:
                avg_local = self.avg_local_price_period(comm, start_d, end_d)
            except Exception:
                avg_local = None
        self.out_vars["AvgLocal_Storage"].set(fmt_num(avg_local, 0) if avg_local is not None else "-")

        # Carry cost using average local price and average holding days (more realistic than total days)
        rate = to_float(self.sd_rate_var.get(), None)
        if rate is not None and rate <= 1:
            rate = rate * 100.0

        local_carry_mt = None
        local_carry_total = None
        if avg_local is not None and avg_holding_days is not None and rate is not None:
            local_carry_mt = avg_local * (rate/100.0) * (avg_holding_days/360.0)
            local_carry_total = local_carry_mt * qty_final

        self.out_vars["LocalCarryEGP_MT"].set(fmt_num(local_carry_mt, 0) if local_carry_mt is not None else "-")
        self.out_vars["LocalCarryTotalEGP"].set(fmt_num(local_carry_total, 0) if local_carry_total is not None else "-")


        try:
            self._refresh_single_styles()
        except Exception:
            pass


    def add_snapshot_from_single(self):
        if not self._last_single_outputs:
            self.calculate_single()
        if not self._last_single_outputs:
            return
        cid  = self._last_single_outputs["cid"]
        comm = self._last_single_outputs["commodity"]
        inp  = self._last_single_outputs["inputs"]
        out  = self._last_single_outputs["outputs"]
        meta = self._last_single_outputs["comm_meta"]

        sid = new_snapshot_id(self.state_obj)
        contract_meta = self.state_obj.get("contracts", {}).get(cid, {}) if cid else {}

        direct_fees   = to_float(inp.get("supplier_direct_egp_mt"), None)
        indirect_fees = to_float(inp.get("supplier_indirect_egp_mt"), None)

        snap = {
            "snapshot_id": sid,
            "contract_id": cid,
            "contract_label": contract_label(self.state_obj, cid) if cid else "",
            "ts": now_ts(),
            "commodity": comm,
            "supplier": contract_meta.get("supplier","") if cid else (self.sd_supplier_var.get() or ""),
            "origin": (contract_meta.get("origin","") if cid else "") or (self.sd_origin_var.get() or "").strip(),
            "qty_mt": out.get("qty_mt"),
            "fx": out.get("fx"),
            "break_even_fx_direct":   out.get("break_even_fx_direct"),
            "break_even_fx_indirect": out.get("break_even_fx_indirect"),
            "local_egp_mt":   to_float(inp.get("local_egp_mt"), None),
            "import_usd_mt":  out.get("import_usd_mt"),
            "finance_days":   to_float(inp.get("finance_days"), None),
            "interest_rate":  to_float(inp.get("interest_rate"), None),
            "hedge_pct":      to_float(inp.get("hedge_pct"), 0.0),
            "hedge_fx":       to_float(inp.get("hedge_fx"), None),
            "sell_price_egp_mt": to_float(inp.get("sell_price_egp_mt"), None),
            # canonical fee fields — used by Savings tracker
            "discharge_egp_mt": direct_fees,
            "clearance_egp_mt": indirect_fees,
            # legacy aliases kept for older exports
            "supplier_direct_egp_mt":   direct_fees,
            "supplier_indirect_egp_mt": indirect_fees,
            "carry_usd_mt":               out.get("carry_usd_mt"),
            "own_after_usd_mt":           out.get("own_after_usd_mt"),
            "own_after_egp_mt":           out.get("own_after_egp_mt"),
            "saving_egp_mt":              out.get("saving_egp_mt"),
            "direct_own_after_egp_mt":    out.get("direct_own_after_egp_mt"),
            "indirect_own_after_egp_mt":  out.get("indirect_own_after_egp_mt"),
            "direct_saving_egp_mt":       out.get("direct_saving_egp_mt"),
            "indirect_saving_egp_mt":     out.get("indirect_saving_egp_mt"),
            "cbot":         to_float(inp.get("cbot"), None) if meta.get("type") == "CBOT" else None,
            "premium_usd_mt": to_float(inp.get("premium_usd_mt"), None) if meta.get("type") == "CBOT" else None,
            "conversion_type":  meta.get("conversion_type", ""),
            "conversion_value": meta.get("conversion_value", ""),
            "conversion_factor": cbot_conv_factor(comm, strict=True) if meta.get("type") == "CBOT" else to_float(meta.get("conversion_value"), 1.0),
            "premium_mode": meta.get("premium_mode", "CBOT_UNIT" if meta.get("type") == "CBOT" else "USD_MT"),
        }

        self.state_obj["snapshots"].append(snap)

        # ── Write back to the contract record ──────────────────────────────
        # This is the single action that closes the three broken data paths:
        #   1. Fees from Calculate now reach Savings tracker (via contract)
        #   2. own_after_usd_mt + delivery_fx populate Contract Performance
        #   3. priced=True makes the contract visible in Scorecard + Savings
        if cid and cid in self.state_obj.get("contracts", {}):
            c = self.state_obj["contracts"][cid]
            own_after_usd = out.get("own_after_usd_mt")
            fx            = out.get("fx")

            if own_after_usd is not None:
                c["own_after_usd_mt"] = round(own_after_usd, 4)
            # cif_usd_mt gets the TRUE CIF from the calculation inputs —
            # never the own-after (which contains finance carry). Writing
            # own-after into the CIF field inflated CIF by the carry amount
            # everywhere CIF is used (MTM, briefs, basis, performance).
            _true_cif = to_float(inp.get("cif_usd_mt") or inp.get("cif"), None)
            if _true_cif is not None:
                c["cif_usd_mt"] = round(_true_cif, 4)

            if fx is not None:
                # Only write delivery_fx when the contract doesn't have one yet
                # (preserve the historical delivery FX on subsequent re-calculations)
                if not c.get("delivery_fx"):
                    c["delivery_fx"] = round(fx, 4)

            # Fees: write to contract only if they came from the form overrides
            # (i.e. user explicitly set them in the Calculate tab)
            if direct_fees is not None and direct_fees != 0.0:
                c.setdefault("discharge_egp_mt", direct_fees)
            if indirect_fees is not None and indirect_fees != 0.0:
                c.setdefault("clearance_egp_mt", indirect_fees)

            # Mark priced when the contract is Closed or has a delivery date
            status = (c.get("status") or "Open").strip()
            if status == "Closed" or c.get("delivery_date"):
                c["priced"] = True

            c["last_snapshot_id"] = sid
            c["last_snapshot_ts"] = snap["ts"]

        save_state(self.state_obj)
        self._autosave_dirty = False
        self.refresh_all()
        messagebox.showinfo(APP_NAME, f"Snapshot {sid} saved.")


    def save_supplier_costs(self):
        sup  = self.sup_name_var.get().strip()
        comm = self.sup_comm_var.get().strip().upper()
        if not sup or not comm:
            messagebox.showwarning(APP_NAME, "Supplier and Commodity are required.")
            return
        d = to_float(self.sup_direct_var.get(), None)
        i = to_float(self.sup_indirect_var.get(), None)
        if d is None and i is None:
            messagebox.showwarning(APP_NAME, "Enter at least one of Direct or Indirect.")
            return
        self.state_obj["suppliers"].setdefault(sup, {})
        self.state_obj["suppliers"][sup].setdefault(comm, {})
        if d is not None: self.state_obj["suppliers"][sup][comm]["direct_egp_mt"]   = d
        if i is not None: self.state_obj["suppliers"][sup][comm]["indirect_egp_mt"] = i

        # Propagate to all matching open contracts immediately
        for c in self.state_obj.get("contracts", {}).values():
            c_sup  = c.get("supplier", "")
            c_comm = (c.get("commodity") or "").upper()
            c_stat = (c.get("status", "Open") or "Open")
            if (c_sup == sup and c_stat == "Open" and
                    (c_comm == comm or
                     (comm.startswith("CORN") and c_comm.startswith("CORN")))):
                if d is not None: c["discharge_egp_mt"] = d
                if i is not None: c["clearance_egp_mt"] = i

        save_state(self.state_obj)
        self.refresh_all()
        self.sup_direct_var.set("")
        self.sup_indirect_var.set("")

    def delete_supplier_costs(self):
        sel = self.sup_tree.selection()
        if not sel:
            messagebox.showwarning(APP_NAME, "Select a supplier row to delete.")
            return
        vals = self.sup_tree.item(sel[0], "values")
        sup = vals[0]; comm = vals[1]
        if not messagebox.askyesno(APP_NAME, f"Delete {sup} - {comm} costs?"):
            return
        try:
            self.state_obj["suppliers"][sup].pop(comm, None)
            if not self.state_obj["suppliers"][sup]:
                self.state_obj["suppliers"].pop(sup, None)
            save_state(self.state_obj)
            self.refresh_all()
        except Exception as e:
            messagebox.showerror(APP_NAME, f"Delete failed:\n{e}")

    def save_commodity(self):
        name = self.cm_name_var.get().strip().upper()
        if not name:
            messagebox.showwarning(APP_NAME, "Commodity name required.")
            return
        meta = {
            "type": self.cm_type_var.get(),
            "unit": self.cm_unit_var.get().strip(),
            "conversion_type": self.cm_conv_type_var.get(),
            "conversion_value": to_float(self.cm_conv_val_var.get(), None) if self.cm_conv_val_var.get().strip() else 1.0,
        }
        self.state_obj["commodities"][name] = meta
        save_state(self.state_obj)
        self.refresh_all()
        self.cm_name_var.set("")
        self.cm_conv_val_var.set("")

    def delete_commodity(self):
        sel = self.cm_tree.selection()
        if not sel:
            messagebox.showwarning(APP_NAME, "Select a commodity row to delete.")
            return
        vals = self.cm_tree.item(sel[0], "values")
        comm = vals[0]
        if not messagebox.askyesno(APP_NAME, f"Delete commodity {comm}?"):
            return
        self.state_obj["commodities"].pop(comm, None)
        save_state(self.state_obj)
        self.refresh_all()


