    def export_manager_pack(self):
        sel = self._get_selected_snapshots()
        if len(sel) != 2:
            messagebox.showwarning(APP_NAME, "Select TWO snapshot rows in History to export a Manager Pack.")
            return
        a, b = sel[0], sel[1]
        base_dir = get_default_export_dir()
        comm = (b.get("commodity") or a.get("commodity") or "COMMODITY").replace("/","-").replace("\\","-").replace(" ","_")
